const int MOD = 1e9 + 7;
const int MR = 2e5 + 10;

LL modPow( LL a, LL x, LL p ) {
    // return a^x mod p
    LL res = 1;
    while (x>0) {
        if (x & 1) res = ( res*a ) % p;
        a = ( a*a ) % p;
        x >>= 1;
    }

    return res;
}

LL modInverse( LL a, LL p ) {
    // return modular multiplicative of: a mod p, assuming p is prime
    return modPow( a, p - 2, p );
}

int sil[MR];

int main()
{
    map < int, vector < int > > M; M.clear();

    int N, X, Y;
    scanf( "%d%d%d", &N, &X, &Y );
    REP( i, N )
    {
        int c, w;
        scanf( "%d%d", &c, &w );
        M[c].push_back( w );
    }

    vector < pair<int, int>> V; V.clear();

    for (auto &color : M)
    {
        int mn = MOD;
        for (auto &weight : color.second)
            mn = min( mn, weight );
        for (auto &weight : color.second)
            if (weight + mn <= X)
                weight = mn;
        for (auto &weight : color.second)
            V.push_back( MP( weight, color.first ) );
    }

    assert( N == V.size() );

    sort( V.begin(), V.end() );

    map<int, int> ile; ile.clear();

    int n = N;
    int next = -1;
    REP( i, N )
    {
        if (V[i].second != V.front().second)
        {
            next = i;
            break;
        }
    }

    int sub = 0;
    REP( i, N )
    {
        if (V[i].first + V.front().first > Y)
        {
            n = i;
            break;
        }
        else if (V[i].second == V.front().second && V[i].first != V.front().first)
        {
            // przypadek, gdzie wierzcholek jest z tego koloru co minimalny
            // ale jednoczesnie nie mozemy zamienic ich miejscami
            // ze wzgledu na ograniczenie przez X
            if (next == -1 || V[i].first + V[next].first > Y)
            {
                // tego dziada nie mozna przesuwac
                sub++;
                continue;
            }
        }
        ile[V[i].second]++;
    }

    n -= sub;

    sil[0] = 1;
    FORQ( i, 1, n )
        sil[i] = ( sil[i - 1] * (LL)i ) % MOD;

    int res = sil[n];

    for (auto &color : ile)
        res = ( res* modInverse( sil[color.second], MOD ) ) % MOD;

    printf( "%d\n", res );

    return 0;
}

