class UnionFindTree {
	const int size_m;					// 頂点数
	mutable std::vector<int> parent_m;	// 親の添字, 根である場合は自身の添字を入れる
	std::vector<int> card_m;			// 部分木のサイズ

public:
	UnionFindTree(int size);

private:
	bool isValidIndex(int i) const;

public:
	int rootOf(int i) const;
	bool isSame(int i, int j) const;
	void unite(int i, int j);

	int size() const;
	int cardinalityOf(int i) const;
	std::vector<std::vector<int>> toGroups() const;
};

class WeightedUnionFindTree {
	const int size_m;
	mutable std::vector<int> parent_m;
	mutable std::vector<uint64_t> diff_m;	// diff_m[i] : i の親ノード p との間の重み差 (weight[i] - weight[p] = diff_m[i]) 
	std::vector<int> card_m;				// 部分木のサイズ

public:
	WeightedUnionFindTree(int size);

private:
	bool isValidIndex(int i) const;

public:
	int rootOf(int i) const;
	bool isSame(int i, int j) const;
	int64_t query(int i, int j) const;
	bool unite(int i, int j, int64_t diff);

private:
	int64_t weight(int i) const;

public:
	int size() const;
};

