int N, X, Y;
int C[200000];
int W[200000];
int main() {
	cin >> N >> X >> Y;
	REP(i, 0, N) {
		cin >> C[i] >> W[i];
	}

	map<int, vector<int>> mp;
	REP(i, 0, N) {
		mp[C[i]].push_back(i);
	}

	for (auto&& p : mp) {
		sort(p.second.begin(), p.second.end(), [](int i, int j) {
			return W[i] < W[j];
		});
	}

	UnionFindTree uf(N);
	for (auto&& p : mp) {
		auto vec = p.second;
		REP(k, 1, vec.size()) {
			if (W[vec[0]] + W[vec[k]] > X) continue;
			uf.unite(vec[0], vec[k]);
		}
	}

	vector<int> cols;
	for (auto&& p : mp) {
		cols.push_back(p.first);
	}

	sort(cols.begin(), cols.end(), [&](int i, int j) {
		return W[mp[i][0]] < W[mp[j][0]];
	});

	{
		int mn_col = cols[0];
		int mn = mp[mn_col][0];
		for (auto&& p : mp) {
			if (p.first == mn_col) continue;
			auto vec = p.second;
			REP(k, 0, vec.size()) {
				if (W[mn] + W[vec[k]] > Y) continue;
				uf.unite(mn, vec[k]);
			}
		}
	}

	if (cols.size() >= 2) {
		int mn_col2 = cols[1];
		int mn2 = mp[mn_col2][0];
		for (auto&& p : mp) {
			if (p.first == mn_col2) continue;
			auto vec = p.second;
			REP(k, 0, vec.size()) {
				if (W[mn2] + W[vec[k]] > Y) continue;
				uf.unite(mn2, vec[k]);
			}
		}
	}

	MInt ans = 1;
	for (auto&& v : uf.toGroups()) {
		ans *= MInt::fact(v.size());

		map<int, int> hist;
		for (int i : v) {
			++hist[C[i]];
		}

		for (auto&& p : hist) {
			ans /= MInt::fact(p.second);
		}
	}
	cout << ans << endl;
	return 0;
}

