	int ret = 1, cnt = 0;
	queue<int> q;
	vis[x] = 1; q.push(x);
	while(!q.empty()) {
		x = q.front(); q.pop(); cc[a[x].first]++;
		ret = 1ll * ret * (++cnt) % mod * inv[cc[a[x].first]] % mod;
		for(auto y: g[x]) if(vis[y] != 1) { vis[y] = 1; q.push(y); }
	}
	vis[x] = 2; q.push(x);
	while(!q.empty()) {
		x = q.front(); q.pop(); cc[a[x].first]--;
		for(auto y: g[x]) if(vis[y] != 2) { vis[y] = 2; q.push(y); }
	}
	return ret;
}

