const int NMAX = 200000;
int X, Y;
int C[NMAX+1];
int W[NMAX+1];

vector<int> byC[NMAX+1];
vector<int> byG[NMAX+1];

int P[NMAX+1];
int find(int u){return P[u]==u?u:P[u]=find(P[u]);}
void merge(int u,int v){
    u=find(u),v=find(v);
    P[u]=v;
}

typedef long long ll;
ll pinv[NMAX+1];
ll fact[NMAX+1];

int main(){
    int N; scanf("%d%d%d",&N,&X,&Y);
    for(int i=1;i<=N;i++) scanf("%d%d",C+i,W+i);

    for(int i=1;i<=N;i++){
        byC[C[i]].push_back(i);
    }

    for(int i=1;i<=N;i++) if(byC[i].size() == N) return !printf("1\n");

    for(int i=1;i<=N;i++){
        sort(byC[i].begin(), byC[i].end(), [&](int x,int y){
                return W[x]<W[y];
                });
    }

    int m1=-1, m2=-1;

    for(int i=1;i<=N;i++) if(!byC[i].empty()){
        int id = byC[i].front();
        if(m2==-1 || W[m2]>W[id]) m2 = id;
        if(m1==-1 || W[m1]>W[m2]) swap(m1,m2);
    }

    for(int i=1;i<=N;i++) P[i] = i;
    for(int i=1;i<=N;i++) if(!byC[i].empty()){
        int base = byC[i].front();
        int bridge = (m1==base ? m2 : m1);
        for(int j=1;j<byC[i].size();j++){
            int target = byC[i][j];
            if(W[base] + W[target] <= X || W[bridge] + W[target] <= Y)
                merge(base, target);
        }
    }

    vector<int> fronts;
    for(int i=1;i<=N;i++) if(!byC[i].empty()) fronts.push_back(byC[i].front());
    sort(fronts.begin(), fronts.end(), [&](int x,int y){
            return W[x]<W[y];
            });

    for(int i=1;i<fronts.size();i++) if(W[fronts[0]] + W[fronts[i]] <= Y)
        merge(fronts[0], fronts[i]);

    pinv[1] = 1;
    const ll MOD = 1e9+7;
    for(int i=2;i<=N;i++){
        pinv[i] = (MOD - pinv[MOD%i] * (MOD/i) % MOD) % MOD;
    }
    fact[1] = 1;
    for(int i=2;i<=N;i++) fact[i]=fact[i-1]*i%MOD;
    for(int i=1;i<=N;i++) byG[find(i)].push_back(i);

    ll ans = 1;
    for(int i=1;i<=N;i++) if(!byG[i].empty()){
        map<int,int> acc;
        ll cur = fact[byG[i].size()];
        for(int x:byG[i])
            acc[C[x]]++;

        for(auto& kv:acc) for(int i=1;i<=kv.second;i++)
            cur = cur * pinv[i] % MOD;

        ans = ans * cur % MOD;
    }

    printf("%lld\n",ans);
}

