    fact[0] = 1; for (reg int i = 1; i <= n; i++) fact[i] = 1LL * fact[i - 1] * i % mod;
    inv[n] = mod_pow(fact[n], mod - 2);
    for (reg int i = n - 1; i >= 0; i--) inv[i] = 1LL * inv[i + 1] * (1LL * i + 1LL) % mod;
    for (reg int i = 1; i <= n; i++) sum += Size[i];
    for (reg int i = 1; i <= n; i++)
        if (Size[i]) ans = 1LL * ans * calc(sum, Size[i]) % mod, sum -= Size[i];
    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
const int md = 1e9 + 7;
const int inf = 1e9 + 123;

int n, X, Y;
int c[N], w[N];
int mn[N], start[N];
int ft[N], inv[N];
int par[N];
vector< pair<int,int> > vec;
map <int,int> cnt[N];

int pw(int a, int b) {
	int res = 1;
	for (int i = 0; (1LL << i) <= b; ++i) {
		if (b & (1LL << i)) res = 1LL * res * a % md;
		a = 1LL * a * a % md;
	}
	return res;
}

void prep() {
	for (int i = 1; i < N; ++i) mn[i] = inf;
	ft[0] = 1; 
	for (int i = 1; i < N; ++i) ft[i] = 1LL * ft[i-1] * i % md;
	for (int i = 0; i < N; ++i) inv[i] = pw(ft[i], md - 2);
	for (int i = 1; i <= n; ++i) par[i] = i;
}

int anc(int p) { return p == par[p] ? p : par[p] = anc(par[p]); }
void join(int p, int q) { p = anc(p), q = anc(q); if (p != q) par[p] = q; }

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> n >> X >> Y;
	prep();
	for (int i = 1; i <= n; ++i) {
		cin >> c[i] >> w[i], mn[c[i]] = min(mn[c[i]], w[i]);
	}

	for (int i = 1; i <= n; ++i) if (w[i] <= X - mn[c[i]]) {
		w[i] = mn[c[i]];
		if (start[c[i]] == 0) start[c[i]] = i; else join(i, start[c[i]]);
	}

	for (int i = 1; i <= n; ++i) vec.push_back(make_pair(w[i], i));
	sort(vec.begin(), vec.end());

	for (int i = 1; i < (int)vec.size(); ++i) {
		int val = vec[i].first;
		if (val > Y - vec[0].first) break;
		join(vec[0].second, vec[i].second);
	}

	for (int i = 1; i <= n; ++i) cnt[anc(i)][c[i]]++;

	int ans = 1;
	for (int i = 1; i <= n; ++i) if (i == anc(i)) {
		int res = 1;
		int sum = 0;
		for (map<int,int>::iterator it = cnt[i].begin(); it != cnt[i].end(); ++it) {
			sum += it->second;
			res = 1LL * res * inv[it->second] % md;
		}
		res = 1LL * res * ft[sum] % md;
		ans = 1LL * res * ans % md;
	}

	cout << ans << '\n';
}

