#include <bits/stdc++.h>
using namespace std;

const int MAX = 200001;
const int64_t MOD = 1e9+7;
void mul(int64_t& a, int64_t b){
    a = a*b % MOD;
}

const int64_t FACT_MAX = MAX;
int64_t famod[FACT_MAX+1];
int64_t simod[FACT_MAX+1];
int64_t fimod[FACT_MAX+1];

void create_fact_mod(int num){
    famod[0] = 1;
    famod[1] = 1;
    for(int i=2; i<=num; i++){
        famod[i] = famod[i-1] * i % MOD;
    }
}

void create_seq_inv_mod(int num){
    simod[0] = 1;
    simod[1] = 1;
    for(int i=2; i<=num; i++){
        simod[i] = (MOD - MOD/i) * simod[MOD%i] % MOD;
    }
}

void create_fact_inv_mod(int num){
    fimod[0] = 1;
    fimod[1] = 1;
    for(int i=2; i<=num; i++){
        fimod[i] = fimod[i-1] * simod[i] % MOD;
    }
}

void create_mod_tables(int num){
    create_fact_mod(num);
    create_seq_inv_mod(num);
    create_fact_inv_mod(num);
}

int64_t comb_mod(int n, int k){
    return famod[n] * fimod[n-k] % MOD * fimod[k] % MOD;
}

int64_t perm_mod(int n, int k){
    return famod[n] * fimod[n-k] % MOD;
}

int main(){
    int i, j, k;
    int N, X, Y;
    cin >> N >> X >> Y;
    vector<int> cw[MAX];
    for(i=0; i<N; i++){
        int c, w;
        cin >> c >> w;
        cw[c-1].push_back(w);
    }

    vector<int> mins;
    for(i=0; i<N; i++){
        if(cw[i].size()){
            sort(cw[i].begin(), cw[i].end());
            mins.push_back(cw[i][0]);
        }
    }
    sort(mins.begin(), mins.end());
    mins.push_back(1e9); //sentinel

    vector<int> swappable;
    for(i=0; i<N; i++){
        if(cw[i].size()){
            int other_min = (mins[0] == cw[i][0] ? mins[1] : mins[0]);
            int numY = upper_bound(cw[i].begin(), cw[i].end(), Y-other_min) - cw[i].begin();
            if(numY == 0) continue;

            int numX = upper_bound(cw[i].begin(), cw[i].end(), X-cw[i][0]) - cw[i].begin();

            swappable.push_back(max(numX, numY));
        }
    }

    int sum = accumulate(swappable.begin(), swappable.end(), 0);
    create_mod_tables(sum);
    int64_t ans = 1;
    for(auto n : swappable){
        mul(ans, comb_mod(sum, n));
        sum -= n;
    }
    cout << ans << endl;
    return 0;
}

