		if (i == mn.se)
			for (auto x : co[i])
				C += (x + M <= X || x + smn.fi <= Y);
		else
			for (auto x : co[i])
				C += (x + M <= X || x + mn.fi <= Y);
		tot += C;
		ans = ans * ivf[C] % mo;
	}
