int find(int x){
	return (par[x] == x ? x : par[x] = find(par[x]));
}

void uni(int x, int y){
	int a = find(x), b = find(y); 
	if(a == b) return; 
	if(rank[a] >= rank[b]){
		par[b] = a; 
		if(rank[a] == rank[b])rank[a]++;
	}
	else par[a] = b;
}

void pre(){
	fact[0] = fact[1] = inv[0] = inv[1] = 1; 
	for(int i = 2; i < N; i++){
		fact[i] = (fact[i-1]*i) % MOD; 
		inv[i] = powerL(fact[i], MOD - 2, MOD); 
	}
}

