			m[c[i]] = i; 
		}
	}

	REPN(i, n){
		if(i != m[c[i]] && w[i] + w[m[c[i]]] <= x){
			uni(i, m[c[i]]); 	
		}
	}
	int mn1 = 0, mn2 = 0;
	REPN(i, n){
		if(!m[i]) continue;
		if(!mn1){
			mn1 = m[i]; 
		}
		else if(w[m[i]] < w[mn1]){
			mn2 = mn1;
			mn1 = m[i]; 
		}
		else if(!mn2 || w[m[i]] < w[mn2]){
			mn2 = m[i]; 
		}
	}

	REPN(i, n){
		if(c[i] != c[mn1] && w[i] + w[mn1] <= y){
			uni(i, mn1); 
		}
		if(mn2 && c[i] != c[mn2] && w[i] + w[mn2] <= y){ 
			uni(i, mn2); 
		}
	}

	REPN(i, n){
		int a = find(i);
		M[a][c[i]]++;
		sz[a]++; 
	}

	int ans = 1; 

	REPN(i, n){
		if(sz[i]){
			ans = (ans * 1LL * fact[sz[i]]) % MOD; 
			for(auto & j : M[i]){
				ans = (ans * 1LL * inv[j.se]) % MOD; 
			}
		}
	}

	cout << ans << endl; 
	return 0; 
}

