const int N = 400010;
const int mod = 1e9 + 7;
typedef long long LL;
typedef pair<int, int> pii;
pii b[N];
vector<int> t[N];
int n, x, y, col[N], ls[N], w[N];

#define bi b[i].second

int f[N], st[N];
int f_f(int x) { return x == f[x] ? x : f[x] = f_f(f[x]);} 

void merge(int x1, int x2)
{
	int f1 = f_f(x1), f2 = f_f(x2);
	if (f1 != f2) f[f1] = f2;
}

LL p[N];
LL qpow(LL a, LL b)
{
	LL ret = 1, base = a;
	while (b) {
		if (b & 1) ret = ret * base % mod;
		base = base * base % mod, b >>= 1;
	}
	return ret;
}
LL C(int a, int b) {return p[a] * qpow(p[b], mod - 2) % mod * qpow(p[a - b], mod - 2) % mod;}

int main()
{
	scanf("%d%d%d", &n, &x, &y);
	Rep(i, n){
		scanf("%d%d", &col[i], &w[i]);
		b[i].first = w[i], b[i].second = i;
		f[i] = i;
	}
	sort(b + 1, b + 1 + n);

	memset(ls, -1, sizeof(ls));
	ls[col[b[1].second]] = 1;
	int ti = -1;
	for (int i = 2; i <= n; i ++){
		int tmp = ls[col[bi]];
		if (tmp != -1 && b[i].first + b[tmp].first <= x)
			merge(bi, b[tmp].second);
		if (col[bi] != col[b[1].second]){
			if (b[i].first + b[1].first <= y) merge(bi, b[1].second);
		}
		else if (ti != -1 && b[i].first + b[ti].first <= y) merge(bi, b[ti].second);

		if (ls[col[bi]] == -1) ls[col[bi]] = i;
		if (ti == -1 && col[bi] != col[b[1].second]) ti = i;
	}

	Rep(i, n) t[f_f(i)].push_back(col[i]);
	p[0] = 1;
	Rep(i, n) p[i] = p[i - 1] * i % mod;

	LL ans = 1;

	Rep(i, n) if (t[i].size()) {
		sort(t[i].begin(), t[i].end());	
		int top = 0, cnt = 0;
		for (int j = 0; j < t[i].size(); j ++){
			if (t[i][j] != t[i][j - 1] && j != 0) st[++ top] = cnt, cnt = 0;
			cnt ++;
		}
		int tmp = cnt;
		LL tans = 1;
		while (top){
			tans = tans * C(tmp + st[top], st[top]) % mod;
			tmp += st[top], top --;
		}
		ans = ans * tans % mod;
	}
	printf("%lld\n", ans);

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define ull unsigned long long

const int MaxN(200003);
const int Mod(1e9 + 7);

int c[MaxN], w[MaxN], Mn[MaxN];
int fac[MaxN], rfac[MaxN];
int tmp[MaxN], tot, res;
vector<int> G[MaxN];
bool Vis[MaxN];

int fexp(int x, int k)
{
	int res = 1;
	for(; k; k >>= 1, x = (ull) x * x % Mod)
		if(k & 1) res = (ull) res * x % Mod;
	return res;
}

inline int mymin(int x, int y)
{
	return x && w[x] < w[y] ? x : y;
}

inline void add(int u, int v)
{
	G[u].push_back(v);
	G[v].push_back(u);
}

void dfs(int u)
{
	Vis[u] = true, tmp[++tot] = c[u];
	for(auto v : G[u]) if(!Vis[v]) dfs(v);
}

int main()
{
	int n, X, Y;
	scanf("%d%d%d", &n, &X, &Y);
	for(int i = 1; i <= n; i++)
	{
		scanf("%d%d", &c[i], &w[i]);
		Mn[c[i]] = mymin(Mn[c[i]], i);
		res = mymin(res, i);
	}
	for(int i = 1; i <= n; i++)
	{
		if(w[Mn[c[i]]] + w[i] <= X) add(Mn[c[i]], i);
		if(Mn[c[i]] == i && res != i && w[res] + w[i] <= Y) add(res, i);
	}
	for(int i = fac[0] = 1; i <= n; i++)
		fac[i] = (ull) fac[i - 1] * i % Mod;
	rfac[n] = fexp(fac[n], Mod - 2);
	for(int i = n; i; i--)
		rfac[i - 1] = (ull) rfac[i] * i % Mod;
	int ans = 1;
	for(int i = 1; i <= n; i++)
		if(!Vis[i])
		{
			tot = 0, dfs(i);
			ans = (ull) ans * fac[tot] % Mod;
			sort(tmp + 1, tmp + 1 + tot);
			for(int j = 1, k; j <= tot; j = k)
			{
				for(k = j; k <= tot && tmp[k] == tmp[j]; k++);
				ans = (ull) ans * rfac[k - j] % Mod;
			}
		}
	printf("%d\n", ans);
	return 0;
}

