int find_set(int v){
	ret (p[v] == v) ? v : p[v] = find_set(p[v]);
}

void unite(int v, int u){
	v = find_set(v); u = find_set(u);
	if(v == u)ret;
	if(rnk[v] > rnk[u])swap(v, u);
	p[v] = u;
	if(rnk[v] == rnk[u])rnk[u]++;
}

