typedef long long ll;
template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return true; } return false; }
template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return true; } return false; }
#define all(x) (x).begin(),(x).end()
#define fi first
#define se second
#define mp make_pair
#define si(x) int(x.size())
const int mod=1000000007,MAX=200005,INF=1<<30;

ll inv[MAX],fac[MAX],finv[MAX];

void make(){

    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;

    for(int i=2;i<MAX;i++){
        inv[i]=mod-inv[mod%i]*(mod/i)%mod;
        fac[i]=fac[i-1]*(ll)i%mod;
        finv[i]=finv[i-1]*inv[i]%mod;
    }

}

ll comb(ll a,ll b){
    if(a<b) return 0;
    return fac[a]*(finv[b]*finv[a-b]%mod)%mod;
}

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    make();

    int N,X,Y;cin>>N>>X>>Y;
    vector<int> A(N),B(N),mini(N,INF),okcolor(N),can(N);
    for(int i=0;i<N;i++){
        cin>>A[i]>>B[i];
        A[i]--;
        chmin(mini[A[i]],B[i]);
    }

    pair<int,int> mi1={INF,INF},mi2={INF,INF};

    for(int i=0;i<N;i++){
        if(mi1>mp(mini[i],i)){
            chmin(mi2,mi1);
            chmin(mi1,{mini[i],i});
        }else if(mi2>mp(mini[i],i)){
            chmin(mi2,{mini[i],i});
        }
    }

    for(int i=0;i<N;i++){
        if(A[i]==mi1.se){
            if(B[i]+mi2.fi<=Y){
                okcolor[A[i]]=1;
                can[i]=1;
            }
        }else{
            if(B[i]+mi1.fi<=Y){
                okcolor[A[i]]=1;
                can[i]=1;
            }
        }
    }

    for(int i=0;i<N;i++){
        if(can[i]) continue;
        if(mini[A[i]]+B[i]<=X&&okcolor[A[i]]) can[i]=1;
    }

    vector<int> cnt(N);
    int sum=0;

    for(int i=0;i<N;i++){
        if(can[i]){
            cnt[A[i]]++;
            sum++;
        }
    }

    sort(all(cnt));
    reverse(all(cnt));

    ll ans=1;

    for(int i=0;i<N;i++){
        if(cnt[i]==0) break;

        ans*=comb(sum,cnt[i]);
        ans%=mod;

        sum-=cnt[i];
    }

    cout<<ans<<endl;

}

