    vector<bool> c_movable1(N, false), c_movable2(N, false);
    REP(i, N){
        if(i == c1 && c_min[i] + min2 <= Y) c_movable1[i] = true;
        if(i != c1 && c_min[i] + min1 <= Y) c_movable1[i] = true;
        if(c[i] == c1 && w[i] + min2 <= Y) c_movable2[i] = true;
        if(c[i] != c1 && w[i] + min1 <= Y) c_movable2[i] = true;
    }
    //自色と交換できるか
    vector<bool> n_movable(N, false);
    REP(i, N) if(w[i] + c_min[c[i]] <= X) n_movable[i] = true;

    //各色で動かせる個数
    vec N_movable(N, 0);
    int tot = 0;
    REP(i, N) if(c_movable2[i] || (c_movable1[c[i]] && n_movable[i])){
        N_movable[c[i]]++;
        tot++;
    }

    Combination C(N, mod);
    int ans = 1;
    REP(i, N){
        ans *= C.nCr(tot, N_movable[i]);
        tot -= N_movable[i];
        ans %= mod;
    }

    cout << ans;

    return 0;
}


