using namespace std;

const long MOD = 1000000007;
const int  N_MAX = 200001;

using namespace std;

long inv[N_MAX];
long fac[N_MAX];
long finv[N_MAX];

void init(){
    inv[0] = 1;
    fac[0] = 1;
    finv[0] = 1;
    inv[1] = 1;
    fac[1] = 1;
    finv[1] = 1;
    for(int i = 2; i < N_MAX; i++){
        fac[i] = (fac[i-1]*i)%MOD;
        inv[i] = ((-(MOD/i)*inv[MOD%i])%MOD+MOD)%MOD;
        finv[i] = (finv[i-1]*inv[i])%MOD;
    }
}


long comb(int n, int m){
    long ans;
    ans = fac[n]*finv[m];
    ans %= MOD;
    ans *= finv[n-m];
    ans %= MOD;
    return ans;
}


int main(){
    init();
    int N, X, Y;
    vector<int> v[200001];
    cin >> N >> X >> Y;
    int c_max = 0;
    for(int i = 0; i < N; i++){
        int c, w;
        cin >> c >> w;
        v[c].push_back(w);
        c_max = max(c, c_max);
    }
    long ans = 1;
    vector<int> buf;
    int v_min = 0;
    int tmp_min = 2e+9;
    for(int i = 1;i <= c_max; i++){
        sort(v[i].begin(), v[i].end());
        if(v[i].size() == 0) continue;
        if(v[i][0] < tmp_min){
            v_min = i;
            tmp_min = v[i][0];
        }
    }
    for(int i = 1;i <= c_max; i++){
        if(v[i].size() == 0) continue;
        if(i == v_min){
            int cnt = 1;
            for(int j = 1; j < v[i].size(); j++){
                if(v[i][0]+v[i][j] <= X) cnt++;
                else break;
            }
            buf.push_back(cnt);
        }else if(v[v_min][0] + v[i][0] <= Y){
            int cnt = 1;
            for(int j = 1; j < v[i].size(); j++){
                if(v[i][0]+v[i][j] <= X) cnt++;
                else break;
            }
            buf.push_back(cnt);
        }
    }
    int sum = 0;
    for(int i = 0; i < buf.size(); i++){
        sum += buf[i];
    }
    //cout << v_min << endl;
    for(int i = 0; i < buf.size(); i++){
        ans *= comb(sum, buf[i]);
        ans %= MOD;
        sum -= buf[i];
        //cout << buf[i] << endl;
    }
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long lint;
typedef long double llf;
typedef pair<int, int> pi;
const int mod = 1e9 + 7;

const int MAXN = 500005;
struct disj{
	int pa[MAXN], sz[MAXN];
	void init(int n){
		for(int i=0; i<=n; i++){
			pa[i] = i;
			sz[i] = 1;
		}
	}
	int find(int x){
		return pa[x] = (pa[x] == x ? x : find(pa[x]));
	}
	bool uni(int p, int q){
		p = find(p);
		q = find(q);
		if(p == q) return 0;
		pa[q] = p;
		sz[p] += sz[q];
		return 1;
	}
}disj;


lint ipow(lint x, lint p){
	lint ret = 1, piv = x % mod;
	while(p){
		if(p&1) ret *= piv;
		piv *= piv;
		ret %= mod;
		piv %= mod;
		p >>= 1;
	}
	return ret % mod;
}


struct ball{
	int c, w, i;
}a[200005];

int n, x, y;
vector<int> col[200005];
lint fact[200005], invf[200005];

int main(){
	fact[0] = invf[0] = 1;
	scanf("%d %d %d",&n,&x,&y);
	for(int i=1; i<=n; i++) fact[i] = fact[i-1] * i % mod, invf[i] = ipow(fact[i], mod - 2);
	disj.init(n);
	for(int i=0; i<n; i++){
		scanf("%d %d",&a[i].c,&a[i].w);
		a[i].i = i;
	}
	sort(a, a+n, [&](const ball &a, const ball &b){
		return pi(a.c, a.w) < pi(b.c, b.w);
	});
	vector<ball> v;
	for(int i=0; i<n; ){
		int e = i;
		while(e < n && a[e].c == a[i].c) e++;
		for(int j=i+1; j<e; j++){
			if(a[j].w + a[i].w <= x) disj.uni(a[j].i, a[i].i);
		}
		v.push_back(a[i]);
		i = e;
	}
	sort(v.begin(), v.end(), [&](const ball &a, const ball &b){
		return a.w < b.w;
	});
	for(int i=1; i<v.size(); i++){
		if(v[0].w + v[i].w <= y) disj.uni(v[0].i, v[i].i);
	}
	for(int i=0; i<n; i++){
		col[disj.find(a[i].i)].push_back(a[i].c);
	}
	lint ans = 1;
	for(int i=0; i<n; i++){
		sort(col[i].begin(), col[i].end());
		ans *= fact[col[i].size()];
		ans %= mod;
		for(int j=0; j<col[i].size(); ){
			int e = j;
			while(e < col[i].size() && col[i][j] == col[i][e]) e++;
			ans *= invf[e - j];
			ans %= mod;
			j = e;
		}
	}
	cout << ans;
}

