int m[N];
int parent[N];
int sizes[N];
int mn1 , mn2;
int ans;
map < int , int > mp[N];
int fact[N];
int ifact[N];
int find(int node){
	if(parent[node] == node){
		return node;
	}
	return parent[node] = find(parent[node]);
}
void join(int x , int y){
	int a = find(x);
	int b = find(y);
	if(a != b){
		if(sizes[a] < sizes[b]){
			swap(a , b);
		}
		sizes[a] += sizes[b];
		parent[b] = a;
	}
}
int main(){
	scanf("%d %d %d" , &n , &x , &y);
	for(int i = 1 ; i <= n ; ++i){
		parent[i] = i;
		sizes[i] = 1;
	}
	fact[0] = 1;
	for(int i = 1 ; i < N ; ++i){
		fact[i] = (1LL * fact[i - 1] * i) % mod;
	}
	ifact[N - 1] = 787600812;
	for(int i = N - 2 ; i >= 0 ; --i){
		ifact[i] = (1LL * ifact[i + 1] * (i + 1LL)) % mod;
	}
	for(int i = 1 ; i <= n ; ++i){
		scanf("%d %d" , c + i , w + i);
		m[c[i]] = i;
	}
