			m[c[i]] = i;
		}
	}
	for(int i = 1 ; i <= n ; ++i){
		if(w[i] + w[m[c[i]]] <= x){
			join(i , m[c[i]]);
		}
	}
	for(int i = 1 ; i <= n ; ++i){
		if(m[i]){
			if(!mn1){
				mn1 = m[i];
			}
			else if(w[m[i]] < w[mn1]){
				mn2 = mn1;
				mn1 = m[i];
			}
			else if(!mn2){
				mn2 = m[i];
			}
			else if(w[m[i]] < w[mn2]){
				mn2 = m[i];
			}
		}
	}
	for(int i = 1 ; i <= n ; ++i){
		if(w[i] + w[mn1] <= y){
			join(i , mn1);
		}
		if(mn2 && w[i] + w[mn2] <= y){
			join(i , mn2);
		}
	}
	ans = 1;
