    REP(i, N) cin >> C[i] >> W[i];
    map<int, int> minimum;
    REP(i, N) {
        if(!minimum.count(C[i]) || minimum[C[i]] > W[i]) {
            minimum[C[i]] = W[i];
        }
    }
    int all_minimum = INT_MAX;
    for(auto p : minimum) all_minimum = min(all_minimum, p.second);
    map<int, int> count;
    REP(i, N) {
        int c = C[i];
        int v = W[i];
        if(minimum[c] + v <= X) {
            v = minimum[c];
        }
        if(all_minimum + v <= Y) {
            count[c]++;
        }
    }
    int sum = 0;
    for(auto p : count) {
        sum += p.second;
    }
    mint res = 1;
    Comb c(300000);
    assert(count.size() >= 3);
    for(auto p : count) {
        res *= c.nCr(sum, p.second);
        sum -= p.second;
    }

