		if (w[i] + w[min_index] <= y) {
			nodes[i].push_back(min_index);
			nodes[min_index].push_back(i);
		}
	}
	//計算の準備
	vvi dat = cc(nodes);
	ll mod = 1e9 + 7;
	vll fact = mod_factorial(n, mod);
	vll invfact(n + 1);
	Loop(i, n + 1) {
		invfact[i] = mod_pow(fact[i], mod - 2, mod);
	}
	ll ans = 1;
	Loop(i, dat.size()) {
		map<ll, ll> mp2;
		Loop(j, dat[i].size()) {
			int index = dat[i][j];
			mp2[c[index]]++;
		}
		ll p = fact[dat[i].size()];
		for (auto itr = mp2.begin(); itr != mp2.end(); itr++) {
			ll k = (*itr).second;
			p = p * invfact[k] % mod;
		}
		ans = ans * p % mod;
	}
	cout << ans << endl;
	return 0;
}

