struct UF {
	vector<int> par, ran;
	void init(int n) {
		par.resize(n); ran.resize(n);
		for(int i = 0; i < n; i++) {
			par[i] = i;
			ran[i] = 0;
		}
	}
	UF(int mx = 0) { init(mx); }

	int find(int x) {
		if(par[x] == x) return x;
		else return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if(x == y) return;
		if(ran[x] < ran[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if(ran[x] == ran[y]) ran[x]++;
		}
	}
	bool same(int x, int y) { return find(x) == find(y); }
};

ll fac[MAX_N], inv[MAX_N], fiv[MAX_N]; //fiv:inv(fac(i))

ll mod_pow(ll a, ll n) {
	if(n == 0) return 1;
	ll res = mod_pow(a, n / 2);
	if(n % 2 == 0) return res * res % mod;
	else return a * res % mod * res % mod;
}

ll invf(ll a) {
	return mod_pow(a, mod - 2);
}

void C_init(int n) {
	fac[0] = fac[1] = 1; inv[1] = 1;
	fiv[0] = fiv[1] = 1;
	rep(i, 2, n + 1) {
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;
		fiv[i] = fiv[i - 1] * inv[i] % mod;
	}
}

ll C_(int a, int b) { //assume a >= b
	if(a < b || a < 0 || b < 0) return 0;
	return fac[a] * fiv[b] % mod * fiv[a - b] % mod;
}

int N; ll X, Y;

vector<pl> group[MAX_N];
ll C[MAX_N], W[MAX_N];

vector<int> con[MAX_N];
int cnt[MAX_N];

void solve() {
	cin >> N >> X >> Y;
	C_init(N);
	rep(i, 0, N) {
		cin >> C[i] >> W[i]; C[i]--;
		group[C[i]].pb(pi(i, W[i]));
	}
	UF uf(N);
	rep(i, 0, N) {
		vector<pl>& g = group[i];
		int at = -1;
		ll w = linf;
		rep(i, 0, sz(g)) {
			pi p = g[i];
			if(w > p.sec) {
				w = p.sec;
				at = p.fst;
			}
		}
		rep(i, 0, sz(g)) {
			pi p = g[i];
			if(p.sec + w <= X) uf.unite(at, p.fst);
		}
	}
	int at = -1;
	ll w = linf;
	rep(i, 0, N) {
		if(w > W[i]) {
			w = W[i];
			at = i;
		}
	}
	rep(i, 0, N) {
		if(w + W[i] <= Y) uf.unite(i, at);
	}

	rep(i, 0, N) con[uf.find(i)].pb(i);

	vi& vec = con[uf.find(at)];
	rep(i, 0, sz(vec)) {
		cnt[C[vec[i]]]++;
	}

	ll ans = fac[sz(vec)];

	rep(i, 0, N) {
		MUL(ans, fiv[cnt[i]]);
	}
	cout << ans << "\n";
}

