LL power(LL x,LL r){
	if(r==0) return 1;
	LL half=power(x,r/2);
	LL ans=1;
	if(r&1) ans*=x;
	ans*=half;
	ans%=p;
	ans*=half;
	return ans%p;
}

LL gyaku(LL x){
	return power(x,p-2)%p;
}

LL nCr(LL n,LL r){
	LL ans=1;
	REP(i,r){
		ans*=n-i;
		ans%=p;
		ans*=gyaku(i+1);
		ans%=p;
	}
	return ans%p;
}
