void prep () {
	fac[0] = 1, ivf[0] = 1;
	fac[1] = ivf[1] = inv[1] = 1;
	for (int i = 2; i <= n; ++i) {
		fac[i] = fac[i - 1] * i % mo;
		inv[i] = mo - 1ll * mo / i * inv[mo % i] % mo;
		ivf[i] = ivf[i - 1] * inv[i] % mo;
	}
	mn = smn = make_pair(inf, 0);
}
int main (){
