		scanf("%d%d", &x, &y), co[x].push_back(y);
		if (y < mn.fi)
			smn = mn, mn = make_pair(y, x);
		else if (y < smn.fi)
			smn = make_pair(y, x);
	}
	int tot = 0;
	for (int i = 1; i <= n; ++i) {
		if (!(int)co[i].size())
			continue;
		int M = inf, C = 0;
		for (auto x : co[i])
			M = min(M, x);

		if (M + mn.fi > Y)
			continue;
		if (i == mn.se)
			for (auto x : co[i]) {
				if (x + M <= X)
					++C;
				else if (smn.se != i)
					C += (x + smn.fi <= Y);
			}
