		cin >> c[i] >> w[i];
		gg[c[i]].pb(i);
	}
	vi ver; FOR(i, 0, n) ver.pb(i);
	sort(all(ver), compare);
	int u = ver[0], v = -1;
	FOR(i, 1, n) if (c[ver[i]] != c[u]) {
		v = ver[i];
		break;
	}
	init();
	FOR(i, 0, n) {
		if (c[u] == c[i] && w[u] + w[i] <= x) {
			join(u, i);
		}
		else if (c[u] != c[i] && w[u] + w[i] <= y) {
			join(u, i);
		}
	}
	if (v != -1) {
		FOR(i, 0, n) {
			if (c[v] == c[i] && w[v] + w[i] <= x) {
				join(v, i);
			}
			else if (c[v] != c[i] && w[v] + w[i] <= y) {
				join(v, i);
			}
		}
	}
	FOR(i, 0, maxn) {
		sort(all(gg[i]), compare);
		FOR(j, 0, sz(gg[i])) {
			int u = gg[i][0];
			int v = gg[i][j];
			if (c[u] == c[v] && w[u] + w[v] <= x) {
				join(u, v);
			}
			else if (c[u] != c[v] && w[u] + w[v] <= y) {
				join(u, v);
			}
		}
	}
	FOR(i, 0, n) {
		hs[find(i)][c[i]]++;
	}
	int ans = 1;
	FOR(i, 0, n) {
		int cnt = 0;
		FORall(it, hs[i]) {
			cnt += it->se;
			ans = mult(ans, binom(it->se, cnt));
		}
	}
	cout << ans << "\n";
}

