int pw(int a, int b){
	int ret = 1;
	while (b){
		if (b & 1)
			ret = 1ll*ret*a%MOD;
		b >>= 1;
		a = 1ll*a*a%MOD;
	}
	return ret;
}

bool cmp(int u, int v){return a[u].S < a[v].S;}

void plant(int v, int b, int e, int de = 0){
	pt[v] = b;
	if (e - b == 1){
		seg[de][b] = b;
		return;
	}

	int mid = b + e >> 1;
	plant(v<<1, b, mid, de+1);
	plant(v<<1^1, mid, e, de+1);
	merge(seg[de + 1] + b, seg[de + 1] + mid, seg[de + 1] + mid, seg[de + 1] + e, seg[de] + b, cmp);
}

