				q[t++] = seg[de][pt[v]];
			}
			pt[v]++;
		}
		return;
	}
	if (r <= b || e <= l) return;

	int mid = b + e >> 1;
	go(v<<1, b, mid, l, r, rem, de+1);
	go(v<<1^1, mid, e, l, r, rem, de+1);
