    for (int i = 0; i < N; i++) {
        if (V[i].size())
            if (MIN > V[i][0]) {
                MIN2 = MIN;
                MIN = V[i][0];
                MIN_c = i;
            }
    }
    UnionFind uf(N);

    for (int i = 0; i < N; i++) {
        auto& v = V[i];
        if (v.size()) {
            if (i != MIN_c) {
                for (auto& p : v) {
                    if (p.first + MIN.first <= Y)
                        uf.unite(p.second, MIN.second);
                    else
                        break;
                }
            } else {
                for (auto& p : v) {
                    if (p.first + MIN2.first <= Y)
                        uf.unite(p.second, MIN.second);
                    else
                        break;
