int Pow(int a,int b){
	int res=1;
	for (;b;b>>=1,a=1ll*a*a%p) if (b&1) res=1ll*res*a%p;
	return res;
}

int c[N],w[N],mn[N],wei[N],fac[N],inv[N],val[N];
int X,Y,amn,n,ans,m;

int main(){
	fac[0]=1;
	For(i,1,N) fac[i]=1ll*fac[i-1]*i%p;
	inv[N-1]=Pow(fac[N-1],p-2);
	for (int i=N-1;i;i--) inv[i-1]=1ll*inv[i]*i%p;
	amn=oo;
	For(i,0,N) mn[i]=oo;
	n=IN(),X=IN(),Y=IN();
	For(i,1,n+1){
		c[i]=IN(),w[i]=IN();
		amn=min(amn,w[i]);
		mn[c[i]]=min(mn[c[i]],w[i]);
	}
	For(i,1,n+1){
