    std::sort(c[i].begin(), c[i].end());
  }
  std::sort(c.begin(), c.end(), [](const std::vector<int> &a, const std::vector<int> &b) {
    if (a.empty()) return false;
    if (b.empty()) return true;
    return a[0] < b[0];
  });
  while (c.back().empty()) c.pop_back();
  n = c.size();
  std::vector<int> ca(n), cb(n);
  int m = 0;
  for (int i = 0; i < n; ++i) {
