struct UF {
	vi t;
	UF(int n) {
		t.resize(n,-1);
	}
	int find(int a){
		return t[a]<0 ? a : t[a] = find(t[a]);
	}
	void uni(int a, int b){
		a = find(a), b = find(b);
		if(a == b) return;
		if(t[a] < t[b]) swap(a,b);
		t[b] += t[a];
		t[a] = b;
	}
};

const ll md = 1e9+7;
const int inf = 1e9+10;

ll inv(ll a, ll b){
	return a-1 ? b-b*inv(b%a,a)/a : 1;
}

