#define MOD 1000000007
long long int ppow(long long int i, long long int j){
	long long int res = 1LL;
	while (j){
		if ((j & 1LL)){
			res *= i;
			if (res >= MOD){
				res %= MOD;
			}
		}
		j >>= 1;
		i *= i;
		if (i >= MOD){
			i %= MOD;
		}
	}
	return res;
}

long long int k[MAX];
long long int rk[MAX];

pair<int, int> rng[MAX];

int pr[MAX];

vector<int> ich[MAX];

int dif_step(int cur, int col){
	if (cur == 0)return -1;
	cur--;
	if (v[cur].second == col)return cur;
	return pr[cur];
}

int upd[MAX];

int main(){
	k[0] = 1;
	for (int i = 1; i < MAX; i++){
		k[i] = k[i - 1];
		k[i] *= (long long int)(i);
		k[i] %= MOD;
		rk[i] = ppow(k[i], MOD - 2);
	}
