	uf.resize(n);
	sort(v.begin(), v.end());
	for (int i = 0; i < n; i++){
		rng[i] = make_pair(-2, -2);
	}
	for (int i = 0; i < MAX; i++){
		ich[i].push_back(-1);
	}
	memset(upd, -1, sizeof(upd));
	for (int i = 0; i < v.size(); i++){
		if (i == 0 || v[i - 1].second != v[i].second){
			pr[i] = i-1;
		}
		else{
			pr[i] = pr[i - 1];
		}
		ich[v[i].second].push_back(i);
		if (rng[v[i].second].second >= 0){
			int j = rng[v[i].second].second;
			if (v[i].second != v[j].second){
				if (v[i].first + v[j].first <= y){
					uf.merge(i, j);
				}
			}
			else{
				if (v[i].first + v[j].first <= x){
					uf.merge(i, j);
				}
			}
		}
		int cur = i;
		while(1){
			cur = dif_step(cur, v[i].second);
			if (cur < 0)break;
			int j = cur;
			if (v[i].first + v[j].first <= y){
				uf.merge(i, j);
			}
			if (upd[j] == -1){
				upd[j] = v[i].second;
			}
			else{

				break;
			}
		}
		int c = v[i].second;
		if (rng[c].second == i - 1){
			rng[c].second = i;
		}
		else{
			rng[c].first = rng[c].second = i;
		}
	}
	for (int i = 0; i < v.size(); i++){
		val[uf.root(i)][v[i].second]++;
		root.push_back(uf.root(i));
	}
	sort(root.begin(), root.end());
	root.erase(unique(root.begin(), root.end()), root.end());
	long long int ans = 1;
	for (int i = 0; i < root.size(); i++){
		long long int up = k[uf.size[root[i]]];
		int num = root[i];
		for (auto it = val[num].begin(); it != val[num].end(); it++){
			up *= rk[(*it).second];
			up %= MOD;
		}
		ans *= up;
		ans %= MOD;
	}
	printf("%lld\n", ans);
	return 0;
}

