vector <int> g[N];
bool seen[N] = {0};

void add_edges(int i, int n, ll x, ll y);
ll bfs(int cur, ll ans);
ll fastModExp(ll x, ll e);

int main()
{
	int n; ll x, y;
	cin >> n >> x >> y;
	for (int i = 1; i <= n; ++i)
		cin >> a[i].second >> a[i].first;

	sort(a + 1, a + 1 + n);
	add_edges(1, n, x, y);
	for (int i = 2; i <= n; ++i)
	{
		if (a[i].second != a[1].second)
		{
			add_edges(i, n, x, y);
			break;
		}
	}

	fact[0] = factInv[0] = 1;
	for (int i = 1; i < N; ++i)
	{
		fact[i] = (i * fact[i - 1]) % mod;
		factInv[i] = fastModExp(fact[i], mod - 2);
	}

	ll ans = 1;
	for (int i = 1; i <= n; ++i)
		if (!seen[i])
			ans = bfs(i, ans);

	cout << ans << endl;
}

void add_edges(int i, int n, ll x, ll y)
{
	for (int j = 1; j <= n; ++j)
	{
		if (a[i].second == a[j].second)
		{
			if (a[i].first + a[j].first <= x)
			{
				g[i].pb(j);
				g[j].pb(i);
			}
		}

		else if (a[i].first + a[j].first <= y)
		{
			g[i].pb(j);
			g[j].pb(i);
		}
	}
}

ll bfs(int cur, ll ans)
{
	seen[cur] = true;
	int ctr = 0;
	queue <int> q;
	map <int, int> m;
	q.push(cur);
	while (!q.empty())
	{
		int x = q.front();
		q.pop();
		++m[a[x].second];
		++ctr;
		for (auto &i : g[x])
		{
			if (!seen[i])
			{
				q.push(i);
				seen[i] = true;
			}
		}
	}

	ans = (ans * fact[ctr]) % mod;
	for (auto &i : m)
		ans = (ans * factInv[i.second]) % mod;

	return ans;
}

ll fastModExp(ll x, ll e)
{
	ll res = 1;
	while (e)
	{
		if (e % 2)
			res = (res * x) % mod;

		e /= 2;
		x = (x * x) % mod;
	}

	return res;
}

