        //rep(i, p) res = (res * ((n - i) % mod)) % mod;
        Rep(i, p+1) res = (res * mod_inverse(i, mod)) % mod;
    }
    //Rep(i, m+1) res = (res * mod_inverse(i, mod)) % mod;
    return res;
}

