{
	inv[0]=inv[1]=1; for (int i=2;i<=n;++i) inv[i]=1ll*(Mod-Mod/i)*inv[Mod%i]%Mod;
	fact[0]=fact[1]=1; for (int i=2;i<=n;++i) fact[i]=1ll*fact[i-1]*i%Mod,inv[i]=1ll*inv[i-1]*inv[i]%Mod;

	for (int i=1;i<=n;++i) Mn[i]=Inf;
