#include <bits/stdc++.h>

using namespace std;

const int N = 500017;
const int MOD = 1000 * 1000 * 1000 + 7;

int n, X, Y;
int c[N], w[N], F[N];
vector<int> cols[N];
int P[N], W[N];

bool read() {
    if (!(cin >> n >> X >> Y))
        return false;

    for (int i = 0; i < n; ++i) {
        cin >> c[i] >> w[i];
        --c[i];
    }

    return true;
}

int getp(int u) { return u == P[u] ? u : P[u] = getp(P[u]); }

bool join(int u, int v) {
    if ((u = getp(u)) == (v = getp(v)))
        return false;

    if (W[u] < W[v])
        swap(u, v);

    P[v] = u;
    W[u] += W[v];
    return true;
}

long long binpow(long long a, int b, long long mod) {
    long long res = 1;

    for (; b > 0; b /= 2, a = a * a % mod)
        if (b & 1)
            res = res * a % mod;

    return res;
}

long long rev(long long a, long long mod) { return binpow(a, mod - 2, mod); }

void solve() {
    long long ans = 1;
    int m1 = min_element(w, w + n) - w;
    int m2 = -1;

    for (int i = 0; i < n; ++i) {
        P[i] = i;
        W[i] = 1;
        cols[c[i]].push_back(i);

        if (c[i] != c[m1] && (m2 == -1 || w[i] < w[m2]))
            m2 = i;
    }

    F[0] = 1;

    for (int i = 1; i <= n; ++i)
        F[i] = (long long) i * F[i - 1] % MOD;

    for (int col = 0; col < n; ++col) {
        if (cols[col].empty())
            continue;

        int m = cols[col][0];

        for (auto i : cols[col])
            if (w[i] < w[m])
                m = i;

        int mn = c[m1] != col ? m1 : m2;
        int cnt = 0;

        for (auto i : cols[col]) {
            int f = 0;

            if (w[i] + w[m] <= X)
                join(i, m), f = 1;

            if (mn != -1 && w[i] + w[mn] <= Y)
                join(i, mn), f = 1;

            cnt += f;
        }

        ans *= rev(F[cnt], MOD);
        ans %= MOD;
    }

    for (int i = 0; i < n; ++i)
        if (i == P[i])
            ans = ans * F[W[i]] % MOD;

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

