using namespace std;

typedef long long int64;
const int mod = 1e9 + 7;

inline int64 modPow(int64 x, int64 n)
{
  if(n == 0) return (1);
  int64 ret = modPow(x, n / 2);
  (ret *= ret) %= mod;
  if(n & 1) (ret *= x) %= mod;
  return (ret);
}

inline int64 modInv(int64 a)
{
  return (modPow(a, mod - 2));
}

int64 fact[202020], rfact[202020];

inline int64 modCombination(int p, int q)
{
  if(fact[0] == 0) {
    fact[0] = rfact[0] = 1;
    for(int i = 1; i < 102020; i++) {
      fact[i] = fact[i - 1] * i % mod;
      rfact[i] = modInv(fact[i]);
    }
  }
  if(q < 0 || p < q) return (0);
  return (fact[p] * rfact[q] % mod * rfact[p - q] % mod);
}

struct UnionFind
{
  vector< int > data;

  UnionFind(int sz)
  {
    data.assign(sz, -1);
  }

  bool unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k)
  {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k)
  {
    return (-data[find(k)]);
  }
};

int main()
{
  int N, X, Y, C[100000], W[100000];

  cin >> N >> X >> Y;
  for(int i = 0; i < N; i++) {
    cin >> C[i] >> W[i];
    --C[i];
  }


  UnionFind tree(N);
  for(int i = 0; i < N; i++) {
    for(int j = 0; j < i; j++) {
      if(C[i] == C[j]) {
        if(W[i] + W[j] <= X) tree.unite(i, j);
      } else {
        if(W[i] + W[j] <= Y) tree.unite(i, j);
      }
    }
  }

  modCombination(0, 0);

  map< int, int > vs[100000];
  for(int i = 0; i < N; i++) {
    ++vs[tree.find(i)][C[i]];
  }

  int64 sz = 1;
  for(int i = 0; i < N; i++) {
    if(tree.find(i) == i) {
      int all = 0;
      for(auto &p : vs[i]) (all += p.second) %= mod;
      int64 ret = fact[all];
      for(auto &p : vs[i]) (ret *= rfact[p.second]) %= mod;
      (sz *= ret) %= mod;
    }
  }

  cout << sz << endl;

}

