int dfs(int u, unordered_map<int, int> &col_cnt) {
    if (vis[u]) return 0;
    vis[u] = true;
    int ans = 1;
    col_cnt[col[u]]++;
    for (int v : adj[u]) {
        ans += dfs(v, col_cnt);
    }
    return ans;
}

int fact(int x) {
    ll ans = 1;
    for (int i = 1; i <= x; i++) {
        ans = (ans * i) % MOD;
    }
    return ans;
}

int pow(int b, int e) {
    if (e == 0) return 1;
    ll res = pow(b, e >> 1);
    res = (res * res) % MOD;
    if (e & 1) res = (res * b) % MOD;
    return res;
}

int inv(int x) {
    return pow(x, MOD - 2);
}

int permute(int cnt, unordered_map<int, int> &col_cnt) {
    ll ans = fact(cnt);
    for (pair<int, int> c : col_cnt) {
        cnt -= c.second;
        if (c.second > 0) {
            ans = (ans * inv(fact(c.second))) % MOD;
        }
    }
    if (cnt != 0) while (1);
    return ans;
}

