using namespace std;

typedef long long int64;
const int mod = 1e9 + 7;

inline int64 modPow(int64 x, int64 n)
{
  if(n == 0) return (1);
  int64 ret = modPow(x, n / 2);
  (ret *= ret) %= mod;
  if(n & 1) (ret *= x) %= mod;
  return (ret);
}

inline int64 modInv(int64 a)
{
  return (modPow(a, mod - 2));
}

int64 fact[202020], rfact[202020];

inline int64 modCombination(int p, int q)
{
  if(fact[0] == 0) {
    fact[0] = rfact[0] = 1;
    for(int i = 1; i < 102020; i++) {
      fact[i] = fact[i - 1] * i % mod;
      rfact[i] = modInv(fact[i]);
    }
  }
  if(q < 0 || p < q) return (0);
  return (fact[p] * rfact[q] % mod * rfact[p - q] % mod);
}

struct UnionFind
{
  vector< int > data;

  UnionFind(int sz)
  {
    data.assign(sz, -1);
  }

  bool unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k)
  {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k)
  {
    return (-data[find(k)]);
  }
};

int main()
{
  int N, X, Y, C[200000], W[200000];
  vector< pair< int, int > > vs[200000];

  cin >> N >> X >> Y;
  for(int i = 0; i < N; i++) {
    cin >> C[i] >> W[i];
    --C[i];
    vs[C[i]].emplace_back(W[i], i);
  }


  UnionFind tree(N);
  vector< pair< int, int > > vv;
  for(int i = 0; i < N; i++) {
    if(vs[i].empty()) continue;
    sort(begin(vs[i]), end(vs[i]));
    for(int j = 1; j < vs[i].size(); j++) {
      if(vs[i][0].first + vs[i][j].first <= X) {
        tree.unite(vs[i][0].second, vs[i][j].second);
      }
    }
    vv.emplace_back(vs[i][0]);
  }

  if(vv.size() == 1) {
    cout << 1 << endl;
    return (0);
  }

  sort(begin(vv), end(vv));
  for(int i = 0; i < N; i++) {
    if(C[vv[0].second] != C[i]) {
      if(vv[0].first + W[i] <= Y) {
        tree.unite(vv[0].second, i);
      }
    } else {
      if(vv[1].first + W[i] <= Y) {
        tree.unite(vv[1].second, i);
      }
    }
  }

  modCombination(0, 0);

  map< int, int > mp[200000];
  for(int i = 0; i < N; i++) {
    ++mp[tree.find(i)][C[i]];
  }

  int64 sz = 1;
  for(int i = 0; i < N; i++) {
    if(tree.find(i) == i) {
      int all = 0;
      for(auto &p : mp[i]) (all += p.second) %= mod;
      int64 ret = fact[all];
      for(auto &p : mp[i]) (ret *= rfact[p.second]) %= mod;
      (sz *= ret) %= mod;
    }
  }
  cout << sz << endl;
}

