long long power(long long a, long long b)
{
	if (b == 0)
	{
		return 1;
	}
	long long ans = power(a, b / 2);
	ans = ans % mod;
	ans = ans * ans;
	ans = ans % mod;
	if (b % 2 == 1)
	{
		ans = ans * a;
		ans = ans % mod;
	}
	return ans;
}

long long choose(long long a, long long b) 
{
	long long t = fac[b];
	t = (t * power(fac[a], mod - 2)) % mod;
	t = (t * power(fac[b - a], mod - 2)) % mod;
	return t;
}

