const int MAX = (2e5)+1;
const long long MOD = (1e9)+7;

int n, x, y, sz, c[MAX], w[MAX];
bool mark[MAX];
long long ans = 1, fact[MAX];
vector<int> par, el[MAX];
vector<vector<pair<int,int> > > same;

long long modPow(long long b, long long e) {
	long long ret = 1;
	while(e) {
		if(e & 1) ret = (ret*b)%MOD;
		b = (b*b)%MOD;
		e >>= 1;
	}
	return ret;
}

int root(int v) { return (par[v] == v ? v : par[v] = root(par[v])); }

void merge(int u, int v) {
	if((u = root(u)) == (v = root(v))) return;
	if(el[u].size() < el[v].size()) swap(u, v);
	el[u].insert(el[u].end(), el[v].begin(), el[v].end());
	el[v].clear();
	par[v] = u;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n >> x >> y;
	fact[0] = 1;
	for(int i = 1; i <= n; i++) fact[i] = (fact[i-1]*i)%MOD;
	par.resize(n);
	same.resize(n);
	iota(par.begin(), par.end(), 0);
	for(int i = 0; i < n; i++) {
		cin >> c[i] >> w[i];
		c[i]--;
		sz += !mark[c[i]];
		mark[c[i]] = true;
		same[c[i]].emplace_back(w[i], i);
		el[i].push_back(i);
	}
	sort(same.begin(), same.end(), [] (auto& a, auto& b) {
		if(a.empty()) return false;
		if(b.empty()) return true;
		return a[0].first < b[0].first;
	});
	for(auto& v: same) sort(v.begin(), v.end());
	same.resize(sz);
	for(int k = 0; k < sz; k++) {
		if(k) for(int i = 1; i < same[k].size(); i++) {
			if(same[k][i].first+same[k][0].first <= x || same[k][i].first+same[0][0].first <= y)
				merge(same[k][i].second, same[k][0].second);
		} else if(sz > 1) {
			for(int i = 1; i < same[k].size(); i++) {
				if(same[k][i].first+same[1][0].first <= y)
					merge(same[k][i].second, same[k][0].second);
			}
		}
	}
	for(int k = 1; k < sz; k++) if(same[k][0].first+same[0][0].first <= y) {
		merge(same[k][0].second, same[0][0].second);
	}
	for(int rt = 0; rt < n; rt++) if(!el[rt].empty()) {
		map<int,int> f;
		long long res = fact[el[rt].size()];
		for(int v: el[rt]) f[c[v]]++;
		for(auto p: f) res = (res*modPow(fact[p.second], MOD-2))%MOD;
		ans = (ans*res)%MOD;
	}
	cout << ans;
}

