void AddEdge(int u,int v){
    lnk[u].push_back(v);
    lnk[v].push_back(u);
}
void DFS(int u){
    tot++;
    cnt[col[u]]++;vis[u]=true;
    for(int i=0;i<(int)lnk[u].size();i++){
        int v=lnk[u][i];
        if(vis[v]) continue;
        DFS(v);
    }
}
int QPow(int A,int B){
    int res=1;
    while(B){
        if(B&1) res=int(1ll*res*A%MOD);
        A=int(1ll*A*A%MOD);
        B>>=1;
    }
    return res;
}
int EC(int A,int B){return int(1ll*fac[B]*inv[A]%MOD*inv[B-A]%MOD);}
int main(){
    scanf("%d%d%d",&n,&X,&Y);
    fac[0]=1;for(int i=1;i<=n;i++) fac[i]=int(1ll*fac[i-1]*i%MOD);
    inv[n]=QPow(fac[n],MOD-2);for(int i=n-1;i>=0;i--) inv[i]=int(1ll*inv[i+1]*(i+1)%MOD);
    for(int i=1;i<=n;i++) cmin[i]=0;
    val[0]=MOD;col[0]=-1;
