        scanf("%d%d",&col[i],&val[i]);
        if(val[cmin[col[i]]]>val[i]) cmin[col[i]]=i;
        if(val[mn1]>val[i]){
            if(col[mn1]!=col[mn2]) mn2=mn1;
            mn1=i;
        }
        else if(val[mn2]>val[i] && col[mn1]!=col[i]) mn2=i;
    }
    for(int i=1;i<=n;i++)
        if(i!=cmin[col[i]] && val[i]+val[cmin[col[i]]]<=X)
            AddEdge(cmin[col[i]],i);
    if(val[mn1]+val[mn2]<=Y) AddEdge(mn1,mn2);
    for(int i=1;i<=n;i++){
        if(col[i]==col[mn1]){
            if(val[i]+val[mn2]<=Y)
                AddEdge(i,mn2);
        }
        else{
            if(val[i]+val[mn1]<=Y)
                AddEdge(i,mn1);
        }
    }
    DFS(mn1);
    int ans=1;
    for(int i=1;i<=n;i++){
        ans=int(1ll*ans*EC(cnt[i],tot)%MOD);
        tot-=cnt[i];
    }
    printf("%d\n",ans);
    return 0;
}

