void calcnr() {
int i;
wm1 = wm2 = 1000000001;

    for(i = 1; i <= n; ++i) {
        if(w[i] + wmin[c[i]] <= x)
            w[i] = wmin[c[i]];
    }

    for(i = 1; i < N; ++i) if(wmin[i]) {
        if(wmin[i] < wm1) {
           wm2 = wm1;
           wm1 = wmin[i];
        }
        else
            wm2 = min(wm2, wmin[i]);
    }


    for(i = 1; i <= n; ++i) {
        int wm = wm1;
        if(wm1 == wmin[c[i]])
            wm = wm2;

        if(w[i] + wm <= y) {
            nr[c[i]]++;
        }
    }
}

int fact[N], inv[N];

int comb(int n, int k) {
    int r = (fact[n] * inv[n - k]) % MOD;
    r = (1LL * r * inv[k]) % MOD;

    return r;
}

int po(int el, int p) {
    int r = 1;

    while(p) {
        if(p & 1)
            r = (1LL * r * el) % MOD;
        el = (1LL * el * el) % MOD;
        p /= 2;
    }

    return r;
}

int invmod(int el) {
    return po(el, MOD - 2);
}

void pre() {
    int i;

    //cout << (1LL * 6 * invmod(6)) % MOD << "\n";

    fact[0] = 1;
    for(i = 1; i < N; ++i)
        fact[i] = (1LL * fact[i - 1] * i) % MOD;

    for(i = 0; i < N; ++i)
        inv[i] = invmod(fact[i]);
}

void calcrez() {
    pre();int i;

    int rez = 1, st = 0;

    for(i = 1; i < N; ++i) if(nr[i]) {
        st += nr[i];
        rez = (1LL * rez * comb(st, nr[i])) % MOD;
    }

    cout << rez;
}

