		return a[0].first < b[0].first;
	});
	for(int i = n-1; i >= 0; i--) if(a[i].empty()) a.pop_back(); 
	for(int k = 0; k < a.size(); k++) for(int i = 1; i < a[k].size(); i++) {
		if(a[k][i].first+a[k][0].first <= x || (k && a[k][i].first+a[0][0].first <= y)
				|| (!k && a.size() > 1 && a[k][i].first+a[1][0].first <= y)) merge(a[k][i].second, a[k][0].second);
	}
	for(int k = 1; k < a.size(); k++) if(a[k][0].first+a[0][0].first <= y) merge(a[k][0].second, a[0][0].second);
	for(int rt = 0; rt < n; rt++) if(!el[rt].empty()) {
		map<int,int> f;
