long long fast_pow(long long a,long long b) {
    long long ans=1,base=a;
    while(b) {
        if(b&1) ans=(ans*base)%mod;
        base=(base*base)%mod, b>>=1;
    }
    return ans;
}

inline void Prepare() {
    C1[0]=1;
    for(int i=1; i<=n; i++) C1[i]=(C1[i-1]*i)%mod, min[i]=inf;
    C2[n]=fast_pow(C1[n],mod-2);
    for(int i=n; i>=1; i--)C2[i-1]=(i*C2[i])%mod;
}

void dfs(int x) {
    vis[x]=true;
    for(int i=head[x]; i; i=edge[i].nex) if(!vis[edge[i].y]) dfs(edge[i].y);
}

long long C(long long n,long long k){
    return(((C1[n]*C2[n-k])%mod)*C2[k])%mod;
}

