ll bp(ll a, ll p) {
	ll r = 1;
	while(p) {
		if(p&1) r = r*a%mod;
		a = a*a%mod, p >>= 1;
	}
	return r;
}

struct dsu {
	vi e, mn;
	vector<map<int, int>> cnt;
	dsu(int n = 0) : e(n, -1), cnt(n), mn(n) {}
	int par(int i) {
		return e[i] > 0 ? e[i] = par(e[i]) : i;
	}
	void unite(int i, int j) {
		i = par(i), j = par(j);
		if(i == j) return;
		if(e[i] > e[j]) swap(i, j);
		e[i] += e[j], e[j] = i;
		mn[i] = min(mn[i], mn[j]);
		for(auto &x : cnt[j]) cnt[i][x.first]+=x.second;
	}
	ll eval(int i) {
		if(par(i) != i) return 1;
		ll res = 1;
		for(int f = 1; f <= -e[i]; f++) res = res*f%mod;
		for(auto t : cnt[i]) {
			ll q = 1;
			for(int f = 1; f <= t.second; f++) q = q*f%mod;
			res = res*bp(q, mod-2)%mod;
		}
		return res;
	}
};
