		if(dif[i]) able[i] = true;
		else if(same[i]){
			if(dif[vec[c[i]][0].second]) able[i] = true;
		}
	}

	llint sum = 0;
	for(int i = 1; i <= N; i++){
		if(able[i]) cnt[c[i]]++, sum++;
	}

	llint ans = fact[sum];
	for(int i = 1; i <= N; i++){
		ans *= fact_inv[cnt[i]];
		ans %= mod;
	}
	cout << ans << endl;

	return 0;
}

