		return fa[x]?fa[x]=find_rt(fa[x]):x;
	}
	inline void link(int x,int y){
		//printf("linked: %d %d\n",x,y);
		x=find_rt(x),y=find_rt(y);
		if(x!=y) fa[x]=y;
	}
}

int solve(const int x){
	static int buk[N];
	int res=fac[size[x]];
	for(int i=0; i<size[x]; ++i){
		++buk[col[list[x][i]]];
	}
	for(int i=0; i<size[x]; ++i){
		if(!buk[col[list[x][i]]]) continue;
		res=(lint)res*ifac[buk[col[list[x][i]]]]%mod;
		buk[col[list[x][i]]]=0;
	}
	return res;
}

