			lpos[col[i]]=i;
		}
	}
	for(int i=1; i<=n; ++i){
		if(i!=lpos[col[i]]&&wgt[i]+wgt[lpos[col[i]]]<=lim1){
			U::link(i,lpos[col[i]]);
		}
	}
	for(int i=1; i<=n; ++i){
		if(!lpos[i]) continue;
		int tmp=lpos[i];
		if(wgt[npos1]>wgt[tmp]) std::swap(npos1,tmp);
		if(wgt[npos2]>wgt[tmp]) std::swap(npos2,tmp);
	}
	assert(npos1);
	for(int i=1; i<=n; ++i){
		if(npos1&&col[i]!=col[npos1]&&wgt[i]+wgt[npos1]<=lim2){
			U::link(i,npos1);
