	}
	for(int i=1; i<=n; ++i){
		++size[U::find_rt(i)];
	}
	for(int i=1; i<=n; ++i){
		if(U::find_rt(i)==i){
			list[i]=new int[size[i]];
			size[i]=0;
		}
	}
	for(int i=1; i<=n; ++i){
		int rt=U::find_rt(i);
