using namespace std;

typedef long long ll;
const ll MAXN=2e5+5;
const ll MOD=1e9+7;
const ll INF=0x7f7f7f7f;

ll n,X,Y,ans;
ll a[MAXN],b[MAXN],vis[MAXN],cnt[MAXN];
ll mine[MAXN],pos[MAXN];
vector<ll> E[MAXN];

void dfs(ll u){
    vis[u]=1;
    for(ll i=0;i<(ll)E[u].size();i++){
        ll v=E[u][i];
        if(vis[v]) continue;
        dfs(v);
    }
}

ll fac[MAXN],inv[MAXN];
void Init(){
    fac[0]=1;
    for(ll i=1;i<MAXN;i++) fac[i]=fac[i-1]*i%MOD;
    inv[1]=1;
    for(ll i=2;i<MAXN;i++) inv[i]=1ll*(MOD-MOD/i)*inv[MOD%i]%MOD;
    inv[0]=1;
    for(ll i=1;i<MAXN;i++) inv[i]=inv[i]*inv[i-1]%MOD;
}

ll C(ll x,ll y){
    if(x<y) return 0;
    return 1ll*(fac[x]*inv[y]%MOD)*inv[x-y]%MOD;
}

void addedge(ll u,ll v){
    E[u].push_back(v);
    E[v].push_back(u);
}

int main(){
    Init();
    memset(mine,0x3f,sizeof mine);
    scanf("%lld%lld%lld",&n,&X,&Y);
    for(ll i=1;i<=n;i++){
        scanf("%lld%lld",&a[i],&b[i]);
        if(mine[a[i]]>b[i]){
            mine[a[i]]=b[i];
            pos[a[i]]=i;
        }
    }
    ll min1,min2,p1,p2,c1,c2;
    min1=min2=INF;
    for(ll i=1;i<=n;i++){
        if(b[i]<min1){
            min1=b[i];
            p1=i; c1=a[i];
        }
        else if(b[i]<min2){
            min2=b[i];
            p2=i; c2=a[i];
        }
        if(pos[a[i]]!=i&&b[i]+mine[a[i]]<=X) addedge(i,pos[a[i]]);
    }
    for(ll i=1;i<=n;i++){
        if(p1==i) continue;
        if(a[i]!=c1&&b[i]+min1<=Y)
            addedge(i,p1);
        if(min2!=INF&&a[i]!=c2&&b[i]+min2<=Y)
            addedge(i,p2);
    }
    dfs(p1);
    ll tot=0,ans=1;
    for(ll i=1;i<=n;i++)
        if(vis[i])
            cnt[a[i]]++,tot++;
    for(ll i=1;i<=n;i++){
        if(!cnt[i]) continue;
        ans=1ll*ans*C(tot,cnt[i])%MOD;
        tot-=cnt[i];
    }
    printf("%lld",ans);

    fclose(stdin);
    fclose(stdout);
}

