LL bp(LL a, int n)
{
	LL res = 1;
	while (n)
	{
		if (n & 1) res = (res * a) % MOD;

		a = (a * a) % MOD;
		n >>= 1;
	}

	return res;
}

LL inv(LL a)
{
	return bp(a, MOD - 2);
}

struct DSU
{
	int P[MAX];
	multiset<int> S[MAX];
	void init()
	{
		FOR(i, 0, n)
		{
			P[i] = i;
			S[i].insert(A[i].second);
		}
	}

	int getParent(int v)
	{
		if (P[v] == v) return v;
		return P[v] = getParent(P[v]);
	}

	void unionSet(int a, int b)
	{
		a = getParent(a);
		b = getParent(b);

		if (a == b) return;
		if (SZ(S[a]) < SZ(S[b])) swap(a, b);

		for (auto i = S[b].begin(); i != S[b].end(); i++)
		{
			S[a].insert(*i);
		}

		P[b] = a;
	}

	LL calc()
	{
		LL ans = 1;
		FOR(i, 0, n)
		{
			if (P[i] != i) continue;

			LL all = SZ(S[i]);
			LL res = F[all];
			mapp.clear();
			for (auto it = S[i].begin(); it != S[i].end(); it++)
			{
				mapp[*it]++;
			}

			for (auto it = mapp.begin(); it != mapp.end(); it++)
			{
				res = (res * FR[it->second]) % MOD;
			}

			ans = (ans * res) % MOD;
		}

		return ans;
	}
} D;

