void solve2()
{
	rep(i,1,n) t.ins((data){dat[i].w,i});
	int i=1;
	while(i<=n)
	{
		int p=i;
		while(p+1<=n && dat[p+1].c==dat[i].c) ++p;
		rep(j,i,p)
			t.erase((data){dat[j].w,j});
		rep(j,i,p) if(dat[j].w<Y) t.modify(Y-dat[j].w,j);
		rep(j,i,p) t.ins((data){dat[j].w,j});
		i=p+1;
	}
	t.dfs();
}

