ll MOD = 1E9 + 7;

ll F[200010];
ll I[200010];

ll power(ll a, ll b) {
	ll res = 1;
	while (b > 0) {
		if (b % 2) {
			res *= a;
			res %= MOD;
		}
		b /= 2;
		a *= a;
		a %= MOD;
	}
	return res;
}

ll nchoosek(int a, int b) {
	ll base = I[a - b] * I[b];
	base %= MOD;
	base *= F[a];
	base %= MOD;
	return base;
}

int main() {
    ios::sync_with_stdio(false);
    ll N, X, Y;
    cin >> N >> X >> Y;
    F[0] = 1;
    for (int i = 1;i <= 200000;i++) {
    	F[i] = F[i - 1] * i;
    	F[i] %= MOD;
    }
    I[200000] = power(F[200000], MOD - 2);
    for (int i = 200000 - 1;i >= 0;i--) {
    	I[i] = I[i + 1] * (i + 1);
    	I[i] %= MOD;
    }
    unordered_map<int, vector<int> > CC;
    int m = 1E9;
    for (int i = 0;i < N;i++) {
    	int c, w;
    	cin >> c >> w;
    	CC[c].push_back(w);
    	m = min(m, w);
    }
    ll tol = 0;
    unordered_map<int, vector<int> >::iterator it;
    vector<int> xy;
    for (it = CC.begin();it != CC.end();++it) {
    	int c = it->first;
    	vector<int> q = it->second;
    	sort(q.begin(), q.end());
    	int r = 0;
    	if (q[0] <= Y - m) {
    		// Mutable.
    		r++;
    		for (int i = 1;i < q.size();i++) {
    			if (q[i] <= X - q[0] || q[i] <= Y - m) r++;
    		}
    		tol += r;
    		xy.push_back(r);
    	}
    }
    ll sol = 1;
    for (int i = 0;i < xy.size();i++) {
    	sol *= nchoosek(tol, xy[i]);
    	sol %= MOD;
    	tol -= xy[i];
    }
    cout << sol << endl;
    return 0;
}

