long long binpow(long long a, long long b)
{
    if(b == 0)
        return 1;
    if(b % 2 == 1)
        return a * binpow(a, b - 1) % mod;
    else
    {
        long long h = binpow(a, b / 2);
        return h * h % mod;
    }
}

