int find(int x) {return lab[x] < 0? x: lab[x] = find(lab[x]);}
void uni(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return;
    if(lab[x] > lab[y]) swap(x, y);
    lab[x] += lab[y], lab[y] = x;
    for(auto p: node[y]) node[x][p.fi] += p.se;
}
void upd(int id) {
