int N, X, Y;
int C[200000];
int W[200000];
int mn[200000];
int mni[200000];
int main() {
	cin >> N >> X >> Y;
	REP(i, 0, N) {
		cin >> C[i] >> W[i];
		--C[i];
	}

	Fill(mn, INF);
	REP(i, 0, N) {
		int c = C[i];
		if (W[i] < mn[c]) {
			mn[c] = W[i];
			mni[c] = i;
		}
	}

	UnionFindTree uf(N);
	REP(i, 0, N) {
		int c = C[i];
		int j = mni[c];
		if (W[i] + W[j] > X) continue;
		uf.unite(i, j);
	}

	vector<int> cs;
	REP(i, 0, N) {
		cs.push_back(i);
	}

	sort(cs.begin(), cs.end(), [](int i, int j) {
		return mn[i] < mn[j];
	});

	REP(k, 0, min(2, N)) {
		int c = cs[k];
		if (mn[c] == INF) continue;
		int j = mni[c];
		REP(i, 0, N) {
			if (C[i] == c) continue;
			if (W[i] + W[j] > Y) continue;
			uf.unite(i, j);
		}
	}

	MInt ans = 1;
	MInt den = 1;
	for (auto&& v : uf.toGroups()) {
		ans *= MInt::fact(v.size());

		map<int, int> hist;
		for (int i : v) {
			++hist[C[i]];
		}

		for (auto&& p : hist) {
			den *= MInt::fact(p.second);
		}
	}
	cout << ans / den << endl;
	return 0;
}

