int64_t modpow(int64_t base,int64_t exp){
  int64_t ac=1;
  for(;exp>0;exp>>=1){
    if(exp&1) ac=ac*base%MOD;
    base=base*base%MOD;
  }
  return ac;
}

int find(int a){
  return (a==uf[a])?a:(uf[a]=find(uf[a]));
}

void unite(int a,int b){
  uf[find(a)]=find(b);
}

int main(){
  for(int i=1;i<=200000;i++){
    fact[i]=fact[i-1]*i%MOD;
  }
