    if(ws[i]<ws[mini]){
      mini=i;
    }
    of[cs[i]].push_back(i);
  }
  for(auto& pair:of){
    std::sort(pair.second.begin(),pair.second.end(),[](int i,int j){return ws[i]<ws[j];});
    int s=pair.second[0];
    for(int i:pair.second){
