	min2i=i;
      }
    }
  }
  if(min2i!=-1){
    for(int i=0;i<N;i++){
      if(cs[i]!=cs[min2i]&&ws[i]+ws[min2i]<=Y){
	unite(i,min2i);
      }
    }
  }
  for(auto pair:of){
    int s=pair.second[0];
    for(int i:pair.second){
      if(find(s)==find(i)){
	same[s]++;
      }
    }
  }
  int64_t num=1,den=1;
