LL fact[K], revfact[K];

LL bigmod(LL a, LL p) {
	if (!p) return 1;

	LL t = bigmod(a, p >> 1);
	t = t * t % M;

	if (p & 1) t = t * a % M;

	return t;	
}

LL C(LL n, LL k) {
	return fact[n] * revfact[k] % M * revfact[n - k] % M;	
}

vector<int> cols;
vector<int> cnts;

int main(){
	scanf("%d%d%d", &n, &x, &y);

	fact[0] = 1;
	FOE(i, 1, n * 3) fact[i] = (fact[i - 1] * i) % M;
	FOE(i, 0, n * 3) revfact[i] = bigmod(fact[i], M - 2);

	FOE(i, 1, n) {
		int c, w; scanf("%d%d", &c, &w);
