		if (val[pos] > 0) {
			int len = val[pos] - 1;
			int color = col[pos];	

			if (!ext[color]) {
				FOE(i, 0, len) {
					int pp = co[color][i].second;

					active[pp] = 1;
				}
				ext[color] = 1;
			}
		}
	}

	LL ret = 1;


	FOE(i, 1, n) {
		if (active[i]) cols.pb(col[i]);
//		if (active[i]) printf("POS %d ACTIVE\n", i);
	}

	if (cols.size()) {
		sort(cols.begin(), cols.end());

		int last = -1, cnt = 0;
