//x! O(x)
vll mod_factorial(ll x, ll mod) {
	if (x < 0) return{};
	else {
		vll ret((int)x + 1);
		ret[0] = 1;
		Loop1(i, (int)x) ret[i] = ret[i - 1] * i % mod;
		return ret;
	}
}

//x^y O(log y)
ll mod_pow(ll x, ll y, ll mod) {
	if (y == 1) return x;
	else {
		ll ans = mod_pow(x, y / 2, mod);
		ans = ans * ans % mod;
		if (y % 2 == 1) ans = ans * x % mod;
		return ans;
	}
}

//無向グラフの隣接リストを受け取って連結成分の一覧を返す
vvi cc(vvi nodes) {
	vvi ret;
	vector<bool> done(nodes.size(), false);
	Loop(i, nodes.size()) {
		if (done[i]) continue;
		queue<int> que;
		ret.push_back({});
		que.push(i);
		while (que.size()) {
			int a = que.front(); que.pop();
			if (done[a]) continue;
			ret.back().push_back(a);
			done[a] = true;
			Loop(j, nodes[a].size()) {
				int b = nodes[a][j];
				if (done[b]) continue;
				else {
					que.push(b);
				}
			}
		}
	}
	return ret;
}

int main() {
	ll n, x, y;
	cin >> n >> x >> y;
	vll c(n), w(n);
	Loop(i, n) cin >> c[i] >> w[i];

	map<ll, ll> mp1; //色→最小重量をもつindex
	ll min_index = 0; //全てのボールの最小重量をもつindex
	Loop(i, n) {
		if (mp1.find(c[i]) == mp1.end()) mp1[c[i]] = i;
		else if (w[mp1[c[i]]] > w[i]) mp1[c[i]] = i;
		if (w[min_index] > w[i]) min_index = i;
	}
	//可換indexどうしでエッジを張る
	vvi nodes(n);
	//操作1
	Loop(i, n) {
		if (w[i] + w[mp1[c[i]]] <= x) {
			int t = mp1[c[i]];
			if (i != t) {
				nodes[i].push_back(t);
				nodes[t].push_back(i);
			}
		}
	}
	//操作2
	Loop(i, n) {
		if (i == min_index) continue;
		if (w[i] + w[min_index] <= y) {
			nodes[i].push_back(min_index);
			nodes[min_index].push_back(i);
		}
	}
	//計算の準備
	vvi dat = cc(nodes);
	ll mod = 1e9 + 7;
	vll fact = mod_factorial(n, mod);
	vll invfact(n + 1);
	Loop(i, n + 1) {
		invfact[i] = mod_pow(fact[i], mod - 2, mod);
	}
	ll ans = 1;
	Loop(i, dat.size()) {
		map<ll, ll> mp2;
		Loop(j, dat[i].size()) {
			int index = dat[i][j];
			mp2[c[index]]++;
		}
		ll p = fact[dat[i].size()];
		for (auto itr = mp2.begin(); itr != mp2.end(); itr++) {
			ll k = (*itr).second;
			p = p * invfact[k] % mod;
		}
		ans = ans * p;
	}
	cout << ans << endl;
	return 0;
}

