    scanf("%lld %lld", &d[i][0], &d[i][1]);
    minC[d[i][0]] = min(minC[d[i][0]], d[i][1]);
  }
  for(int i=0;i<n;i++){
    ll c = d[i][0], num = d[i][1];
    C[c].push_back(i);
    if(minC[c]==num) {
      seg.update(num, c);//最小となる数字
      mindex[c] = i;
    }
  }

  for(int i=0;i<=n;i++){
    if(C[i].size()==0) continue;
    ll MINDEX = mindex[i];//色iの最小のidx
    vll L = seg.query(0,i);
    vll R = seg.query(i+1,n+1);
    ll min_other = INF, cc = -1;
    if(L[0]<R[0]&&L[0]!=INF) min_other=L[0], cc = L[1];
    if(L[0]>=R[0]&&R[0]!=INF) min_other=R[0], cc = R[1];
    for(auto k:C[i]){
      if(k==MINDEX) continue;
      //MINDEX + w[k] <= x || w[k] + min(othercolor) <= yならその色の親と併合
      ll w = d[k][1];
      if(d[MINDEX][1]+w<=x||w+min_other<=y) uf.unite(k, MINDEX);
    }
    if(min_other+d[MINDEX][1]<=y) uf.unite(mindex[cc], MINDEX);
  }

  // A:同じ色のボール
  // -> 色CのminCとotherCについて、minC + otherC <= XならotherCをminCに変換
  //
  // B:違う色のボール
  // -> 全体の最小値Mについて、
  // -> 1個とも交換できないものが仕切りになる
  // -> 連結成分の階乗?
  // 同じ色同士での隣接判定　最小値 + otherC <= Xか　O(N)
  // 異なる色同士での隣接判定

  vvl G = VV(n, 0, 0, ll);

  ll ans = 1;
  for(int i=0;i<n;i++) G[uf.find(i)].push_back(i);

  for(int i=0;i<n;i++){
    if(uf.find(i)!=i) continue;
    map<ll, ll> mp;

    for(auto to:G[i]){
      ll now_c = d[to][0];
      auto it = mp.find(now_c);
      if(it==mp.end()) mp.emplace(now_c, 1);
      else (*it).second++;
    }
    ll tmp = fac[uf.sz[i]];
    for(auto itr = mp.begin();itr!=mp.end();itr++){
      ll num = (*itr).second;
      tmp = (tmp * finv[num])%P;
    }
    //std::cout << "!" << i << " " << tmp << '\n';
    ans = (ans * tmp)%P;
  }
  /*
