const int kN = 2e5 + 5, kInf = 0x3f3f3f3f;
const ll kMod = 1e9 + 7;

ll QPow(ll a, ll b) {
	ll ans = 1, bas = a;
	for(; b; b >>= 1, bas = bas * bas % kMod) if(b & 1) ans = ans * bas % kMod;
	return ans;
}

int fa[kN], siz[kN]; ll fac[kN], fac_inv[kN];
int Find(int x) { return x == fa[x] ? x : fa[x] = Find(fa[x]); }
void Merge(int x, int y) {
	int f_x = Find(x), f_y = Find(y);
	if(f_x == f_y) return;
	siz[f_x] += siz[f_y]; fa[f_y] = f_x;
}

int cm[kN], w[kN], c[kN]; std::vector <int> cb[kN];
int main() {
	w[0] = kInf;
	int n, X, Y; rd(n, X, Y);
	if(n == 1) { printf("1"); return 0; }
	for(int i = 1; i <= n; ++i) {
		rd(c[i], w[i]);
		fa[i] = i; siz[i] = 1;
		cb[c[i]].push_back(i);
	}
	ll ans = 1; fac[0] = 1;
	for(int i = 1; i <= n; ++i) fac[i] = fac[i - 1] * i % kMod;
	fac_inv[n] = QPow(fac[n], kMod - 2);
	for(int i = n - 1; ~i; --i) fac_inv[i] = fac_inv[i + 1] * (i + 1) % kMod;
	for(int i = 1; i <= n; ++i) {
		if(!cb[i].size()) continue;
		int cnt = 0;
		for(auto x : cb[i]) {
			if(w[x] < w[cm[i]])
				cm[i] = x;
		}
		for(auto x : cb[i]) if(w[x] + w[cm[i]] <= X) {
			Merge(cm[i], x); ++cnt;
		}
		ans = ans * fac_inv[cnt] % kMod;
	}
	std::sort(cm + 1, cm + n + 1, [w](int a, int b) { return w[a] < w[b]; });
	for(int i = 1; i <= n; ++i) if(w[cm[1]] + w[i] <= Y && c[cm[1]] != c[i]) Merge(cm[1], i);
	for(int i = 1; i <= n; ++i) if(w[cm[2]] + w[i] <= Y && c[cm[2]] != c[i]) Merge(cm[2], i);
	for(int i = 1; i <= n; ++i) if(fa[i] == i) ans = ans * fac[siz[i]] % kMod;
	printf("%lld", ans);
	return 0;
}

