/*
	考虑到交换操作的传递性
	可以交换的球连边, 那么同一个联通块内的点都可以相互交换
	而且, 每种颜色只需要考虑其最小的重量, 它可以代表全部的交换
	不同种颜色也只需要考虑最小和次小就行了...
	有一些神奇的性质 :
	对答案有贡献的交换集合有且只有 1 个
	所以答案是一个多项式系数
*/
#include <algorithm>
#include <iostream>
#include <cstdio>
#include <vector>
#define N 200005

using namespace std;

const int mod = 1e9 + 7;

int n, x, y;
int fac[N], cnt[N];

struct node { int c, w; } ball[N], mBall[N], m1Ball, m2Ball;

inline void read(int &x) {
	x = 0; char ch = getchar();
	while(!isdigit(ch)) ch = getchar();
	while(isdigit(ch)) x = x * 10 + ch - '0', ch = getchar();
}
inline int fpm(int bs, int mi) {
	int res = 1;
	while(mi) {
		if(mi & 1) res = 1LL * res * bs % mod;
		bs = 1LL * bs * bs % mod, mi >>= 1;
	}
	return res;
}

inline bool judge(node A, node B) { return A.c == B.c ? A.w + B.w <= x : A.w + B.w <= y; }

int main() {
	read(n), read(x), read(y);

	fac[0] = 1;
	for(int i = 1; i <= n; ++i) {
		fac[i] = 1LL * i * fac[i - 1] % mod;
		mBall[i].c = i, mBall[i].w = 1e9;
	}
	for(int i = 1, c, w; i <= n; ++i) {
		read(c), read(w);
		ball[i].c = c, ball[i].w = w;
		mBall[c].w = min(mBall[c].w, w);
	}

	m1Ball.w = m2Ball.w = 1e9;
	for(int i = 1; i <= n; ++i) {
		if(mBall[i].w < m2Ball.w) {
			m2Ball = mBall[i];
			if(m2Ball.w < m1Ball.w)
				swap(m1Ball, m2Ball);
		}
	}

	if(m1Ball.w + m2Ball.w > y) return puts("1"), 0;

	for(int i = 1; i <= n; ++i) {
		int c = ball[i].c;
		if(judge(m1Ball, ball[i])) {
			++cnt[c];
		} else if(judge(m2Ball, ball[i])) {
			++cnt[c];
		} else if(judge(m1Ball, mBall[c]) && judge(mBall[c], ball[i])) {
			++cnt[c];
		}
	}

	int ans = 1, sum = 0;
	for(int i = 1; i <= n; ++i) {
		if(!cnt[i]) continue;
		sum += cnt[i];
		ans = 1LL * ans * fpm(fac[cnt[i]], mod - 2) % mod;
	}
	ans = 1LL * fac[sum] * ans % mod;
	printf("%d\n", ans);
	return 0;
}

