#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 100, MOD = 1000 * 1000 * 1000 + 7;

int sum(int a, int b) {
	a += b;
	if (a < 0)
		a += MOD;
	else if (a >= MOD)
		a -= MOD;
	return a;
}
void _sum(int &a, int b) {
	a = sum(a, b);
}
int mul(int a, int b) {
	return 1LL * a * b % MOD;
}
void _mul(int &a, int b) {
	a = mul(a, b);
}

int n, X, Y, c, w, col[N], last, mn1 = -1, mn2 = -1, fac[N], inv[N];
bool mark[N];
vector<int> vec[N], dex[N], nei[N];

void input() {
	cin >> n >> X >> Y;
	for (int i = 0; i < n; i++) {
		cin >> c >> w;
		vec[--c].push_back(w);
	}
}

void ready() {
	for (int i = 0; i < n; i++) {
		if (vec[i].size()) {
			sort(vec[i].begin(), vec[i].end());
			if (mn2 == -1 || vec[i][0] < vec[mn2][0]) {
				mn2 = i;
				if (mn1 == -1 || vec[mn2][0] < vec[mn1][0])
					swap(mn1, mn2);
			}
		}
		for (int j = 0; j < vec[i].size(); j++) {
			col[last] = i;
			dex[i].push_back(last++);
		}
	}
}

void add_edge(int u, int v) {
	nei[u].push_back(v);
	nei[v].push_back(u);
}

void add_in() {
	for (int i = 0; i < n; i++)
		for (int j = 1; j < vec[i].size() && vec[i][0] + vec[i][j] <= X; j++)
			add_edge(dex[i][0], dex[i][j]);
}

void add_out() {
	for (int i = 0; i < n; i++)
		for (int j = 0; j < vec[i].size(); j++) {
			if (mn1 != -1 && i != mn1 && vec[i][j] + vec[mn1][0] <= Y)
				add_edge(dex[mn1][0], dex[i][j]);
			if (mn2 != -1 && i != mn2 && vec[i][j] + vec[mn2][0] <= Y)
				add_edge(dex[mn2][0], dex[i][j]);
		}
}

void pre_pro() {
	fac[0] = 1;
	for (int i = 1; i < N; i++)
		fac[i] = mul(fac[i - 1], i);

	inv[0] = inv[1] = 1;
	for (int i = 2; i < N; i++)
		inv[i] = mul(MOD - MOD / i, inv[MOD % i]);
	for (int i = 2; i < N; i++)
		_mul(inv[i], inv[i - 1]);
}

int C(int n, int m) {
	return (n > m? 0: mul(fac[m], mul(inv[n], inv[m - n])));
}

void dfs(int v, vector<int> *vec) {
	vec->push_back(col[v]);
	mark[v] = true;
	for (int u: nei[v])
		if (mark[u] == false)
			dfs(u, vec);
}

int f(vector<int> vec) {
	int res = 1, rem = vec.size();
	unordered_map<int, int> cnt;
	for (int x: vec)
		cnt[x]++;
	for (auto p: cnt) {
		_mul(res, C(p.second, rem));
		rem -= p.second;
	}
	return res;
}

void solve() {
	int ans = 1;
	for (int i = 0; i < n; i++)
		if (mark[i] == false) {
			vector<int> vec;
			dfs(i, &vec);
			_mul(ans, f(vec));
		}
	cout << ans;
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	input();
	ready();
	add_in();
	add_out();
	pre_pro();
	solve();
}

