vector<pi> List;

int getMulti(int a, int b) {
	ll res = 1, pow = a;
	while(b) {
		if(b%2 == 1) res *= pow, res %= MOD;
		pow *= pow; pow %= MOD;
		b /= 2;
	}
	return res;
}

int main() {
