			if(Color[c][i] + Color[c][0] > X)
				Color[c].pop_back();
		if(Color[c].size() == 1)
			if(Color[c][0] > X)
				Color[c].pop_back();
		if(Color[c].size() != 0) {
			List.emplace_back(Color[c][0], (int)Color[c].size());
		}
	}
