	int ans = 1;
	for(int i=1; i<=sum; i++)
		ans = 1ll * ans * i % MOD;


	for(pi &e : List)
		ans = 1ll * ans * Inv[e.second] % MOD;

	printf("%d\n", ans);

	return 0;
}

