const int N = 3e5 + 233;
map<int, int> mp[N];
vector<pair<int, int> > vec[N];
int fac[N], fac_inv[N];
int c[N], w[N], pre[N];
int n, X, Y, ans = 1;
inline void init(void) {
  fac[0] = 1;
  for(int i = 1; i < N; i ++)
    fac[i] = mul(fac[i - 1], i);
  fac_inv[N - 1] = pw(fac[N - 1], mo - 2, mo);
  for(int i = N - 2; i >= 0; i --)
    fac_inv[i] = mul(fac_inv[i + 1], i + 1);    
}

inline int find(int x) {
  return pre[x] == x ? x : pre[x] = find(pre[x]);
}

inline void uni(int x, int y) {
  // cout << x << " " << y << "\n";
  int fx = find(x), fy = find(y);
  if(fx == fy) return ;
  if((int) mp[fx].size() < (int) mp[fy].size())
    swap(fx, fy);
  pre[fy] = fx;
  for(auto v: mp[fy])
    mp[fx][v.first] += v.second;
  mp[fy].clear();
}

inline int gao(int id) {
  int ans = 1;
  int tot = 0;
  for(auto v: mp[id]) {
    ans = mul(ans, fac_inv[v.second]);
    tot += v.second;
  }
  ans = mul(ans, fac[tot]);
  return ans;
}

main(void) {
  init();
  read(n); read(X); read(Y);
  for(int i = 1; i <= n; i ++) {
    read(c[i]); read(w[i]);
    vec[c[i]].push_back({w[i], i});
    pre[i] = i; mp[i][c[i]] = 1;
  }
  int id = -1, mn = 1e11;
  int seid = -1, semn = 1e11;
  for(int i = 1; i <= n; i ++) if((int) vec[i].size()) {
      auto &v = vec[i];
      sort(v.begin(), v.end());
      if(mn > v[0].first) {
        seid = id; semn = mn;
        id = i; mn = v[0].first;
      }
      else if(semn > v[0].first) {
        seid = i; semn = v[0].first;
      }
    }
  if(id != -1) {
    int pid = vec[id][0].second;
    for(int i = 1; i <= n; i ++)
      if(w[i] + w[pid] <= (c[i] == c[pid] ? X : Y))
        uni(pid, i);
  }
  if(seid != -1) {
    swap(seid, id);
    int pid = vec[id][0].second;
    for(int i = 1; i <= n; i ++)
      if(w[i] + w[pid] <= (c[i] == c[pid] ? X : Y))
        uni(pid, i);
  }
  for(int i = 1; i <= n; i ++)
    if(pre[i] == i)
      ans = mul(ans, gao(i));
  cout << ans << "\n";
}

