  for(ll i=1;i<N;i++)
    fact[i]=(fact[i-1]*i)%MOD;
  //calculate inverses of [1,N] mod p
  inv[1]=1;
  for(ll i=2;i<N;i++)inv[i]=inv[MOD%i]*(MOD-MOD/i)%MOD;

  invfact[0]=1;
  for(ll i=1;i<N;i++)invfact[i]=(invfact[i-1]*inv[i])%MOD;
}

ll ncr(ll n,ll r)
{
