        col.pb(p[nod].fi);
    ++fr[p[nod].fi];
    ++nr;
    viz[nod] = 1;
    for(int i = 0; i < v[nod].size(); ++i)
    {
        int vecin = v[nod][i];
        if(!viz[vecin])
            dfs(vecin);
    }
}
ll sol(int start_point)
{
