using namespace std;

typedef long long LL;

const int N = 2e5 + 10, INF = 1e9 + 7, MOD = 1e9 + 7;
int fac[N], inv[N], c[N], w[N], mn[N], cnt[N];

LL powMod(LL a, LL b) {
    LL ret = 1;
    while (b) {
        if (b & 1) ret = ret * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return ret;
}

int main() {
    fac[0] = 1;
    for (int i = 1; i < N; i++) fac[i] = 1ll * fac[i-1] * i % MOD;
    inv[N - 1] = powMod(fac[N - 1], MOD - 2);
    for (int i = N - 2; i >= 0; i--) inv[i] = 1ll * inv[i + 1] * (i + 1) % MOD;
    int n, x, y;
    scanf("%d%d%d", &n, &x, &y);
    for (int i = 0; i < n; i++) scanf("%d%d", c + i, w + i);
    int c1, c2, w1, w2;
    w1 = w2 = INF;
    for (int i = 0; i < n; i++) if (w[i] < w1)  w1 = w[i], c1 = c[i];
    for (int i = 0; i < n; i++) if (w[i] < w2 && c[i] != c1) w2 = w[i], c2 = c[i];
    fill(mn + 1, mn + n + 1, INF);
    for (int i = 1; i <= n; i++) mn[c[i]] = min(mn[c[i]], w[i]);
    for (int i = 0; i < n; i++) {
        if (c[i] == c1) {
            if (w[i] + w1 <= x || w[i] + w2 <= y) cnt[c[i]]++;
        } else {
            if (w[i] + w1 <= y || w[i] + mn[c[i]] <= x && mn[c[i]] + w1 <= y) cnt[c[i]]++;
        }
    }
    int ans = 1, sum = 0;
    for (int i = 1; i <= n; i++) if (cnt[i]) {
        sum += cnt[i];
        ans = 1ll * ans * inv[cnt[i]] % MOD;
    }
    ans = 1ll * ans * fac[sum] % MOD;
    printf("%d\n", ans);
    return 0;
}

