struct dsu {
	int par[N];
	dsu() {
		for (int i = 1; i <= N - 5; i++) par[i] = i;
	}
	int find(int x) {
		if (par[x] == x) return x;
		return par[x] = find(par[x]);
	}
	void uni(int x, int y) {
		x = find(x); y = find(y);
		if (x != y) par[x] = y;
	}
} d;

#define pow binPow
long long binPow(long long a, long long q) {
	long long ret = 1;
	for (int i = 0; (1LL << i) <= q; i++) {
		if (q & (1LL << i)) ret = (ret * a) % mod;
		a = (a * a) % mod;
	}
	return ret;
}

#define exp exp__
int n, X, Y;
pair<int, int> a[N];
vector<vector<int> > mem(N);
int exp[N];

void prep() {
	exp[1] = 1;
	for (int i = 2; i <= N - 5; i++) exp[i] = exp[i - 1] * i % mod;
}

pair<int, int> mn = mp(2e9, 0);
pair<int, int> mn2 = mp(2e9, 0);
void makeEdge() {
	for (int i = 1; i <= n; i++) {
		int c = a[i].se + a[mn.se].se;
		if (a[i].fi == a[mn.se].fi && c <= X) d.uni(i, mn.se);
		else if (a[i].fi != a[mn.se].fi && c <= Y) d.uni(i, mn.se);
	}
	for (int i = 1; i <= n; i++) {
		int c = a[i].se + a[mn2.se].se;
		if (a[i].fi == a[mn2.se].fi && c <= X) d.uni(i, mn2.se);
		else if (a[i].fi != a[mn2.se].fi && c <= Y) d.uni(i, mn2.se);
	}
}

void solve() {
	for (int i = 1; i <= n; i++) {
		int u = d.find(i);
		mem[u].push_back(a[i].fi);
	}
	int ans = 1;
	for (int i = 1; i <= n; i++) {
		sort(mem[i].begin(), mem[i].end());
		if (mem[i].size() >= 2) {
			ans = ans * exp[mem[i].size()] % mod;
			int cnt = 1;
			for (int j = 1; j < mem[i].size(); j++) {
				if (mem[i][j] != mem[i][j - 1]) {
					ans = ans * binPow(exp[cnt], mod - 2) % mod;
					cnt = 1;
				}
				else cnt++;
			}
			ans = ans * binPow(exp[cnt], mod - 2) % mod;
		}
	}
	cout << ans << endl;
}

signed main() {
