ll QPow(ll a, ll b) {
	ll ans = 1, bas = a;
	for(; b; b >>= 1, bas = bas * bas % kMod) if(b & 1) ans = ans * bas % kMod;
	return ans;
}

int fa[kN], siz[kN]; ll fac[kN];
int Find(int x) { return x == fa[x] ? x : fa[x] = Find(fa[x]); }
void Merge(int x, int y) {
	int f_x = Find(x), f_y = Find(y);
	if(f_x == f_y) return;
	siz[f_x] += siz[f_y]; fa[f_y] = f_x;
}

int cm[kN], w[kN], c[kN], ccnt = 0; std::vector <int> cb[kN];
int main() {
	w[0] = kInf;
	int n, X, Y; rd(n, X, Y);
	for(int i = 1; i <= n; ++i) {
		rd(c[i], w[i]); siz[i] = 1; fa[i] = i;
		cb[c[i]].push_back(i);
	}
	if(n == 1) { printf("1"); return 0; }
	ll ans = 1, divans = 1; fac[0] = 1;
	for(int i = 1; i <= n; ++i) fac[i] = fac[i - 1] * i % kMod;
	for(int i = 1; i <= n; ++i) {
		if(!cb[i].size()) continue;
		for(auto x : cb[i]) {
			if(w[x] < w[cm[i]])
				cm[i] = x;
		}
		for(auto x : cb[i]) if(w[x] + w[cm[i]] <= X) Merge(cm[i], x);
	}
	int m1 = 0, m2 = 0;
	for(int i = 1; i <= n; ++i) {
		if(w[cm[i]] < w[m1]) m2 = m1, m1 = cm[i];
		else if(w[cm[i]] < w[m2]) m2 = cm[i];
	}
	for(int i = 1; i <= n; ++i) if(w[m1] + w[i] <= Y && c[m1] != c[i]) Merge(m1, i);
	for(int i = 1; i <= n; ++i) if(w[m2] + w[i] <= Y && c[m2] != c[i]) Merge(m2, i);
	for(int i = 1; i <= n; ++i) if(fa[i] == i) ans = ans * fac[siz[i]] % kMod;
	for(int i = 1; i <= n; ++i) {
		if(!cb[i].size()) continue;
		int cnt = 0;
		for(auto x : cb[i]) if(Find(x) == Find(cm[i])) ++cnt;
		divans = divans * fac[cnt] % kMod;
	}
	printf("%lld", ans * QPow(divans, kMod - 2) % kMod);
	return 0;
}

