ll fact[MAXN],inv[MAXN],w[MAXN];
int u[MAXN],mn[MAXN],arr[MAXN];
map<int,int> mp[MAXN];

ll mod_pow(ll a,ll b,ll m){
	ll ans = 1;
	for(; b ; b >>= 1){
		if(b & 1) ans = ans * a % m;
		a = a * a % m;
	}
	return ans;
}

void pre(){
	fact[0] = 1; 
	for(int i=1;i<MAXN;i++) fact[i] = fact[i-1] * i % MOD;
	inv[MAXN-1] = mod_pow(fact[MAXN-1],MOD-2,MOD);
	for(int i=MAXN-2;i>=0;i--) inv[i] = inv[i+1] * (i+1) % MOD;
}

int root(int a) { return u[a] == a ? a : u[a] = root(u[a]); }

int main(){
