typedef pair<int, int> pi;
const int mod = 1e9 + 7;

const int MAXN = 500005;
struct disj{
	int pa[MAXN], sz[MAXN];
	void init(int n){
		for(int i=0; i<=n; i++){
			pa[i] = i;
			sz[i] = 1;
		}
	}
	int find(int x){
		return pa[x] = (pa[x] == x ? x : find(pa[x]));
	}
	bool uni(int p, int q){
		p = find(p);
		q = find(q);
		if(p == q) return 0;
		pa[q] = p;
		sz[p] += sz[q];
		return 1;
	}
}disj;


lint ipow(lint x, lint p){
	lint ret = 1, piv = x % mod;
	while(p){
		if(p&1) ret *= piv;
		piv *= piv;
		ret %= mod;
		piv %= mod;
		p >>= 1;
	}
	return ret % mod;
}


struct ball{
	int c, w, i;
}a[200005];

int n, x, y;
vector<int> col[200005];
lint fact[200005], invf[200005];

int main(){
	fact[0] = invf[0] = 1;
	scanf("%d %d %d",&n,&x,&y);
	for(int i=1; i<=n; i++) fact[i] = fact[i-1] * i % mod, invf[i] = ipow(fact[i], mod - 2);
	disj.init(n);
	for(int i=0; i<n; i++){
		scanf("%d %d",&a[i].c,&a[i].w);
		a[i].i = i;
	}
	sort(a, a+n, [&](const ball &a, const ball &b){
		return pi(a.c, a.w) < pi(b.c, b.w);
	});
	vector<ball> v;
	for(int i=0; i<n; ){
		int e = i;
		while(e < n && a[e].c == a[i].c) e++;
		for(int j=i+1; j<e; j++){
			if(a[j].w + a[i].w <= x) disj.uni(a[j].i, a[i].i);
		}
		v.push_back(a[i]);
		i = e;
	}
	sort(v.begin(), v.end(), [&](const ball &a, const ball &b){
		return a.w < b.w;
	});
	for(int i=0; i<v.size() && i<2; i++){
		for(int j=0; j<n; j++){
			if(a[j].c != v[i].c && v[i].w + a[j].w <= y) disj.uni(v[i].i, a[j].i);
		}
	}
	for(int i=0; i<n; i++){
		col[disj.find(a[i].i)].push_back(a[i].c);
	}
	lint ans = 1;
	for(int i=0; i<n; i++){
		sort(col[i].begin(), col[i].end());
		ans *= fact[col[i].size()];
		ans %= mod;
		for(int j=0; j<col[i].size(); ){
			int e = j;
			while(e < col[i].size() && col[i][j] == col[i][e]) e++;
			ans *= invf[e - j];
			ans %= mod;
			j = e;
		}
	}
	cout << ans;
}

