vector<pii> a[MAXN];
int parent[MAXN];
int siz[MAXN];

int get_parent(int v) {
    if (v == parent[v])
        return v;
    return parent[v] = get_parent(parent[v]);
}

void union_set(int a, int b) {
    a = get_parent(a);
    b = get_parent(b);
    if (a != b) {
        parent[b] = a;
        siz[a] += siz[b];
    }
}

map<int, int> mapik[MAXN];


int CLR[MAXN], COST[MAXN];

ll bin_pow(ll a, int n) {
    ll res = 1;
    while (n) {
        if (n & 1) {
            res = (res * a) % mod;
        }
        a = (a * a) % mod;
        n >>= 1;
    }
    return res;
}

ll inverse(ll a) {
    return bin_pow(a, mod - 2);
}

void solve() {
    int n, x, y;
    cin >> n >> x >> y;
    for (int i = 1; i <= n; ++i) {
        parent[i] = i;
        siz[i] = 1;
    }
    for (int i = 1; i <= n; ++i) {
        int clr, cost;
        cin >> clr >> cost;
        a[clr].pb({cost, i});
        CLR[i] = clr;
        COST[i] = cost;
    }
    vector<pii> min_clr;
    for (int i = 1; i <= n; ++i) {
        if (a[i].empty())
            continue;
        sort(all(a[i]));
        min_clr.pb(a[i][0]);
        for (int j = 1; j < sz(a[i]); ++j) {
            if (a[i][j].fi + a[i][0].fi <= x) {
                union_set(a[i][0].se, a[i][j].se);
            }
        }
    }
    sort(all(min_clr));
    for (int j = 1; j < sz(min_clr); ++j) {
        if (min_clr[j].fi + min_clr[0].fi <= y) {
            union_set(min_clr[j].se, min_clr[0].se);
        }
    }


    for (int i = 1; i <= n; ++i) {
        mapik[get_parent(i)][CLR[i]]++;
    }

    ll ans = 1;

    for (int i = 1; i <= n; ++i) {
        if (get_parent(i) == i) {
            for (int j = 0; j < siz[i]; ++j) {
                ans = ans * (j + 1);
                ans %= mod;
            }
        }
    }
    dout <<"ans " <<ans<<endl;

    for (int i = 1; i <= n; ++i) {
        for (auto x:mapik[i]) {
            int cnt = x.se;
            ll fac = 1;
            for (int j = 1; j <= cnt; ++j) {
                fac = (fac * j) % mod;
            }
            ans = (ans * inverse(fac)) % mod;
        }
    }
    cout << ans;
}

