vector<long long int> factmod(200001);
vector<long long int> inversefactmod(200001);

void getfactmod()
{
	factmod[0] = 1;
	for(long long int i = 1; i < 200001; i++){
		factmod[i] = (factmod[i - 1] * i) % mod;
	}
	return;
}

void getinversefactmod()
{
	for(long long int i = 0; i < 200001; i++){
		// tmp[j] = factmod[i]^(2^j) % mod
		long long int tmp[31];
		tmp[0] = factmod[i];
		for(long long int j = 1; j < 31; j++){
			tmp[j] = (tmp[j - 1] * tmp[j - 1]) % mod;
		}
		long long int m = mod - 2;
		inversefactmod[i] = 1;
		for(long long int j = 30; j >= 0; j--){
			long long int pow2 = (long long int)pow(2, j);
			if(m >= pow2){
				inversefactmod[i] = (inversefactmod[i] * tmp[j]) % mod;
				m -= pow2;
			}
		}
	}
	return;
}

long long int comb(long long int n, long long int k)
{
	return factmod[n] * ((inversefactmod[k] * inversefactmod[n - k]) % mod) % mod;
}

long long int nibutan(vector<int> v, long long int a, long long int b)
{
	int l = 0, r = v.size();
	while(r - l > 1){
		int mid = (l + r) / 2;
		if((long long int)v[mid] + a > b) r = mid;
		else l = mid;
	}
	return l;
}

long long int solve1()
{
	vector<pair<int, int> > tmp;
	for(int i = 1; i <= n; i++){
		if(color[i].size() == 0 || color[i][0] >= x) continue;
		tmp.push_back(make_pair(color[i][0], nibutan(color[i], color[i][0], x) + 1));
	}
	if(tmp.size() == 0) return 1;
	sort(tmp.begin(), tmp.end());
	int l = 0, r = tmp.size();
	while(r - l > 1){
		int mid = (l + r) / 2;
		if(tmp[mid].first + tmp[0].first > y) r = mid;
		else l = mid;
	}
	int sum = 0;
	for(int i = 0; i <= l; i++){
		sum += tmp[i].second;
	}
	long long int ans = 1;
	for(int i = 0; i <= l; i++){
		ans = (ans * comb(sum, tmp[i].second)) % mod;
		sum -= tmp[i].second;
	}
	return ans;
}

long long int solve2()
{
	int mincolor = 0;
	for(int i = 1; i <= n; i++){
		if(color[i].size() == 0) continue;
		if(mincolor == 0 || color[i][0] < color[mincolor][0]) mincolor = i;
	}
	if(color[mincolor][0] >= y) return 1;
	int l = nibutan(color[mincolor], color[mincolor][0], x);
	vector<int> tmp;
	tmp.push_back(l + 1);
	int sum = l + 1;
	for(int i = 1; i <= n; i++){
		if(color[i].size() == 0 || color[i][0] + color[mincolor][0] > y) continue;
		int l = nibutan(color[i], color[mincolor][0], y);
		tmp.push_back(l + 1);
		sum += l + 1;
	}
	long long int ans = 1;
	for(int i = 0; i < tmp.size(); i++){
		ans = (ans * comb(sum, tmp[i])) % mod;
		sum -= tmp[i];
	}
	return ans;
}

int main()
{
	cin >> n >> x >> y;
	for(int i = 0; i < n; i++){
		int c, w;
		cin >> c >> w;
		color[c].push_back(w);
	}
	for(int i = 1; i <= n; i++){
		if(color[i].size() != 0) sort(color[i].begin(), color[i].end());
	}
	getfactmod();
	getinversefactmod();
	if(x >= y) cout << solve1() << endl;
	else cout << solve2() << endl;
	return 0;

}

