long long int ipow(long long int e, long long int a) {
    if (e == 0) return 1;
    if (e == 1) return a;
    if (e & 1) return ((ipow(e - 1, a) * a) % 1000000007);
    long long v = ipow(e / 2, a);
    return (v * v) % 1000000007;
}

int main() {
	ll fact[300000];
	ll invfact[300000];

	fact[0] = 1; fact[1] = 1; invfact[0] = 1; invfact[1] = 1;

	for(int i = 2; i < 300000; i++) {
		fact[i] = i * fact[i-1];
		fact[i] %= MOD;
	}

	for(int i = 2; i < 300000; i++) {
		invfact[i] = ipow(1000000005, fact[i]);
	}

	ll N, X, Y;
	ll overmin = 999999999999999;
	cin >> N >> X >> Y;

	vector< vector<ll> > storage;

	for(int i = 0; i < N+1; i++) {
		vector<ll> empty;
		storage.push_back(empty);
	}

	for(int i = 0; i < N; i++) {
		ll c, w;
		cin >> c >> w;
		storage[c].push_back(w);
		if(w < overmin) {
			overmin = w;
		}
	}

	vector<ll> combinations;
	ll totalcomb = 0;

	for(int i = 0; i < N+1; i++) {
		if(storage[i].size() > 0) {
			sort(storage[i].begin(), storage[i].end());
			if(overmin + storage[i][0] <= Y) {
				ll current = 0;
				while(current != storage[i].size() - 1 && ( (storage[i][0] + storage[i][current + 1] <= X) || (storage[i][current + 1] + overmin <= Y) )) {
					current++;
				}
				combinations.push_back(current + 1);
				totalcomb += (current + 1);
			}
		} 
	}

	ll answer = fact[totalcomb];
	if(totalcomb <= 1) {cout << 1 << endl;} 
	else {
		for(int i = 0; i < combinations.size(); i++) {
			answer *= invfact[combinations[i]];
			answer %= MOD;
		}
		cout << answer << endl; }
}

