void Up(int l, int r, int i, int Y) {
	for (l += B, r += B; l / 2 != r / 2; l /= 2, r /= 2) {
		if (!(l & 1))tr[l + 1].emplace_back(i, Y);
		if (r & 1)tr[r - 1].emplace_back(i, Y);
	}
}
