template <std::uint_fast64_t Modulus> class modint {
  using u64 = std::uint_fast64_t;

public:
  u64 a;

  constexpr modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 &value() noexcept { return a; }
  constexpr const u64 &value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
	return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
	return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
	return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
	return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
	a += rhs.a;
	if (a >= Modulus) {
	  a -= Modulus;
	}
	return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
	if (a < rhs.a) {
	  a += Modulus;
	}
	a -= rhs.a;
	return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
	a = a * rhs.a % Modulus;
	return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
	u64 exp = Modulus - 2;
	while (exp) {
	  if (exp % 2) {
		*this *= rhs;
	  }
	  rhs *= rhs;
	  exp /= 2;
	}
	return *this;
  }
};

using mint = modint<mod>;

struct UnionFind{
	vl p;
	vl rank;
	vl cnt;

	UnionFind(ll n){
		rank.resize(n,0);
		p.resize(n,0);
		cnt.resize(n,0);
		rep(i,n){
			p[i] = i;
			rank[i] = 0;
			cnt[i] = 1;
		}
	}

	ll find(ll x){
		if(x != p[x]) p[x] = find(p[x]);
		return p[x];
	}

	bool same(ll x, ll y){
		return find(x) == find(y);
	}

	void unite(ll x, ll y){
		x = find(x);
		y = find(y);
		if(x == y) return;
		if(rank[x] > rank[y]){
			p[y] = x;
			cnt[x] += cnt[y];
		}else{
			p[x] = y;
			cnt[y] += cnt[x];
			if(rank[x] == rank[y]) rank[y]++;
		}
	}

	ll size(ll x){
		return cnt[find(x)];
	}
};

vector<ll> fac(MAX), finv(MAX), inv(MAX);

void comInit(){
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for(ll i=2; i<MAX; i++){
		fac[i] = fac[i-1]*i % mod;
		inv[i] = mod - inv[mod%i] * (mod/i) % mod;
		finv[i] = finv[i-1] * inv[i] % mod;
	}
}


ll com(ll n, ll k){
	if(n < k) return 0;
	if(n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}

int main(){
	ll n,x,y; cin >> n >> x >> y;
	vl c(n), w(n); rep(i,n) cin >> c[i] >> w[i], c[i]--;
	comInit();
	UnionFind uf(n);
	vector<vpl> colors(n);
	rep(i,n) colors[c[i]].emplace_back(w[i],i);
	rep(i,n) sort(all(colors[i]));
	set<P> se;
	rep(i,n) se.emplace(w[i],i);
	rep(i,n){
		P X = {inf,inf};
		if(colors[c[i]].size() > 1){
			if(colors[c[i]][0].second == i) X = colors[c[i]][1];
			else X = colors[c[i]][0];
		}
		P Y = {inf,inf};
		for(auto j : se){
			if(c[j.second] != c[i]){
				Y = j;
				break;
			}
		}
		if(w[i] + X.first <= x) uf.unite(i,X.second);
		if(w[i] + Y.first <= y) uf.unite(i,Y.second);
	}
	vvl ls(n);
	rep(i,n){
		ls[uf.find(i)].push_back(i);
	}
	mint ans = 1;
	rep(i,n){
		map<ll,ll> mp;
		if(ls[i].empty()) continue;
		ans *= fac[ls[i].size()];
		for(auto j : ls[i]){
			mp[c[j]]++;
		}
		for(auto j : mp){
			ans *= finv[j.second];
		}
	}
	cout << ans.value() << "\n";
}

