int get(int x) {
    if (p[x] == -1) {
        return x;
    }
    return p[x] = get(p[x]);
}

void unite(int a, int b) {
    a = get(a);
    b = get(b);
    if (a == b) {
        return;
    }
    p[a] = b;
}

ll pw(ll a, ll b = MOD - 2) {
    ll r = 1;
    for (; b > 0; b >>= 1) {
        if (b & 1) {
            r = r * a % MOD;
        }
        a = a * a % MOD;
    }
    return r;
}

void precalc() {
    fact[0] = 1;
    ifact[0] = 1;
    for (int i = 1; i < N; i++) {
        fact[i] = i * fact[i - 1] % MOD;
        ifact[i] = pw(fact[i], MOD - 2);
    }
}

