vector <int> ind, t;

void dfs(int i, int k)
{
    if (u[i][k])
    {
        return;
    }
    u[i][k] = true;
    for (auto to : g[i][k])
    {
        dfs(to.first, to.second);
    }
    if (k == 0)
    {
        ind.push_back(i);
    }
}

void zhfs(int i, int k)
{
    if (u[i][k])
    {
        return;
    }
    u[i][k] = true;
    for (auto to : g[i][k])
    {
        dfs(to.first, to.second);
    }
    if (k == 0)
    {
        t.push_back(i);
    }
}

int bin(int a, int n)
{
    if (!n)
    {
        return 1;
    }
    if (n % 2 == 0)
    {
        int t = bin(a, n / 2);
        return (t * (ll) t) % M;
    }
    else
    {
        return (a * (ll) bin(a, n - 1)) % M;
    }
}

