using namespace std;

#define mod 1000000007

int n, x, y;
vector<vector<int> > color(200001);

vector<long long int> factmod(200001);
vector<long long int> inversefactmod(200001);

void getfactmod()
{
	factmod[0] = 1;
	for(long long int i = 1; i < 200001; i++){
		factmod[i] = (factmod[i - 1] * i) % mod;
	}
	return;
}

void getinversefactmod()
{
	for(long long int i = 0; i < 200001; i++){
		// tmp[j] = factmod[i]^(2^j) % mod
		long long int tmp[31];
		tmp[0] = factmod[i];
		for(long long int j = 1; j < 31; j++){
			tmp[j] = (tmp[j - 1] * tmp[j - 1]) % mod;
		}
		long long int m = mod - 2;
		inversefactmod[i] = 1;
		for(long long int j = 30; j >= 0; j--){
			long long int pow2 = (long long int)pow(2, j);
			if(m >= pow2){
				inversefactmod[i] = (inversefactmod[i] * tmp[j]) % mod;
				m -= pow2;
			}
		}
	}
	return;
}

long long int comb(long long int n, long long int k)
{
	return factmod[n] * ((inversefactmod[k] * inversefactmod[n - k]) % mod) % mod;
}

long long int solve()
{
	int minw = 0, secminw = 0;
	for(int i = 1; i <= n; i++){
		if(color[i].size() == 0) continue;
		if(minw == 0 || color[minw][0] > color[i][0]){
			secminw = minw;
			minw = i;
		} else if(secminw == 0 || color[secminw][0] > color[i][0]){
			secminw = i;
		}
	}
	if(secminw == 0 || color[minw][0] + color[secminw][0] > y) return 1;
	vector<int> tmp;
	int sum = 0;
	for(int i = 1; i <= n; i++){
		if(color[i].size() == 0) continue;
		int l = -1, r = color[i].size();
		while(r - l > 1){
			int mid = (r + l) / 2;
			if((i == minw && (mid == 0 || color[i][0] + color[i][mid] <= x || color[secminw][0] + color[i][mid] <= y)) || (color[i][0] + color[minw][0] <= y && color[i][0] + color[i][mid] <= x) || color[i][mid] + color[minw][0] <= y) l = mid;
			else r = mid;
		}
		tmp.push_back(l + 1);
		sum += l + 1;
	}
	long long int ans = 1;
	for(int i = 0; i < tmp.size(); i++){
		ans = (ans * comb(sum, tmp[i])) % mod;
		// cout << sum << " " << tmp[i] << " " << comb(sum, tmp[i]) << endl;
		sum -= tmp[i];
	}
	return ans;
}

int main()
{
	cin >> n >> x >> y;
	for(int i = 0; i < n; i++){
		int c, w;
		cin >> c >> w;
		color[c].push_back(w);
	}
	for(int i = 1; i <= n; i++){
		if(color[i].size() != 0) sort(color[i].begin(), color[i].end());
	}
	getfactmod();
	getinversefactmod();
	cout << solve() << endl;
	return 0;

}

