const int MAX_COMB = 200010;
const LL mod = 1e9 + 7;
LL fct[MAX_COMB+1];
LL invfct[MAX_COMB+1];

void build(){
	fct[0] = fct[1] = 1;
	repp(i,2,MAX_COMB+1){
		fct[i] = fct[i-1] * i % mod;
	}
	LL x = fct[MAX_COMB];
	invfct[MAX_COMB] = 1;
	for(int i = mod - 2 ; i > 0 ; i >>= 1){
		if(i % 2 == 1) (invfct[MAX_COMB] *= x) %= mod;
		(x *= x) %= mod;
	}
	repm(i,MAX_COMB,0){
		invfct[i-1] = invfct[i] * i % mod;
	}
}

const int UF_MAX = 200010;

class UF{
	int x[UF_MAX];

public:

	UF(){
		fill(x,x+UF_MAX,-1);
	}

	int boss(int a){
		int s = a;
		while(x[s] > -1) s = x[s];
		if(s != a) x[a] = s;
		return s;
	}

	void uni(int a , int b){
		int s = boss(a);
		int t = boss(b);
		if(s != t){
			if(x[s] < x[t]){
				x[s] += x[t];
				x[t] = s;
			} else {
				x[t] += x[s];
				x[s] = t;
			}
		}
	}

	bool find(int a , int b){
		return boss(a) == boss(b);
	}

	int member(int a){
		return -x[boss(a)];
	}
} uf;

int N,X,Y;
vector<P2> W[200010];
vector<int> V[200010];
P2 ball[200010];
int s[200010];
int b[200010];

int main(){
	build();
	scanf("%d%d%d" , &N , &X , &Y);
	repp(i,0,N){
		int c,w;
		scanf("%d%d" , &c , &w);
		W[c].PB(MP(w,i));
		ball[i] = MP(c,w);
		s[i] = i;
	}
	repp(i,1,N+1){
		if(W[i].size() < 2) continue;
		sort(W[i].begin() , W[i].end());
		int d = 1;
		while(W[i].size() > d && W[i][0].first + W[i][d].first <= X) uf.uni(W[i][0].second,W[i][d++].second);
	}
	sort(s,s+N,[&](const int x , const int y){return ball[x].second < ball[y].second;});
	int r = -1;
	repp(i,1,N){
		if(ball[s[i]].second + ball[s[0]].second > Y) break;
		if(ball[s[i]].first == ball[s[0]].first) continue;
		uf.uni(s[i],s[0]);
		if(r < 0) r = s[i];
	}
	if(r >= 0){
		for(auto e : W[ball[s[0]].first]){
			if(ball[r].second + e.first > Y) break;
			uf.uni(r,e.second);
		}
	}
	LL ans = 1;
	repp(i,0,N){
		b[i] = uf.boss(i);
		if(b[i] == i) (ans *= fct[uf.member(i)]) %= mod;
		V[b[i]].PB(ball[i].first);
	}
	repp(i,0,N){
		if(V[i].size() == 0) continue;
		sort(V[i].begin(),V[i].end());
		int p = 0 , q = 1;
		repp(j,1,V[i].size()){
			if(V[i][j] == V[i][p]){
				++q;
			} else {
				(ans *= invfct[q]) %= mod;
				q = 1;
				p = j;
			}
		}
		(ans *= invfct[q]) %= mod;
	}
	printf("%lld\n" , ans);
	return 0;
}

