ll pw(ll x, ll y){
	ll res = 1;
	while(y){
		if(y & 1)res = res * x % MOD;
		x = x * x % MOD;
		y >>= 1;
	}
	return res;
}

void solve(){
	scanf("%d%d%d", &N, &X, &Y);
	for(int i=1;i<=N;i++)p[i] = i;
	for(int i=1;i<=N;i++){
		scanf("%d%d", C+i, W+i);
		E[C[i]].pb(pii(W[i], i));
		P[i] = t3(W[i], C[i], i);
	}
	for(int i=1;i<=N;i++)sort(all(E[i]));
	for(int i=1;i<=N;i++){
		for(int j=1;j<sz(E[i]);j++){
			if(E[i][j].Fi + E[i][0].Fi <= X){
				Uni(E[i][j].Se, E[i][0].Se);
			}
		}
	}
	sort(P+1, P+1+N);
	int idx[3] = {};
	for(int u=0;u<3;u++){
		idx[u] = -1;
		for(int i=1;i<=N;i++){
			int ok = 1;
			rep(v, u)if(idx[v] == -1 || get<1>(P[idx[v]]) == get<1>(P[i]))ok = 0;
			if(ok){
				idx[u] = i;
				break;
			}
		}
	}
	for(int i=1;i<=N;i++){
		int t = (int)(upper_bound(P+1, P+1+N, t3(Y - get<0>(P[i]), 1e9, 1e9)) - P - 1);
		t = min(t, i-1);
		if(t){
			rep(u, 3){
				int v = idx[u];
				if(v > t || idx[u] == -1)break;
				if(get<1>(P[v]) != get<1>(P[i])){
					Uni(get<2>(P[v]), get<2>(P[i]));
				}
			}
		}
		for(int k=0;k<50;k++){
			int u = t - k;
			if(u > 0 && get<1>(P[u]) != get<1>(P[i])){
				Uni(get<2>(P[u]), get<2>(P[i]));
			}
		}
	}
	vector <int> ch[200020];
	for(int i=1;i<=N;i++){
		ch[Find(i)].pb(i);
	}
	//for(int i=1;i<=N;i++)printf("%d ", Find(i)); puts("");
	int ans = 1;
	F[0] = IF[0] = 1;
	for(int i=1;i<=N;i++)F[i] = i * F[i-1] % MOD;
	for(int i=1;i<=N;i++)IF[i] = IF[i-1] * pw(i, MOD-2) % MOD;
	for(int i=1;i<=N;i++)if(sz(ch[i])){
		map <int, int> M;
		for(int e : ch[i])M[C[e]]++;
		ll c = F[sz(ch[i])];
		for(auto e : M)c = c * IF[e.Se] % MOD;
		ans = (ll)ans * c % MOD;
	}
	printf("%d\n", ans);
}

