	ivf[n] = pow_mod(fac[n], mo - 2, mo);
	for (int i = n - 1; i >= 1; --i) ivf[i] = 1LL * ivf[i + 1] * (i + 1) % mo;
	for (int i = 1; i <= n; ++i) {
