			nc = n = v;
			rk.assign(n,0);
			sz.assign(n,1);
			for(int i=0;i<n;i++) {p.push_back(i);}
		}
		int find(int a) {
			if(a == p[a]) return a;
			return p[a] = find(p[a]);
		}
		bool same(int a, int b) {return find(a) == find(b);}
		int size(int a) {return sz[find(a)];}
		bool un(int a, int b) {
			int x = find(a),y = find(b);
			if(x == y) return false;
			nc--;
			if(rk[x] > rk[y]) {
				p[y] = x;
				sz[x] += sz[y];
				return true;}
			if(rk[x] == rk[y]) rk[y]++;
			p[x] = y;
			sz[y] += sz[x];
