int modpow(int x, int k) {
  int a = 1;
  while (k > 0) {
    if (k & 1) a = (1LL*a*x) % MOD;
    x = (1LL*x*x) % MOD;
    k >>= 1;
  }
  return a;
}

int inv(int x) {
  return modpow(x, MOD-2);
}

int find(int x) {
  if (U[x] == x) return x;
  return U[x] = find(U[x]);
}

void unite(int x, int y) {
  x = find(x), y = find(y);
  if (x == y) return;
  if (R[x] < R[y]) swap(x, y);
  U[y] = x;
  R[x] += R[y];
  R[y] = 0;
}

bool same(int x, int y) {
  return find(x) == find(y);
}

signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> N >> X >> Y;
  fact[0] = 1;
  factinv[0] = 1;
  for (int i=1; i<=N; i++) {
    fact[i] = (1LL*i*fact[i-1]) % MOD;
    factinv[i] = inv(fact[i]);
  }

  rep(i, N) {
    cin >> C[i] >> W[i];
    C[i]--;
    G[C[i]].pb(P(W[i], i));
  }
  vector<P> vs;
  rep(i, N) {
    sort(all(G[i]));
    if (!G[i].empty()) {
      vs.pb(G[i][0]);
    }
  }
  sort(all(vs));
  for (int i=0; i<N; i++) U[i] = i, R[i] = 1;
  rep(i, N) {
    int m = 0;
    if (C[vs[0]._2] == C[i]) {
      if (vs.size() <= 1) continue;
      m = 1;
    }
    if (vs[m]._1 + W[i] <= Y) unite(i, vs[m]._2);
  }
  rep(i, N) {
    if (G[i].size() <= 1) continue;
    int lim = X - G[i][0]._1;
    for (int j=1; j<G[i].size(); j++) {
      if (G[i][j]._1 > lim) break;
      unite(G[i][0]._2, G[i][j]._2);
    }
  }

  int rt = find(vs[0]._2);
  int ans = fact[R[rt]];
  rep(i, N) {
    if (find(i) == rt) ctr[C[i]]++;
  }
  rep(i, N) {
    ans = (1LL*ans*factinv[ctr[i]]) % MOD;
  }
  cout << ans << "\n";
  return 0;
}

