const int N = 200005, mo = 1000000007, inf = mo ; 
using namespace std ;

map <int, map<int, int> > h ;
int n, X, Y, inv[N], fa[N], ml[N], mr[N], b[N], fac[N], f[N], tot[N] ;
struct poi {
	int c, w ;
} a[N] ;

bool cmp(poi a, poi b) {
	return (a.c < b.c || (a.c == b.c && a.w < b.w)) ;
}

int getfa(int x) {
	return fa[x] == x ? x : fa[x] = getfa(fa[x]) ;
}

void merge(int x, int y) {
	x = getfa(x), y = getfa(y) ;
	if (x != y) fa[x] = y ; 
}

void pre(int l, int r) {
	int mn = min(ml[l - 1], mr[r + 1]) ;
	rep(i, l + 1, r) if (mn + a[i].w <= Y) {
		merge(i, i - 1) ;
	}
	per(i, r, l) if (a[l].w + a[i].w <= X) {
		merge(l, i) ;
	}
}

bool _cmp(int x, int y) {
	return a[x].w < a[y].w ;
}

void solve() {
	sort(b + 1, b + b[0] + 1, _cmp) ;
	int top = 1 ;
	per(i, b[0], 1) {
		for ( ; top <= i && a[b[top]].w + a[b[i]].w <= Y ; ++ top) {
			if (top - 1) merge(b[top], b[top - 1]) ;
		}
		if (top > i) break ;
		if (top - 1) merge(b[i], b[top - 1]) ;
	}
}

inline int mul(int a, int b) {
	int ans = 1, w = a % mo ;
	for ( ; b; b /= 2) {
		if (b & 1) ans = (ll) ans * w % mo ;
		w = (ll) w * w % mo ;
	}
	return ans ;
}


int main() {
	scanf("%d%d%d", &n, &X, &Y) ;
	rep(i, 1, n) {
		scanf("%d%d", &a[i].c, &a[i].w) ;
		fa[i] = i ;
	}
	sort(a + 1, a + n + 1, cmp) ;
	ml[0] = mr[n + 1] = inf ;
	rep(i, 1, n) ml[i] = min(ml[i - 1], a[i].w) ;
	per(i, n, 1) mr[i] = min(mr[i + 1], a[i].w) ;
	b[0] = 0 ;
	for (int i = 1, j; i <= n; i = j) {
		for (j = i + 1; j <= n && a[i].c == a[j].c; ++ j) ;
		pre(i, j - 1) ;
		b[++ b[0]] = i ; 
	}
	solve() ;
	int ans = 1 ;
	rep(i, 1, n) tot[i] = 0, f[i] = 1 ;
	fac[0] = inv[0] = 1 ;
	rep(i, 1, n) fac[i] = (ll) fac[i - 1] * i % mo ;
	rep(i, 1, n) inv[i] = mul(fac[i], mo - 2) ;
	rep(i, 1, n) {
		int u = getfa(i) ;
		++ tot[u] ;
		f[u] = (ll) f[u] * inv[tot[u] - 1] % mo ;
		f[u] = (ll) f[u] * fac[tot[u]] % mo ;
		f[u] = (ll) f[u] * fac[h[u][a[i].c]] % mo ;
		++ h[u][a[i].c] ;
		f[u] = (ll) f[u] * inv[h[u][a[i].c]] % mo ;
	}
	rep(i, 1, n) if (getfa(i) == i) 
		ans = (ll) ans * f[i] % mo ;
	printf("%d\n", ans) ;
	return 0 ; 
}

