int get(int x) {
  return x == p[x] ? x : p[x] = get(p[x]);
}

void unite(int x, int y) {
  x = get(x);
  y = get(y);
  if (x == y) {
    return;
  }
  if (ts[x] < ts[y]) {
    swap(x, y);
  }
  p[y] = x;
  ts[x] += ts[y];
  for (int i = 0; i < sz(comp[y]); i++) {
    comp[x].push_back(comp[y][i]);
  }
  comp[y].clear();
}

void solve() {
  for (int i = 0; i < n; i++) {
    sort(a[i].begin(), a[i].end());
    cs[i] = make_pair(a[i].empty() ? inf : a[i][0].first, i);
  }
  sort(cs, cs + n);
  for (int i = 0; i < n; i++) {
    p[i] = i;
    ts[i] = 1;
    comp[i].clear();
    comp[i].push_back(c[i]);
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < sz(a[i]); j++) {
      if (a[i][j].first + a[i][0].first <= x) {
        unite(a[i][j].second, a[i][0].second);
      }
      if (cs[0].second != i) {
        if (a[i][j].first + a[cs[0].second][0].first <= y) {
          unite(a[cs[0].second][0].second, a[i][j].second);
        }
      } else {
        if (cs[1].first != inf) {
          if (a[i][j].first + a[cs[1].second][0].first <= y) {
            unite(a[cs[1].second][0].second, a[i][j].second);
          }
        }
      }
    }
  }
  int res = 1;
  for (int it = 0; it < n; it++) {
    if (p[it] != it) {
      continue;
    }
    auto &comp = ::comp[it];
    sort(comp.begin(), comp.end());
    res = mul(res, f[ts[it]]);
    for (int r = 0; r < sz(comp);) {
      int l = r;
      while (r < sz(comp) && comp[r] == comp[l]) {
        r++;
      }
      res = mul(res, finv[r - l]);
    }
  }
  printf("%d\n", res);
}

