long long int ipow(long long int e, long long int a) {
    if (e == 0) return 1;
    if (e == 1) return a;
    if (e & 1) return ((ipow(e - 1, a) * a) % 1000000007);
    long long v = ipow(e / 2, a);
    return (v * v) % 1000000007;
}

int main() {
