using namespace std;

typedef long long ll;


int add(int a, int b)
{
    ll x = a+b;
    if(x >= mod)
        x -= mod;
    if(x < 0)
        x += mod;
    return x;
}
ll mul(ll a, ll b)
{
    return (a*b) % mod;
}

ll pw(ll a, ll b)
{
    ll ans = 1;
    while(b)
    {
        if(b & 1)
            ans = (ans * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return ans;
}

int n, x, y;
pair<int, int> p[200002];
vector<int>cols[200002];
vector<int>v[200002];

ll fact[200002], inv[200002];

bool cmp(int a, int b)
{
    return p[a].se < p[b].se;
}

bool viz[200002];
bool is[200002];
int fr[200002], nr;
vector<int>col;

void dfs(int nod)
{
    if(fr[p[nod].fi] == 0)
        col.pb(p[nod].fi);
    ++fr[p[nod].fi];
    ++nr;
    viz[nod] = 1;
    for(int i = 0; i < v[nod].size(); ++i)
    {
        int vecin = v[nod][i];
        if(!viz[vecin])
            dfs(vecin);
    }
}
ll sol(int start_point)
{
    ll ans = 1;
    nr = 0;
    col.clear();
    dfs(start_point);
    ans = fact[nr];
 //   cout << ans << " " << start_point << " " << nr << '\n';
    for(int i = 0; i < col.size(); ++i)
    {
      //  cout << col[i] << " " << fr[col[i]] << '\n';
        ans = mul(ans, inv[fr[col[i]]]), fr[col[i]] = 0;
      //  cout << ans << '\n';
    }
    return ans;
}
int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> n >> x >> y;
    for(int i = 1; i <= n; ++i)
    {
        cin >> p[i].fi >> p[i].se;
        cols[p[i].fi].pb(i);
    }
    fact[0] = inv[0] = 1;
    for(int i = 1; i <= n; ++i)
    {
        fact[i] = mul(fact[i-1], i);
        inv[i] = pw(fact[i], mod - 2);
    }

    // build edges from nodes with same color

    for(int i = 1; i <= n; ++i)
    {
        sort(cols[i].begin(), cols[i].end(), cmp);
        int pz = 1;
        while(pz < cols[i].size() && p[cols[i][0]].se + p[cols[i][pz]].se <= x)
        {
            v[cols[i][0]].pb(cols[i][pz]);
            v[cols[i][pz]].pb(cols[i][0]);
            ++pz;
        }
    }

    // build edges from nodes with different color

    vector<int>mv;
    for(int i = 1; i <= n; ++i)
        mv.pb(i);
    sort(mv.begin(), mv.end(), cmp);
    int rms = 100;
    for(int i = 0; i < (int)mv.size(); ++i)
    {
        if(viz[p[mv[i]].fi])
            continue;
        --rms;
        viz[p[mv[i]].fi] = 1;
        for(int j = i+1; j < mv.size(); ++j)
            if(p[mv[i]].fi != p[mv[j]].fi && p[mv[i]].se + p[mv[j]].se <= y)
            {
                v[mv[i]].pb(mv[j]);
                v[mv[j]].pb(mv[i]);
            }
        if(rms == 0)
            break;
    }
    memset(viz, 0, sizeof(viz));
    ll ans = 1;
    for(int i = 1; i <= n; ++i)
