        if(ar[i].color != ar[1].color)
            mn = min(mn, i);
    }
    if(mn != 1e9)
    for(int i = 1; i <= n; i++)
        if(ar[i].color == ar[1].color && ar[mn].w + ar[i].w <= y)
            dsu[get_dsu(ar[i].ind)] = get_dsu(ar[mn].ind);

    for(int i = 1; i <= n; i++)
    {
        kol[get_dsu(i)]++;
        vc[get_dsu(i)].push_back(ar[i].color);
    }


    long long ans = 1;
    for(int i = 1; i <= n; i++)
    {
        if(dsu[i] == i)
        {
            long long k = 1;
            for(long long j = 0; j < kol[i]; j++)
            {
                k *= (j + 1);
                k = k % mod;
            }
            int l = 0, r = 0;
            sort(vc[i].begin(), vc[i].end());
            while(vc[i].size() > l)
            {
                while(vc[i][l] == vc[i][r + 1] && r < vc[i].size() - 1)
                {
                    r++;
                }
                k = k * binpow(f[r - l + 1], mod - 2) % mod;
                l = r + 1;
            }
            //cout << i << " " << k << endl;
            ans = ans * k % mod;
        }
    }
    cout << 1;
    return 0;
}

