inline void solve()
{
	static vector<int> id[MAXN + 5];
	static int mn[MAXN + 5], mn_id[MAXN + 5];

	for(int i = 1; i <= n; ++i) mn[i] = INF;
	for(int i = 1; i <= n; ++i)
	{
		id[c[i]].push_back(i);
		if(chkmin(mn[c[i]], w[i])) mn_id[c[i]] = i;
	}

	int p = 0, q = 0;
	mn[0] = INF;
	for(int i = 1; i <= n; ++i)
	{
		if(mn[i] < mn[p]) q = p, p = i;
		else if(mn[i] < mn[q]) q = i;
	}

	for(int k = 1; k <= n; ++k)
	{
		int r = mn_id[k], t = mn_id[p == k ? q : p];
		for(auto i : id[k])
		{
			if(r && w[i] + w[r] <= X)
