			if(t && w[i] + w[t] <= Y)
			{
				adj[t].push_back(i);
				adj[i].push_back(t);
			}
		}
	}

	int ans = 1;
	for(int i = 1; i <= n; ++i) if(!vis[i])
	{
		++cur, col.clear(), dfs(i);

