int find (int x) { return x == f[x] ? x : f[x] = find(f[x]); }

void Merge (int x, int y) { f[find(x)] = find(y); }

int qp (int a, int b) { int c = 1; for (; b; b >>= 1, a = 1ll * a * a % P) if (b & 1) c = 1ll * c * a % P; return c; }

int mi1, mi2;

int main () {
	scanf("%d%d%d", &n, &x, &y);
