		if(Mn[i]<Mn[M])
			M=i;
	for(i=1;i<=N;i++)
		if(C[i]^M)
			mn=min(mn,W[i]);
	for(i=1;i<=N;i++){
		if(W[i]^Mn[C[i]]&&W[i]+Mn[C[i]]<=X)
			continue;
		if(W[i]+(C[i]^M?Mn[M]:mn)<=Y)
			continue;
		Cnt[C[i]]--;
	}
	Inv[0]=Inv[1]=1;
	for(i=2;i<=N;i++)
		Inv[i]=1llu*(Mod-Mod/i)*Inv[Mod%i]%Mod;
