class Euclid {
private:
	ll m, n;
	vvll mx_multiply(vvll mx1, vvll mx2) {
		int l = mx1.size();
		int m = mx1[0].size();
		int n = mx2[0].size();
		vvll ret(l, vll(n, 0));
		Loop(i, l) {
			Loop(j, n) {
				Loop(k, m) {
					ret[i][j] += mx1[i][k] * mx2[k][j];
				}
			}
		}
		return ret;
	}
public:
	ll x, y, gcd;
	Euclid(ll M, ll N) {
		m = M;
		n = N;
	}
	//mx+ny=gcd(m,n)であるx,yを求める
	void mainfunc() {
		vll r(100), k(100);
		bool swapflag = false, mflag = false, nflag = false;
		if (m < n) { swap(m, n); swapflag = true; }
		if (m < 0) { m *= -1; mflag = true; }
		if (n < 0) { n *= -1; nflag = true; }
		r[0] = m;
		r[1] = n;
		int h = 1; //rの数
		while (1) {
			k[h - 1] = r[h - 1] / r[h];
			r[h + 1] = r[h - 1] % r[h];
			if (r[h + 1] == 0) break;
			h++;
		}
		gcd = r[h];
		vvll mx(2, vll(2, 1));
		mx[0][0] = 0;
		mx[1][1] = (-1) * k[0];
		Loop1(i, h - 1) {
			vvll multiplier(2, vll(2, 1));
			multiplier[0][0] = 0;
			multiplier[1][1] = (-1) * k[i];
			mx = mx_multiply(multiplier, mx);
		}
		x = mx[0][0];
		y = mx[0][1];
		if (nflag) { n *= -1; y *= -1; }
		if (mflag) { m *= -1; x *= -1; }
		if (swapflag) {	swap(m, n); swap(x, y); }
	}
};

//x! O(x)
vll mod_factorial(ll x, ll mod) {
	if (x < 0) return{};
	else {
		vll ret((int)x + 1);
		ret[0] = 1;
		Loop1(i, (int)x) ret[i] = ret[i - 1] * i % mod;
		return ret;
	}
}

//p!/(Πary!)  O(p+log(Σary))
ll mod_multicombination(ll p, vll ary, ll mod) {
	vll fact = mod_factorial(p, mod);
	p = fact[(int)p];
	Loop(i, ary.size()) ary[i] = fact[(int)ary[i]];
	ll q = 1;
	Loop(i, ary.size()) q = q * ary[i] % mod;
	Euclid *euclid = new Euclid(q, mod * (-1));
	euclid->mainfunc();
	ll r = euclid->x;
	if (r < 0) r += mod;
	return p * r % mod;
}

class Union_Find {
private:
	vll p, r;
public:
	Union_Find(ll N) {
		p.resize(N);
		r.resize(N);
		Loop(i, N) {
			p[i] = i;
			r[i] = 0;
		}
	}
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (r[x] < r[y]) p[x] = y;
		else {
			p[y] = x;
			if (r[x] == r[y]) r[x]++;
		}
	}
	bool same(ll x, ll y) {
		return find(x) == find(y);
	}
	int find(ll x) {
		if (p[x] == x) return x;
		else return p[x] = find(p[x]);
	}
};


ll n, x, y;
vll c, w;

void solve() {
	map<ll, ll> mp1; //色→最小重量をもつindex
	ll min_index = 0; //全てのボールの最小重量をもつindex
	Loop(i, n) {
		if (mp1.find(c[i]) == mp1.end()) mp1[c[i]] = i;
		else if (w[mp1[c[i]]] > w[i]) mp1[c[i]] = i;
		if (w[min_index] > w[i]) min_index = i;
	}
	//unionfindにより可換indexを連結
	Union_Find *uf = new Union_Find(n);
	//操作1
	Loop(i, n) {
		if (w[i] + w[mp1[c[i]]] <= x) {
			uf->unite(i, mp1[c[i]]);
		}
	}
	//操作2
	Loop(i, n) {
		if (w[i] + w[min_index] <= y) {
			uf->unite(i, min_index);
		}
	}
	//計算の準備
	map<ll, vll> mp2;
	ll ans = 1;
	ll mod = 1e9 + 7;
	Loop(i, n) {
		mp2[uf->find(i)].push_back(i);
	}
	for (auto itr = mp2.begin(); itr != mp2.end(); itr++) {
		map<ll, ll> mp3;
		Loop(i, (*itr).second.size()) {
			int index = (*itr).second[i];
			mp3[c[index]]++;
		}
		vll ary;
		ll sum = 0;
		for (auto itr2 = mp3.begin(); itr2 != mp3.end(); itr2++) {
			ary.push_back((*itr2).second);
			sum += (*itr2).second;
		}
		ans = ans*mod_multicombination(sum, ary, mod) % mod;
	}
	cout << ans << endl;
}

int main() {
	cin >> n >> x >> y;
	c.resize(n);
	w.resize(n);
	Loop(i, n) cin >> c[i] >> w[i];
	solve();
	return 0;
}

