}

inline void uni(int x, int y) {
  // cout << x << " " << y << "\n";
  int fx = find(x), fy = find(y);
  if(fx == fy) return ;
  if((int) mp[fx].size() < (int) mp[fy].size())
    swap(fx, fy);
  pre[fy] = fx;
  for(auto v: mp[fy])
    mp[fx][v.first] += v.second;
  mp[fy].clear();
}

inline int gao(int id) {
  int ans = 1;
  int tot = 0;
  for(auto v: mp[id]) {
    ans = mul(ans, fac_inv[v.second]);
    tot += v.second;
  }
  ans = mul(ans, fac[tot]);
  return ans;
}

