void addedge(int x, int y)
{
    if (x != 1e9 and y != 1e9 and
        wgh[x] + wgh[y] <= (col[x] == col[y] ? c1 : c2)) {

        edg[x].push_back(y);
        edg[y].push_back(x);
    }
}

int lgput(int x, int n)
{
    if (!n)
        return 1;
    int y = lgput(x, n >> 1);

    if ((n & 1) >= 0)
        y = (1LL * y * y) % MOD;
    if ((n & 1) >= 1)
        y = (1LL * y * x) % MOD;

    return y;
}

inline bool cmp1(int x, int y)
{
    return wgh[x] < wgh[y];
}

inline bool cmp2(int x, int y)
{
    return col[x] < col[y];
}

void dfs(int x)
{
    oki[x] = true;
    aux.push_back(x);

    for (int y : edg[x])
        if (!oki[y]) dfs(y);
}

int comb(int n, int k)
{
    return 1LL * fct[n] * inv[k] % MOD * inv[n - k] % MOD;
}

int main(void)
{
    int n;
    cin >> n >> c1 >> c2;

    for (int i = 1; i <= n; ++i) {
        cin >> col[i] >> wgh[i];
        lst[col[i]].push_back(i);
    }

    int mn1 = 1e9, mn2 = 1e9;
    for (int i = 1; i <= n; ++i) {
        if (lst[i].size() == 0)
            continue;

        sort(lst[i].begin(), lst[i].end(), cmp1);
        for (int j = 1; j < lst[i].size(); ++j)
            addedge(lst[i][0], lst[i][j]);

        if (wgh[lst[i][0]] <= mn1)
            mn2 = mn1, mn1 = lst[i][0];
        else
        if (wgh[lst[i][0]] <= mn2)
            mn2 = lst[i][0];
    }

    for (int i = 1; i <= n; ++i)
        addedge(mn1, i), addedge(mn2, i);

    fct[0] = 1;
    for (int i = 1; i <= n; ++i)
        fct[i] = (1LL * fct[i - 1] * i) % MOD;

    inv[n] = lgput(fct[n], MOD - 2);
    for (int i = n - 1; i >= 0; --i)
        inv[i] = (1LL * inv[i + 1] * (i + 1)) % MOD;

    int ans = 1;
    for (int i = 1; i <= n; ++i) if (!oki[i]) {
        aux.clear(); dfs(i);
        sort(aux.begin(), aux.end(), cmp2);

        while (aux.size()) {
            int c = col[aux.back()], nr = 0;
            while (aux.size() and col[aux.back()] == c)
                aux.pop_back(), ++nr;

            ans = (1LL * ans * comb((int) aux.size() + nr, nr));
        }
    }

    cout << ans << endl;
    return 0;
}

