struct UF{
	vector<int> belong;
	vector<int> size;
	void resize(int n){
		belong.assign(n + 1, -1);
		size.assign(n + 1, 1);
	}
	inline int root(int b){
		if (belong[b] == -1){
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b){
		a = root(a);
		b = root(b);
		if (a == b)return;
		belong[a] = b;
		size[b] += size[a];
	}
};

UF uf;

map<int, int> val[MAX];

vector<int> root;


#define MOD 1000000007
long long int ppow(long long int i, long long int j){
	long long int res = 1LL;
	while (j){
		if ((j & 1LL)){
			res *= i;
			if (res >= MOD){
				res %= MOD;
			}
		}
		j >>= 1;
		i *= i;
		if (i >= MOD){
			i %= MOD;
		}
	}
	return res;
}

long long int k[MAX];
long long int rk[MAX];

int pr[MAX];

vector<int> ich[MAX];

int dif_step(int cur, int col){
	if (cur == 0)return -1;
	cur--;
	if (v[cur].second != col)return cur;
	return pr[cur];
}

int upd[MAX];

int main(){
	k[0] = 1;
	for (int i = 1; i < MAX; i++){
		k[i] = k[i - 1];
		k[i] *= (long long int)(i);
		k[i] %= MOD;
		rk[i] = ppow(k[i], MOD - 2);
	}
	cin >> n;
	cin >> x >> y;
	for (int i = 0; i < n; i++){
		int c, w;
		scanf("%d%d", &c, &w);
		v.push_back(make_pair(w, c));
	}
	uf.resize(n);
	sort(v.begin(), v.end());
	memset(upd, -1, sizeof(upd));
	int idx = -1;
	for (int i = 0; i < v.size(); i++){
		if (i == 0 || v[i - 1].second != v[i].second){
			pr[i] = i-1;
		}
		else{
			pr[i] = pr[i - 1];
		}
		ich[v[i].second].push_back(i);
		if (ich[v[i].second].size()>1){
			int j = ich[v[i].second][0];
			if (v[i].first + v[j].first <= x){
				uf.merge(i, j);
			}
		}
		while (idx + 1 < i&&v[idx + 1].first + v[i].first <= y){
			idx++;
		}
		while (idx >= 0 && v[idx].first + v[i].first > y){
			idx--;
		}
		int cur = idx+1;
		while(cur>=0){
			cur = dif_step(cur, v[i].second);
			if (cur < 0)break;
			int j = cur;
			if (v[i].first + v[j].first <= y){
				uf.merge(i, j);
				if (upd[j] == -1){
					upd[j] = v[i].second;
				}
				else{
					break;
				}
			}
		}
	}
	for (int i = 0; i < v.size(); i++){
		val[uf.root(i)][v[i].second]++;
		root.push_back(uf.root(i));
	}
	sort(root.begin(), root.end());
	root.erase(unique(root.begin(), root.end()), root.end());
	long long int ans = 1;
	for (int i = 0; i < root.size(); i++){
		long long int up = k[uf.size[root[i]]];
		int num = root[i];
		for (auto it = val[num].begin(); it != val[num].end(); it++){
			up *= rk[(*it).second];
			up %= MOD;
		}
		ans *= up;
		ans %= MOD;
	}
	printf("%lld\n", ans);
	return 0;
}

