		for (auto x : cnt[i]) {
			sum += x.second;
			tmp = 1ll * tmp * power(fac[x.second], mod - 2) % mod;
		}
		ans = 1ll * ans * fac[sum] % mod;
		ans = 1ll * ans * tmp % mod;
	}
	printf("%d\n", ans);
	return 0;
}

