            }
            else {
                if (w[q] + w[it.second] <= y) {
                    g[q].emplace_back(it.second);
                    g[it.second].emplace_back(q);
                }
            }
        }
        if (!has && r.size() < 3) r.emplace_back(it.second);
    }
    for (auto it : r) {
        for (int i = 1; i <= n; i++) {
            if (it == i) continue;
            if (c[it] == c[i]) continue;
            if (w[it] + w[i] <= y) {
                g[it].emplace_back(i);
                g[i].emplace_back(it);
            }
        }
