	add_edges(1, n, x, y);
	for (int i = 2; i <= n; ++i)
	{
		if (a[i].second != a[1].second)
		{
			add_edges(i, n, x, y);
			break;
		}
	}

	fact[0] = factInv[0] = 1;
	for (int i = 1; i < N; ++i)
	{
		fact[i] = (i * fact[i - 1]) % mod;
		factInv[i] = fastModExp(fact[i], mod - 2);
	}

	ll ans = 1;
	for (int i = 1; i <= n; ++i)
		if (!seen[i])
			ans = bfs(i, ans);

