#include<cstdio>
#include<algorithm>
#include<vector>
#define MAXN 200006
#define MOD 1000000007
using namespace std;
int n,X,Y,c,p,fa[MAXN],cnt,a[MAXN],minone,tot,sum[MAXN],co,mintwo;
long long fac[MAXN],inv[MAXN];
vector<int> v[MAXN];
long long ksm(long long x,int p)
{
	if(!p) return 1;
	long long nex=ksm(x,p/2);
	nex=nex*nex%MOD;
	if(p%2) nex=nex*x%MOD;
	return nex;
}
void waiting()
{
	fac[0]=1;
	for(int i=1;i<MAXN;i++)
		fac[i]=1ll*fac[i-1]*i%MOD;
	inv[MAXN-1]=ksm(fac[MAXN-1],MOD-2);
	for(int i=MAXN-2;i>=0;i--)
		inv[i]=1ll*inv[i+1]*(i+1)%MOD;
}
int root(int x)
{
	if(fa[x]==x) return x;
	fa[x]=root(fa[x]);
	return fa[x];
}
int main()
{
	//freopen("colorball.in","r",stdin);
	//freopen("colorball.out","w",stdout);
	waiting();
	scanf("%d%d%d",&n,&X,&Y);
	for(int i=1;i<=n;i++)
	{
		scanf("%d%d",&c,&p);
		v[c].push_back(p);
		fa[i]=i;
	}
	long long ans;
	for(int i=1;i<MAXN;i++)
		if(v[i].size()) sort(v[i].begin(),v[i].end());
	for(int i=1;i<MAXN;i++)
	{
		for(int j=0;j<(int)v[i].size();j++)
		{
			a[++cnt]=v[i][j];
			v[i][j]=cnt;
			if(a[cnt]-X<=a[cnt-j]) fa[cnt]=cnt-j;
		}
	}
	a[0]=MOD;
	co=0;
	minone=0;
	for(int i=1;i<MAXN;i++)
		if(v[i].size())
		{
			if(a[v[i][0]]<a[minone])
			{
				co=i;
				minone=v[i][0];
			}
		}
	for(int i=1;i<MAXN;i++)
	{
		if(co==i) continue;
		for(int j=0;j<(int)v[i].size();j++)
			if(a[minone]+a[v[i][j]]<=Y) fa[root(v[i][j])]=minone;
	}
	mintwo=0;
	for(int i=1;i<MAXN;i++)
	{
		if(co==i||v[i].size()==0) continue;
		if(a[v[i][0]]<a[mintwo]) mintwo=v[i][0];
	}
	if(a[mintwo]+a[minone]>Y) mintwo=0;
	if(mintwo)
	{
		for(int j=0;j<(int)v[co].size();j++)
			if(a[mintwo]+a[v[co][j]]<=Y) fa[root(v[co][j])]=minone;
	}
	for(int i=1;i<MAXN;i++)
		for(int j=0;j<(int)v[i].size();j++)
			if(root(v[i][j])==minone)
			{
				tot++;
				sum[i]++;
			}
	ans=fac[tot];
	for(int i=1;i<MAXN;i++)
		if(sum[i]) ans=ans*inv[sum[i]]%MOD;
	printf("%lld",ans);
}

