	n=nxi(),lim1=nxi(),lim2=nxi();
	init();
	wgt[0]=mod;
	for(int i=1; i<=n; ++i){
		col[i]=nxi(),wgt[i]=nxi();
		if(!lpos[col[i]]||wgt[lpos[col[i]]]>wgt[i]){
			lpos[col[i]]=i;
		}
	}
	for(int i=1; i<=n; ++i){
		if(i!=lpos[col[i]]&&wgt[i]+wgt[lpos[col[i]]]<=lim1){
			U::link(i,lpos[col[i]]);
		}
	}
	for(int i=1; i<=n; ++i){
