int N, X, Y, Inv[MAX_N], Fast[MAX_N];
int MinL[MAX_N], MinR[MAX_N];
vector<int> Color[MAX_N];
vector<pi> List;

int getMulti(int a, int b) {
	ll res = 1, pow = a;
	while(b) {
		if(b%2 == 1) res *= pow, res %= MOD;
		pow *= pow; pow %= MOD;
		b /= 2;
	}
	return res;
}

int main() {
	scanf("%d%d%d", &N, &X, &Y);
	for(int i=0; i<N; i++) {
		int c, w; scanf("%d%d", &c, &w);
		Color[c].push_back(w);
	}
	for(int c=1; c<=N; c++) {
		sort(Color[c].begin(), Color[c].end());
	}
	MinL[0] = MinR[N+1] = MOD;
	for(int i=1; i<=N; i++)
		MinL[i] = min(MinL[i-1], Color[i].size()>0?Color[i][0]:MOD);
	for(int i=N; i>=1; i--)
		MinR[i] = min(MinR[i+1], Color[i].size()>0?Color[i][0]:MOD);
	for(int c=1; c<=N; c++) {
		int n = (int)Color[c].size();
		for(int i=n-1; i>=1; i--)
			if(Color[c][i] + Color[c][0] > X && MinL[c-1] + Color[c][i] > Y && MinR[c+1] + Color[c][i] > Y)
				Color[c].pop_back();
		if(Color[c].size() == 1)
			if(Color[c][0] > X && MinL[c-1] + Color[c][0] > Y && MinR[c+1] + Color[c][0] > Y)
				Color[c].pop_back();
		if(Color[c].size() != 0) {
			List.emplace_back(Color[c][0], (int)Color[c].size());
		}
	}
	Inv[0] = 1; Fast[0] = 1;
	for(int i=1; i<=N; i++)
		Fast[i] = 1ll * Fast[i-1] * MOD;
	for(int i=1; i<=N; i++)
		Inv[i] = 1ll * Inv[i-1] * getMulti(i, MOD-2) % MOD;


	sort(List.begin(), List.end());
	int LN = (int)List.size();
	for(int i=LN-1; i>=0; i--)
		if(List[i].first + List[0].first > Y)
			List.pop_back();

	int sum = 0;
	for(pi &e : List) sum += e.second;

	int ans = 1;
	for(int i=1; i<=sum; i++)
		ans = 1ll * ans * i % MOD;


	for(pi &e : List)
		ans = 1ll * ans * Inv[e.second] % MOD;

	printf("%d\n", ans);

	return 0;
}

