const int N = 2e5 + 5;
vector<int> g[N];

int fact[N], ifact[N];
int c[N], w[N];
bool vis[N];

map<int, vector<pii>> m;

void add(int u,int v) {
    debug(u, v);
    g[u].pb(v);
    g[v].pb(u);
}

map<int,int> cnt;

int dfs(int u) {
    vis[u] = 1;
    cnt[c[u]]++;
    int s = 1;
    for(int v : g[u]) {
        if(!vis[v]) {
            s += dfs(v);
        }
    }
    return s;
}

void solve() {
	int n, x, y;
    sc(n, x, y);
    fact[0] = 1;
    fr(i, 1, N - 1) {
        fact[i] = (i * 1LL * fact[i - 1]) % mod;
    }
    ifact[N - 1] = pwr(fact[N - 1], mod - 2);
    for(int i = N - 2; i >= 0; i--) {
        ifact[i] = (ifact[i + 1] * 1LL * (i + 1)) % mod;
    }
    fr(i, 1, n) {
        sc(c[i], w[i]);
        m[c[i]].pb({w[i], i});
    }
    vector<pii> glob;
    for(auto &p : m) {
        auto v = p.se;
        sort(all(v));
        glob.pb(v[0]);
        fr(i, 1, sz(v) - 1) {
            if(v[i].fi + v[0].fi <= x) {
                add(v[i].se, v[0].se);
            }
            else {
                glob.pb(v[i]);
            }
        }
    }
    sort(all(glob));
    int p = -1;
    fr(i, 1, sz(glob) - 1) {
        if(c[glob[0].se] != c[glob[i].se] && w[glob[0].se] + w[glob[i].se] <= y) {
            add(glob[0].se, glob[i].se);
        }
        if(c[glob[0].se] != c[glob[i].se] && p == -1) {
            p = glob[i].se;
        }
    }
    if(p != -1)
        fr(i, 0, sz(glob) - 1) {
            if(c[p] != c[glob[i].se] && w[p] + w[glob[i].se] <= y) {
                add(p, glob[i].se);
            }
        }
    int ans = 1;
    fr(i, 1, n) {
        if(!vis[i]) {
            cnt.clear();
            int s = dfs(i);
            ans = (ans * 1LL * fact[s]) % mod;
            for(auto x : cnt) {
                ans = (ans * 1LL * ifact[x.se]) % mod;
            }
        }
    }
    cout << ans;
}

