int tote,FIR[maxn],TO[maxm],NEXT[maxm];
bool vis[maxn];

int power(int x,int k)
{
	int res=1;
	while (k)
	{
		if (k&1) res=(LL)res*x%mo;
		x=(LL)x*x%mo;
		k>>=1;
	}
	return res;
}

void addedge(int u,int v)
{
	TO[++tote]=v;
	NEXT[tote]=FIR[u];
	FIR[u]=tote;
}

void search(int u)
{
	vis[u]=1;
	cnt[c[u]]++;
	q[++q[0]]=c[u];
	for (int p=FIR[u];p;p=NEXT[p])
	{
		int v=TO[p];
		if (!vis[v]) search(v);
	}
}

