template<typename T>inline void check_min(T a,T &b){if(a<b)b=a;}
template<typename T>inline void check_max(T a,T &b){if(a>b)b=a;}

namespace pu
{
	typedef long long ll;
	const int N=201000,MOD=1000000007;
	ll inv(ll x){return x==1?1:(-(MOD/x)*inv(MOD%x)%MOD);}
	ll fact[N],ifact[N];
	ll C(int n,int m){return fact[n]*ifact[m]%MOD*ifact[n-m]%MOD;}

	std::vector<int> V[N];
	int pos[N];
	int n,X,Y;
	void initialize()
	{
		scanf("%d%d%d",&n,&X,&Y);
		for(int i=1,c,x;i<=n;i++)
		{
			scanf("%d%d",&c,&x);
			V[c].push_back(x);
		}
		for(int i=1;i<=n;i++)
			std::sort(V[i].begin(),V[i].end());

		fact[0]=1;
		for(int i=1;i<N;i++)fact[i]=fact[i-1]*i%MOD;
		ifact[N-1]=inv(fact[N-1]);
		for(int i=N-1;i;i--)ifact[i-1]=ifact[i]*i%MOD;
	}
	void getpos()
	{
		int minw=2147483647,w;
		for(int i=1;i<=n;i++)
		{
			if(V[i].empty())continue;
			check_min(w=V[i][0],minw);
			pos[i]=std::upper_bound(V[i].begin(),V[i].end(),X-w)-V[i].begin();
		}
		for(int i=1;i<=n;i++)
		{
			w=std::upper_bound(V[i].begin(),V[i].end(),Y-minw)-V[i].begin();
			if(!w)pos[i]=0;
			else check_max(w,pos[i]);
		}
	}
	ll calc()
	{
		int cnt=0;
		ll ret=1;
		for(int i=1;i<=n;i++)cnt+=pos[i];

		for(int i=1;i<=n;i++)
			ret=ret*C(cnt,pos[i])%MOD,cnt-=pos[i];
		return ret;
	}
	void solve()
	{
		initialize();
		getpos();
		printf("%lld\n",calc());
	}
}
int main()
{
	pu::solve();
	return 0;
}

