	jc[0]=1;
	for (int i=1; i<=n; i++) jc[i]=1ll*i*jc[i-1]%mod;
	inv[n]=quickmi(jc[n],mod-2);
	for (int i=n; i; i--) inv[i-1]=1ll*i*inv[i]%mod;
	for (int i=1; i<=n; i++) scanf("%d%d",&a[i].c,&a[i].v),A[i].ord=i,A[i].v=a[i].c;
	sort(A+1,A+1+n,cmp2); A[0].v=-1; int cnt=0;
	for (int i=1; i<=n; i++)
		if (A[i].v!=A[i-1].v) a[A[i].ord].c=(++cnt);
		else a[A[i].ord].c=cnt;
	sort(a+1,a+1+n,cmp);
	for (int i=1; i<=cnt; i++) c[i].clear();
	for (int i=1; i<=n; i++) c[a[i].c].push_back(i);
	for (int i=1; i<=n; i++) fa[i]=l[i]=r[i]=i,v[i].clear(),v[i].push_back(i);
	for (int i=1; i<=n; i++)
		for (int j=i+1; j<=n&&a[j].v+a[i].v<=Y; j=r[ask(j)]+1)
			if (a[i].c!=a[j].c) unite(i,j);
	for (int i=1; i<=cnt; i++)
	{
		sz=c[i].size();
		for (int j=1; j<sz; j++)
			if (a[c[i][j]].v+a[c[i][0]].v<=X) unite(c[i][j],c[i][0]);
	}
	memset(C,0,sizeof(C));
	ans=1;
	for (int i=1; i<=n; i++)
		if (fa[i]==i) 
		{
			sz=v[i].size();
			for (int j=0; j<sz; j++) C[a[v[i][j]].c]++;
			ans=1ll*ans*jc[sz]%mod;
			for (int j=0; j<sz; j++) ans=1ll*ans*inv[C[a[v[i][j]].c]]%mod,C[a[v[i][j]].c]=0;
		}
	printf("%d\n",ans);
	return 0;
}

