int ksm(int x,int y){
	int i=1;
	for (;y;y>>=1,x=1ll*x*x%mo)
		if (y&1) i=1ll*i*x%mo;
	return i;
}

int main(){
	int n,X,Y;
	scanf("%d%d%d",&n,&X,&Y);
	for (int i=0;i<=n;i++) a[i]=mo;
	for (int i=1;i<=n;i++){
		scanf("%d%d",&c[i],&w[i]);
		if (w[i]<a[c[i]]) a[c[i]]=w[i];
	}
	int c1=0,c2=0;
	for (int i=1;i<=n;i++)
		if (a[i]<a[c1]) c2=c1,c1=i;
			else if (a[i]<a[c2]) c2=i;
	for (int i=1;i<=n;i++)
		if ((c[i]!=c1 && w[i]+a[c1]<=Y)||(c[i]!=c2 && w[i]+a[c2]<=Y)
			||(w[i]+a[c[i]]<=X && a[c[i]]+a[c1]<=Y)) cnt[c[i]]++;
	int ans1=1,ans2=1;
	for (int i=1,j=0;i<=n;i++)
		for (int k=1;k<=cnt[i];k++){
			ans1=1ll*ans1*(++j)%mo;
			ans2=1ll*ans2*k%mo;
		}
	ans1=1ll*ans1*ksm(ans2,mo-2)%mo;
	printf("%d\n",ans1);
}

