const int N = 200005;
const int mod = 1000*1000*1000+7;

int n, x, y, fact[N], ifact[N];
vector<int> g[N];

int power(int a, int n) {
	int result = 1;
	while (n > 0) {
		if (n & 1) {
			result = (1LL * result * a) % mod;
		}
		a = (1LL * a * a) % mod;
		n /= 2;
	}
	return result;
}

int inv(int a) {
	return power(a, mod - 2);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> x >> y;
	REP(i, n) {
		int c, w;
		cin >> c >> w;
		g[c - 1].push_back(w);
	}

	multiset<int> s;
	vector<int> sizes;
	int all = 0;

	REP(i, n) if (!g[i].empty()) {
		sort(g[i].begin(), g[i].end());
		s.insert(g[i][0]);
	}
	REP(i, n) if (!g[i].empty()) {
		int val = x - g[i][0];
		s.erase(s.find(g[i][0]));
		if (!s.empty()) {
			val = max(val, y - (*s.begin()));
		}
		s.insert(g[i][0]);
		int cnt = lower_bound(g[i].begin(), g[i].end(), val) - g[i].begin();
		sizes.push_back(cnt);
		all += cnt;
	}

	fact[0] = ifact[0] = 1;
	for (int i = 1; i <= n; ++i) {
		fact[i] = (1LL * fact[i - 1] * i) % mod;
		ifact[i] = inv(fact[i]);
	}

	int result = fact[all];
	for(auto& item : sizes) {
		result = (1LL * result * ifact[item]) % mod;
	}

	cout << result << '\n';

	return 0;
}

