	return w[a]<w[b];
}
void ins (int a,int b){
	//cout<<a<<" "<<b<<" "<<w[a]<<" "<<w[b]<<endl;
	int t1=getfather(a),t2=getfather(b);
	if(t1!=t2)father[t2]=t1;
}
void check(int a,int b){
	if(c[a]!=c[b]&&w[a]+w[b]<=y)ins(b,a);
	if(c[a]==c[b]&&w[a]+w[b]<=x)ins(b,a);
}
