const int N = 2e5 + 5, mo = 1e9 + 7, inf = 1e9;
int n, X, Y;
ll ans, fac[N], ivf[N], inv[N];
vector <int> co[N];
pair <int, int> mn, smn, tmp;
vector <pair <int, int> > rec;
set <pair <int, int> > S;

void prep () {
	fac[0] = 1, ivf[0] = 1;
	fac[1] = ivf[1] = inv[1] = 1;
	for (int i = 2; i <= n; ++i) {
		fac[i] = fac[i - 1] * i % mo;
		inv[i] = mo - 1ll * mo / i * inv[mo % i] % mo;
		ivf[i] = ivf[i - 1] * inv[i] % mo;
	}
	mn = smn = make_pair(inf, 0);
}
int main (){
	cin >> n >> X >> Y, ans = 1, prep();
	for (int i = 1, x, y; i <= n; ++i) {
		scanf("%d%d", &x, &y), co[x].push_back(y);
		S.insert(make_pair(y, x));
	}
	int tot = 0;
	for (int i = 1; i <= n; ++i) {
		if (!(int)co[i].size())
			continue;
		sort(co[i].begin(), co[i].end());
		int M = co[i][0], C = 0;
		for ( ; !S.empty(); ) {
			tmp = *S.begin();
			if (tmp.se == i)
				rec.push_back(tmp), S.erase(tmp);
			else
				break;
		}
		if (!S.empty() && tmp.fi + M <= Y) {
			C = 1;
			for (int j = 1; j < co[i].size(); ++j)
				C += (co[i][j] + M <= X);
			tot += C;
			ans = ans * ivf[C] % mo;
		}
		for (auto x : rec)
			S.insert(x);
		rec.clear();
	}
	ans = ans * fac[tot] % mo;
	cout << ans << endl;
	return 0;
}

