void read(int &x)
{
    x=0;
    char ch=getchar();
    int pd=1;
    while(ch<'0'||ch>'9')
    {
        if(ch=='-')
        {
            pd=-pd;
        }
        ch=getchar();
    }
    while(ch<='9'&&ch>='0')
    {
        x=x*10+ch-'0';
        ch=getchar();
    }
    x*=pd;
}
void write(const int &x)
{
    char f[100001];
    int s=0;
    int tmp=x;
    if(tmp==0)
    {
        putchar('0');
        return;
    }
    if(tmp<0)
    {
        tmp=-tmp;
        putchar('-');
    }
    while(tmp>0)
    {
        f[s++]=tmp%10+'0';
        tmp/=10;
    }
    while(s>0)
    {
        putchar(f[--s]);
    }
}

const int mod=1e9+7;
const int N=2e5+10;
int jie[N],ni[N],n,A,B;
int c[N],w[N],minn[N],cnt[N];
int sum,ans=1;
int ksm(int x,int y)
{
	int ans=1;
	while(y)
	{
		if(y&1)
		{
			ans=(ans*x)%mod;
		}
		x=(x*x)%mod;
		y>>=1;
	}
	return ans%mod;
}
int zuhe(int x,int y)
{
	return ((jie[x]*ni[y])%mod*ni[x-y])%mod;
}
signed main()
{
//	freopen("keep.in","r",stdin);
//	freopen("keep.out","w",stdout);
	jie[0]=1;
	read(n);
	read(A);
	read(B);
	for(register int i=1;i<=n;++i)
	{
		read(c[i]);
		read(w[i]);
		minn[i]=big;
		cnt[c[i]]++;
		jie[i]=jie[i-1]*i%mod;
	}

	ni[n]=ksm(jie[n],mod-2);
	for(register int i=n-1;i>=0;--i)
	{
		ni[i]=(ni[i+1]*(i+1))%mod;
//		cout<<ni[i]<<endl;
	}

//	cout<<zuhe(3,1)<<"   QWQ"<<endl;
	for(register int i=1;i<=n;++i)
	{
		minn[c[i]]=min(minn[c[i]],w[i]);
	}
	int min1=0,allmin=0;
	for(register int i=1;i<=n;++i)
	{
		if(minn[i]!=big)
		{
			if(!min1||minn[i]<minn[min1])
			{
				allmin=min1;
				min1=i;
			}
			else 
			{
				if(!allmin||minn[i]<minn[allmin])
				{
					allmin=i;
				}
			}
		}
	}
	for(register int i=1;i<=n;++i)
	{
		if(minn[c[i]]!=w[i]&&w[i]+minn[c[i]]<=A)continue;
		if(c[i]==min1&&w[i]+minn[allmin]<=B)continue;
		if(c[i]!=min1&&w[i]+minn[min1]<=B)continue;
		cnt[c[i]]--;
	}
	sum=cnt[min1];
	for(register int i=1;i<=n;++i)
	{
		if(i!=min1&&minn[i]+minn[min1]<=B)
		{
			sum+=cnt[i];
//			cout<<sum<<endl;
			ans=(ans*zuhe(sum,cnt[i]))%mod;
//			cout<<ans<<endl;
		}
	}
	write(ans);
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, x, y; scanf("%d%d%d", &n, &x, &y);
    vector<int> c(n), w(n);
    vector<vector<int>> ball(n);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", &c[i], &w[i]);
        c[i]--;
        ball[c[i]].push_back(i);
    }
    vector<int> uf(n);
    for (int i = 0; i < n; ++i) uf[i] = i;

    function<int(int)> Find = [&](int x) {
        if (x == uf[x]) return x;
        return uf[x] = Find(uf[x]);
    };

    auto Merge = [&](int x, int y) {
        uf[Find(x)] = Find(y);
    };

    vector<int> pv;
    for (int i = 0; i < n; ++i) {
        if (ball[i].empty()) continue;
        sort(ball[i].begin(), ball[i].end(), [&](int x, int y) { return w[x] < w[y]; });
        for (int j = 1; j < ball[i].size(); ++j) {
            if (w[ball[i][j]] + w[ball[i][0]] > x) break;
            Merge(ball[i][j], ball[i][0]);
        }
        pv.push_back(ball[i][0]);
    }

    sort(pv.begin(), pv.end(), [&](int i, int j) { return w[i] < w[j]; });
    for (int i = 1; i < pv.size(); ++i) {
        if (w[pv[i]] + w[pv[0]] > y) break;
        Merge(pv[i], pv[0]);
    }

    for (int i = 0; i < n; ++i) {
        int j = -1;
        for (int d = 20; d >= 0; --d) {
            if (j + (1 << d) >= pv.size()) continue;
            if (w[pv[j + (1 << d)]] + w[i] <= y) j += (1 << d);
        }
        if (j != -1) Merge(i, pv[j]);
    }

    // for (int i = 0; i < n; ++i) {
        // for (int j = 0; j < n; ++j) {
            // if (j == c[i] || ball[j].empty()) continue;
            // if (w[ball[j][0]] + w[i] <= y) Merge(ball[j][0], i);
        // }
    // }

    vector<map<int, int>> cnt(n);
    for (int i = 0; i < n; ++i) cnt[Find(i)][c[i]]++;

    constexpr int kMod = 1'000'000'000 + 7;

    auto fpow = [&](int a, int n) {
        int res = 1;
        while (n > 0) {
            if (n & 1) res = 1LL * res * a % kMod;
            a = 1LL * a * a % kMod;
            n >>= 1;
        }
        return res;
    };

    vector<int> fc(n + 1, 1), iv(n + 1, 1);
    for (int i = 1; i <= n; ++i) fc[i] = 1LL * fc[i - 1] * i % kMod;
    iv[n] = fpow(fc[n], kMod - 2);
    for (int i = n - 1; i > 0; --i) iv[i] = 1LL * iv[i + 1] * (i + 1) % kMod;

    int ans = 1;
    for (int i = 0; i < n; ++i) {
        if (Find(i) != i) continue;
        int s = 0, p = 1;
        for (auto it : cnt[i]) {
            s += it.second;
            p = 1LL * p * iv[it.second] % kMod;
        }
        p = 1LL * p * fc[s] % kMod;
        ans = 1LL * ans * p % kMod;
    }
    printf("%d\n", ans);
    return 0;
}

