typedef long long llint;

const int MAXN = 200010;
const int MOD = 1e9 + 7;

llint mpow(int a, int m) {
  if (m == 0) return 1;
  if (!(m & 1)) {
    llint t = mpow(a, m / 2);
    return t * t % MOD;
  }
  return mpow(a, m - 1) * a % MOD;
}

int n, x, y, f[MAXN], inv[MAXN], bio[MAXN];
pii p[MAXN];
vector<int> cols, e[MAXN];
llint sol = 1;

void dfs(int i) {
  cols.push_back(p[i].c);
  bio[i] = 1;

  for (int j : e[i])
    if (!bio[j])
      dfs(j);
}

int main(void) {
  f[0] = inv[0] = 1;
  FOR(i, 1, MAXN) {
    f[i] = (llint)f[i - 1] * i % MOD;
    inv[i] = mpow(f[i], MOD - 2);
  }

  scanf("%d %d %d",&n,&x,&y);
  REP(i, n) scanf("%d %d",&p[i].c,&p[i].w);

  sort(p, p + n);
  int prv = -1;

  REP(i, n)
    if (prv == -1 || p[i].c != p[prv].c) {
      REP(j, n) 
	if ((p[i].c == p[j].c && p[i].w + p[j].w <= x) ||
	    (p[i].c != p[j].c && p[i].w + p[j].w <= y)) {
	  e[i].push_back(j);
	  e[j].push_back(i);
	}
      if (prv != -1) break;
    }

  REP(i, n) {
    if (bio[i]) continue;
    cols.clear();
    dfs(i);
    sort(cols.begin(), cols.end());

    int k = (int)cols.size();

    sol = sol * f[k] % MOD;
    int curr = 0;
    REP(j, k) {
      ++curr;
      if (j == k-1 || cols[j] != cols[j+1]) {
	sol = sol * inv[curr] % MOD;
	curr = 0;
      }
    }
  }

  cout << sol << endl;

  return 0;
}

