const int MAX = (2e5)+1;
const long long MOD = (1e9)+7;

int n, x, y, c[MAX], w[MAX];
bool mark[MAX];
long long ans = 1, fact[MAX];
vector<int> p, el[MAX], a;
set<pair<int,int> > same[MAX], okd;

long long modPow(long long b, long long e) {
	long long ret = 1;
	while(e) {
		if(e & 1) ret = (ret*b)%MOD;
		b = (b*b)%MOD;
		e >>= 1;
	}
	return ret;
}

int root(int v) { return (p[v] == v ? v : p[v] = root(p[v])); }

void merge(int u, int v) {
	if((u = root(u)) == (v = root(v))) return;
	if(el[u].size() < el[v].size()) swap(u, v);
	el[u].insert(el[u].end(), el[v].begin(), el[v].end());
	el[v].clear();
	p[v] = u;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n >> x >> y;
	fact[0] = 1;
	for(int i = 1; i <= n; i++) fact[i] = (fact[i-1]*i)%MOD;
	a.resize(n);
	p.resize(n);
	iota(a.begin(), a.end(), 0);
	iota(p.begin(), p.end(), 0);
	for(int i = 0; i < n; i++) cin >> c[i] >> w[i], el[i].push_back(i);
	sort(a.begin(), a.end(), [] (int i, int j) { return w[i] < w[j]; });
	for(int i: a) {
		auto it = same[c[i]].lower_bound(make_pair(w[i]-x, 0));
		if(it != same[c[i]].end()) merge(i, it->second);
		same[c[i]].emplace(-w[i], i);
		it = okd.lower_bound(make_pair(w[i]-y, 0));
		if(it != okd.end()) merge(i, it->second);
		if(!mark[c[i]]) okd.emplace(-w[i], i), mark[c[i]] = true;
	}
	for(int rt = 0; rt < n; rt++) if(!el[rt].empty()) {
		map<int,int> f;
		long long res = fact[el[rt].size()];
		for(int v: el[rt]) f[c[v]]++;
		for(auto p: f) res = (res*modPow(fact[p.second], MOD-2))%MOD;
		ans = (ans*res)%MOD;
	}
	cout << ans;
}

