	repm(i,MAX_COMB,0){
		invfct[i-1] = invfct[i] * i % mod;
	}
}

const int UF_MAX = 200010;

class UF{
	int x[UF_MAX];

public:

	UF(){
		fill(x,x+UF_MAX,-1);
	}

	int boss(int a){
		int s = a;
		while(x[s] > -1) s = x[s];
		if(s != a) x[a] = s;
		return s;
	}

	void uni(int a , int b){
		int s = boss(a);
		int t = boss(b);
		if(s != t){
			if(x[s] < x[t]){
				x[s] += x[t];
				x[t] = s;
			} else {
				x[t] += x[s];
				x[s] = t;
			}
		}
	}

	bool find(int a , int b){
		return boss(a) == boss(b);
	}

	int member(int a){
		return -x[boss(a)];
	}
} uf;

