	rb(i,1,n){
		for(auto it:col[i]){
			if(w[it]+w[col[i][0]]<=x){
					merge(it,col[i][0]);
			}
		}
	}//连同色边 
	rb(i,1,n)
		if(root(i)==i){
			dsu[have[i][0]].PB(i);
			heap.push(II(w[col[have[i][0]][0]],have[i][0]));
		}
	rb(i,1,n){
		vector<int> ban;
		while(!heap.empty()&&heap.top().SEC==i)
			ban.PB(heap.top().FIR),heap.pop();
		if(!heap.empty())
		for(auto it:dsu[i]){
			if(w[it]+heap.top().FIR<=y){
				merge(it,col[heap.top().SEC][0]);
			}
		}
		for(auto it:ban)
			heap.push(II(it,i));
	}
	LL rest=1ll;
	rb(i,1,n)
	if(root(i)==i){
		sort(ALL(have[i]));
		int sum=0,sum_=0,las=-1;
		for(auto it:have[i]){
			if(las!=it){
				rest=rest*c(sum,sum_)%MOD;
				sum_=0;
				las=it;
			}
			sum_++;
			sum++;
		}
				rest=rest*c(sum,sum_)%MOD;
	}
	cout<<rest<<endl;
	return 0;
}
