// set of integers in different components
multiset<int> component[200005];

long long modPow(long long a, long long b){
    if(b == 0){
        return 1%MOD;
    }else if(b == 1){
        return a%MOD;
    }else{
        long long temp = modPow(a, b>>1);
        if(b&1){
            return (temp*temp)%MOD*a%MOD;
        }else{
            return (temp*temp)%MOD;
        }
    }
}

int main(){
    int N, X, Y;
    scanf("%d%d%d", &N, &X, &Y);

    fact[0] = 1;
    for(int i = 1; i <= N; i ++){
        fact[i] = (fact[i-1]*i)%MOD;
        colour[i] = ii(2147483647, 2147483647);
    }

    for(int i = 0; i < N; i ++){
        int c, w;
        scanf("%d%d", &c, &w);
        CW[i] = ii(c, w);
        colour[c] = min(colour[c], ii(w, i));
        colourList[c].push_back(i);
    }

    for(int c = 1; c <= N; c ++){
        int minIndx = colour[c].second;
        for(int i: colourList[c]){
            if(i != minIndx && CW[i].second+CW[minIndx].second <= X){
                AdjList[i].push_back(minIndx);
                AdjList[minIndx].push_back(i);
                //printf("pushed in: %d %d colour=%d\n", i, minIndx, c);
            }
        }
    }

    for(int i = 1; i <= N; i ++){
        colour2[i] = colour[i];
    }
    sort(colour2+1, colour2+(N+1));

