        int c = CW[indx].first;

        for(int i = 0; i < N; i ++){
            if(CW[i].first != c){
                // colour is different
                if(CW[i].second + CW[indx].second <= Y){
                    AdjList[i].push_back(indx);
                    AdjList[indx].push_back(i);
                    //printf("pushed in: %d %d\n", i, indx);
                }
            }
        }
    }

    int cnt = 0;
    memset(visited, 0, sizeof(visited));
    for(int i = 0; i < N; i ++){
        if(!visited[i]){
            visited[i] = true;
            queue<int> q;
            q.push(i);
            component[cnt].insert(CW[i].first);
            while(!q.empty()){
                int u = q.front(); q.pop();
                for(int v: AdjList[u]){
                    if(!visited[v]){
                        visited[v] = true;
                        q.push(v);
                        component[cnt].insert(CW[v].first);
                    }
                }
            }
            cnt ++;
        }
    }

    long long ans = 1;
    for(int i = 0; i < cnt; i ++){
        set<int> s;
        //printf("Component %d: ", i);
        for(int j: component[i]){
            //printf("%d ", j);
            s.insert(j);
        }
        //printf("\n");

        ans = ans*fact[component[i].size()]%MOD;

        for(int j: s){
            ans = ans*modPow(fact[component[i].count(j)], MOD-2)%MOD;
        }
    }

    printf("%lld", ans);
    return 0;
}

