long long modpow(long long a, long long b){
    if(b == 0){
        return 1%MOD;
    }else if(b == 1){
        return a%MOD;
    }else{
        long long temp = modpow(a, b>>1);
        if(b&1){
            return ((temp*temp)%MOD) *a %MOD;
        }else{
            return (temp*temp)%MOD;
        }
    }
}

