    }
    for( int i = 0; i < N; ++i ){
      sort( c2w[ i ].begin(), c2w[ i ].end() );
    }
  }
  {
    sort( W, W + N );
    int minw = W[ 0 ];
    int minw2 = W[ 1 ];
    for( int i = 0; i < N; ++i ){
      if( c2w[ i ].empty() ) continue;
      {
        for( int lb = 2, ub = c2w[ i ].size(); lb <= ub; ){
          int mid = lb + ub >> 1;
          if( c2w[ i ][ 0 ] + c2w[ i ][ mid - 1 ] <= X ){
            cmax[ i ] = mid;
            lb = mid + 1;
          } else{
            ub = mid - 1;
          }
        }
      }
