template<uint_fast64_t Modulus = MOD>
struct Modint {
  using u64 = uint_fast64_t;
  u64 a;

  constexpr Modint(const u64 x = 0) noexcept : a(x % Modulus) {}

  constexpr Modint operator+(const Modint rhs) const noexcept {
    return Modint(*this) += rhs;
  }
  constexpr Modint operator-(const Modint rhs) const noexcept {
    return Modint(*this) -= rhs;
  }
  constexpr Modint operator*(const Modint rhs) const noexcept {
    return Modint(*this) *= rhs;
  }
  constexpr Modint operator/(const Modint rhs) const noexcept {
    return Modint(*this) /= rhs;
  }

  constexpr Modint &operator+=(const Modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) a -= Modulus;
    return *this;
  }
  constexpr Modint &operator-=(const Modint rhs) noexcept {
    if (a < rhs.a) a += Modulus;
    a -= rhs.a;
    return *this;
  }
  constexpr Modint &operator*=(const Modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr Modint &operator/=(Modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp & 1) *this *= rhs;
      rhs *= rhs;
      exp >>= 1;
    }
    return *this;
  }

  Modint pow(u64 t) const {
    if (!t) return 1;
    Modint x = pow(t>>1);
    x *= x;
    if (t&1) x *= *this;
    return x;
  }

  explicit operator bool() const {
    return a;
  }

  friend ostream &operator<<(ostream &os, const Modint &m) {
    return os << m.a;
  }
};

using mint = Modint<>;

template<typename T>
struct ModCombination {
  vector<T> fac, finv, inv;

  ModCombination(int MAX) : fac(MAX + 1), finv(MAX + 1), inv(MAX + 1) {
    fac[0] = finv[MAX] = inv[0] = 1;
    for (int i=1; i<=MAX; ++i) fac[i] = fac[i-1] * i;
    finv[MAX] /= fac[MAX];
    for (int i=MAX-1; i>=0; --i) finv[i] = finv[i+1] * (i+1);
    for (int i=1; i<=MAX; ++i) inv[i] = finv[i] * fac[i-1];
  }

  T P(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * finv[n-r];
  }

  T C(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * finv[r] * finv[n-r];
  }

  T H(int n, int r) const {
    if (n < 0 || r < 0) return 0;
    return C(n + r - 1, r);
  }
};

void solve() {
  int n, x, y; cin >> n >> x >> y;
  unordered_map<int, vi> ump;
  rep(i,n) {
    int c, w; cin >> c >> w;
    ump[c].emplace_back(w);
  }

  if (ump.size() == 1) {
    cout << 1 << endl;
    return;
  }

  vector<pii> arr;

  for (auto &p : ump) {
    sort(ALL(p.second));
    arr.emplace_back(p.second[0], p.first);
  }

  sort(ALL(arr));

  int idx = arr[0].second;

  ModCombination<mint> comb(n);
  mint ans = 1;
  int sum = 0;

  if (arr[0].first + arr[1].first <= y) {
    int MAX = max(x - arr[0].first, y - arr[1].first);
    int cnt = upper_bound(ALL(ump[idx]), MAX) - ump[idx].begin();
    sum += cnt;
    ans /= comb.P(cnt, cnt);
  }

  for (auto &p : ump) {
    if (p.first != idx && p.second[0] + arr[0].first <= y) {
      int MAX = max(x - p.second[0], y - arr[0].first);
      int cnt = upper_bound(ALL(p.second), MAX) - p.second.begin();
      sum += cnt;
      ans /= comb.P(cnt, cnt);
    }
  }

  cout << ans * comb.P(sum, sum) << endl;
}


