typedef long long int64;
const int kMaxN = 2e5+10;
const int kMod = 1e9+7;

int c[kMaxN], w[kMaxN], reach[kMaxN];
int64 fac[kMaxN];
vector<vector<int>> B;

void solve() {

	int n, x, y;

	cin >> n >> x >> y;

	fac[0] = 1;
	for (int i = 1; i <= n; ++i) {
		fac[i] = fac[i-1] * i % kMod;	
	}

	B.resize(n+1);

	for (int i = 1; i <= n; ++i) {
		cin >> c[i] >> w[i];

		B[c[i]].push_back(w[i]);
	}

	for (int i = 1; i <= n; ++i) {
		sort(B[i].begin(), B[i].end());	
	}

	sort(B.begin(), B.end());

	int minb = 0;

	for (int i = 1; i <= n; ++i) {
		if (B[i].empty()) {
			continue;
		}
		if (minb == 0) {
			minb = i;
		}

		for (int j = 1; j < B[i].size(); ++j) {
			if (B[i][0] + B[i][j] <= x) {
				reach[i] = j-1;
			}
		}
	}

	int totalReach = 0;

	for (int i = 1; i <= n; ++i) {
		if (B[i].empty() || i == minb)
			continue;
		if (B[minb][0] + B[i][0] > y) {
			totalReach = i-1;
		}

		for (int j = 1; j < B[i].size(); ++j) {
			if (B[minb][0] + B[i][j] <= y) {
				if (j-1 > reach[i]) {
					reach[i] = j-1;
				}
			}
		}
	}

	int64 ans = 1;
	int total = 0;

	for (int i = 1; i <= n; ++i) {
		if (i <= totalReach) {
			total += reach[i];
		} else {
			ans = ans * fac[reach[i]] % kMod;
		}
	}
	ans = ans * fac[total] % kMod;

	cout << ans << "\n";
}

