	swap(ws[0], ws[pos] );
	pos = min_element(ws + 1, ws + m, cmp) - ws;
	swap(ws[1], ws[pos] );

	vector <int> ks;

	int ans = 1;
	for (int i = 0; i < m; i++)
	{
		int oth = 0;
