ModInt<> solve() {
  ModInt<> res = 1;
  int all = 0;
  for (int i = 0; i < n; ++i)
    if (w[i].size()) {
      int len = w[i].size(), cnt = 0;
      sort(w[i].begin(), w[i].end());
      for (int j = 0; j < len; ++j) {
        if (w[i][0] + w[i][j] <= x) w[i][j] = w[i][0];
        if (num + w[i][j] <= y) ++cnt;
      }
      all += cnt;
      res *= com.rfact(cnt);
    }
  return res * com.fact(all);
}

