// Union-Find 木 (Verified: AtCoder Typical Contest 001 B)
struct UnionFind {
private:
    const int n;
    int __size;
    vector<int> uf;
public:
    // 初期化 UnionFind uni(n) のように宣言すれば良い
    UnionFind(int _n) : n(_n), __size(_n), uf(_n, -1) {}
    // find (木の根を求める)
    int find(int x) {return (uf[x] < 0) ? x : uf[x] = find(uf[x]);}
    // x と y が同じ集合に属するかどうか
    bool same(int x, int y) {return find(x) == find(y);}
    // x が属する集合の要素数
    int size(int x) {return -uf[find(x)];}
    // 集合はいくつあるか
    int size()      {return __size;}
    // x と y の属する集合を併合
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        __size--;
        if(uf[y] < uf[x]) swap(x, y);
        uf[x] += uf[y]; uf[y] = x;
    }
};

signed main() {
    fact[0] = 1;
    for(int i=1; i<=MAXN; i++) fact[i] = (fact[i-1] * i) % MOD;
    finv[MAXN] = mod_pow(fact[MAXN], MOD-2);
    for(int i=MAXN-1; i>=0; i--) finv[i] = (finv[i+1] * (i+1)) % MOD;

    int N, X, Y; cin >> N >> X >> Y;
    vector< vector<int> > cols(N);
    for(int i=0; i<N; i++) {
        int c, w; cin >> c >> w;
        c--;
        cols[c].push_back(w);
    }

    for(int i=0; i<N; i++) {
        sort(cols[i].begin(), cols[i].end());
    }
    sort(cols.rbegin(), cols.rend());

    // 空の vector を消す
    while(cols.size() and cols.back().empty()) cols.pop_back();
    reverse(cols.begin(), cols.end());


    UnionFind uf(N);
    vector< vector<int> > id(N);
    int M = cols.size();

    // id を振り直す
    int num = 0;
    for(int i=0; i<M; i++) {
        int sz = cols[i].size();
        for(int j=0; j<sz; j++) {
            id[i].push_back(num++);
        }
    }

    for(int i=0; i<M; i++) {
        int sz = cols[i].size();
        for(int j=0; j<sz; j++) {
            // 同じ色同士の結合
            if(cols[i][0] + cols[i][j] <= X) {
                int u = id[i][0], v = id[i][j];
                uf.unite(u, v);
            }

            // 異なる色同士の結合
            int op = (i ? 0 : 1);
            if(op >= M) continue;
            // fprintf(stderr, "%lld and %lld\n", cols[op][0], cols[i][j]);
            if(cols[op][0] + cols[i][j] <= Y) {
                int u = id[op][0], v = id[i][j];
                uf.unite(u, v);
            }
        }
    }

    // 連結成分ごとに何色が何個あるか
    map< int, map<int, int> > rec;
    for(int i=0; i<M; i++) {
        int sz = cols[i].size();
        for(int j=0; j<sz; j++) {
            int u = id[i][j];
            u = uf.find(u);

            // u 番目の連結成分、i 色目
            rec[u][i]++;
        }
    }

    int res = 1;
    for(auto mp : rec) {
        // fprintf(stderr, "! mp\n");
        int sum = 0;
        for(auto elem : mp.second) {
            // fprintf(stderr, "col = %lld, val = %lld\n", elem.first, elem.second);
            sum += elem.second;
            (res *= finv[elem.second]) %= MOD;
        }
        (res *= fact[sum]) %= MOD;
    }
    cout << res << endl;
    return 0;
}

