ll mult(ll a, ll b)
{
	return (a*b)%MOD;
}

ll modpow(ll a, ll b)
{
	ll r=1;
	while(b)
	{
		if(b&1) r=(r*a)%MOD;
		a=(a*a)%MOD;
		b>>=1;
	}
	return r;
}

ll inv(ll a)
{
	return modpow(a,MOD-2);
}

map<int,int> dsu[200001];
int par[200001];

int rt(int u)
{
	if(par[u]<0) return u;
	return (par[u]=rt(par[u]));
}

void merge(int u, int v)
{
	u=rt(u);v=rt(v);
	if(dsu[u].size()<dsu[v].size()) swap(u,v);
	for(mit it = dsu[v].begin();it!=dsu[v].end();it++)
	{
		dsu[u][it->fi]+=it->se;
	}
	par[v]=u;
	par[u]=-1;
}

ll solve(int x)
{
	if(x!=rt(x)) return 1;
	ll tot = 0;
	ll ans = 1;
	for(mit it = dsu[x].begin();it!=dsu[x].end();it++)
	{
		tot+=it->se;
		ans=(ans*ifact[it->se])%MOD;
	}
	ans=mult(ans,fact[tot]);
	return ans;
}

