int power(int a, int n) {
	int result = 1;
	while (n > 0) {
		if (n & 1) {
			result = (1LL * result * a) % mod;
		}
		a = (1LL * a * a) % mod;
		n /= 2;
	}
	return result;
}

int inv(int a) {
	return power(a, mod - 2);
}

