intl fpm(intl a, intl b) {
	if (!a) return 0LL;
	intl ans = 1LL;
	for (; b; b >>= 1) {
		if (b & 1LL) ans *= a, ans %= Mo;
		a *= a; a %= Mo;
	}
	return ans;
}

intl C(int a, int b) {
	return fac[a] * inv[b] % Mo * inv[a - b] % Mo;
}

int main() {
	scanf("%d %d %d",&n,&x,&y);
	fac[0] = 1;
	for (int i = 1; i <= n; i++)
		fac[i] = fac[i - 1] * (intl) i % Mo;
	inv[n] = fpm(fac[n], Mo - 2LL);
	for (int i = n; i >= 1; i--)
		inv[i - 1] = inv[i] * (intl) i % Mo;	
	for (int i = 1; i <= n; i++) {
		int c, w;
		scanf("%d %d",&c,&w);
		vec[c].push_back(w);
	}
