	for (int i = 1; i <= n; i++) {
		if (!vec[i].empty()) {
			if (just > vec[i][0]) tp = i;
			just = min(just, vec[i][0]);
		}
		L[i] = just;
	}

	just = 1 << 30;
	R[n + 1] = 1 << 30;
	for (int i = n; i >= 1; i--) {
		if (!vec[i].empty()) {
			just = min(just, vec[i][0]);
		}
		R[i] = just;
	}
	for (int i = 1; i <= n; i++) {
		int jus = min(L[i - 1], R[i + 1]);
		for (auto j = vec[i].begin(); j != vec[i].end(); j++)
			if (vec[i][0] + *j <= x || j == vec[i].begin() || jus + *j <= y) cnt[i]++;		
	}
	CNT[++top] = cnt[tp];
	for (int i = 1; i <= n; i++) {
		if (vec[i].empty() || i == tp) continue;
		if (vec[i][0] + just <= y) CNT[++top] = cnt[i];
		//else TNC[++tp] = cnt[i];
	}
	for (int i = 1; i <= top; i++) CNT[i] += CNT[i - 1];
	ans = 1LL;
	for (int i = top; i >= 1; i--)
		(ans *= C(CNT[i], CNT[i - 1])) %= Mo;
	cout << ans << endl;
	return 0;
}

