	ll m, mn[N], fac[N], inv[N], cnt[N];

	inline ll power ( ll a, ll b ) {
		ll res = 1;
		for (; b; b >>= 1, a = a * a % p) res = (b & 1)? res * a % p: res;
		return res;
	}

	inline ll C ( ll n, ll m ) {
		if ( n < m || m < 0 ) return 0;
		return fac[n] * inv[m] % p * inv[n - m] % p;
	}

	inline void Init() {
		For ( i, 1, n ) mn[i] = inf;
		fac[0] = 1;
		For ( i, 1, n ) fac[i] = fac[i - 1] * i % p;
		inv[n] = power ( fac[n], p - 2 );
		foR ( i, n - 1, 0 ) inv[i] = inv[i + 1] * (i + 1) % p;
		For ( i, 1, n )
			cnt[c[i]]++, mn[c[i]] = min ( w[i], mn[c[i]] );
	}

