#include <bits/stdc++.h>
using i64 = long long;

long long *fact, *inv;

template <class T>
T pow(T x, T n, T mod) {
    T ret = 1;
    while(n > 0) {
        if ((n & 1) == 1) ret = (ret * x) % mod;
        x = (x * x) % mod;
        n >>= 1;
    }
    return ret;
}

template <class T>
T inverse(T x, T p) { return pow(x, p - 2, p); }

void init_factorial(int n, long long mod) {
    fact = new long long[n + 1];
    inv = new long long[n + 1];
    fact[0] = 1;
    for (long long i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    inv[n] = inverse(fact[n], mod);
    for (long long i = n; i > 0; i--) inv[i - 1] = inv[i] * i % mod;
}

int main() {
    constexpr i64 mod = 1000000007;
    int n, x, y;
    std::cin >> n >> x >> y;
    init_factorial(n, mod);

    std::vector<std::deque<int>> v(n);
    int min = std::numeric_limits<int>::max(), minc = -1;
    for (int i = 0; i < n; i++) {
        int c, w;
        std::cin >> c >> w;
        --c;
        v[c].push_back(w);
        if (min > w) {
            min = w;
            minc = c;
        }
    }

    int min2 = -1;
    for (int i = 0; i < n; i++) {
        if (v[i].empty()) continue;
        std::sort(v[i].begin(), v[i].end());
        if (i != minc) min2 = v[i].front();
    }

    std::deque<int> a;
    for (int i = 0; i < n; i++) {
        if (v[i].empty() || (i != minc && v[i].front() + min > y)) continue;
        if (i == minc) {
            int c1 = std::upper_bound(v[i].begin() + 1, v[i].end(), x - v[i].front()) - v[i].begin();
            int c2 = min2 > 0 ? std::upper_bound(v[i].begin(), v[i].end(), y - min2) - v[i].begin() : 0;
            a.push_back(std::max(c1, c2));
        } else {
            int c1 = std::upper_bound(v[i].begin() + 1, v[i].end(), x - v[i].front()) - v[i].begin();
            int c2 = std::upper_bound(v[i].begin(), v[i].end(), y - min) - v[i].begin();
            a.push_back(std::max(c1, c2));
        }
    }

    i64 ret = fact[std::accumulate(a.begin(), a.end(), 0)];
    for (auto &e : a) ret = ret * inv[e] % mod;
    std::cout << ret << std::endl;

    return 0;
}

