		while(grp[i].size() > 1) {
			if(grp[i].back().X + grp[i][0].X > x) {
				grp[++cc].push_back(grp[i].back());
				grp[i].pop_back();
			}
			else break;
		}
		pq.push({-grp[i][0].X, i});
	}
	ll idx = pq.top().Y; pq.pop();
	while(!pq.empty()) {
		ll cur = pq.top().Y; pq.pop();
		if(grp[cur][0].X + grp[idx][0].X > y) break;
