void build(int v=1,int tl=1,int tr=n){
  if(tl==tr){
    t[v].c=a[tl].c;
    t[v].w=a[tl].w;
    t[v].id=tl;
  } else {
    int mid=(tl+tr)/2;
    build(v+v,tl,mid);
    build(v+v+1,mid+1,tr);
    t[v]=min(t[v+v],t[v+v+1]);
  }
}
tree get(int l,int r,int v=1,int tl=1,int tr=n){
  if(tl>r||tr<l)return tree();
  if (l <=tl&&tr<=r)return t[v];
  int mid=(tl+tr)/2;
  return min(get(l,r,v+v,tl,mid),get(l,r,v+v+1,mid+1,tr));
}
void kill(int pos,int v=1,int tl=1,int tr=n){
  if(tl==tr)t[v].w=(ll)1e18;
  else {
    int mid=(tl+tr)/2;
    if(pos<=mid)kill(pos,v+v,tl,mid);
    else kill(pos,v+v+1,mid+1,tr);
    t[v]=min(t[v+v],t[v+v+1]);
  }
}
