typedef long long ll;
typedef pair<ll, ll> P;
const ll INF = 2000000000;
const ll mod = 1000000007;
int c_num[200010], c_num2[200010];
ll ans[200010];

ll modpow(ll x, ll y){
	if(y == 1) return x;
	if(y % 2 == 0){
		ll aa = modpow(x, y/2);
		return aa*aa%mod;
	}else{
		return x*modpow(x, y-1)%mod;
	}
}

int main(){
	int N, X, Y; cin >> N >> X >> Y;
	vector<P> ball;
	vector<int> color[N+1];
	for(int i=0; i<N; i++){
		int c, w; cin >> c >> w;
		color[c].push_back(w);
		ball.push_back(P(w, c));
	}
	ll fact[N+1];
	fact[1] = 1;
	for(int i=2; i<N+1; i++) fact[i] = fact[i-1] * i % mod;
	for(int i=1; i<=N; i++){
		ll mi = INF, index;
		for(int j=0; j<color[i].size(); j++){
			if(mi > color[i][j]){ mi = color[i][j]; index = j; }
		}
		c_num[i] = 1;
		for(int j=0; j<color[i].size(); j++){
			if(mi + color[i][j] <= X && index != j) c_num[i]++;
		}
	}

	sort(ball.begin(), ball.end());
	ll m1 = ball[0].first, m2 = INF, c1 = ball[0].second;
	ans[c1] = 1;
	long long size = 1;
	for(int i=1; i<N; i++){
		if(ball[i].second != c1 && m2 == INF){
			m2 = ball[i].first;
		}
		if(ball[i].second == c1 && ball[i].first + m1 <= X){
			size++;
			ans[c1]++;
		}else if(ball[i].second != c1 && ball[i].first + m1 <= Y){
			c_num2[ball[i].second]++;
		}
	}
	for(int i=1; i<=N; i++){
		if(c_num2[i] != 0 && i != c1){
			size += max(c_num[i], c_num2[i]);
			ans[i] += max(c_num[i], c_num2[i]);
		}
	}
	for(int i=0; i<color[c1].size(); i++){
		if(color[c1][i] + m1 > X && color[c1][i] + m2 <= Y){
			size++;
			ans[c1]++;
		}
	}
	ll p = 1;
	for(int i=1; i<=N; i++){
		if(ans[i] != 0){
			p = p * fact[ans[i]] % mod;
		}
	}
	cout << fact[size] * modpow(p, mod-2) % mod << "\n";
	return 0;
}

