#include<bits/stdc++.h>
#define rep(i,a,b) for (int i=(a); i<=(b); i++)
#define per(i,a,b) for (int i=(a); i>=(b); i++)
using namespace std;

const int maxn = 200005;
const int mod = 1000000007;
int pa[maxn], c[maxn], w[maxn], rk[maxn], fac[maxn];
int n, X, Y, sz, sum, tmp, ans = 1;
map<int,int> cnt[maxn];
vector<int> p[maxn];

inline int power(int x, int p) {
	int res = 1;
	while (p) {
		if (p & 1) res = 1ll * res * x % mod;
		x = 1ll * x * x % mod; p >>= 1;
	}
	return res;
}

inline int getpa(int x) {
	return pa[x] == x ? x : pa[x] = getpa(pa[x]);
}

inline bool cmp(int a, int b) {
	return w[a] < w[b];
}

int main() {
	scanf("%d%d%d", &n, &X, &Y);
	fac[0] = 1;
	rep (i, 1, n)
		fac[i] = 1ll * fac[i-1] * i % mod;
	rep (i, 1, n) {
		scanf("%d%d", &c[i], &w[i]);
		p[c[i]].push_back(i);
		rk[i] = pa[i] = i;
	}
	rep (i, 1, n) if (p[i].size() >= 2) {
		sort(p[i].begin(), p[i].end(), cmp);
		sz = p[i].size();
		rep (j, 1, sz - 1)
			if (w[p[i][0]] + w[p[i][j]] <= X) {
				pa[getpa(p[i][j])] = getpa(p[i][0]);
			}
	}
	sort(rk+1, rk+n+1, cmp);
	int cur = 0;
	rep (i, 2, n) {
		if (w[rk[1]] + w[rk[i]] <= Y && c[rk[1]] != c[rk[i]]) 
			pa[getpa(rk[i])] = getpa(rk[1]);
		if (!cur && c[rk[i]] != c[rk[1]]) cur = i;
	}
	if (cur) {
		rep (i, cur + 1, n)
			if (w[rk[cur]] + w[rk[i]] <= Y && c[rk[cur]] != c[rk[i]]) 
				pa[getpa(rk[i])] = getpa(rk[cur]);
	}
	rep (i, 1, n) 
		cnt[getpa(i)][c[i]]++;
	rep (i, 1, n) if (pa[i] == i) {
		sum = 0; tmp = 1;
		for (auto x : cnt[i]) {
			sum += x.second;
			tmp = 1ll * tmp * power(fac[x.second], mod - 2) % mod;
		}
		ans = 1ll * ans * fac[sum] % mod;
		ans = 1ll * ans * tmp % mod;
	}
	printf("%d\n", ans);
	return 0;
}

#include <cstdio>
