using namespace std;

#define FOE(i, s, t) for (int i = s; i <= t; i++)
#define FOR(i, s, t) for (int i = s; i < t; i++)

#define LL long long
#define mp make_pair
#define pb push_back

#define M 1000000007

int n, x, y;

#define K 600001

vector<pair<int, int> > co[K];

int val[K], col[K], ext[K], active[K];
pair<int, int> a[K];

vector<int> count;

LL fact[K], revfact[K];

LL bigmod(LL a, LL p) {
	if (!p) return 1;

	LL t = bigmod(a, p >> 1);
	t = t * t % M;

	if (p & 1) t = t * a % M;

	return t;	
}

LL C(LL n, LL k) {
	return fact[n] * revfact[k] % M * revfact[n - k] % M;	
}

vector<int> cols;
vector<int> cnts;

int main(){
	scanf("%d%d%d", &n, &x, &y);

	fact[0] = 1;
	FOE(i, 1, n * 3) fact[i] = (fact[i - 1] * i) % M;
	FOE(i, 0, n * 3) revfact[i] = bigmod(fact[i], M - 2);

	FOE(i, 1, n) {
		int c, w; scanf("%d%d", &c, &w);
		co[c].pb(mp(w, i));

		col[i] = c;
		a[i] = mp(w, i);
	}

	FOE(i, 1, n) if (co[i].size()) {
		sort(co[i].begin(), co[i].end());

		int low = -1;

		while (low + 1 != co[i].size() && co[i][low + 1].first + co[i][0].first <= x) low++;

		FOE(j, 0, low) {
			int pos = co[i][j].second;

			val[pos] = low + 1;				
		}
	}

	sort(a + 1, a + n + 1);

	int low = 0;

	int secLow = 1;

	while (secLow <= n && col[a[secLow].second] == col[a[1].second]) secLow++;

	while (low != n && a[low + 1].first + a[1].first <= y) {
		low++;

		int ok = (col[a[low].second] != col[a[1].second] || a[secLow].first + a[low].first <= y);

		if (ok) {

			int pos = a[low].second;

			active[pos] = 1;

		//	printf("POS %d\n", pos);

			if (val[pos] > 0) {
				int len = val[pos] - 1;
				int color = col[pos];	

				if (!ext[color]) {
					FOE(i, 0, len) {
						int pp = co[color][i].second;

						active[pp] = 1;
					}
					ext[color] = 1;
				}
			}
		}
	}

	LL ret = 1;


	FOE(i, 1, n) {
		if (active[i]) cols.pb(col[i]);
//		if (active[i]) printf("POS %d ACTIVE\n", i);
	}

	if (cols.size()) {
		sort(cols.begin(), cols.end());

		int last = -1, cnt = 0;
//		FOR(i, 0, cols.size()) printf("cols[%d] = %d\n", i, cols[i]);

		FOR(i, 0, cols.size()) {
			if (last == -1) {
				cnt = 1; 
				last = cols[0];	
			} else if (cols[i] != last) {
				cnts.pb(cnt);
				cnt = 1;
				last = cols[i];	
			} else {
				cnt++;	
			}
		}

		cnts.pb(cnt);

//		FOR(i, 0, cnts.size()) printf("cnts[%d] = %d\n", i, cnts[i]);

		int slot = 1;

		FOR(i, 0, cnts.size()) {
			ret = ret * C(slot + cnts[i] - 1, cnts[i]) % M;

			slot += cnts[i];
		}
	}

	cout << ret << endl;
}

