	for (int i = 2; i <= n; ++i)
	{
		if (a[i].first == a[cur].first)
		{
			if (a[i].second + a[cur].second <= x)
				add_edge(i, cur);
		}

		else
		{
			cur = i;
			if (a[i].second < a[m1].second)
			{
				m2 = m1;
				m1 = i;
			}

			else if (a[i].second < a[m2].second or m1 == m2)
			{
				m2 = i;
			}
		}
	}

	add_edges(m1, n, y);
	add_edges(m2, n, y);
	fact[0] = factInv[0] = 1;
	for (int i = 1; i < N; ++i)
	{
		fact[i] = (i * fact[i - 1]) % mod;
		factInv[i] = fastModExp(fact[i], mod - 2);
	}

