void add_edges(int i, int n, ll y)
{
	for (int j = 1; j <= n; ++j)
		if ((a[i].first != a[j].first) and (a[i].second + a[j].second <= y))
			add_edge(i, j);
}

void add_edge(int i, int j)
{
	g[i].pb(j);
	g[j].pb(i);
}

ll bfs(int cur, ll ans)
{
	map <int, int> m;
	seen[cur] = true;
	queue <int> q;
	q.push(cur);
	int ctr = 0;
	while (!q.empty())
	{
		int x = q.front();
		q.pop();
		++m[a[x].first];
		++ctr;
		for (auto &i : g[x])
		{
			if (!seen[i])
			{
				q.push(i);
				seen[i] = true;
			}
		}
	}

	ans = (ans * fact[ctr]) % mod;
	for (auto &i : m)
		ans = (ans * factInv[i.second]) % mod;

	return ans;
}

ll fastModExp(ll x, ll e)
{
	ll res = 1;
	while (e)
	{
		if (e % 2)
			res = (res * x) % mod;

		e /= 2;
		x = (x * x) % mod;
	}

	return res;
}

