        }
        if (i == balls[0].second || color[i][0] + balls[0].first <= y) {
            main_part[i] = true;
            len_main_part += len[i];
        }
    }
    ll res = fact[len_main_part];
    for (int i = 0; i < n; i++) {
        if (main_part[i]) {
            res = mul(res, rev(fact[len[i]]));
        }
    }
