		fac[i] = fac[i-1]*i % mod;
		inv[i] = mod - inv[mod%i] * (mod/i) % mod;
		finv[i] = finv[i-1] * inv[i] % mod;
	}
}


ll com(ll n, ll k){
	if(n < k) return 0;
	if(n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}

int main(){
	ll n,x,y; cin >> n >> x >> y;
	vl c(n), w(n); rep(i,n) cin >> c[i] >> w[i], c[i]--;
	comInit();
	UnionFind uf(n);
	vector<vpl> colors(n);
	rep(i,n) colors[c[i]].emplace_back(w[i],i);
	rep(i,n) sort(all(colors[i]));
	set<P> se;
	rep(i,n) se.emplace(w[i],i);
	vpl lowest(n,{-1,-1});
	rep(i,n){
		P X = {inf,inf};
		if(colors[c[i]].size() > 1){
			if(colors[c[i]][0].second == i) X = colors[c[i]][1];
			else X = colors[c[i]][0];
		}
		P Y = {inf,inf};
		if(lowest[c[i]] == P(-1,-1)){
			for(auto j : se){
				if(c[j.second] != c[i]){
					Y = j;
					break;
				}
			}
			lowest[c[i]] = Y;
		}else{
			Y = lowest[c[i]];
		}
		if(w[i] + X.first <= x) uf.unite(i,X.second);
		if(w[i] + Y.first <= y) uf.unite(i,Y.second);
	}
	vvl ls(n);
	rep(i,n){
		ls[uf.find(i)].push_back(i);
	}
	mint ans = 1;
	rep(i,n){
		map<ll,ll> mp;
		if(ls[i].empty()) continue;
		ans *= fac[ls[i].size()];
		for(auto j : ls[i]){
			mp[c[j]]++;
		}
		for(auto j : mp){
			ans *= finv[j.second];
		}
	}
	cout << ans.value() << "\n";
}

