struct perm {
private:
	int sz;
	vector<ll> p, invp;
public:
	perm(int n) {
		sz = n + 1;
		p.resize(sz), invp.resize(sz);
		p[0] = 1;
		rep1(i, sz - 1) {
			p[i] = p[i - 1] * i%mod;
		}
		invp[sz - 1] = 1;
		ll cop = mod - 2, x = p[sz - 1];
		while (cop) {
			if (cop % 2)invp[sz - 1] = invp[sz - 1] * x%mod;
			cop >>= 1; x = x * x % mod;
		}
		per(i, sz - 1) {
			invp[i] = invp[i + 1] * (i + 1) % mod;
		}
	}
	ll comb(ll x, ll y) {
		if (x < y || y < 0)return 0;
		ll ret = p[x];
		(ret *= invp[y]) %= mod;
		(ret *= invp[x - y]) %= mod;
		return ret;
	}
	ll combP(ll x, ll y) {
		if (x < y || y < 0)return 0;
		return p[x] * invp[x - y] % mod;
	}
};
ll mod_pow(ll x, ll n = mod - 2) {
	ll ret = 1;
	while (n) {
		if (n % 2)ret = ret * x%mod;
		x = x * x%mod; n >>= 1;
	}
	return ret;
}
perm p(1 << 18);

struct uf {
private:
	vector<int> par, ran;
public:
	void init(int n) {
		par.resize(n, 0);
		ran.resize(n, 0);
		rep(i, n) {
			par[i] = i;
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		else return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y)return;
		if (ran[x] < ran[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (ran[x] == ran[y])ran[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

vector<int> loc[1 << 18];
int cnt[1 << 18];

void solve() {
	int n, x, y; cin >> n >> x >> y;
	vector<int> c(n), w(n);
	rep(i, n) {
		cin >> c[i] >> w[i];
		loc[c[i]].push_back(i);
	}
	vector<P> v;
	rep(i, n)v.push_back({ w[i],i });
	sort(v.begin(), v.end());
	uf u; u.init(n+1);
	int root = v[0].second;
	rep(i, n) {
		if (v[0].first + v[i].first <= y) {
			if (i > 0) {
				u.unite(v[i-1].second,v[i].second);
			}
		}
	}
	rep1(i, n) {
		vector<P> vv;
		rep(j, loc[i].size()) {
			vv.push_back({ w[loc[i][j]],loc[i][j] });
		}
		sort(vv.begin(), vv.end());
		rep(j, vv.size()) {
			if (vv[j].first + vv[0].first <= x) {
				if (j > 0) {
					u.unite(vv[j - 1].second, vv[j].second);
				}
			}
		}
	}
	ll ans = 1;
	int tmp = 0;
	rep(i, n) {
		if (u.same(root, i)) {
			tmp++;
			cnt[c[i]]++;
		}
	}
	ans = p.combP(tmp, tmp);
	rep1(i, n) {
		if (cnt[i] == 0)continue;
		ll r = p.combP(cnt[i], cnt[i]); r = mod_pow(r);
		ans = ans * r%mod;
	}
