    void init(int n){
        REP(i,n)d[i]=i,num[i]=1;
    }
    int find(int x){
        return (x!=d[x])?(d[x]=find(d[x])):x;
    }
    bool uu(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y)return 0;
        if(num[x]>num[y])swap(x,y);
        num[y]+=num[x];
        d[x]=y;
        return 1;
    }
}U;
LL fac[SIZE],inv[SIZE];
LL mypow(LL x,LL y){
    LL res=1;
    while(y){
        if(y&1)res=res*x%MOD;
        y>>=1;
        x=x*x%MOD;
    }
    return res;
}
LL C(int x,int y){
    if(y<0||y>x)return 0;
    return fac[x]*inv[y]%MOD*inv[x-y]%MOD;
}
void build(){
    assert(MOD>=SIZE);
    fac[0]=1;
    REPP(i,1,SIZE)fac[i]=fac[i-1]*i%MOD;
    inv[SIZE-1]=mypow(fac[SIZE-1],MOD-2);
    for(int i=SIZE-2;i>=0;i--)inv[i]=inv[i+1]*(i+1)%MOD;
}
int c[SIZE],w[SIZE];
int main(){
    build();
    DRIII(N,X,Y);
    U.init(N);
    VPII mi(N,MP(INF,0));
    REP(i,N){
        RII(c[i],w[i]);
        c[i]--;
        p[c[i]].PB(MP(w[i],i));
        mii(mi[c[i]],MP(w[i],i));
    }
    REP(i,N){
        sort(ALL(p[i]));
        REPP(j,1,SZ(p[i])){
            if(p[i][j].F+p[i][0].F<=X)U.uu(p[i][j].S,p[i][0].S);
        }
    }
    sort(ALL(mi));
    REP(i,min(SZ(mi),2)){
        if(mi[i].F>=Y)continue;
        REP(j,N){
            if(c[mi[i].S]!=c[j]&&mi[i].F+w[j]<=Y)U.uu(mi[i].S,j);
        }
    }
    map<PII,int>cnt;
    LL an=1;
    REP(i,N){
        if(U.find(i)==i){
            an=an*fac[U.num[i]]%MOD;
        }
        cnt[MP(U.find(i),c[i])]++;
    }
    for(map<PII,int>::iterator it=cnt.begin();it!=cnt.end();it++){
        an=an*inv[it->S]%MOD;
    }
    cout<<an<<endl;
    return 0;
}

