    sort(ALL(wl[i]));
    for (int j = 0; j < (int)(wl[i].size()); ++j) {
      if (wl[i][0].first + wl[i][j].first <= X)
        uf.merge(wl[i][0].second, wl[i][j].second);
    }
  }
  vector<pair<int,int>> vec;
  REP(i,N) {
    if (wl[i].empty()) continue;
    vec.emplace_back(wl[i][0].first, wl[i][0].second);
  }
  sort(ALL(vec));
  for (int i = 0; i < int(vec.size()); ++i) {
    if (vec[i].first + vec[0].first <= Y) uf.merge(vec[i].second, vec[0].second);
  }
  REP(i,N) {
    mapsto[uf.root(i)][c[i] - 1]++;
  }
  Mod res = 1;
  REP(i,N) {
    if (mapsto[i].empty()) continue;
    int sum = 0;
    for (auto j: mapsto[i]) {
      sum += j.second;
    }
    Mod prod = fact[sum];
    for (auto j: mapsto[i]) {
      prod *= factinv[j.second];
    }
    res *= prod;
  }
  cout << res << endl;
}

