		else if (a[i].fi != a[mn.se].fi && c <= Y) d.uni(i, mn.se);
	}
	for (int i = 1; i <= n; i++) {
		int c = a[i].se + a[mn2.se].se;
		if (a[i].fi == a[mn2.se].fi && c <= X) d.uni(i, mn2.se);
		else if (a[i].fi != a[mn2.se].fi && c <= Y) d.uni(i, mn2.se);
	}
