void solve() {
	for (int i = 1; i <= n; i++) {
		int u = d.find(i);
		mem[u].push_back(a[i].fi);
	}
	int ans = 1;
	for (int i = 1; i <= n; i++) {
		sort(mem[i].begin(), mem[i].end());
		if (mem[i].size() >= 2) {
			ans = ans * exp[mem[i].size()] % mod;
			int cnt = 1;
			for (int j = 1; j < mem[i].size(); j++) {
				if (mem[i][j] != mem[i][j - 1]) {
					ans = ans * binPow(exp[cnt], mod - 2) % mod;
					cnt = 1;
				}
				else cnt++;
			}
			ans = ans * binPow(exp[cnt], mod - 2) % mod;
		}
	}
	cout << ans << endl;
}

