int cnt[202020];
int clr[202020];

void solve() {
    first();
    pair<int, int> MIN{INF, -1}, MIN2{INF, -1};
    int MIN_c = 0;
    for (int i = 0; i < N; i++) {
        if (V[i].size())
            if (MIN > V[i][0]) {
                MIN2 = MIN;
                MIN = V[i][0];
                MIN_c = i;
            } else
                chmin(MIN2, V[i][0]);
    }
    cerr << MIN.first << " " << MIN.second << endl;
    cerr << MIN2.first << " " << MIN2.second << endl;
    UnionFind uf(N);

    for (int i = 0; i < N; i++) {
        auto& v = V[i];
        if (v.size()) {
            if (i != MIN_c) {
                for (auto& p : v) {
                    if (p.first + MIN.first <= Y)
                        uf.unite(p.second, MIN.second);
                    else
                        break;
                }
            } else {
                for (auto& p : v) {
                    if (p.first + MIN2.first <= Y)
                        uf.unite(p.second, MIN.second);
                    else
                        break;
                }
            }
            auto MIN = v[0];
            for (auto& p : v) {
                if (p.first + MIN.first <= X)
                    uf.unite(p.second, MIN.second);
                else
                    break;
            }
        }
    }

    Mint ans = 1;
    map<int, map<int, int>> mp;
    int tot[202020] = {};
    for (int i = 0; i < N; i++) {
        mp[uf.find(i)][clr[i]]++;
        tot[uf.find(i)]++;
    }
    for (auto& p : mp) {
        auto m = p.second;
        ans *= fact[tot[p.first]];
        //cerr << tot[p.first] << endl;
        for (auto& pp : m) {
            ans *= iFac[pp.second];
            //cerr << "->" << pp.first + 1 << " " << pp.second << endl;
        }
    }
    cout << ans << endl;
}

