		for (i=l;i<r;i++) if (p[i].w+p[l].w<=x) merge(p[l].id,p[i].id);
	}
	sort(p+1,p+1+n,cmpw);
	for (i=2;i<=n;i++) if (p[i].c!=p[1].c&&p[i].w+p[1].w<=y) merge(p[1].id,p[i].id);
	for (i=2;i<=n;i++) if (p[i].c!=p[1].c) break;
	if (i<=n)
		for (k=1;k<=n;k++) if (p[k].c==p[1].c&&p[k].w+p[i].w<=y) merge(p[k].id,p[i].id);

	for (i=fac[0]=1;i<=n;i++) fac[i]=1LL*fac[i-1]*i%mod;
	for (i=2,inv[0]=inv[1]=1;i<=n;i++) inv[i]=-1LL*(mod/i)*inv[mod%i]%mod;
	for (i=3;i<=n;i++) inv[i]=1LL*inv[i]*inv[i-1]%mod;
	for (i=1;i<=n;i++) mp[find(i)][c[i]]++;
	int ans=1;
	for (i=1;i<=n;i++)
		if (fa[i]==i) {
			k=0;
			for (auto pr:mp[i])
				ans=1LL*ans*inv[pr.second]%mod,k+=pr.second;
			ans=1LL*ans*fac[k]%mod;
		}
	printf("%d\n",(ans+mod)%mod);
	return 0;
}

