#define iter(i, n) for (int i = 1; i <= n; ++i)
#define iter_r(i, n) for (int i = n; i >= 1; --i)
#define NR 201000
const int inf = 1e9;
const int mod = 1e9 + 7;

typedef pair<int, int> pii;
int w[NR], c[NR], n, X, Y, cnt[NR], li[NR], len, fac[NR], inv[NR];
pii minw[NR], pre[NR], suf[NR];
#define fi first
#define se second
vector<int> e[NR];
bool vis[NR];

void add_edge(int x, int y) { e[x].push_back(y); e[y].push_back(x); }

void dfs(int x) {
	if (cnt[c[x]] == 0) li[++len] = c[x];
	++cnt[c[x]];
	vis[x] = true;
	for (int v : e[x]) if (!vis[v]) dfs(v);
}

int pr(int a, int z) {
	int s = 1;
	while (z > 0) {
		if (z % 2 == 1) s = 1ll * s * a % mod;
		a = 1ll * a * a % mod;
		z /= 2;
	}
	return s;
}

int binom(int n, int k) { return 1ll * fac[n] * inv[k] % mod * inv[n - k] % mod; }

int main() {
	scanf("%d%d%d", &n, &X, &Y);
	fac[0] = inv[0] = 1;
	iter(i, n) {
		minw[i] = pii(inf, 0);
		fac[i] = 1ll * fac[i - 1] * i % mod;
	}
	inv[n] = pr(fac[n], mod - 2);
	iter_r(i, n - 1) inv[i] = 1ll * inv[i + 1] * (i + 1) % mod;

	iter(i, n) {
		scanf("%d%d", &c[i], &w[i]);
		minw[c[i]] = min(minw[c[i]], pii(w[i], i));
	}
	pre[0] = suf[n + 1] = pii(inf, 0);
	iter(i, n) pre[i] = min(pre[i - 1], minw[i]);
	iter_r(i, n) suf[i] = min(suf[i + 1], minw[i]);

	iter(i, n) {
		if (minw[c[i]].fi + w[i] <= X && minw[c[i]].se != i) add_edge(minw[c[i]].se, i);
		pii tmp = min(pre[c[i] - 1], suf[c[i] + 1]);
		if (tmp.se != 0 && tmp.fi + w[i] <= Y) add_edge(tmp.se, i);
	}

	int ans = 1;
	iter(i, n) {
		if (!vis[i]) dfs(i);
		int cur = 0;
		iter(k, len) {
			int &c = cnt[li[k]];
			cur += c; ans = 1ll * ans * binom(cur, c) % mod;
			c = 0;
		}
		len = 0;
	}

	printf("%d\n", ans);
	return 0;
}

