int bin(int a, int n)
{
    if (!n)
    {
        return 1;
    }
    if (n % 2 == 0)
    {
        int t = bin(a, n / 2);
        return (t * (ll) t) % M;
    }
    else
    {
        return (a * (ll) bin(a, n - 1)) % M;
    }
}

