void prep () {
	fac[0] = 1, ivf[0] = 1;
	fac[1] = ivf[1] = inv[1] = 1;
	for (int i = 2; i <= n; ++i) {
		fac[i] = fac[i - 1] * i % mo;
		inv[i] = mo - 1ll * mo / i * inv[mo % i] % mo;
		ivf[i] = ivf[i - 1] * inv[i] % mo;
	}
	mn = smn = make_pair(inf, 0);
}
int main (){
	cin >> n >> X >> Y, ans = 1, prep();
	for (int i = 1, x, y; i <= n; ++i) {
		scanf("%d%d", &x, &y), co[x].push_back(y);
		if (y < mn.fi)
			smn = mn, mn = make_pair(y, x);
		else if (y < smn.fi)
			smn = make_pair(y, x);
	}
	int tot = 0;
	for (int i = 1; i <= n; ++i) {
		if (!(int)co[i].size())
			continue;
		int M = inf, C = 0;
		for (auto x : co[i])
			M = min(M, x);

		if (i == mn.se)
			for (auto x : co[i]) {
				if (x + M <= X)
					++C;
				else
				if (smn.se != i && x + smn.fi <= Y)
					++C;
			}
		else
			for (auto x : co[i]) {
				if (x + M <= X)
					++C;
				else if (smn.se != i)
					C += (x + smn.fi <= Y);
			}
