int par[N], sz[N];
int val[N];
int fact[N];
vector<int> all[N];

int root(int v)
{
	return par[v] == -1 ? v : par[v] = root(par[v]);
}
void merge(int v, int u)
{
	v = root(v);
	u = root(u);
	if (v == u)
		return;
	par[v] = u;
	sz[u] += sz[v];
}

bool cmp(int a, int b)
{
	return val[a] < val[b];
}

int bpow(int a, int b)
{
	int res = 1;
	while (b)
	{
		if (b & 1)
			res = 1LL * res * a % MOD;
		a = 1LL * a * a % MOD;
		b >>= 1;
	}
	return res;
}

int main()
{
	ios::sync_with_stdio(false);

	fact[0] = 1;
	for (int i=1; i<N; i++)
		fact[i] = 1LL * i * fact[i-1] % MOD;
	for (int i=0; i<N; i++)
		sz[i] = 1, par[i] = -1;

	int n, A, B;
	cin >> n >> A >> B;
	for (int i=0; i<n; i++)
	{
