		all[--c].push_back(i);
	}
	for (int i=0; i<N; i++)
		sort(all[i].begin(), all[i].end(), cmp);
	int mn = -1, mn2 = -1;
	for (int i=0; i<N; i++)
		if (!all[i].empty())
		{
			if (mn == -1 || val[all[mn][0]] > val[all[i][0]])
				mn2 = mn, mn = i;
			else if (mn2 == -1 || val[all[mn2][0]] > val[all[i][0]])
				mn2 = i;
		}
	for (int i=0; i<N; i++)
	{
		for (auto x : all[i])
		{
			if (val[all[i][0]] + val[x] <= A)
				merge(all[i][0], x);
			if (mn != -1 && mn != i)
			{
				if (val[all[mn][0]] + val[x] <= B)
					merge(all[mn][0], x);
			}
			else if (mn2 != -1 && mn2 != i)
			{
				if (val[all[mn2][0]] + val[x] <= B)
					merge(all[mn2][0], x);
			}
		}
	}
	int res = 1;
	for (int i=0; i<n; i++)
		if (par[i] == -1)
			res = 1LL * res * fact[sz[i]] % MOD;
	for (int i=0; i<N; i++)
	{
		map<int, int> mp;
		for (auto x : all[i])
			mp[root(x)]++;
		for (auto &x : mp)
			res = 1LL * res * bpow(fact[x.second], MOD - 2) % MOD;
	}
	cout << res << "\n";
	return 0;
}

