void solve() {
	int n, x, y; cin >> n >> x >> y;
	vector<int> c(n), w(n);
	rep(i, n) {
		cin >> c[i] >> w[i];
		loc[c[i]].push_back(i);
	}
	vector<P> v;
	rep(i, n)v.push_back({ w[i],i });
	sort(v.begin(), v.end());
	uf u; u.init(n+1);
	int root = v[0].second;
	int memo = -1;
	int col = c[root];
	bool f = false;
	rep1(i, n - 1) {
		if (!f) {
			if (c[i] != col) {
				rep(j, i) {
					if (v[j].first + v[i].first <= y) {
						u.unite(v[j].second, v[i].second);
					}
				}
				f = true; memo = i;
			}
		}
		else {
			if (c[i] == col) {
				if (v[i].first + v[memo].first <= y) {
					u.unite(v[i].second, v[memo].second);
				}
			}
			else {
				if (v[0].first + v[i].first <= y) {
					u.unite(v[0].second, v[i].second);
				}
			}
		}
	}

	rep1(i, n) {
		vector<P> vv;
		rep(j, loc[i].size()) {
			vv.push_back({ w[loc[i][j]],loc[i][j] });
		}
		sort(vv.begin(), vv.end());
		rep(j, vv.size()) {
			if (vv[j].first + vv[0].first <= x) {
				u.unite(vv[0].second, vv[j].second);
			}
		}
	}
	ll ans = 1;
	int tmp = 0;
	rep(i, n) {
		if (u.same(root, i)) {
			tmp++;
			cnt[c[i]]++;
		}
	}
	ans = p.combP(tmp, tmp);
	rep1(i, n) {
		if (cnt[i] == 0)continue;
		ll r = p.combP(cnt[i], cnt[i]); r = mod_pow(r);
		ans = ans * r%mod;
	}
	cout << ans << endl;
}

