int find(int x) {
	if (par[x] == x) return x;
	return par[x] = find(par[x]);
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);

	if (x == y) return;

	par[x] = y;
}

void calc_inv(int n, int mod) {
    inv[1] = 1;
    for (int i = 2; i <= n; i++) inv[i] = inv[mod % i] * (mod - mod / i) % mod;

    fact[0] = invfact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    for (int i = 1; i <= n; i++) invfact[i] = invfact[i - 1] * inv[i] % mod;
}

int main() {
	int n, x, y, m = 1000000007, m1 = 1e9 + 1, c1 = -1, p1 = -1, m2 = 1e9 + 1, c2 = -1, p2 = -1, p = 0, i, j;
	long long ans = 1;
	map <int, int>::iterator it;

	calc_inv(200000, m);

	scanf("%d %d %d", &n, &x, &y);

	for (i = 0; i < n; i++) {
		int c, w;

		scanf("%d %d", &c, &w);

		v[c].push_back(w);
	}

	for (i = 1; i <= n; i++) {
		if (v[i].size() == 0) continue;

		sort(v[i].begin(), v[i].end());

		if (v[i][0] < m1) {
			m2 = m1;
			c2 = c1;
			p2 = p1;
			m1 = v[i][0];
			c1 = i;
			p1 = p;
		} else if (v[i][0] < m2) {
			m2 = v[i][0];
			c2 = i;
			p2 = p;
		}

		p += v[i].size();
	}

	for (i = 0; i < n; i++) par[i] = i;

	p = 0;

	for (i = 1; i <= n; i++) {
		for (j = 0; j < v[i].size(); j++) {
			if (v[i][j] + v[i][0] <= x) unite(p, p + j);
			if (c1 != i && m1 + v[i][j] <= y) unite(p1, p + j);
			if (c2 != i && m2 + v[i][j] <= y) unite(p2, p + j);
		}

		p += v[i].size();
	}

	p = 0;

	for (i = 1; i <= n; i++) {
		for (j = 0; j < v[i].size(); j++) {
			int x = find(p + j);

			cnt[x]++;
			mp[x][i]++;
		}

		p += v[i].size();
	}

	for (i = 0; i < n; i++) {
		if (cnt[i] == 0) continue;

		ans = ans * fact[cnt[i]] % m;

		for (it = mp[i].begin(); it != mp[i].end(); it++) ans = ans * invfact[it->second] % m;
	}

	printf("%lld\n", ans);

	return 0;
}

