LL inv(LL a){
	return powmod(a,MOD-2);
}

int par[220000];
int __rank[220000];
int sz[220000];
int find(int a){
	if(a != par[a]) par[a] = find(par[a]);
	return par[a];
}
void join(int a, int b){
	int pa = find(a);
	int pb = find(b);
	if(pa == pb) return;
	if(__rank[pa] < __rank[pb]){
		par[pa] = pb;
		sz[pb] += sz[pa];
	} else if(__rank[pb] < __rank[pa]){
		par[pb] = pa;
		sz[pa] += sz[pb];
	} else {
		par[pb] = pa;
		sz[pa] += sz[pb];
		__rank[pa]++;
	}
}


