map<int,int> tot[maxn];
vector<int> wt;
inline void maintain(){
	while(heap.size()>=2){
		pin x=heap.top();heap.pop();
		pin y=heap.top();heap.pop();
		if(x.w1+y.w1<=Y){
			fa[y.w2]=x.w2;
			heap.push(x);
		}else{
			heap.push(x);
			heap.push(y);
			break;
		}
	}
}
