    	//		assert(heap.top()==mk(v[id2],id2));
    			if(v[id2]==lv2&&heap.top()==mk(v[id2],id2))maintain();
    			if(heap.top()!=mk(v[id2],id2))maintain();
    			id2=0;lv1=0;lv2=0;
    		}
    		for(int x:wt){
    			heap.push(mk(v[x],x));
    		}
    		wt.clear();
    	}
    	if(id2){
    		if(a[i].w+lv2<=X){
    			fa[i]=id2;
