	rep(i, n) {
		cin >> p[i].first >> p[i].second;
		p[i].first--;
		ball[p[i].first].pb(p[i].second);
		if (chmin(mi, p[i].second)) col = p[i].first;
	}
	int mi2 = inf;
	rep(i, n) {
		if (p[i].first != col) chmin(mi2, p[i].second);
	}
	bool flag = false;
	if (mi + mi2 <= y) flag = true;
	if (!flag) {
		cout << "1\n";
		return 0;
	}
	ll ans = 1; ll sum = 0;
