void solve() {
  map<int, vector<int> > ws;
  int mn = inf, mn2 = inf;
  int mni = -1, mni2 = -1;
  for (int i = 0; i < n; i++) {
    ws[c[i]].pb(w[i]);
    if (w[i] < mn2) {
      mn2 = w[i];
      mni2 = c[i];
    }
    if (mn2 < mn) {
      swap(mn2, mn);
      swap(mni2, mni);
    }
  }
  vector<int> mult;
  int sum = 0;
  for (auto vi : ws) {
    auto & v = vi.second;
    sort(v.begin(), v.end());
