            if (v[i] + mn > y) {
              break;
            }
          } else {
            if (mn2 + v[i] > y) {
              break;
            }
          }
        }
        cur++;
        sum++;
      }
      mult.pb(cur);
    }
  }
  int res = fact[sum];
  for (auto i : mult) {
    res = ::mult(res, inv(fact[i]));
  }
  printf("%d\n", res);
}

