		chkmin(cheapest[c[i]],w[i]);
	}
	pll cheap[3]; cheap[0]=MP(INF,INF); cheap[1]=MP(INF,INF);
	for (ll col=1;col<=n;col++) {
		chkmin(cheap[0],MP(cheapest[col],col));
	}
	for (ll col=1;col<=n;col++) {
		if (col!=cheap[0].snd) chkmin(cheap[1],MP(cheapest[col],col));
	}
