template<int MOD>
struct CombM{
    static const int Mod = MOD;
    typedef ModInt<MOD> mint;
    vector<mint> fact;
    vector<mint> factinv;
    CombM(int N) {
        N = min(N, MOD-1);
        fact.resize(N+1);
        factinv.resize(N+1);
        REP(i, N+1) {
            fact[i] = (i == 0 ? 1 : fact[i-1] * i);
        }
        factinv[N] = fact[N].inv();
        for(int i = N; i >= 1; i--) factinv[i-1] = factinv[i] * i;
    }

    mint nCr(int n, int r) {
        assert(n < (int)fact.size());
        if(n >= MOD) return nCr(n%MOD, r%MOD) * nCr(n/MOD, r/MOD); // Lucas' theorem
        return r > n ? 0 : fact[n] * factinv[n-r] * factinv[r];
    }

    mint nHr(int n, int r) {
        return r == 0 ? 1 : nCr(n+r-1, r);
    }
};
typedef CombM<1000000007> Comb;
int main(){
    iostream_init();
    int N, X, Y;
    cin >> N >> X >> Y;
    vector<int> C(N);
    vector<int> W(N);
    REP(i, N) cin >> C[i] >> W[i];
    map<int, int> minimum;
    REP(i, N) {
        if(!minimum.count(C[i]) || minimum[C[i]] > W[i]) {
            minimum[C[i]] = W[i];
        }
    }
    int all_minimum = INT_MAX;
    for(auto p : minimum) all_minimum = min(all_minimum, p.second);
    map<int, int> count;
    REP(i, N) {
        int c = C[i];
        int v = W[i];
        if(minimum[c] + v <= X) {
            v = minimum[c];
        }
        if(all_minimum + v <= Y) {
            count[c]++;
        }
    }
    int sum = 0;
    for(auto p : count) {
        sum += p.second;
    }
    mint res = 1;
    Comb c(300000);
    for(auto p : count) {
        res *= c.nCr(sum, p.second);
        sum -= p.second;
    }

    cout << res << endl;

    return 0;
}

