typedef long long ll;
const int N=1e6+5;
const ll mod=1e9+7;
ll fact[N+2],inv[N+2];
void Init(){
    fact[0]=1;
    for(int i=1;i<=N;i++)
        fact[i]=(fact[i-1]*i)%mod;
    inv[1]=1;
    for(int i=2;i<=N;i++)
        inv[i]=((mod-mod/i)*inv[mod%i])%mod;
    inv[0]=1;
    for(int i=1;i<=N;i++)
        inv[i]=inv[i]*inv[i-1]%mod;
}
int c[N],w[N];
int fa[N];
int mv[N],mp[N];
int cnt[N];
int find_father(int x){
    if(x==fa[x])
        return x;
    return fa[x]=find_father(fa[x]);
}
void Merge(int x,int y){
    int f1=find_father(x),f2=find_father(y);
    if(f1==f2)
        return ;
    fa[f2]=f1;
}
int n,x,y;
int main()
{
    memset(mv,0x3f,sizeof mv);
    Init();
    scanf("%d%d%d",&n,&x,&y);
    for(int i=1;i<=n;i++)
        scanf("%d%d",&c[i],&w[i]),fa[i]=i;
    int mn1=-1,mn2=-1;
    for(int i=1;i<=n;i++){
        if(mv[c[i]]>w[i]){
            mv[c[i]]=w[i];
            mp[c[i]]=i;
        }
        if(mn1==-1||w[mn1]>w[i])
            mn1=i;
        else if(mn2==-1||(w[mn2]>w[i]&&c[mn2]!=c[mn1]))
            mn2=i;
    }
    for(int i=1;i<=n;i++){
        if(mv[c[i]]+w[i]<=x)
            Merge(mp[c[i]],i);
        if(c[i]!=c[mn1]&&w[i]+w[mn1]<=y)
            Merge(mn1,i);
        if(mn2!=-1&&c[i]==c[mn1]&&w[i]+w[mn2]<=y)
            Merge(mn2,i);
    }
    int rt=find_father(mn1);
    int sz=0;
    for(int i=1;i<=n;i++)
        if(find_father(i)==rt){
            sz++;
            cnt[c[i]]++;
        }
    ll ans=fact[sz];
    for(int i=1;i<=n;i++){
        ans=ans*inv[cnt[i]]%mod;
    }
    printf("%lld\n",ans);
}

