		m1[i] = min(m1[i - 1], mn[i]);

	m2[n + 1] = INT_MAX;
	for (int i = n; i >= 1; i --)
		m2[i] = min(m2[i + 1], mn[i]);

	int ans = 1, sum = 0;
	for (int i = 1; i <= n; i ++)
	{
		if (mn[i] + min(m1[i - 1], m2[i + 1]) > y)
			continue;

		int cnt = 0;
		for (int a : v[i])
			cnt += ((a + mn[i] <= x) || (a + min(m1[i - 1], m2[i + 1]) <= y));
		sum += cnt;
		ans *= choose(cnt, sum);
		ans %= MOD;
	}
	cout << ans << endl;

	return 0;
}

