constexpr lint MOD = 1e9 + 7;

vector<lint> fac, facInv, inv;
void facInit(int nmax)
{
    fac = facInv = inv = vector<lint>(nmax + 1, 1);
    for (int i = 2; i <= nmax; i++)
    {
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        facInv[i] = facInv[i-1] * inv[i] % MOD;
    }
}

struct UnionFind // UnionFind Tree (0-indexed)
{
    vector<int> par, rank;
    UnionFind(int N) : par(N), rank(N) { REP(i, N) par[i] = i; }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        if (rank[x] < rank[y]) par[x] = y; else par[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
    }
    bool same(int x, int y) { return find(x) == find(y); }
};



int main()
{
    cin >> N >> X >> Y;
    c.resize(N);
    w.resize(N);

    UnionFind uf(N + 1);

    map<int, int> ec_min_pos;
    priority_queue<pint, vector<pint>, greater<pint>> pq;

    REP(i, N)
    {
        cin >> c[i] >> w[i];
        pq.push(pint(w[i], i));
        if (ec_min_pos[c[i]])
        {
            if (w[ec_min_pos[c[i]]] > w[i]) ec_min_pos[c[i]] = i;
        }
        else ec_min_pos[c[i]] = i;
    }

    if (ec_min_pos.size() == 1) cout << 1 << endl, exit(0);

    int w1, i1, w2, i2;
    tie(w1, i1) = pq.top();
    while (c[pq.top().second] == c[i1]) pq.pop();
    tie(w2, i2) = pq.top();

    uf.unite(N, i1);

    REP(i, N)
    {
        if (w[ec_min_pos[c[i]]] + w[i] <= X) uf.unite(i, ec_min_pos[c[i]]);
        if (c[i] != c[i1] && w[i] + w1 <= Y) uf.unite(N, i);
        if (c[i] == c[i1])
        {
            if (w[i] + w[i1] <= X) uf.unite(i, i1);
            if (w[i] + w2 <= Y && w1 + w2 <= Y) uf.unite(i, i1);
        }
    }

    map<int, int> movable_ec;
    int num = 0;
    REP(i, N) if (uf.same(N, i))
    {
        movable_ec[c[i]]++;
        num++;
    }

    facInit(N);
    lint ans = 1;
    int count = 0;
    for (auto pa : movable_ec)
    {
        (ans *= facInv[pa.second]) %= MOD;
        count += pa.second;
    }
    cout << ans * fac[count] % MOD << endl;
}

