    if (pw & 1) {
      mod_mult(res, x);
      --pw;
    } else {
      mod_mult(x, x);
      pw >>= 1;
    }
  }
  return res;
}

int get_inv(int x) {
  return bin_pow(x, MOD - 2);
}

