	UF uf(N);
	fill(mel, mel + N, pl(linf, linf));
	rep(i, 0, N) {
		vector<pl>& g = group[i];
		int at = -1;
		ll w = linf;
		rep(i, 0, sz(g)) {
			pl p = g[i];
			if(w > p.sec) {
				w = p.sec;
				at = p.fst;
			}
		}
		mel[i] = pl(w, at);
		rep(i, 0, sz(g)) {
			pl p = g[i];
			if(p.sec + w <= X) uf.unite(at, p.fst);
		}
	}
	sort(mel, mel + N);

	rep(i, 0, min(2, N)) {
		int at = mel[i].sec;
		ll w = mel[i].fst;
		rep(j, 0, N) {
			if(C[at] != C[j] && w + W[j] <= Y) uf.unite(j, at);
		}
	}

	rep(i, 0, N) con[uf.find(i)].pb(i);

	ll ans = 1;
	int at = uf.find(mel[0].sec);
	vi& vec = con[at];
	rep(i, 0, sz(vec)) cnt[C[vec[i]]]++;
	ans = fac[sz(vec)];
	rep(i, 0, N) MUL(ans, fiv[cnt[i]]);
	cout << ans << "\n";
}

