                    uf.unite(cv[i][0], cv[i][j]);
                }
            }
        }
    }

    std::sort(colors.begin(), colors.end(),
        [](const int a, const int b) { return w[cv[a][0]] < w[cv[b][0]]; }
    );

    for (int j = 1; j < colors.size(); j++) {
        if (w[cv[colors[0]][0]] + w[cv[colors[j]][0]] <= Y) {
            uf.unite(cv[colors[0]][0], cv[colors[j]][0]);
        }
    }

    for (int i = 0; i < std::min((int)colors.size(), 2); i++) {
        for (int j = 1; j <= N; j++) {
            if (c[j] != colors[i]) {
                if (w[j] + w[cv[colors[i]][0]] <= Y) {
                    uf.unite(j, cv[colors[i]][0]);
                }
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        count[uf.find(i)][c[i]]++;
    }

    long long ret = 1;
    for (int i = 1; i <= N; i++) {
        long long sum = 0;
        long long inv = 1;
        for (auto itr = count[i].begin(); itr != count[i].end(); ++itr) {
            sum += itr->second;
            inv = (inv * combi_num.factorial_inv[itr->second]) % MOD;
        }

        ret = (ret * combi_num.factorial[sum]) % MOD;
        ret = (ret * inv) % MOD;
    }

    std::cout << ret << std::endl;

    return 0;
}

