using namespace std;
typedef long long ll;
const int N = 200005;
const int mod = 1000000007;
int n,x,y;
int c[N], w[N];
int mn[N];
int sz[N];
int min1 = -1, min2 = -1;
ll f[N], inv[N];
ll exp(int a, int x){
    if (x == 0) return 1;
    ll p = exp(a,x/2);
    p *= p; p %= mod;
    if (x & 1){
        p *= a; p %= mod;
    }
    return p;
}
int main(){
    scanf("%d%d%d",&n,&x,&y);
    memset(mn,-1,sizeof(mn));
    f[0] = inv[0] = 1;
    for (int i = 1; i < N; i++) {
        f[i] = (f[i-1]*i)%mod;
        inv[i] = (inv[i-1] * exp(i,mod-2))%mod;
    }
    for (int i = 1; i <= n; i++){
        scanf("%d%d",&c[i],&w[i]);
        if (mn[c[i]] == -1 || mn[c[i]] > w[i]) mn[c[i]] = w[i];
        if (min1 == -1 || w[min1] > w[i]) min1 = i;
    }
    for (int i = 1; i <= n; i++){
        if (c[i] != c[min1]){
            if (min2 == -1 || w[min2] > w[i]) min2 = i;
        }
    }
    for (int i = 1; i <= n; i++){
        w[i] = min(w[i],mn[c[i]]);
    }
    for (int i = 1; i <= n; i++){
        if ( (w[i]+w[min2] <= y) || (c[i] != c[min1] && w[i] + w[min1] <= y)){
            sz[c[i]]++;
        }
    }
    ll ans = 1;
    int sum = 0;
    for (int i = 1; i <= n; i++){
        if (sz[i]) {
            ans *= inv[sz[i]]; ans %= mod;
            sum += sz[i];
        }
    }
    ans *= f[sum];
    ans %= mod;
    printf("%lld",ans);
}

