{
	if(p[x]==x)
		return x;
	return p[x]=get(p[x]);
}

inline uni(int x, int y)
{
	x=get(x);
	y=get(y);
	if(rand()&1)
		p[x]=y;
	else
		p[y]=x;
}

ll bin(ll x, ll k)
{
	ll res=1;
	while(k)
	{
		if(k&1)
			res=res*x%mod;
		x=x*x%mod;
		k>>=1;
	}
	return res;
}

