int fac[200010], inv[200010];
vector<pair<int, int> > per, all[200010];
bool vis[200010];
vector<int> seq, con[200010];

void dfs(const int &u) {
	vis[u] = 1;
	++cnt;
	++bin[col[u]];
	seq.push_back(col[u]);
	for (int _i = 0; _i < con[u].size(); ++_i) {
		int v = con[u][_i];
		if (!vis[v]) dfs(v);
	}
}

int main() {
	scanf("%d%d%d", &n, &x, &y);
	fac[0] = fac[1] = inv[0] = inv[1] = 1;
	for (int i = 2; i <= n; ++i) {
		fac[i] = (long long)fac[i - 1] * i % mod;
		inv[i] = (long long)(mod - mod / i) * inv[mod % i] % mod;
	}
	for (int i = 2; i <= n; ++i)
		inv[i] = (long long)inv[i] * inv[i - 1] % mod;
	for (int i = 1; i <= n; ++i) {
		scanf("%d%d", col + i, wei + i);
		all[col[i]].push_back(make_pair(wei[i], i));
	}
	for (int i = 1; i <= n; ++i)
		if (all[i].size()) {
			sort(all[i].begin(), all[i].end());
			per.push_back(all[i][0]);
			for (int j = 1; j < all[i].size(); ++j)
				if (all[i][j].first + all[i][0].first <= x) {
					con[all[i][0].second].push_back(all[i][j].second);
					con[all[i][j].second].push_back(all[i][0].second);
				}
		}
	sort(per.begin(), per.end());
	if (per.size()) {
		int id = per[0].second;
		for (int i = 1; i <= n; ++i)
			if (col[i] != col[id] && wei[i] + wei[id] <= y) {
				con[id].push_back(i);
				con[i].push_back(id);
			}
	}
	if (per.size() > 1) {
		int id = per[1].second, min_col = col[per[0].second];
		for (vector<pair<int, int> >::iterator it = all[min_col].begin(); it != all[min_col].end(); ++it)
			if (it->first + wei[id] <= y) {
				con[id].push_back(it->second);
				con[it->second].push_back(id);
			}
	}
	dfs(per[0].second);
	int ans = fac[cnt];
	for (int i = 0; i < seq.size(); ++i) {
		int small = bin[seq[i]];
		bin[seq[i]] = 0;
		ans = (long long)ans * inv[small] % mod;
	}
	printf("%d\n", ans);
}

