const int MOD = int(1e9) + 7;

int n, x, y;
int c[200005], w[200005];

int par[200005], ra[200005];

void dsuInit() {
    forn(i, n) par[i] = i, ra[i] = 1;
}

int dsuParent(int v) {
    if (v == par[v]) return v;
    return par[v] = dsuParent(par[v]);
}

void dsuMerge(int u, int v) {
    u = dsuParent(u);
    v = dsuParent(v);
    if (u == v) return;
    if (ra[u] < ra[v]) swap(u, v);
    par[v] = u;
    ra[u] += ra[v];
}

vector<int> cm[200005];
map<int, int> cnt;
int f[200005], rf[200005];

int binPow(LL x, int p) {
    LL res = 1;
    while (p) {
        if (p & 1) res = res * x % MOD;
        p >>= 1;
        if (p) x = x * x % MOD;
    }
    return (int)res;
}

int C(int n, int k) {
    return (LL)f[n] * rf[k] % MOD * rf[n - k] % MOD;
}

inline bool cmp(const int &lhs, const int &rhs) {
    return w[lhs] < w[rhs];
}

vector<int> pos[200005];
vector<int> upto[200005];

const int INF = int(2e9) + 123;

int main() {
    f[0] = rf[0] = 1;
    for (int i = 1; i < 200005; ++i) {
        f[i] = (LL)f[i - 1] * i % MOD;
        rf[i] = binPow(f[i], MOD - 2);
    }
    scanf("%d%d%d", &n, &x, &y);
    forn(i, n) scanf("%d%d", c + i, w + i), --c[i];
    dsuInit();

    forn(i, n) pos[c[i]].pb(i);
    forn(i, n) sort(pos[i].begin(), pos[i].end(), cmp);
    int best = -1, best2 = -1;
    int bestVal = INF, bestVal2 = INF;
    forn(i, n) if (!pos[i].empty()) {
        int val = w[pos[i][0]];
        if (val < bestVal) {
            bestVal2 = bestVal;
            best2 = best;
            best = i;
            bestVal = val;
        } else if (val < bestVal2) {
            bestVal2 = val;
            best2 = i;
        }
    }

    forn(i, n) if (!pos[i].empty()) {
        for (int j = 1; j < (int)pos[i].size() && w[pos[i][0]] + w[pos[i][j]] <= x; ++j) {
            dsuMerge(pos[i][0], pos[i][j]);
        }
        if (best != -1 && best != i) {
            for (int j = 0; j < (int)pos[i].size() && w[pos[best][0]] + w[pos[i][j]] <= y; ++j) {
                dsuMerge(pos[best][0], pos[i][j]);
            }
        }
        if (best2 != -1 && best2 != i) {
            for (int j = 0; j < (int)pos[i].size() && w[pos[best2][0]] + w[pos[i][j]] <= y; ++j) {
                dsuMerge(pos[best2][0], pos[i][j]);
            }
        }
    }

    forn(i, n) {
        cm[dsuParent(i)].pb(i);
    }
    int ans = 1;
    forn(i, n) if (!cm[i].empty()) {
        cnt.clear();
        for (int x : cm[i]) {
            ++cnt[c[x]];
        }
        int cc = 0;
        for (PII p : cnt) {
            ans = (LL)ans * C(cc + p.second, p.second) % MOD;
            cc += p.second;
        }
    }
    cout << ans << endl;
    return 0;
}

