ll facs[200005];
ll ifacs[200005];
const int MOD = 1000000007;

ll modpow(ll b, ll e, ll m) {
  ll r = 1;
  while(e) {
    if(e%2) {
      r*=b;
      r%=m;
    }
    b*=b;
    b%=m;
    e/=2;
  }
  return r;
}
void init() {
  facs[0] = 1;
  for(int i = 1; i <= 200000; i++) {
    facs[i] = facs[i-1] * i;
    facs[i] %= MOD;
  }
  ifacs[200000] = modpow(facs[200000], MOD-2, MOD);
  for(int i = 199999; i >= 0; i--) {
    ifacs[i] = ifacs[i+1] * (i+1);
    ifacs[i] %= MOD;
  }
}

int color[200005];
int weight[200005];
vector<pii> colorToPair[200005];
vector<int> parentToColor[200005];

void solve() {
  int n, x, y;
  cin >> n >> x >> y;
  int lowestIndex = -1;
  int lowestWeight = 2e9;
  for(int i = 0; i < n; i++) {
    par[i] = i;
    cin >> color[i] >> weight[i];
    colorToPair[--color[i]].push_back({weight[i], i});
    if(weight[i] < lowestWeight) {
      lowestWeight = weight[i];
      lowestIndex = i;
    }
  }
  for(int i = 0; i < n; i++) {
    if(color[i] == color[lowestIndex]) continue;
    if(weight[i] + weight[lowestIndex] <= y) {
      merge(lowestIndex, i);
    }
  }
  for(int i = 0; i < n; i++) {
    if(colorToPair[i].empty()) continue;
    sort(colorToPair[i].begin(), colorToPair[i].end());
    for(int j = 1; j < colorToPair[i].size(); j++) {
      if(colorToPair[i][0].first + colorToPair[i][j].first <= x) {
        merge(colorToPair[i][0].second, colorToPair[i][j].second);
      }
      else {
        break;
      }
    }
  }
  ll ret = 1;
  for(int i = 0; i < n; i++) {
    parentToColor[find(i)].push_back(color[i]);
  }
  for(int i = 0; i < n; i++) {
    if(parentToColor[i].size() <= 1) continue;
    sort(parentToColor[i].begin(), parentToColor[i].end());
    ll inc = facs[parentToColor[i].size()];
    for(int j = 0; j < parentToColor[i].size();) {
      int k = j;
      while(k < parentToColor[i].size() && parentToColor[i][j] == parentToColor[i][k]) {
        k++;
      }
      inc *= ifacs[k-j];
      inc %= MOD;
      j = k;
    }
    ret *= inc;
    ret %= MOD;
  }
  cout << ret << "\n";
}

void casesolve() {
  int t;
  cin >> t;
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << ":" << "\n";
    solve();
  }
}

int main() {
  init();
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);
  solve();
