  for(int i=1;i<=n;++i) if(G[i].size()) {
    sort(G[i].begin(),G[i].end(),cmp);
    int j=0; while(j!=(int)G[i].size()-1&&B[G[i][0]]+B[G[i][j+1]]<=X) F[Find(G[i][++j])]=F[Find(G[i][0])];
    T.push_back(G[i][0]);
  }
  sort(T.begin(),T.end(),cmp);
  int p=0; while(p!=(int)T.size()-1&&B[T[0]]+B[T[p+1]]<=Y) F[Find(T[++p])]=F[Find(T[0])];
  Fac[0]=1;
  for(int i=1;i<=n;++i) Fac[i]=1ll*Fac[i-1]*i%P;
  Inv[n]=Pow(Fac[n],P-2);
  for(int i=n-1;~i;--i) Inv[i]=1ll*(i+1)*Inv[i+1]%P;
  for(int i=1;i<=n;++i) S[Find(i)].push_back(i);
  int res=1;
  for(int i=1;i<=n;++i) if(S[i].size()) {
    int t=Fac[S[i].size()];
    for(auto v: S[i]) {
      t=1ll*t*Fac[cnt[A[v]]]%P;
      ++cnt[A[v]];
      t=1ll*t*Inv[cnt[A[v]]]%P;
    }
    for(auto v: S[i]) --cnt[A[v]];
    res=1ll*res*t%P;
  }
  printf("%d\n",res);
  return 0;
}

#include <algorithm>
#include <cstdio>
#include <cstring>
