const int MaxN = 200000 + 5;
const int Mod = 1000000007;

int N, X, Y;
int A[MaxN], B[MaxN];
int Fac[MaxN];
std::vector<int> Col[MaxN];

inline int add(int x, int y) { return (x += y) >= Mod ? x - Mod : x; }
inline int sub(int x, int y) { return (x -= y) < 0 ? x + Mod : x; }
inline int mul(int x, int y) { return 1LL * x * y % Mod; }
inline int pw(int x, int y) { int z = 1; for (; y; y >>= 1, x = mul(x, x)) if (y & 1) z = mul(z, x); return z; }
inline int inv(int x) { return pw(x, Mod - 2); }
inline int sep(int x, int y) { return mul(x, inv(y)); }

void init() {
  scanf("%d %d %d", &N, &X, &Y);
  for (int i = 1; i <= N; ++i) {
    scanf("%d %d", &A[i], &B[i]);
    Col[A[i]].push_back(B[i]);
  }
  Fac[0] = 1;
  for (int i = 1; i <= N; ++i) Fac[i] = mul(Fac[i - 1], i);
}

inline bool cmp(int x, int y) {
  return Col[x][0] < Col[y][0];
}

void solve() {
  for (int i = 1; i <= N; ++i) {
    std::sort(Col[i].begin(), Col[i].end());
//    if (!Col[i].empty()) printf("Col[%d][0] = %d\n", i, Col[i][0]);
  }
  static int vec[MaxN]; int cntv = 0;
  for (int i = 1; i <= N; ++i)
    if (!Col[i].empty()) vec[++cntv] = i;
  std::sort(vec + 1, vec + 1 + cntv, cmp);

  int totSize = 0, ans = 1;
  for (int i = 1; i <= cntv; ++i) {
//    printf("%d + %d = %d\n", Col[vec[1]][0], Col[vec[i]][0], Col[vec[1]][0] + Col[vec[i]][0]);
    if (Col[vec[1]][0] + Col[vec[i]][0] > Y) break;
    int num = 1;
    for (int j = 1; j < (int) Col[vec[i]].size(); ++j) {
      int mnOutsize = 1;
      if (cntv != 1 && i == 1) mnOutsize = 2;
      if ((Col[vec[1]][0] + Col[vec[i]][j] > Y || mnOutsize == i) && Col[vec[i]][0] + Col[vec[i]][j] > X) break;
      num++;
    }
    totSize += num;
    ans = mul(ans, Fac[num]);
  }
  ans = sep(Fac[totSize], ans);
  printf("%d\n", ans);
}

int main() {
  init();
  solve();
  return 0;
}

