namespace ModCalculator {
	inline void Inc(int &x, int y) {
		x += y; if (x >= MOD) x -= MOD;
	}
	inline void Dec(int &x, int y) {
		x -= y; if (x < 0) x += MOD;
	}
	inline int Add(int x, int y) {
		Inc(x, y); return x;
	}
	inline int Sub(int x, int y) {
		Dec(x, y); return x;
	}
	inline int Mul(int x, int y) {
		return 1LL * x * y % MOD;
	}
}
using namespace ModCalculator;

inline int ksm(int x, int k) {
    int ret = 1;
   	for (; k; k >>= 1) {
        if (k & 1) ret = Mul(ret, x);
        x = Mul(x, x);
    }
    return ret;
}

int n, col[MAXN], X, Y, fac[MAXN], finv[MAXN];

struct Node {
	int w, id;
	bool operator < (const Node &rhs) const {
		return w < rhs.w;
	}
} mn, mn2;
vector<Node> a[MAXN];

int vis[MAXN], siz;
vector<int> g[MAXN];
map<int, int> mp;

inline void AddEdge(int u, int v) {
	g[u].push_back(v);
	g[v].push_back(u);
}

void DFS(int u) {
	siz += (vis[u] = 1);
	++mp[col[u]];
	for (auto v : g[u]) {
		if (vis[v]) continue;
		DFS(v);
	}
}

void init() {
	read(n); read(X); read(Y);
	for (int i = 1, w; i <= n; ++i) {
		read(col[i]); read(w);
		a[col[i]].push_back((Node){w, i});
	}
	fac[0] = 1;
	for (int i = 1; i <= n; ++i) {
		fac[i] = Mul(fac[i - 1], i);
	}
	finv[n] = ksm(fac[n], MOD - 2);
	for (int i = n; i >= 1; --i) {
		finv[i - 1] = Mul(finv[i], i);
	}
}

void solve() {
	mn.w = mn2.w = INF;
	for (int i = 1; i <= n; ++i) {
		int sz = a[i].size();
		if (sz == 0) continue;
		sort(a[i].begin(), a[i].end());
		for (int j = 0; j < sz - 1; ++j) {
			if (a[i][j].w + a[i][j + 1].w <= X) {
				AddEdge(a[i][j].id, a[i][j + 1].id);
			}
		}
		if (a[i][0] < mn) {
			mn2 = mn;
			mn = a[i][0];
		} else if (a[i][0] < mn2) {
			mn2 = a[i][0];
		}
	}
	for (int i = 1; i <= n; ++i) {
		Node cur = ((i == col[mn.id])? mn2 : mn);
		for (auto p : a[i]) {
			if (p.w + cur.w <= Y) {
				AddEdge(p.id, cur.id);
			} else {
				break;
			}
		}
	}

	int ans = 1;
	for (int i = 1; i <= n; ++i) {
		if (vis[i]) continue;
		siz = 0;
		mp.clear();
		DFS(i);
		ans = Mul(ans, fac[siz]);
		for (auto p : mp) {
			ans = Mul(ans, finv[p.second]);
		}
	}
	printf("%d\n", ans);
}

int main() {
	init();
	solve();	
	return 0;
}

