            }
        }
        pref[i+1] = pref[i];
        if (!e[i].empty()) pref[i+1] = min(pref[i+1], e[i].front());
    }
    pair<int, int> mini = {inf, 0};
    for (int i = n-1; i >= 0; i--) {
        for (auto &p: e[i]) {
            if (pref[i].first + p.first <= y) {
                uf.unite(pref[i].second, p.second);
            }
            if (mini.first + p.first <= y) {
