        mv[x][col[i-1]]++;
    } 
    long long ans = 1;
    for (auto &m: mv) {
        int sum = 0;
        for (auto &iter: m) {
            ans = ans * inv_factorial[iter.second] % mod;
            sum += iter.second;
        }
        if (sum != 0) ans = ans * factorial[sum] % mod;
    }
    cout << ans << "\n";
    return 0;
}

