	}
};

struct treap
{
	data t[N];
	int tot,l[N],r[N],cur[N],root,stk[N];
	LL key[N<<1];

	LL ran()
	{
		return seed=((seed^998244353)*1000000007ll+19260817)%1000000009;
	}

	int New()
	{
		return *stk?stk[(*stk)--]:++tot;
	}

	int getfa(int x)
	{
		return fa[x]==x?x:fa[x]=getfa(fa[x]);
	}

	void merge(int x,int y)
	{
		x=getfa(x),y=getfa(y);
		if(x!=y) fa[x]=y;
	}

   void rotate(int &x,bool tp)
    {
        int y=tp?r[x]:l[x];
        if(tp) r[x]=l[y],l[y]=x;
        else l[x]=r[y],r[y]=x;
        x=y;
    }	

	void turn(int rt,int x)
	{
		if(!rt) return;
		if(cur[rt]) merge(cur[rt],x);
		else cur[rt]=x,merge(x,t[rt].y);
	}

	void pushdown(int rt)
	{
		if(cur[rt]) turn(l[rt],cur[rt]),turn(r[rt],cur[rt]),cur[rt]=0;
	}

	void ins(int &rt,data x)
	{
		if(!rt)
		{
			rt=New(),key[rt]=ran(),t[rt]=x;
			return;
		}
		pushdown(rt);
		if(x<t[rt])
		{
			ins(l[rt],x);
			if(key[l[rt]]>key[rt]) rotate(rt,0);
		}
		else
		{
			ins(r[rt],x);
			if(key[r[rt]]>key[rt]) rotate(rt,1);
		}
	}

	void ins(data x)
	{
		ins(root,x);
	}

	void erase(int &rt,data x)
	{
		if(pushdown(rt),t[rt]==x)
		{
			if(!l[rt] && !r[rt]) {stk[++*stk]=rt,rt=0; return;}
			if(key[l[rt]]>key[r[rt]]) pushdown(l[rt]),rotate(rt,0),erase(r[rt],x);
			else pushdown(r[rt]),rotate(rt,1),erase(l[rt],x);
		}
		else if(x<t[rt]) erase(l[rt],x);
		else erase(r[rt],x);
	}

	void erase(data x)
	{
		erase(root,x);
	}

	void modify(int rt,int lim,int x)
	{
		if(!rt) return;
		if(t[rt].x<=lim) merge(x,t[rt].y),turn(l[rt],x),modify(r[rt],lim,x);
		else modify(l[rt],lim,x);
	}

	void modify(int lim,int x)
	{
		modify(root,lim,x);
	}

	void dfs(int rt)
	{
		if(!rt) return;
		pushdown(rt);
		dfs(l[rt]),dfs(r[rt]);
	}

	void dfs()
	{
		dfs(root);
	}
} t;

