const int mod = 1e9 + 7;
const int N = 2e5 + 100;

int mn1, mn2, rem1, rem2;
int n, X, Y;
int col[N], w[N];
vi all;

struct color
{
	int mn, mx, cnt;
	vi apr;

	void init()
	{
		cnt = 0, mx = 0, mn = iinf;
		for(int i: apr)
		{
			chkmin(mn, w[i]);
			chkmax(mx, w[i]);
		}
		return;
	}

	void work(int o_mn)
	{
		for(int i: apr)
		{
			int w = ::w[i];
			if(w + mn <= X || w + o_mn <= Y) ++cnt;
		}
		return;
	}
}a[N];

int fac[N], ifac[N];

int pow_mod(int x, int n)
{
	int ret = 1;
	while(n)
	{
		if(n & 1) ret = 1ll * ret * x % mod;
		x = 1ll * x * x % mod;
		n >>= 1;
	}
	return ret;
}

int C(int n, int m)
{
	if(n < m || n < 0 || m < 0) return 0;
	return 1ll * fac[n] * ifac[m] % mod * ifac[n - m] % mod;
}

void TZL()
{
	scf(n, X, Y);
	forn(i, 1, n) scf(col[i], w[i]);
	forn(i, 1, n) a[col[i]].apr.pb(i), all.pb(col[i]);
	sort(ALL(all)); all.resize(unique(ALL(all)) - all.begin());
	for(int c: all) a[c].init();

	mn1 = iinf, mn2 = iinf;
	for(int c: all)
	{
		int mn = a[c].mn;
		if(mn < mn1) mn2 = mn1, rem2 = rem1, mn1 = mn, rem1 = c;
		else if(mn < mn2) mn2 = mn, rem2 = c;
	}

	for(int c: all)
	{
		if(c == rem1) a[c].work(mn2); else a[c].work(mn1);
	}

	fac[0] = 1;
	forn(i, 1, n) fac[i] = 1ll * i * fac[i - 1] % mod;
	forn(i, 0, n) ifac[i] = pow_mod(fac[i], mod - 2);
	return;
}

vi lft;

void RANK1()
{
	int sum = 0, ans = 1;
	for(int c: all)
	{
		int o_mn;
		if(c == rem1) o_mn = mn2; else o_mn = mn1;
		if(o_mn + a[c].mn <= Y) lft.pb(a[c].cnt), sum += a[c].cnt;
	}

	for(int x: lft)
	{
		ans = 1ll * ans * C(sum, x) % mod;
		sum -= x;
	}
	printf("%d\n", ans);
	return;
}

