const int inf = 0x7fffffff;

typedef long long ll;

/*
 边应该分为两类：
 第一类：同色。考虑与最小w连边。
 第二类：异色。
 考虑两种交换

 */

int n = 0, x, y;

int jc[maxn], inv[maxn], ijc[maxn];
int c[maxn], w[maxn], cnt[maxn];
vector<int> vec[maxn];
int fa[maxn];
int mn_c[maxn], mn_i[maxn];
int zx, cx;

int getroot(int x) {
    return (fa[x] == x) ? x : (fa[x] = getroot(fa[x]));
}

void Union(int x, int y) {
    int rx = getroot(x), ry = getroot(y);
    if (rx == ry) return;
    fa[rx] = ry;
}

int main() {
    scanf("%d%d%d", &n, &x, &y);
    for (int i = 1; i <= n; i++) fa[i] = i;
    jc[0] = ijc[0] = 1;
    for (int i = 1; i <= n; i++) {
        mn_c[i] = inf;
        jc[i] = 1ll*jc[i-1]*i%mod;
        if (i > 1) {
            inv[i] = mod-1ll*(mod/i)*inv[mod%i]%mod;
            ijc[i] = 1ll*ijc[i-1]*inv[i]%mod;
        } else inv[1] = ijc[1] = 1;
    }
    for (int i = 1; i <= n; i++) {
        scanf("%d%d", &c[i], &w[i]);
        if (w[i] < mn_c[c[i]]) {
            mn_c[c[i]] = w[i];
            mn_i[c[i]] = i;
        }
    }
    mn_c[0] = inf;
    for (int i = 1; i <= n; i++) {
        if (mn_c[i] <= mn_c[zx]) {
            cx = zx;
            zx = i;
        } else if (mn_c[i] < mn_c[cx])
            cx = i;
    }
    for (int i = 1; i <= n; i++) {
        int t = c[i];
        if (mn_c[t]+w[i] <= x) Union(i, mn_i[t]);
        if (i == zx) {
            if (cx) {
                if (mn_c[cx]+w[i] <= y) Union(i, mn_i[cx]);
            }
        } else {
            if (mn_c[zx]+w[i] <= y) Union(i, mn_i[zx]);
        }
    }
    int ans = 1;
    for (int i = 1; i <= n; i++) vec[getroot(i)].push_back(i);
    for (int i = 1; i <= n; i++) {
        int tot = (int)vec[i].size();
        int tmp = jc[tot];
        for (int j = 0; j < vec[i].size(); j++) cnt[c[vec[i][j]]] ++;
        for (int j = int(vec[i].size())-1; j >= 0; j--) {
            if (cnt[c[vec[i][j]]]) {
                tmp = 1ll*tmp*ijc[cnt[c[vec[i][j]]]]%mod;
            }
            cnt[c[vec[i][j]]] = 0;
        }
        ans = 1ll*ans*tmp%mod;
    }
    printf("%d\n", ans);
    return 0;
}

