ll mul(ll a, ll b){
    return ((a%mod)*(b%mod))%mod;
}

ll pw(ll b, ll e){
    if(e==0) return 1;
    ll t = pw(b,e/2);
    if(e&1) return mul(b,mul(t,t));
    return mul(t,t);
}

ll inverse(ll x){
    return pw(x,mod-2);
}

