const intl Mo = 1000000007LL;

int n, top;
vector<int> vec[maxn];
int CNT[maxn], cnt[maxn];
intl fac[maxn], inv[maxn];
int x, y;
intl ans;

intl fpm(intl a, intl b) {
	if (!a) return 0LL;
	intl ans = 1LL;
	for (; b; b >>= 1) {
		if (b & 1LL) ans *= a, ans %= Mo;
		a *= a; a %= Mo;
	}
	return ans;
}

intl C(int a, int b) {
	return fac[a] * inv[b] % Mo * inv[a - b] % Mo;
}

int main() {
	scanf("%d %d %d",&n,&x,&y);
	fac[0] = 1;
	for (int i = 1; i <= n; i++)
		fac[i] = fac[i - 1] * (intl) i % Mo;
	inv[n] = fpm(fac[n], Mo - 2LL);
	for (int i = n; i >= 1; i--)
		inv[i - 1] = inv[i] * (intl) i % Mo;	
	for (int i = 1; i <= n; i++) {
		int c, w;
		scanf("%d %d",&c,&w);
		vec[c].push_back(w);
	}
	for (int i = 1; i <= n; i++)
		sort(vec[i].begin(), vec[i].end());
	int just = 1 << 30;
	int tp = 0;
	for (int i = 1; i <= n; i++) {
		if (!vec[i].empty()) {
			if (just > vec[i][0]) tp = i;
			just = min(just, vec[i][0]);
		}
	}

	for (int i = 1; i <= n; i++) {
		for (auto j = vec[i].begin(); j != vec[i].end(); j++)
			if (vec[i][0] + *j <= x || j == vec[i].begin() || just + *j <= y) cnt[i]++;		
	}
	CNT[++top] = cnt[tp];
	for (int i = 1; i <= n; i++) {
		if (vec[i].empty() || i == tp) continue;
		if (vec[i][0] + just <= y) CNT[++top] = cnt[i];
		//else TNC[++tp] = cnt[i];
	}
	for (int i = 1; i <= top; i++) CNT[i] += CNT[i - 1];
	ans = 1LL;
	for (int i = top; i >= 1; i--)
		(ans *= C(CNT[i], CNT[i - 1])) %= Mo;
	cout << ans << endl;
	return 0;
}

