using namespace std;
int N, X ,Y;
pair <int, int> Array[200005];
int Fact[200005], InvFact[200005];
const int MOD = 1000000007;
int MinW[200005];
set <pair <int, int> > S;
int Colour[200005], total;
int powerLog(int n, int p)
{
    int sol = 1;
    while(p)
    {
        if((p & 1))
        {
            sol = (1LL * sol * n) % MOD;
        }
        n = (1LL * n * n) % MOD;
        p /= 2;
    }
    return sol;
}
void precalcFact()
{
    Fact[0] = InvFact[0] = 1;
    for(int i = 1; i <= N; i++)
    {
        Fact[i] = (1LL * Fact[i - 1] * i) % MOD;
        InvFact[i] = powerLog(Fact[i], MOD - 2);
    }

}

void Read()
{
    cin >> N >> X >> Y;
    total = N;
    for(int i = 1; i <= N; i++)
    {
        cin >> Array[i].first >> Array[i].second;
        Colour[Array[i].first]++;
        MinW[i] = 1000000005;
    }
}

void precalcMinW()
{
    for(int i = 1; i <= N; i++)
    {
        MinW[Array[i].first] = min(MinW[Array[i].first], Array[i].second);
    }
    for(int i = 1; i <= N; i++)
    {
        if(Array[i].second + MinW[Array[i].first] <= X)
            Array[i].second = MinW[Array[i].first];
        S.insert(make_pair(MinW[Array[i].first], Array[i].first));
    }
}

void Solve()
{
    for(int i = 1; i <= N; i++)
    {
        S.erase(make_pair(MinW[Array[i].first], Array[i].first));
        if(S.size() != 0)
        {
            auto it = S.begin();
            if(it -> first + Array[i].second > Y)
            {
                Colour[Array[i].first]--;
                --total;
            }
        }
        else
            Colour[Array[i].first]--, total--;
        S.insert(make_pair(MinW[Array[i].first], Array[i].first));
    }
    int ans = Fact[total];
    for(int i = 1; i <= N; i++)
        ans = (1LL * ans * InvFact[Colour[i]]) % MOD;
    cout << ans << "\n";
}


int main()
{
    Read();
    precalcFact();
    precalcMinW();
    Solve();
    return 0;
}

