ll mod=1000000007;
struct UnionFind{
    public:
    vector<int> data;
    UnionFind(ll sz){
        data.assign(sz, -1);
    }
    int find(int p){
        if(data[p]<0) return p;
        return data[p]=find(data[p]);
    }
    bool unite(int X, int Y){
        X=find(X), Y=find(Y);
        if(X==Y) return false;
        if(data[X]>data[Y]) swap(X, Y);
        data[X] += data[Y];
        data[Y]=X;
        return true;
    }
    ll size(int k){
        return -data[find(k)];
    }
};

ll modpow(ll a, ll b, ll m){
    ll res=1, p=0, now=a;
    b %= (m-1);
    for(int i=0; b>p; ++i){
        if(b&((ll) 1<<i)){
            res=(res*now)%m;
            p |= ((ll) 1<<i);
        }
        now=(now*now)%mod;
    }
    return res;
}

int main() {
	int N;
	ll X, Y;
	cin >> N >> X >> Y;
	vector<vector<int>> b(N+1);
	vector<pair<ll, int>> t(N);
	for(int i=0; i<N; ++i){
		int c;
		ll w;
		cin >> c >> w;
		t[i]=make_pair(w, c);
	}
	sort(t.begin(), t.end());
	vector<pair<ll, int>> mn1(N+1, make_pair(1e9, -1)), mn2(N+1, make_pair(1e9, 0));
	UnionFind uf(N);
	for(int i=0; i<N; ++i){
		if(mn1[t[i].second].second<0) mn1[t[i].second]=make_pair(t[i].first, i);
		else if(t[i].first+mn1[t[i].second].first<=X){
			uf.unite(i, mn1[t[i].second].second);
		}
		b[t[i].second].push_back(i);
	}
	for(int i=1; i<=N; ++i){
		if(i!=t[0].second) mn2[i]=make_pair(t[0].first, 0);
	}
	int now=1;
	while(now<N){
		if(t[now].second!=t[0].second) break;
		++now;
	}
	if(now<N) mn2[t[0].second]=make_pair(t[now].first, now);
	for(int i=0; i<N; ++i){
		if(t[i].first+mn2[t[i].second].first<=Y){
			uf.unite(i, mn2[t[i].second].second);
		}
	}
	ll ans=1;
	vector<ll> cnt(N+1, 0);
	vector<int> num(N+1, 0);
	for(int i=0; i<N; ++i) ++cnt[uf.size(i)];
	for(int i=1; i<=N; ++i) cnt[i] /= i;
	for(int i=1; i<=N; ++i){
		vector<int> see;
		for(int j=0; j<b[i].size(); ++j){
			int aa=uf.find(b[i][j]);
			if(num[aa]==0) see.push_back(aa);
			++num[aa];
		}
		for(int j=0; j<see.size(); ++j){
			cnt[num[see[j]]]=(cnt[num[see[j]]]+mod-2)%(mod-1);
			num[see[j]]=0;
		}
	}
	ll frac=1;
	for(int i=1; i<=N; ++i){
		frac=(frac*i)%mod;
		ans=(ans*modpow(frac, cnt[i], mod))%mod;
	}
	cout << ans << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Mod
{
    static const auto P = int(1e9+7);
    long long k;

    Mod() = default;
    Mod(const long long k) : k(k%P) {}
};

Mod operator*(const Mod a, const Mod b) { return a.k * b.k; }
Mod& operator*=(Mod& a, const Mod b) { return a = a*b; }
Mod power(const Mod a, const int k)
{
    if (k == 0) return 1;
    else if (k % 2 == 0) return power(a*a, k/2);
    else return a * power(a*a, k/2);
}
Mod inverse(const Mod a) { return power(a, Mod::P-2); }

struct DisjointSets
{
    int N;
    vector<int> representatives, sizes;

    DisjointSets(const int N) : N(N), representatives(N), sizes(N, 1)
    {
        iota(begin(representatives), end(representatives), 0);
    }

    int find(const int n)
    {
        if (representatives[n] != n)
            representatives[n] = find(representatives[n]);
        return representatives[n];
    }

    void merge(int n, int m)
    {
        n = find(n), m = find(m);
        if (n == m) return;
        representatives[n] = m;
        sizes[m] += sizes[n];
    }

    int size(const int n) { return sizes[find(n)]; }
};

int main()
{
    int N, X, Y; cin >> N >> X >> Y;

    struct Ball { int index, color, weight; };
    auto balls = vector<vector<Ball>>(N);
    for (auto i = 0; i < N; i++)
    {
        int c, w; cin >> c >> w;
        c--;
        balls[c].push_back({i, c, w});
    }

    for (auto& bs : balls) sort(begin(bs), end(bs), [](const Ball a, const Ball b) { return a.weight < b.weight; });
    const auto compare = [](const vector<Ball>& a, const vector<Ball>& b)
    {
        if (b.empty()) return true;
        else if (a.empty()) return false;
        else return a[0].weight < b[0].weight;
    };
    sort(begin(balls), end(balls), compare);

    auto components = DisjointSets(N);
    const auto add_edge = [&](const Ball a, const Ball b)
    {
        const auto bound = a.color == b.color ? X : Y;
        if (a.weight + b.weight <= bound)
            components.merge(a.index, b.index);
    };

    for (const auto& bs : balls) for (const auto b : bs)
    {
        add_edge(b, bs[0]);
        add_edge(b, balls[0][0]);
        if (N >= 2 && !balls[1].empty()) add_edge(b, balls[1][0]);
    }

    auto color_counts = vector<map<int, int>>(N);
    for (const auto& bs : balls) for (const auto b : bs)
        color_counts[components.find(b.index)][b.color]++;

    auto factorials = vector<Mod>(N+1);
    factorials[0] = 1;
    for (auto n = 1; n <= N; n++) factorials[n] = n * factorials[n-1];

    auto inverse_factorials = vector<Mod>(N+1);
    inverse_factorials[N] = inverse(factorials[N]);
    for (auto n = N; n >= 1; n--) inverse_factorials[n-1] = n * inverse_factorials[n];

    auto result = Mod(1);
    for (auto i = 0; i < N; i++) if (components.find(i) == i)
    {
        result *= factorials[components.size(i)];
        for (const auto kv : color_counts[i])
            result *= inverse_factorials[kv.second];
    }
    cout << result.k << endl;
}

