// a,b の最大公約数と、ax + by = gcd(a,b) となる x,y を求める
long long extgcd(long long a, long long b, long long &x, long long &y) {
    long long g = a;
    if(b != 0){
        g = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }else{
        x = 1;
        y = 0;
    }
    return g;
}

// ax ≡ gcd(a, m) (mod m) となる x を求める
// a, m が互いに素ならば、関数値は mod m での a の逆数となる
long long mod_inverse(long long a, long long m)
{
    long long x, y;
    extgcd(a, m, x, y);
    return (x % m + m) % m;
}

// 階乗数の事前計算を用いた各種組合せ
class FactorialCalculation
{
private:
    const int mod;
    vector<long long> factorial;
    vector<long long> invFactorial;
public:
    FactorialCalculation(int n, int mod) : mod(mod)
    {
        factorial.resize(n+1, 1);
        invFactorial.resize(n+1, 1);
        for(int i=1; i<=n; ++i){
            factorial[i] = factorial[i-1] * i % mod;
            invFactorial[i] = mod_inverse(factorial[i], mod);
        }
    }
    long long getFactorial(int n){
        return factorial[n];
    }
    long long getPermutation(int n, int r){
        if(n < r)
            return 0;
        return factorial[n] * invFactorial[n-r] % mod;
    }
    long long getCombination(int n, int r){
        if(n < r)
            return 0;
        return getPermutation(n, r) * invFactorial[r] % mod;
    }
    long long getHomogeneous(int n, int r){
        return getCombination(n+r-1, r);
    }
};

const int INF = INT_MAX / 2;
const int MOD = 1000000007;

int main()
{
    int n, x, y;
    cin >> n >> x >> y;
    FactorialCalculation calc(n, MOD);

    vector<vector<int> > weight(n, vector<int>(1, INF));
    for(int i=0; i<n; ++i){
        int c, w;
        cin >> c >> w;
        weight[c-1].push_back(w);
    }
    for(int i=0; i<n; ++i)
        sort(weight[i].begin(), weight[i].end());
    sort(weight.begin(), weight.end());
    int m = 0;
    while(m < n && weight[m].size() > 1)
        ++ m;
    weight.resize(m);

    vector<int> cnt(m, 0);
    cnt[0] = 1;
    for(int i=0; i<m; ++i){
        if(i != 0){
            while(weight[0][0] + weight[i][cnt[i]] <= y)
                ++ cnt[i];
        }
        if(cnt[i] > 0){
            while(weight[i][0] + weight[i][cnt[i]] <= x)
                ++ cnt[i];
        }
    }

    int sum = 0;
    long long ans = 1;
    for(int i=0; i<m; ++i){
        sum += cnt[i];
        ans *= calc.getCombination(sum, cnt[i]);
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

