			if(c[i] != c[mn1] && w[i] + w[mn1] <= Y)
				add_edge(i, mn1);
		for(int i = 1; i <= n; i++)
			if(c[i] != c[mn2] && w[i] + w[mn2] <= Y)
				add_edge(i, mn2);
	}
	int ans = 1, tmp = 1;
	for(int i = 1; i <= n; i++)
