#define Int long long
Int extgcd(Int a, Int b, Int &x, Int &y) {
	Int g = a; x = 1; y = 0;
	if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
	return g;
}
Int invMod(Int a, Int m) {
	Int x, y;
	if (extgcd(a, m, x, y) == 1) return (x + m) % m;
	else                         return 0; // unsolvable
}

void calc() {
	int n, x, y; cin >> n >> x >> y;
	map<int, int> cmap;
	int cnt = 0;
	vector<vector<P>> ws;
	UnionFind uf(n);
	for (int i = 0; i < n; i++) {
		int c, w; cin >> c >> w;
		if (!cmap.count(c)) {
			cmap[c] = cnt++;
			ws.push_back(vector<P>());
		}
		c = cmap[c];
		ws[c].push_back(P(w, i));
	}
	vector<P> mins(cnt);
	V ss(cnt);
	for (int i = 0; i < cnt; i++) {
		sort(all(ws[i]));
		mins[i] = ws[i][0];
		int midx = upper_bound(all(ws[i]), P(x - ws[i][0].first, -1)) - ws[i].begin();
		for (int j = 0; j < midx; j++) {
			uf.unite(ws[i][0].second, ws[i][j].second);
		}
		ss[i] = uf.size(ws[i][0].second);
	}
	for (int i = 0; i < cnt; i++) {
		sort(all(mins));
		int midx = upper_bound(all(mins), P(x - mins[0].first, -1)) - mins.begin();
		for (int j = 0; j < midx; j++) {
			uf.unite(mins[0].second, mins[j].second);
		}
	}

	const int mod = 1e9 + 7;
	V facts(n + 1);
	facts[1] = 1;
	for (int i = 2; i < n + 1; i++) {
		facts[i] = (facts[i - 1] * i) % mod;
	}

	int ans = 1;
	for (int i = 0; i < n; i++) if (uf.isroot(i)) {
		int s = uf.size(i);
		ans = ((ans * facts[s]) % mod);
	}
	rep(i, cnt) {
		ans = (ans * invMod(ss[i], mod)) % mod;
	}
	cout << ans << endl;
}

