const int mod = 1e9 + 7;
int fct[200005], ifct[200005];

int N, X, Y;
vector <int> w[200005];
bitset <200005> f;
vector <int> clr;
int cnt[200005];
int tot;

int power(int x, int y)
{
    int p = x, r = 1;
    while(y)
    {
        if(y & 1)   r = (1LL * r * p) % mod;
        p = (1LL * p * p) % mod;
        y >>= 1;
    }
    return r;
}

bool cmp(int a, int b)
{
    return w[a][0] < w[b][0];
}

void calc(int c, int vmin, int valc)
{
    int p = 0;
    int u = (int)w[c].size() - 1;
    int pos = 0;
    while(p <= u)
    {
        int mij = p + (u - p) / 2;
        int val = w[c][mij];
        if(Y - vmin >= val || X - valc >= val)
        {
            pos = mij;
            p = mij + 1;
        }
        else
            u = mij - 1;
    }
    cnt[c] = pos + 1;
    tot += cnt[c];
}

int main()
{
    #ifdef FILE_IO
    freopen("1.in", "r", stdin);
    freopen("1.out", "w", stdout);
