    {
        int c, v;
        scanf("%d%d", &c, &v);
        w[c].push_back(v);
        if(f[c])    continue;
        f[c] = 1;
        clr.push_back(c);
    }

    if(clr.size() == 1)
    {
        printf("1\n");
        return 0;
    }

    fct[0] = 1;
    for(int i = 1; i <= N; i++) fct[i] = (1LL * fct[i - 1] * i) % mod;
    ifct[N] = power(fct[N], mod - 2);
    for(int i = N - 1; i >= 1; i--) ifct[i] = (1LL * ifct[i + 1] * (i + 1)) % mod;
    ifct[0] = 1;

    for(auto c: clr)    sort(w[c].begin(), w[c].end());
    sort(clr.begin(), clr.end(), cmp);
    int vmin = w[ clr[0] ][0];
    for(int i = 1; i < clr.size(); i++)
    {
        int c = clr[i];
        if(Y - vmin < w[c][0]) break;
        int valc = w[c][0];
        calc(c, vmin, valc);
    }

    if(cnt[ clr[1] ] == 0)
    {
        printf("1\n");
        return 0;
    }

    calc(clr[0], w[ clr[1] ][0], vmin);

    int ans = fct[tot];
    for(auto c: clr)    ans = (1LL * ans * ifct[ cnt[c] ]) % mod;

    printf("%d\n", ans);


    return 0;
}

