struct Mod
{
    static const auto P = int(1e9+7);
    long long k;

    Mod() = default;
    Mod(const long long k) : k(k%P) {}
};

Mod operator*(const Mod a, const Mod b) { return a.k * b.k; }
Mod& operator*=(Mod& a, const Mod b) { return a = a*b; }
Mod power(const Mod a, const int k)
{
    if (k == 0) return 1;
    else if (k % 2 == 0) return power(a*a, k/2);
    else return a * power(a*a, k/2);
}
Mod inverse(const Mod a) { return power(a, Mod::P-2); }

int main()
{
    int N, X, Y; cin >> N >> X >> Y;

    struct Ball { int index, color, weight; };
    auto balls = vector<vector<Ball>>(N);
    for (auto i = 0; i < N; i++)
    {
        int c, w; cin >> c >> w;
        c--;
        balls[c].push_back({i, c, w});
    }

    for (auto& bs : balls)
    {
        sort(begin(bs), end(bs), [](const Ball a, const Ball b) { return a.weight < b.weight; });
        for (auto& b : bs)
            if (b.weight + bs[0].weight <= X)
                b.weight = bs[0].weight;
    }

    const auto compare = [](const vector<Ball>& a, const vector<Ball>& b)
    {
        if (a.empty() && b.empty()) return false;
        else if (a.empty()) return false;
        else if (b.empty()) return true;
        return a[0].weight < b[0].weight;
    };
    sort(begin(balls), end(balls), compare);

    if (N == 1 || balls[1].empty())
    {
        cout << 1 << endl;
        return 0;
    }

    auto counts = vector<int>(N);
    for (const auto& bs : balls) for (const auto b : bs)
    {
        const auto x = b.color == balls[0][0].color ? balls[1][0].weight : balls[0][0].weight;
        if (b.weight + x <= Y) counts[b.color]++;
    }

    auto factorials = vector<Mod>(N+1);
    factorials[0] = 1;
    for (auto n = 1; n <= N; n++)
        factorials[n] = n * factorials[n-1];

    auto inverse_factorials = vector<Mod>(N+1);
    inverse_factorials[N] = inverse(factorials[N]);
    for (auto n = N; n >= 1; n--)
        inverse_factorials[n-1] = n * inverse_factorials[n];

    auto result = factorials[accumulate(begin(counts), end(counts), 0)];
    for (const auto x : counts) result *= inverse_factorials[x];
    cout << result.k << endl;
}

