struct UF{
	vector<int> belong;
	vector<int> size;
	void resize(int n){
		belong.assign(n + 1, -1);
		size.assign(n + 1, 1);
	}
	inline int root(int b){
		if (belong[b] == -1){
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b){
		a = root(a);
		b = root(b);
		if (a == b)return;
		belong[a] = b;
		size[b] += size[a];
	}
};

UF uf;

map<int, int> val[MAX];

vector<int> root;


#define MOD 1000000007
long long int ppow(long long int i, long long int j){
	long long int res = 1LL;
	while (j){
		if ((j & 1LL)){
			res *= i;
			if (res >= MOD){
				res %= MOD;
			}
		}
		j >>= 1;
		i *= i;
		if (i >= MOD){
			i %= MOD;
		}
	}
	return res;
}

long long int k[MAX];
long long int rk[MAX];

pair<int, int> rng[MAX];

int pr[MAX];

vector<int> ich[MAX];

int dif_step(int cur, int col){
	if (cur == 0)return -1;
	cur--;
	if (v[cur].second != col)return cur;
	return pr[cur];
}

