#define int long long

const int MAXN = ( int ) 2e5 + 5;

int N, X, Y;
int C[ MAXN ], W[ MAXN ];
vector< int > c2w[ MAXN ];

int cmax[ MAXN ];
int fact[ MAXN + 1 ];
int inv_fact[ MAXN + 1 ];

int int_pow( int v, int p, int m ){
  int res = not ( v == 0 and p != 0 );
  while( p ){
    if( p & 1 ){
      res = 1LL * res * v % m;
    }
    p >>= 1;
    v = 1LL * v * v % m;
  }
  return res;
}

int unite[ MAXN ];

signed main(){
  ios::sync_with_stdio( 0 );
  {
    cin >> N >> X >> Y;
    for( int i = 0; i < N; ++i ){
      cin >> C[ i ] >> W[ i ];
      --C[ i ];
      c2w[ C[ i ] ].emplace_back( W[ i ] );
    }
    for( int i = 0; i < N; ++i ){
      sort( c2w[ i ].begin(), c2w[ i ].end() );
    }
  }
  {
    int minw = *min_element( W, W + N );
    for( int i = 0; i < N; ++i ){
      if( c2w[ i ].empty() ) continue;
      cmax[ i ] = 1;
      {
        for( int lb = 2, ub = c2w[ i ].size(); lb <= ub; ){
          int mid = lb + ub >> 1;
          if( c2w[ i ][ 0 ] + c2w[ i ][ mid - 1 ] <= X ){
            cmax[ i ] = mid;
            lb = mid + 1;
          } else{
            ub = mid - 1;
          }
        }
      }
      {
        for( int lb = 1, ub = c2w[ i ].size(); lb <= ub; ){
          int mid = lb + ub >> 1;
          if( minw + c2w[ i ][ mid - 1 ] <= Y ){
            unite[ i ] = mid;
            lb = mid + 1;
          } else{
            ub = mid - 1;
          }
        }
      }
    }
  }
  {
    const int MOD = ( int ) 1e9 + 7;
    {
      for( int i = fact[ 0 ] = inv_fact[ 0 ] = 1; i <= MAXN; ++i ){
        fact[ i ] = 1LL * fact[ i - 1 ] * i % MOD;
        inv_fact[ i ] = int_pow( fact[ i ], MOD - 2, MOD );
      }
    }
    int sum = 0;
    for( int i = 0; i < N; ++i ){
      if( not unite[ i ] ) continue;
      sum += max( unite[ i ], cmax[ i ] );
    }
    int ans = fact[ sum ];
    for( int i = 0; i < N; ++i ){
      if( c2w[ i ].empty() ) continue;
      if( not unite[ i ] ) continue;
      ans = 1LL * ans * inv_fact[ max( unite[ i ], cmax[ i ] ) ] % MOD;
    }
    cout << ans << "\n";
  }
  return 0;
}

