  cin >> N >> X >> Y;
  fact[0] = 1;
  factinv[0] = 1;
  for (int i=1; i<=N; i++) {
    fact[i] = (1LL*i*fact[i-1]) % MOD;
    factinv[i] = inv(fact[i]);
  }

  rep(i, N) {
    cin >> C[i] >> W[i];
    C[i]--;
    G[C[i]].pb(P(W[i], i));
  }
