  for (int i=0; i<N; i++) U[i] = i, R[i] = 1;
  rep(i, N) {
    int m = 0;
    if (C[vs[0]._2] == C[i]) {
      if (vs[0]._1 + W[i] <= X) unite(i, vs[0]._2);
      if (vs.size() <= 1) continue;
