	for(int i=0;i<n;i++){
		if(w[i]<mini){
			mini2=mini;
			mini=w[i];
		}else if(w[i]<mini2){
			mini2=w[i];
		}
	}
	ll res=1;
	ll all=0;
	for(int i=0;i<n;i++){
