				int r2=upper_bound(col[i].begin(),col[i].end(),y-mini)-col[i].begin();
				if(mini==col[i][0]){
					r2=upper_bound(col[i].begin(),col[i].end(),y-mini2)-col[i].begin();
				}
				r=max(r,r2);
				if(r<=1){
					all+=1;
				}else{
					all+=r;
					res=res*mod_inverse(fact[r],MOD)%MOD;
				}
			}
		}
	}
