class U {
	private:
		int n,nc;
		vi p,rk,sz;
	public:
		int num() {return nc;}
		U(int v) {
			nc = n = v;
			rk.assign(n,0);
			sz.assign(n,1);
			for(int i=0;i<n;i++) {p.push_back(i);}
		}
		int find(int a) {
			if(a == p[a]) return a;
			return p[a] = find(p[a]);
		}
		bool same(int a, int b) {return find(a) == find(b);}
		int size(int a) {return sz[find(a)];}
		bool un(int a, int b) {
			int x = find(a),y = find(b);
			if(x == y) return false;
			nc--;
			if(rk[x] > rk[y]) {
				p[y] = x;
				sz[x] += sz[y];
				return true;}
			if(rk[x] == rk[y]) rk[y]++;
			p[x] = y;
			sz[y] += sz[x];
			return true;
		}
};
inline ll mul(ll a, ll b) {return (a*b)%M;}
ll bp(ll b, ll p) {
	ll ac = 1;
	while(p) {
		if(p&1) {ac = mul(ac,b);}
		b = mul(b,b);
		p >>= 1;
	}
	return ac;
}
inline ll inv(ll v) {return bp(v,M-2);}
