    auto try_connect = [&](u32 i, u32 j) {
        if (i!=j && w.at(i) + w.at(j) <= (c.at(i)==c.at(j) ? X : Y)) {
            g.at(i).push_back(j);
            g.at(j).push_back(i);
        }
    };

    u32 i0 = std::min_element(ALL(w)) - w.begin();
    REP (i, n) try_connect(i, i0);
    u32 i1 = n;
    REP (i, n) if (c.at(i)!=c.at(i0) && (i1==n || w.at(i) < w.at(i1) )) i1 = i;
    if (i1!=n) REP (i, n)try_connect(i, i1);
    for (auto&& v: cinv) if (!v.empty()) {
        std::sort(ALL(v));
        u32 i = v.front().second;
        for (auto&& p: v) try_connect(p.second, i);
    }

    factorials fact(n+1);

    mint ans = 1;
    std::map<u32, u32> map;
    vec<u32> ckd(n);
    auto dfs = [&](auto&& f, u32 x) -> void {
        ckd.at(x) = true;
        map[c.at(x)]++;
        for (u32 y: g.at(x)) if (!ckd.at(y)) {
            f(f, y);
        }
    };
    for (u32 i=0; i<n; i++) if (!ckd.at(i)) {
        map.clear();
        dfs(dfs, i);
        u32 sum = 0;
        for (auto&& p: map) {
            u32 x = p.second;
            sum += x;
            ans *= fact.inv(x);
        }
        ans *= fact.at(sum);
    }
    std::cout << ans << '\n';
}

