struct Ball {
	int c,w,id;
}b[maxn];

int quick(int a,int b) {
	int sum=1;
	while(b) {
		if(b&1)sum=1ll*sum*a%pps;
		a=1ll*a*a%pps,b>>=1;
	}
	return sum;
}

