	if(a.c==b.c)return a.w<b.w;
	return a.c<b.c;
}

bool cmp2(Ball a,Ball b) {
	if(a.w==b.w)return a.c<b.c;
	return a.w<b.w;
}

void add(int a,int b) {
	pre[++tot]=now[a];
	now[a]=tot,son[tot]=b;
}

void work1() {
	int lst=0;
	for(int i=1;i<=n;i++) {
		if(b[i].c!=b[lst].c) {
			lst=i;continue;
