		if(b[i].w+b[lst].w<=x) {
			add(b[i].id,b[lst].id);
			add(b[lst].id,b[i].id);
		}
	}
}

void work2() {
	for(int i=2;i<=n;i++)
		if(b[i].c!=b[1].c) {
			if(b[i].w+b[1].w>y)break;
			add(b[i].id,b[1].id);
			add(b[1].id,b[i].id);
		}
}

