	sort(b+1,b+n+1,cmp1);work1();
	sort(b+1,b+n+1,cmp2);work2();
	for(int i=1;i<=n;i++)
		if(!vis[i])dfs(i),calc();
	printf("%d\n",ans);
	return 0;
}

