using namespace std;
const int MAXN = 200005;
const int MOD = 1000000007;

ll fact[MAXN],inv[MAXN],w[MAXN];
int u[MAXN],mn[MAXN],arr[MAXN];
map<int,int> mp[MAXN];

ll mod_pow(ll a,ll b,ll m){
	ll ans = 1;
	for(; b ; b >>= 1){
		if(b & 1) ans = ans * a % m;
		a = a * a % m;
	}
	return ans;
}

void pre(){
	fact[0] = 1; 
	for(int i=1;i<MAXN;i++) fact[i] = fact[i-1] * i % MOD;
	inv[MAXN-1] = mod_pow(fact[MAXN-1],MOD-2,MOD);
	for(int i=MAXN-2;i>=0;i--) inv[i] = inv[i+1] * (i+1) % MOD;
}

int root(int a) { return u[a] == a ? a : u[a] = root(u[a]); }

int main(){
	ios_base::sync_with_stdio(false); cin.tie(0);
	pre();
	ll n,x,y;
	cin >> n >> x >> y;
	for(int i=1;i<=n;i++) u[i] = i;
	int id = 0;
	w[0] = 2e9;
	for(int i=1;i<=n;i++){
		cin >> arr[i] >> w[i];
		if(w[i] < w[id]) id = i;
		if(w[i] < w[mn[arr[i]]]) mn[arr[i]] = i;
	}
	int id2 = 0;
	for(int i=1;i<=n;i++){
		if(arr[id] != arr[i] && w[id] + w[i] <= y) u[root(i)] = root(id); 
		if(w[mn[arr[i]]] + w[i] <= x) u[root(i)] = root(mn[arr[i]]);
		if(arr[id] != arr[i] && w[i] < w[id2]) id2 = i;
	}
	for(int i=1;i<=n;i++) if(arr[i] == arr[id] && w[id2] + w[i] <= y) u[root(i)] = root(id2);
	for(int i=1;i<=n;i++){
		mp[root(i)][arr[i]]++;
	}
	ll ans = 1;
	for(int i=1;i<=n;i++){
		ll cur = 0;
		for(auto j:mp[i]){
			ans = ans * inv[j.second] % MOD;
			cur += j.second;
		}
		ans = ans * fact[cur] % MOD;
	}
	cout << ans << '\n';
	return 0;
}

