const int MAXN = 2e5 + 5;
const int MOD = 1e9 + 7;

int N, X, Y;
vector<int> A[MAXN];

void input()
{
    read(N); read(X); read(Y);
    for (int i = 1; i <= N; ++i) {
        int c, w;
        read(c); read(w);
        A[c].push_back(w);
    }
}

int fpm(LL base, LL exp)
{
    LL ret = 1;
    for (; exp; exp >>= 1) {
        if (exp & 1)
            (ret *= base) %= MOD;
        (base *= base) %= MOD;
    }
    return ret;
}

void solve()
{
    static int bnd[MAXN];
    int minfr = 0, secfr = 0;

    A[0].push_back(+oo);
    for (int i = 1; i <= N; ++i) {
        if (SZ(A[i])) {
            std::sort(ALL(A[i]));
            if (A[i][0] + A[i][1] <= X)
                bnd[i] = int(std::upper_bound(ALL(A[i]), X - A[i][0]) - A[i].begin() - 1);
            if (A[secfr][0] > A[i][0]) {
                secfr = i;
                if (A[minfr][0] > A[secfr][0])
                    std::swap(minfr, secfr);
            }
        }
    }

    static bool flag[MAXN];

    for (int i = 1; i <= N; ++i) {
        if (SZ(A[i])) {
            int t = (minfr == i ? secfr : minfr);
            if (A[i][0] + A[t][0] <= Y) {
                flag[i] = true;
                chkmax(bnd[i], int(std::upper_bound(ALL(A[i]), Y - A[t][0]) - A[i].begin() - 1));
            }
        }
    }

    static LL fac[MAXN], ifac[MAXN];

    fac[0] = 1;
    for (int i = 1; i <= N; ++i) fac[i] = fac[i-1] * i % MOD;
    ifac[N] = fpm(fac[N], MOD - 2);
    for (int i = N; i >= 1; --i) ifac[i-1] = ifac[i] * i % MOD;

    LL ans = 1;
    LL allcnt = 0, allcoef = 1;
    for (int i = 1; i <= N; ++i) {
        if (SZ(A[i])) {
            if (flag[i]) {
                allcnt += bnd[i] + 1;
                (allcoef *= ifac[bnd[i] + 1]) %= MOD;
            }
        }
    }
    (ans *= fac[allcnt]) %= MOD;
    (ans *= allcoef) %= MOD;

    printf("%lld\n", ans);
}

int main()
{
#ifdef __DEBUG
    freopen("D.in", "r", stdin);
    freopen("D.out", "w", stdout);
#endif

    input();
    solve();

    return 0;
}

