const int N = 2e5 + 10;
const int M = 1e9 + 7;

int pw(int a, int n = M - 2) {
    int ret = 1;
    while (n) {
        if (n & 1)
            ret = (ll) ret * a % M;
        a = (ll) a * a % M;
        n >>= 1;
    }
    return ret;
}

int parent[N];
int sz[N];
map<int, int> cnt[N];

vector<pii> a;

void make_set(int v) {
    parent[v] = v;
    sz[v] = 1;
    cnt[v][a[v].second]++;
}

int find_set(int v) {
    return v == parent[v] ? v : parent[v] = find_set(parent[v]);
}

void union_sets(int u, int v) {
    u = find_set(u);
    v = find_set(v);
    if (u == v)
        return;
    if ( sz[u] < sz[v])
        swap(u, v);
    sz[u] += sz[v];
    parent[v] = u;
    for (auto item : cnt[v]) {
        cnt[u][item.first] += item.second;
    }
}

void smain() {

    int n, x, y;
    cin >> n >> x >> y;
    a.resize(n);
    map<int, int> col;
    fori (i, n) {
        int c, w;
        cin >> c >> w;
        a[i] = {w, c};

    }
    sort(ALL(a));
    fori (i, n) {
        make_set(i);
    }
    vi first;
    fori (i, n) {
        if (a[i].second == a[0].second) {
            first.push_back(i);
        }
    }
    int cn = -1;
    fori (i, n) {
        if (col.count(a[i].second)) {
            int j = col[a[i].second];
            if (a[i].first + a[j].first <= x)
                union_sets(i, j);
        } else {
            col[a[i].second] = i;
        }
        if (a[i].second == a[0].second)
            continue;
        int l = -1, r = SZ(first);
        while (r - l > 1) {
            int m = r + l >> 1;
            int j = first[m];
            if (a[j].first + a[i].first <= y) {
                l = m;
            } else {
                r = m;
            }
        }
        inmax(cn, l);
        if (l != -1)
            union_sets(first[l], i);
    }

    for (int i = 1; i <= cn; ++i) {
        union_sets(first[i], first[i - 1]);
    }

    vl f(N, 1);
    int M = 1e9 + 7;
    for (int i = 1; i < N; ++i) {
        f[i] = f[i - 1] * i % M;
    }

    int ans = 1;
    fori (i, n) {
        if (parent[i] == i) {
            ans = (ll)ans * f[sz[i]] % M;
            for (auto item : cnt[i]) {
                ans = (ll) ans * pw(f[item.second]) % M;
            }
        }
    }
    cout << ans;
}

