int find(int x){
	if (par[x] != x){
		return par[x] = find(par[x]);
	}
	return par[x];
}

void merge(int x,int y){
//	printf("[%d %d]\n",x,y);
	x = find(x) , y = find(y);
	if (x ^ y){
		par[x] = y;
	}
