    for(int i = 1; i <= N; i++) {
        cin >> c[i] >> w[i];
        balls[c[i]].push_back({w[i], i});
        min_index = c[i];
    }
    for(int i = 1; i <= N; i++) {
        //cout << i << endl;
        sort(balls[i].begin(), balls[i].end());
        if(balls[i].empty()) continue;
        if(balls[i][0].first < balls[min_index][0].first) min_index = i;
        for(int j = 1; j < balls[i].size(); j++) {
            if(balls[i][0].first + balls[i][j].first > X) break;
            uni.merge(balls[i][0].second, balls[i][j].second);
        }
    }
    for(int i = 1; i <= N; i++) {
        //cout << i << endl;
        if(i == min_index) continue;
        for(int j = 0; j < balls[i].size(); j++) {
            int now_val = balls[i][j].first;
            int now_index = balls[i][j].second;
            int ok = -1;
            int ng = balls[min_index].size();
            while(ng - ok > 1) {
                int mid = (ok + ng) / 2;
                if(now_val + balls[min_index][mid].first <= Y) ok = mid;
                else ng = mid;
            }
            if(ok == -1) break;
            uni.merge(balls[min_index][ok].second, now_index);
            while(ok >= 1) {
                if(!uni.merge(balls[min_index][ok].second, balls[min_index][ok - 1].second)) break;
                ok--;
            }
        }
    }
    for(int i = 1; i <= N; i++) {
        //cout << uni.root(i) << endl;
    }
    int occupied = 0;
    int inv[200005];
    for(int i = 1; i <= N; i++) {
        inv[i] = -1;
    }
    for(int i = 1; i <= N; i++) {
        int ROOT = uni.root(i);
        if(inv[ROOT] == -1) {
            inv[ROOT] = occupied;
            occupied++;
        }
        int index = inv[ROOT];
        mp[index][c[i]]++;
        use[index].push_back(c[i]);
    }
    //cout << occupied << endl;
    ll ans = 1;
    for(int check = 0; check < occupied; check++) {
        sort(use[check].begin(), use[check].end());
        use[check].erase(unique(use[check].begin(), use[check].end()), use[check].end());
        ll sum = 0;
        for(int i = 0; i < use[check].size(); i++) {
            int now = mp[check][use[check][i]];
            ans = (ans * FactorialInv[now]) % mod;
            sum += now;
        }
        ans = (ans * Factorial[sum]) % mod;
    }
    cout << ans << endl;
    return 0;
}

