const int MAXN = 200000 + 1000;
const int MOD = 1000000000 + 7;

int fpow(int x, int p)
{
	int ret = 1;
	for(; p; p >>= 1, x = (long long)x * x % MOD)
		if(p & 1)
			ret = (long long)ret * x % MOD;
	return ret;
}
int inv(int x)
{
	return fpow(x, MOD - 2);
}

int n, X, Y;
int c[MAXN], w[MAXN], mn[MAXN];
vector<int> edg[MAXN];
bool vis[MAXN];

void add_edge(int x, int y)
{
	edg[x].push_back(y);
	edg[y].push_back(x);
}

vector<int> vec;
int cnt[MAXN];
void dfs(int x)
{
	vis[x] = true, vec.push_back(x);
	for(int i = 0; i < edg[x].size(); i++)
		if(!vis[edg[x][i]])
			dfs(edg[x][i]);
}

void solve()
{
	for(int i = 1; i <= n; i++)
		mn[c[i]] = i;
	for(int i = 1; i <= n; i++)
		if(!mn[c[i]] || w[i] < w[mn[c[i]]])
			mn[c[i]] = i;
	for(int i = 1; i <= n; i++)
		if(i != mn[c[i]] && w[i] + w[mn[c[i]]] <= X)
			add_edge(i, mn[c[i]]);
	int mn1 = 0, mn2 = 0;
	for(int i = 1; i <= n; i++)
		if(mn[i])
		{
			if(!mn1 || w[mn[i]] < w[mn1])
				mn2 = mn1, mn1 = w[mn[i]];
			else if(!mn2 || w[mn[i]] < w[mn2])
				mn2 = w[mn[i]];
		}
	if(mn1 && mn2)
	{
		for(int i = 1; i <= n; i++)
			if(c[i] != c[mn1] && w[i] + w[mn1] <= Y)
				add_edge(i, mn1);
		for(int i = 1; i <= n; i++)
			if(c[i] != c[mn2] && w[i] + w[mn2] <= Y)
				add_edge(i, mn2);
	}
	int ans = 1, tmp = 1;
	for(int i = 1; i <= n; i++)
		if(!vis[i])
		{
			vec.clear();
			dfs(i);
			// cerr << vec.size() << endl;
			for(int j = 1; j <= vec.size(); j++)
				ans = (long long)ans * j % MOD;
			for(int j = 0; j < vec.size(); j++)
				cnt[c[vec[j]]]++, tmp = (long long)tmp * cnt[c[vec[j]]] % MOD;
			for(int j = 0; j < vec.size(); j++)
				cnt[c[vec[j]]]--;
		}
	ans = (long long)ans * inv(tmp) % MOD;
	cout << ans << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	// freopen("1.in", "r", stdin);
	// freopen("1.out", "w", stdout);

	cin >> n >> X >> Y;
	for(int i = 1; i <= n; i++)
		cin >> c[i] >> w[i];

	solve();



	return 0;
}

