int ksm(int x,int k)
{
    int res=1;
    while(k)
    {
        if(k&1)res=res*x%mo;
        x=x*x%mo;
        k>>=1;
    }
    return res;
}
int mn[maxn],c[maxn],w[maxn],cnt[maxn],jc[maxn],inv[maxn],n,A,B,ans;
signed main()
{
