    memset(mn,0x3f,sizeof(mn));
    jc[0]=1;
    for(int i=1;i<=n;i++)jc[i]=jc[i-1]*i%mo;
    inv[n]=ksm(jc[n],mo-2);
    for(int i=n-1;i>=0;i--)inv[i]=inv[i+1]*(i+1)%mo;
	for (int i=1;i<=n;++i)
    {
		cin>>c[i]>>w[i];
		mn[c[i]]=min(mn[c[i]],w[i]);
		++cnt[c[i]];
	}
