	for (int i=1;i<=n;++i)
		if (mn[i]<mn[Mn])Mn=i;
	for (int i=1;i<=n;++i)
		if (i!=Mn)mnn=min(mn[i],mnn); 
	for (int i=1;i<=n;++i)
    {
		if (w[i]!=mn[c[i]]&&w[i]+mn[c[i]]<=A)continue; 
