#define mod 1000000007

vector<long long int> factmod(200001, 1);
vector<long long int> invfactmod(200001, -1);

void getfactmod()
{
	for(int i = 1; i < 200001; i++){
		factmod[i] = (i * factmod[i - 1]) % mod;
	}
}

long long int getinvfactmod(int n)
{
	if(invfactmod[n] > 0) return invfactmod[n];
	invfactmod[n] = 1;
	long long int tmp[31];
	tmp[0] = factmod[n];
	for(int j = 1; j < 31; j++){
		tmp[j] = (tmp[j - 1] * tmp[j - 1]) % mod;
	}
	long long int m = mod - 2;
	for(int j = 30; j >= 0; j--){
		long long int p = pow(2, j);
		if(m >= p){
			m -= p;
			invfactmod[n] = (invfactmod[n] * tmp[j]) % mod;
		}
	}
	return invfactmod[n];
}

long long int comb(int n, int r)
{
	return (factmod[n] * ((getinvfactmod(r) * getinvfactmod(n - r)) % mod)) % mod;
}

