	REP(i,1,t)has[B[i].se.fi]+=B[i].se.se;
	int tot=0;
	REP(i,1,n)tot+=has[i];
	ans=1LL*ans*fac[tot];
	REP(i,1,n)ans=1LL*ans*fexp(fac[has[i]],mod-2)%mod;
	iout(ans);
}

void Init(){
	read(n,X,Y);
	REP(i,1,n)read(c[i],w[i]),A[i]=MP(c[i],w[i]);
	sort(A+1,A+n+1);
	for(int i=1,j;i<=n;i=j+1){
		for(j=i;A[j+1].fi==A[j].fi;j++);
		int k=i;
		for(;k<j&&A[k+1].se+A[i].se<=X;k++);
		B[++cnt]=MP(A[i].se,MP(A[i].fi,k-i+1));
		REP(t,k+1,j)B[++cnt]=MP(A[t].se,MP(A[t].fi,1));
	}
	sort(B+1,B+cnt+1);
//	REP(i,1,cnt)cout<<B[i].se.fi<<' '<<B[i].fi<<' '<<B[i].se.se<<endl;
}

int main(){
	Init();
	Work();
	return 0;
}

