    vector<int> uf(n);
    for (int i = 0; i < n; ++i) uf[i] = i;

    function<int(int)> Find = [&](int x) {
        if (x == uf[x]) return x;
        return uf[x] = Find(uf[x]);
    };

    auto Merge = [&](int x, int y) {
        uf[Find(x)] = Find(y);
    };

    vector<int> pv;
    for (int i = 0; i < n; ++i) {
        if (ball[i].empty()) continue;
        sort(ball[i].begin(), ball[i].end(), [&](int x, int y) { return w[x] < w[y]; });
        for (int j = 1; j < ball[i].size(); ++j) {
            if (w[ball[i][j]] + w[ball[i][0]] > x) break;
            Merge(ball[i][j], ball[i][0]);
        }
        pv.push_back(ball[i][0]);
    }

    sort(pv.begin(), pv.end(), [&](int i, int j) { return w[i] < w[j]; });
    for (int i = 1; i < pv.size(); ++i) {
        if (w[pv[i]] + w[pv[0]] > y) break;
        Merge(pv[i], pv[0]);
    }

    int gd = -1;
    for (int i = 0; i < n; ++i) {
        int j = -1;
        for (int d = 20; d >= 0; --d) {
            if (j + (1 << d) >= pv.size()) continue;
            if (w[pv[j + (1 << d)]] + w[i] <= y) j += (1 << d);
        }
        while (j >= 0 && c[pv[j]] == c[i]) j--;
        if (j != -1) {
            Merge(i, pv[j]);
            gd = max(gd, j);
        }
    }
    for (int i = 1; i < gd; ++i) Merge(pv[i], pv[0]);

