            // if (w[ball[j][0]] + w[i] <= y) Merge(ball[j][0], i);
        // }
    // }

    vector<map<int, int>> cnt(n);
    for (int i = 0; i < n; ++i) cnt[Find(i)][c[i]]++;

    constexpr int kMod = 1'000'000'000 + 7;

    auto fpow = [&](int a, int n) {
        int res = 1;
        while (n > 0) {
            if (n & 1) res = 1LL * res * a % kMod;
            a = 1LL * a * a % kMod;
            n >>= 1;
        }
        return res;
    };

    vector<int> fc(n + 1, 1), iv(n + 1, 1);
    for (int i = 1; i <= n; ++i) fc[i] = 1LL * fc[i - 1] * i % kMod;
    iv[n] = fpow(fc[n], kMod - 2);
    for (int i = n - 1; i > 0; --i) iv[i] = 1LL * iv[i + 1] * (i + 1) % kMod;

    int ans = 1;
    for (int i = 0; i < n; ++i) {
        if (Find(i) != i) continue;
        int s = 0, p = 1;
        for (auto it : cnt[i]) {
            s += it.second;
            p = 1LL * p * iv[it.second] % kMod;
        }
        p = 1LL * p * fc[s] % kMod;
        ans = 1LL * ans * p % kMod;
    }
    printf("%d\n", ans);
    return 0;
}

