const int MOD = 1000000007;
int fac[MAXN],invfac[MAXN],N,X,Y;
int vp[MAXN],fa[MAXN],id[MAXN];
pii c[MAXN];
int inc(int a,int b) {
    return a + b >= MOD ? a + b - MOD : a + b;
}
int mul(int a,int b) {
    return 1LL * a * b % MOD;
}
void update(int &x,int y) {
    x = inc(x,y);
}
int fpow(int x,int c) {
    int res = 1,t = x;
    while(c) {
        if(c & 1) res = mul(res,t);
        t = mul(t,t);
        c >>= 1;
    }
    return res;
}
int getfa(int x) {
    return fa[x] == x ? x : fa[x] = getfa(fa[x]);
}
void Solve() {
    read(N);read(X);read(Y);
    for(int i = 1 ; i <= N ; ++i) {
        read(c[i].se);read(c[i].fi);
    }
    sort(c + 1,c + N + 1);
    int sec = 2;
    while(sec <= N && c[sec].se == c[1].se) ++sec;
    if(sec > N) {puts("1");return;}
    for(int i = N ; i >= 1 ; --i) {
        vp[c[i].se] = i;
        fa[i] = i;
    }
    for(int i = N ; i >= 1 ; --i) {
        if(i != vp[c[i].se] && c[i].fi + c[vp[c[i].se]].fi <= X) {
            fa[getfa(i)] = getfa(vp[c[i].se]);
        }
        else if(c[i].se != c[1].se && c[i].fi + c[1].fi <= Y) {
            fa[getfa(i)] = getfa(1);
        }
//        else if(c[i].se != c[sec].se && c[i].fi + c[sec].fi <= Y) {
//            fa[getfa(i)] = getfa(sec);
//        }
    }
    fac[0] = 1;
    for(int i = 1 ; i <= N ; ++i) fac[i] = mul(fac[i - 1],i);
    invfac[N] = fpow(fac[N],MOD - 2);
    for(int i = N - 1 ; i >= 0 ; --i) invfac[i] = mul(invfac[i + 1],i + 1);
    int siz = 0;
    for(int i = 1 ; i <= N ; ++i) {
        if(getfa(i) == getfa(1)) {
            id[c[i].se]++;
            ++siz;
        }
    }
    int ans = fac[siz];
    for(int i = 1 ; i <= N; ++i) {
        ans = mul(ans,invfac[id[i]]);
    }
    out(ans);enter;
}
