    for(int i=0;i<n;i++){uft[i]={i,1};}
    for(int i=0;i<n;i++){
        ll c,w;
        cin>>c>>w;
        c--;
        a[i]={c,w};
        A[c].push_back({w,i});
    }
    for(int i=0;i<n;i++){sort(A[i].begin(),A[i].end());}
    sort(A.begin(),A.end());
    for(auto &I:A){
        for(auto &T:I){
            if(T.F+I[0].F<=x){merge(T.S,I[0].S);}
        }
    }
    ll w=0;
    while(A[w].size()==0){w++;}
    for(ll i=w+1;i<n;i++){
        for(auto &T:A[i]){
            if(T.F+A[w][0].F<=y){merge(A[w][0].S,T.S);}
        }
    }
    for(ll i=w+1;i<n;i+=MOD){
        for(auto &T:A[w]){
            if(A[i][0].F+T.F<=y){merge(A[i][0].S,T.S);}
        }
    }
    vector<map<ll,ll>> M(n);
    for(int i=0;i<n;i++){M[parent(i)][a[i].F]++;}
    ll ans=1;
    for(int i=0;i<n;i++){
        if(parent(i)!=i){continue;}
        ll cnt=uft[parent(i)].S;
        for(auto it=M[i].begin();it!=M[i].end();it++){
            ans*=C.c(cnt,it->second);
            cnt-=it->second;
            ans%=MOD;
        }
    }
    cout<<ans<<endl;


