#define MOD 1000000007
typedef long long ll;
inline ll quick_pow(ll a, int n)
{
	ll res = 1;
	while (n)
	{
		if (n & 1)
			res = res * a % MOD;
		a = a * a % MOD;
		n >>= 1;
	}
	return res;
}
std::vector<int> vec[200005], bel[200005];
int idx[200005], col[200005], w[200005], fa[200005], app[200005];
int getfa(int u)
{
	if (u == fa[u])
		return u;
	return fa[u] = getfa(fa[u]);
}
inline void unite(int u, int v)
{
	u = getfa(u);
	v = getfa(v);
	fa[u] = v;
}
int main()
{
	// freopen("AGC012-D.in", "r", stdin);
	int n, a, b, cnt = 0;
	scanf("%d%d%d", &n, &a, &b);
	for (int i = 0; i < n; i++)
	{
		scanf("%d%d", col + i, w + i);
		vec[--col[i]].push_back(i);
		fa[i] = i;
	}
	for (int i = 0; i < n; i++)
	{
		if (vec[i].size())
			idx[cnt++] = i;
		std::sort(vec[i].begin(), vec[i].end(), [&] (const int &x, const int &y)
		{
			return w[x] < w[y];
		});
		for (int j = 1; j < vec[i].size() && w[vec[i][0]] + w[vec[i][j]] <= a; j++)
			unite(vec[i][0], vec[i][j]);
	}
	std::sort(idx, idx + cnt, [&] (const int &x, const int &y)
	{
		return w[vec[x][0]] < w[vec[y][0]];
	});
	for (int i = 0; i < n; i++)
	{
		if (cnt)
		{
			int x = vec[idx[0]][0];
			if (col[i] != x && w[i] + w[x] <= b)
				unite(i, x);
		}
		if (cnt >= 2)
		{
			int x = vec[idx[1]][0];
			if (col[i] != x && w[i] + w[x] <= b)
				unite(i, x);
		}
	}
	for (int i = 0; i < n; i++)
		bel[getfa(i)].push_back(i);
	ll ans = 1;
	for (int i = 0; i < n; i++)
	{
		for (int x : bel[i])
			ans = ans * quick_pow(++app[col[x]], MOD - 2) % MOD;
		for (int x : bel[i])
			app[col[x]] = 0;
		int x = bel[i].size();
		while (x)
			ans = ans * x-- % MOD;
	}
	printf("%lld\n", ans);
	return 0;
}

