    int w1, i1, w2, i2;
    tie(w1, i1) = pq.top();
    while (c[pq.top().second] == c[i1]) pq.pop();
    tie(w2, i2) = pq.top();
    if (w1 + w2 > Y) cout << 1 << endl, exit(0);

    uf.unite(N, i1);
    uf.unite(N, i2);

    REP(i, N)
    {
        if (w[ec_min_pos[c[i]]] + w[i] <= X) uf.unite(i, ec_min_pos[c[i]]);
        if (c[i] != c[i1] and w[i] + w1 <= Y) uf.unite(N, i);
        if (c[i] != c[i2] and w[i] + w2 <= Y) uf.unite(N, i);
    }

    map<int, int> movable_ec;
    int num = 0;
    REP(i, N) if (uf.same(N, i))
    {
        movable_ec[c[i]]++;
        num++;
    }

    mint ans = mint(num).fac();
    for (auto pa : movable_ec) ans /= mint(pa.second).fac();
    cout << ans << endl;
}

