template<typename T>inline bool check_min(T a,T &b){return a<b?b=a,1:0;}
template<typename T>inline bool check_max(T a,T &b){return a>b?b=a,1:0;}

namespace pu
{
	typedef long long ll;
	const int N=201000,MOD=1000000007;
	ll inv(ll x){return x==1?1:(-(MOD/x)*inv(MOD%x)%MOD);}
	ll fact[N],ifact[N];
	ll C(int n,int m){return fact[n]*ifact[m]%MOD*ifact[n-m]%MOD;}

	std::vector<int> V[N];
	int pos[N];
	int n,X,Y;
	void initialize()
	{
		scanf("%d%d%d",&n,&X,&Y);
		for(int i=1,c,x;i<=n;i++)
		{
			scanf("%d%d",&c,&x);
			V[c].push_back(x);
		}
		for(int i=1;i<=n;i++)
			std::sort(V[i].begin(),V[i].end());

		fact[0]=1;
		for(int i=1;i<N;i++)fact[i]=fact[i-1]*i%MOD;
		ifact[N-1]=inv(fact[N-1]);
		for(int i=N-1;i;i--)ifact[i-1]=ifact[i]*i%MOD;
	}
	void getpos()
	{
		int minw=2147483647,w,id=0;
		for(int i=1;i<=n;i++)
		{
			if(V[i].empty())continue;

			w=V[i][0];
			if(w==minw)id=0;
			if(check_min(w,minw))id=i;

			pos[i]=std::upper_bound(V[i].begin(),V[i].end(),X-w)-V[i].begin();
		}

		int dmin=2147483647;

		for(int i=1;i<=n;i++)
		{
			if(V[i].empty())continue;
			if(i==id)continue;

			check_min(V[i][0],dmin);

			w=std::upper_bound(V[i].begin(),V[i].end(),Y-minw)-V[i].begin();

			if(!w)pos[i]=0;
			else check_max(w,pos[i]);
		}

		if(!id)return;

		w=std::upper_bound(V[id].begin(),V[id].end(),Y-dmin)-V[id].begin();
		if(!w)pos[id]=0;
		else check_max(w,pos[id]);
	}
	ll calc()
	{
		int cnt=0;
		ll ret=1;
		for(int i=1;i<=n;i++)cnt+=pos[i];

		for(int i=1;i<=n;i++)
			ret=ret*C(cnt,pos[i])%MOD,cnt-=pos[i];

		return (ret%MOD+MOD)%MOD;
	}
	void solve()
	{
		initialize();
		getpos();
		printf("%lld\n",calc());
	}
}
int main()
{
	pu::solve();
	return 0;
}

