ll fact[MAXN];
ll inv[MAXN];

ll Pow(ll x, ll n) {
  ll result = 1;
  while (n) {
    if (n % 2) result = result * x % MODULO;
    n /= 2;
    x = x * x % MODULO;
  }
  return result;
}

ll Inv(ll x) {
  return Pow(x, MODULO - 2);
}

ll C(ll n, ll k) {
  ll result = fact[n];
  result = result * inv[k] % MODULO;
  result = result * inv[n - k] % MODULO;
  return result;
}

