const int MOD=1e9+7;
LL fact[200000+20],rfact[200000+20];
LL quick(LL A,LL B){
	if(B==0) return 1;
	LL  tmp=quick(A,B>>1);
	tmp*=tmp;
	tmp%=MOD;
	if(B&1)
		tmp*=A,tmp%=MOD;
 	return tmp;
}
LL c(int A,int B){
	return fact[A]*rfact[B]%MOD*rfact[A-B]%MOD;
}
vector<int> have[200000+20];
int fa[200000+20];
int root(int u){
	return fa[u]=(fa[u]==u? u:root(fa[u]));
}
void merge(int u,int v){
	if(root(u)!=root(v)){
		u=root(u);
		v=root(v);
		if(have[u]>have[v]){
			fa[v]=u;
			for(auto it:have[v])
				have[u].PB(it);
			have[v].clear();
		}
		else{
			fa[u]=v;
			for(auto it:have[u])
				have[v].PB(it);
			have[u].clear();
		}
	}
}
