	REP(i,n) { int c=col[i]; if(!used[c]) used[c]=true,mn[c]=w[i]; else if(w[i]<mn[c]) mn[c]=w[i]; }
	mnc1=mnc2=-1; REP(c,n) if(used[c]) { if(mnc1==-1||mn[c]<mn[mnc1]) mnc2=mnc1,mnc1=c; else if(mnc2==-1||mn[c]<mn[mnc2]) mnc2=c; }
	REP(i,n) { posfixed[i]=true; int c=col[i]; if(w[i]+mn[c]<=samelim) posfixed[i]=false; if(mnc1!=-1&&c!=mnc1&&w[i]+mn[mnc1]<=difflim) posfixed[i]=false; if(mnc2!=-1&&c!=mnc2&&w[i]+mn[mnc2]<=difflim) posfixed[i]=false; }
	REP(c,n) if(used[c]) { colfixed[c]=true; if(mnc1!=-1&&c!=mnc1&&mn[c]+mn[mnc1]<=difflim) colfixed[c]=false; if(mnc2!=-1&&c!=mnc2&&mn[c]+mn[mnc2]<=difflim) colfixed[c]=false; }
	REP(c,n) cnt[c]=0; REP(i,n) if(!posfixed[i]) ++cnt[col[i]];
	int ret=1,sum=0;
	REP(c,n) if(!colfixed[c]) { sum+=cnt[c]; ret=(ll)ret*fac[sum]%MOD*ifac[cnt[c]]%MOD*ifac[sum-cnt[c]]%MOD; }
	printf("%d\n",ret);
}

int main() {
	run();
	return 0;
}

