int inv_fact[ MAXN + 1 ];

int int_pow( int v, int p, int m ){
  int res = not ( v == 0 and p != 0 );
  while( p ){
    if( p & 1 ){
      res = 1LL * res * v % m;
    }
    p >>= 1;
    v = 1LL * v * v % m;
  }
  return res;
}
void ext_gcd( int a, int &x, int b, int &y ){
  if( b == 0 ){
    x = 1;
    y = 0;
    return;
  }
  int xx, yy;
  ext_gcd( b, xx, a % b, yy );
  x = yy;
  y = xx - a / b * yy;
}

int mod_inv( int a, int m ){
  int x, y;
  ext_gcd( a, x, m, y );
  return x;
}
int unite[ MAXN ];

signed main(){
