int find(int node){
	if(parent[node] == node){
		return node;
	}
	return parent[node] = find(parent[node]);
}
void join(int x , int y){
	int a = find(x);
	int b = find(y);
	if(a != b){
		if(sizes[a] < sizes[b]){
			swap(a , b);
		}
		sizes[a] += sizes[b];
		parent[b] = a;
	}
}
