	for(int i=1;i<=N;i++){
		for(int j=1;j<sz(E[i]);j++){
			if(E[i][j].Fi + E[i][0].Fi <= X){
				Uni(E[i][j].Se, E[i][0].Se);
			}
		}
	}
	sort(P+1, P+1+N);
	int idx[2] = {};
	for(int u=0;u<2;u++){
