		for(int i=1;i<=N;i++){
			int ok = 1;
			rep(v, u)if(idx[v] == -1 || get<1>(P[idx[v]]) == get<1>(P[i]))ok = 0;
			if(ok){
				idx[u] = i;
				break;
			}
		}
	}
	for(int i=1;i<=N;i++){
		int t = (int)(upper_bound(P+1, P+1+N, t3(Y - get<0>(P[i]), 1e9, 1e9)) - P - 1);
		rep(u, 2){
			int v = idx[u];
			if(v > t || idx[u] == -1)break;
			if(get<1>(P[v]) != get<1>(P[i])){
				Uni(get<2>(P[v]), get<2>(P[i]));
			}
		}
	}
