		ch[Find(i)].pb(i);
	}
	//for(int i=1;i<=N;i++)printf("%d ", Find(i)); puts("");
	int ans = 1;
	F[0] = IF[0] = 1;
	for(int i=1;i<=N;i++)F[i] = i * F[i-1] % MOD;
	for(int i=1;i<=N;i++)IF[i] = IF[i-1] * pw(i, MOD-2) % MOD;
	for(int i=1;i<=N;i++)if(sz(ch[i])){
