int64 fact[MAXN], fact_inv[MAXN];
inline int64 fpow(int64 base, int exp)
{
    int64 ans = 1;
    for (; exp; exp >>= 1) {
        if (exp & 1) (ans *= base)__; (base *= base)__;
    }
    return ans;
}
inline void preprocess_binomials()
{
    fact[0] = fact_inv[0] = 1;
    for (int i = 1; i < MAXN; ++i) {
        fact[i] = fact[i - 1] * i _;
        fact_inv[i] = fpow(fact[i], MODULUS - 2);
    }
}
inline int64 binomial(int n, int m)
{
    if (n < m || m < 0) return 0;
    return fact[n] * fact_inv[n - m]_ * fact_inv[m]_;
}

