void add(int &a, int b){
	a += b;
	if(a >= MOD) a -= MOD;
}

int mul(int a, int b){
	return a * 1LL * b % MOD;
}

int bp(int x, int d){
	if(!d) return 1;
	if(d&1) return mul(x, bp(x, d-1));
	int r = bp(x, d/2);
	return mul(r, r);
}

int f[N], invF[N];
int n, x, y;
vector<int> a[N];
vector<int> b;
int cur[N];

bool comp(int i, int j){
	if(sz(a[i]) == 0 && sz(a[j]) == 0) return i < j;
	if(sz(a[i]) == 0) return false;
	if(sz(a[j]) == 0) return true;
	return a[i][0] < a[j][0];
}

int calc(int id, int val, int maxi){
	int l = -1;
	int r = sz(a[id]);
	while(r-l>1){
		int m = (l+r)/2;
		if(a[id][m] + val <= maxi) l = m;
		else r = m;
	}
	return l;
}

void solve(){
	f[0] = invF[0] = 1;
	fi(1, N){
		f[i] = mul(f[i-1], i);
