	fi(0, n) b.pb(i);
	sort(b.begin(), b.end(), comp);

	int ans = 1;
	int mini = INF;
	fi(1, n){
		if(sz(a[b[i]])) mini = min(mini, a[b[i]][0]);
	}
	int sum = 0;
	fi(0, n){
		if(sz(a[b[i]]) == 0) continue;
		cur[i] = calc(b[i], mini, y);
		if(cur[i] == -1) continue;
		cur[i] = max(cur[i], calc(b[i], a[b[i]][0], x));
		sum += cur[i] + 1;
		mini = min(mini, a[b[i]][0]);
	}
	ans = f[sum];
	fi(0, n) ans = mul(ans, invF[cur[i]+1]);
	printf("%d\n",ans);
}

