    for (reg int i = 1; i <= n; i++)
        if (used[i]) Size[c[i]]++;
    for (reg int i = 1; i <= n; i++) sum += Size[i];
    for (reg int i = 1; i <= n; i++)
        if (Size[i]) ans = 1LL * ans * calc(sum, Size[i]) % mod, sum -= Size[i];
    printf("%d\n", ans);
    return 0;
}

