//x! O(x)
ll mod_factorial(ll x, ll mod) {
	if (x < 0) return -1;
	else {
		ll ret = 1;
		Loopr1(i, x) ret = ret * i % mod;
		return ret;
	}
}

//nCr O(nr') r'=min(r, n-r)
ll mod_combination(ll n, ll r, ll mod) {
	if (n < r) return 0;
	if (n < r * 2) r = n - r;
	if (r == 0) return 1;
	if (r == 1) return n;
	vll dp(r + 1, 0), dp2(r + 1, 0);
	dp[0] = dp2[0] = 1;
	Loop1(i, n) {
		Loop1(j, r) {
			dp2[j] = dp[j - 1] + dp[j];
			if (dp2[j] >= mod) dp2[j] -= mod;
		}
		dp = dp2;
	}
	return dp[r];
}

//p!/(Πary!) 
ll mod_multicombination(ll p, vll ary, ll mod) {
	ll ret = 1;
	ll a = p;
	Loop(i, ary.size()) {
		ll b = ary[i];
		ret = ret * mod_combination(a, b, mod) % mod;
		a -= b;
	}
	ret = ret * mod_factorial(a, mod) % mod;

	return ret;
}

class Union_Find {
private:
	vll p, r;
public:
	Union_Find(ll N) {
		p.resize(N);
		r.resize(N);
		Loop(i, N) {
			p[i] = i;
			r[i] = 0;
		}
	}
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (r[x] < r[y]) p[x] = y;
		else {
			p[y] = x;
			if (r[x] == r[y]) r[x]++;
		}
	}
	bool same(ll x, ll y) {
		return find(x) == find(y);
	}
	int find(ll x) {
		if (p[x] == x) return x;
		else return p[x] = find(p[x]);
	}
};


ll n, x, y;
vll c, w;

void solve() {
	map<ll, ll> mp1; //色→最小重量をもつindex
	ll min_index = 0; //全てのボールの最小重量をもつindex
	Loop(i, n) {
		if (mp1.find(c[i]) == mp1.end()) mp1[c[i]] = i;
		else if (w[mp1[c[i]]] > w[i]) mp1[c[i]] = i;
		if (w[min_index] > w[i]) min_index = i;
	}
	//unionfindにより可換indexを連結
	Union_Find *uf = new Union_Find(n);
	//操作1
	Loop(i, n) {
		if (w[i] + w[mp1[c[i]]] <= x) {
			uf->unite(i, mp1[c[i]]);
		}
	}
	//操作2
	Loop(i, n) {
		if (w[i] + w[min_index] <= y) {
			uf->unite(i, min_index);
		}
	}
	//計算の準備
	map<ll, vll> mp2;
	ll ans = 1;
	ll mod = 1e9 + 7;
	Loop(i, n) {
		mp2[uf->find(i)].push_back(i);
	}
	for (auto itr = mp2.begin(); itr != mp2.end(); itr++) {
		map<ll, ll> mp3;
		Loop(i, (*itr).second.size()) {
			int index = (*itr).second[i];
			mp3[c[index]]++;
		}
		vll ary;
		ll sum = 0;
		for (auto itr2 = mp3.begin(); itr2 != mp3.end(); itr2++) {
			ary.push_back((*itr2).second);
			sum += (*itr2).second;
		}
		ans = ans*mod_multicombination(sum, ary, mod) % mod;
	}
	cout << ans << endl;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
	cout.precision(15);
	cin >> n >> x >> y;
	c.resize(n);
	w.resize(n);
	Loop(i, n) cin >> c[i] >> w[i];
	solve();
	return 0;
}

