#include <bits/stdc++.h>
using namespace std;
using ll = long long;
constexpr ll MOD = 1000000007LL;

class ModCombination
{
public:
    ModCombination(const int n, const ll mod = MOD) : fact(n + 1, 1), inv(n + 1, 1), inv_fact(n + 1, 1)  // mod should be prime
    {
        for (ll i = 2; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % mod;
            inv[i] = ((mod - (mod / i)) * inv[mod % i]) % mod;
            inv_fact[i] = (inv_fact[i - 1] * inv[i]) % mod;
        }
    }
    ll factorial(const int n) const { return fact[n]; }
    ll inverseFactorial(const int n) const { return inv_fact[n]; }

private:
    vector<ll> fact;
    vector<ll> inv;
    vector<ll> inv_fact;
};

int main()
{
    int N;
    ll X, Y;
    cin >> N >> X >> Y;
    vector<vector<ll>> weight(N);
    for (int i = 0; i < N; i++) {
        int c;
        ll w;
        cin >> c >> w;
        weight[c - 1].push_back(w);
    }
    ll mini = 1LL << 60;
    int minind = -1;
    for (int i = 0; i < N; i++) {
        if (weight[i].empty()) { continue; }
        sort(weight[i].begin(), weight[i].end());
        if (mini > weight[i].front()) {
            mini = weight[i].front();
            minind = i;
        }
    }
    ll mini2 = 1LL << 60;
    for (int i = 0; i < N; i++) {
        if (weight[i].empty()) { continue; }
        if (minind == i) { continue; }
        mini2 = min(mini2, weight[i].front());
    }
    int sum = 0;
    vector<int> len(N, 0);
    vector<bool> mix(N, false);
    mix[minind] = true;
    for (int i = 0; i < N; i++) {
        if (weight[i].empty()) { continue; }
        sort(weight[i].begin(), weight[i].end());
        const ll inf = weight[i].front();
        len[i] = max(1, (int)(upper_bound(weight[i].begin(), weight[i].end(), X - inf) - weight[i].begin()));
        const int tmp = (i == minind) ? upper_bound(weight[i].begin(), weight[i].end(), Y - mini2) - weight[i].begin()
                                      : upper_bound(weight[i].begin(), weight[i].end(), Y - mini) - weight[i].begin();
        len[i] = max(len[i], tmp);
        if (tmp > 0) { mix[i] = true; }
        if (mix[i]) { sum += len[i]; }
    }
    ModCombination mod(N);
    ll ans = mod.factorial(sum);
    for (int i = 0; i < N; i++) {
        if (mix[i]) { (ans *= mod.inverseFactorial(len[i])) %= MOD; }
    }
    cout << ans << endl;
    return 0;
}

