using namespace std;
const int MAX=200005;
const long long int MOD=1000000007;
int X,Y;
int n,moveable;
vector<int> sub[MAX];
int w[MAX],c[MAX],done[MAX],best[MAX],force[MAX];
long long int cal[MAX];
void preCal()
{
	cal[0]=1;
	for(int i=1;i<=n;++i){
		cal[i]=(cal[i-1]*(long long int)(i))%MOD;
	}
}
long long int inverse(long long int m,long long int p)
{
	if(p==0) return 1;
	long long int temp=inverse(m,p/2);
	if(p%2==0) return (temp*temp)%MOD;
	return (((temp*temp)%MOD)*m)%MOD;
}
int main()
{
	int indexA=0,index=0,minimum=1e9+5,boss;
	cin>>n>>X>>Y;
	for(int i=1;i<=n;++i){
		cin>>c[i]>>w[i];
		sub[c[i]].push_back(i);
		if(minimum>w[i]){
			minimum=w[i];
			indexA=i;
		}
	}
	preCal();
	for(int i=1;i<=n;++i){
		if(sub[i].size()==0){
			continue;	
		} 
		minimum=1e9+5;
		for(int j=0;j<sub[i].size();++j){
			int t=sub[i][j];
			if(minimum>w[t]){
				best[i]=t;
				minimum=w[t];
			}
		}
		if(i==c[indexA]) boss=i;
		index=best[i];
		force[i]=1;
		for(int j=0;j<sub[i].size();++j){
			int t=sub[i][j];
			if(t!=index&&w[t]+w[index]<=X) force[i]++;
		}
	}
//	cout<<boss<<endl;	
	moveable=force[boss];
	done[boss]=1;
	for(int i=1;i<=n;++i){
		if(best[i]!=indexA){
			if(i!=c[indexA]&&w[best[i]]+w[indexA]<=Y){
				moveable+=force[i];
				done[i]=1;
			}
		}
	}
	long long int ans=cal[moveable];
	for(int i=1;i<=n;++i){
		if(done[i]){
			ans=(ans*inverse(cal[force[i]],MOD-2))%MOD;
		}
	}
	cout<<ans<<endl;
	return 0;
}

