int		IN()	{
		int x= 0, f= 0, ch;
		for	(; CH < '0' || ch > '9';)	f= (ch == '-');
		for	(; ch >= '0' && ch <= '9'; CH)	x= x*10 + ch -'0';
		return	f? -x : x;
}

#define n	200005
#define P	1000000007
#define INF	(1 << 30)

int		N, X, Y, L[n], R[n];

Vec		A[n];

int		Pow(int a,int b){
		int ret=1;
		for (;b;b>>=1,a=1ll*a*a%P)
			if  (b&1)	ret=1ll*ret*a%P;
		return	ret;
}

int		main(int argc, char* argv[]){
		N= IN();
		X= IN();
		Y= IN();

		L[0]= 1;
		For(i, 1, N)	L[i]= 1ll*L[i-1]*i%P;
		For(i, 0, N)	R[i]= Pow(L[i], P-2);

		For(i, 1, N)	{
			int c= IN(), w= IN();
			A[c].pb(w);
		}

		For(i, 1, N)	sort(A[i].begin(), A[i].end());

		int	m1= INF, m2= INF, c1= 0, c2= 0;
		For(i, 1, N)	if	(A[i].size()){
			if	(A[i][0] < m1)	m2= m1, c2= c1, m1= A[i][0], c1= i;
			lf	(A[i][0] < m2)	m2= A[i][0], c2= i;
		}

		int	tot= 0, Ans= 1;
		For(i, 1, N)	if	(A[i].size())	{
			int t= 1;
			For(j, 2, A[i].size())	{
				if	(A[i][0] +  A[i][j-1] <= X)	t++;
				lf	(c1 != i && m1 + A[i][0] <= Y && m1 + A[i][j-1] <= Y)	t++;
				lf	(c2 != i && m2 + A[i][0] <= Y && m2 + A[i][j-1] <= Y)	t++;
					else	break;
			}

			if	(c1 != i && m1 + A[i][0] <= Y)	tot+= t, Ans= 1ll*Ans*R[t]%P;
			lf	(c2 != i && m2 + A[i][0] <= Y)	tot+= t, Ans= 1ll*Ans*R[t]%P;
		}

		Ans= 1ll*Ans*L[tot]%P;
		printf("%d\n", Ans);

		return	0;
}

