	static int buk[N];
	int res=fac[list[x].size()];
	for(std::vector <int> ::iterator it=list[x].begin(); it!=list[x].end(); ++it){
		++buk[col[*it]];
	}
	for(std::vector <int> ::iterator it=list[x].begin(); it!=list[x].end(); ++it){
		if(!buk[col[*it]]) continue;
		res=(lint)res*ifac[buk[col[*it]]]%mod;
		buk[col[*it]]=0;
	}
	return res;
}

