	for(int i=1; i<=n; ++i){
		if(npos1&&col[i]!=col[npos1]&&wgt[i]+wgt[npos1]<=lim2){
			U::link(i,npos1);
		}
		if(npos2&&col[i]!=col[npos2]&&wgt[i]+wgt[npos2]<=lim2){
			U::link(i,npos2);
		}
