	for(int i=1; i<=n; ++i){
		list[U::find_rt(i)].push_back(i);
	}
	int ans=1;
	for(int i=1; i<=n; ++i){
		if(U::find_rt(i)==i){
			ans=(lint)ans*solve(i)%mod;
		}
	}
	printf("%d\n",ans);
	return 0;
}

