#include <bits/stdc++.h>
using namespace std;

struct Mod
{
    static const auto P = int(1e9+7);
    long long k;

    Mod() = default;
    Mod(const long long k) : k(k%P) {}
};

Mod operator*(const Mod a, const Mod b) { return a.k * b.k; }
Mod& operator*=(Mod& a, const Mod b) { return a = a*b; }
Mod power(const Mod a, const int k)
{
    if (k == 0) return 1;
    else if (k % 2 == 0) return power(a*a, k/2);
    else return a * power(a*a, k/2);
}
Mod inverse(const Mod a) { return power(a, Mod::P-2); }

struct DisjointSets
{
    int N;
    vector<int> representatives, sizes;

    DisjointSets(const int N) : N(N), representatives(N), sizes(N, 1)
    {
        iota(begin(representatives), end(representatives), 0);
    }

    int find(const int n)
    {
        if (representatives[n] != n)
            representatives[n] = find(representatives[n]);
        return representatives[n];
    }

    void merge(int n, int m)
    {
        n = find(n), m = find(m);
        if (n == m) return;
        representatives[n] = m;
        sizes[m] += sizes[n];
    }

    int size(const int n) { return sizes[find(n)]; }
};

int main()
{
    int N, X, Y; cin >> N >> X >> Y;

    struct Ball { int index, color, weight; };
    auto balls = vector<vector<Ball>>(N);
    for (auto i = 0; i < N; i++)
    {
        int c, w; cin >> c >> w;
        c--;
        balls[c].push_back({i, c, w});
    }

    for (auto& bs : balls) sort(begin(bs), end(bs), [](const Ball a, const Ball b) { return a.weight < b.weight; });
    const auto compare = [](const vector<Ball>& a, const vector<Ball>& b)
    {
        if (a.empty() && b.empty()) return false;
        else if (a.empty()) return false;
        else if (b.empty()) return true;
        else return a[0].weight < b[0].weight;
    };
    sort(begin(balls), end(balls), compare);

    auto components = DisjointSets(N);
    const auto add_edge = [&](const Ball a, const Ball b)
    {
        const auto bound = a.color == b.color ? X : Y;
        if (a.weight + b.weight <= bound)
            components.merge(a.index, b.index);
    };

    for (const auto& bs : balls) for (const auto b : bs)
    {
        add_edge(b, bs[0]);
        add_edge(b, balls[0][0]);
        if (N >= 2 && !balls[1].empty()) add_edge(b, balls[1][0]);
    }

    auto color_counts = vector<map<int, int>>(N);
    for (const auto& bs : balls) for (const auto b : bs)
        color_counts[components.find(b.index)][b.color]++;

    auto factorials = vector<Mod>(N+1);
    factorials[0] = 1;
    for (auto n = 1; n <= N; n++) factorials[n] = n * factorials[n-1];

    auto inverse_factorials = vector<Mod>(N+1);
    inverse_factorials[N] = inverse(factorials[N]);
    for (auto n = N; n >= 1; n--) inverse_factorials[n-1] = n * inverse_factorials[n];

    auto result = Mod(1);
    for (auto i = 0; i < N; i++) if (components.find(i) == i)
    {
        result *= factorials[components.size(i)];
        for (const auto kv : color_counts[i])
            result *= inverse_factorials[kv.second];
    }
    cout << result.k << endl;
}

