        mi[c[i]]=min(mi[c[i]],w[i]);
        cnt[c[i]]++;
    }
    fo(i,1,n) 
        if (mi[i]!=inf){
            if (m==0) m=i;
            else if (mi[i]<mi[m]) m=i;
        }
    t=inf;
    fo(i,1,n)
        if (mi[i]!=inf&&i!=m) t=min(t,mi[i]);
