int binom(int a, int b) {
	if (a < 0 || a > b) return 0;
	if (!a || a == b) return 1;
	return mult(fac[b], mult(ifac[a], ifac[b - a]));
}

void init() {
	FOR(i, 0, n) dj[i] = i, sz[i] = 1;
}
int find(int u) {
	return dj[u] == u ? dj[u] : dj[u] = find(dj[u]);
}
void join(int u, int v) {
	int p = find(u);
	int q = find(v);
	if (p != q) {
		dj[p] = q;
		sz[q] += sz[p];
	}
}

int compare(int i, int j) {
	if (w[i] != w[j]) return w[i] < w[j];
	return i < j;
}

void solve() {
	fac[0] = 1; FOR(i, 1, maxn) fac[i] = mult(fac[i - 1], i);
	FOR(i, 0, maxn) ifac[i] = inv(fac[i]);
	cin >> n >> x >> y;
	FOR(i, 0, n) cin >> c[i] >> w[i];
	vi ver; FOR(i, 0, n) ver.pb(i);
	sort(all(ver), compare);
	int list[100], list2[100];
	fill_n(list, 100, -1), fill_n(list2, 100, -1);
	FOR(i, 0, 100) {
		FOR(j, 0, n) {
			int x = ver[j];
			int ok = 1;
			FOR(k, 0, i) {
				if (c[x] == c[list[k]]) {
					ok = 0;
					break;
				}
			}
			if (ok) {
				list[i] = x;
				FOR(k, j + 1, n) {
					int y = ver[k];
					if (c[x] == c[y]) {
						list2[i] = y;
						break;
					}
				}
				break;
			}
		}
	}
	init();
	FOR(it, 0, 100) {
		int u = list[it];
		if (u == -1) break;
		FOR(i, 0, n) {
			if (c[u] == c[i] && w[u] + w[i] <= x) {
				join(u, i);
			}
			else if (c[u] != c[i] && w[u] + w[i] <= y) {
				join(u, i);
			}
		}
	}
	FOR(it, 0, 3) {
		int u = list2[it];
		if (u == -1) break;
		FOR(i, 0, n) {
			if (c[u] == c[i] && w[u] + w[i] <= x) {
				join(u, i);
			}
			else if (c[u] != c[i] && w[u] + w[i] <= y) {
				join(u, i);
			}
		}
	}
	FOR(i, 0, n) {
		hs[find(i)][c[i]]++;
	}
	int ans = 1;
	FOR(i, 0, n) {
		int cnt = 0;
		FORall(it, hs[i]) {
			cnt += it->se;
			ans = mult(ans, binom(it->se, cnt));
		}
	}
	cout << ans << "\n";
}

