vector<int> v[200001],c[200001];
struct node{int c,v;}a[200001];
struct node2{int ord,v;}A[200001];

bool cmp(node a,node b) {return a.v<b.v;}
bool cmp2(node2 a,node2 b) {return a.v<b.v;}
int ask(int x) {return fa[x]==x?x:fa[x]=ask(fa[x]);}
int nxt(int x,int c) {if (a[x+1].c==c) return g[x]; return x+1;}

void unite(int x,int y)
{
	int p=ask(x),q=ask(y);
	if (p==q) return;
	if (v[p].size()<v[q].size()) t=p,p=q,q=t;
	int sz=v[q].size(); fa[q]=p;
	for (int j=0; j<sz; j++) v[p].push_back(v[q][j]);
	v[q].clear();
}

int quickmi(int a,int b)
{
	int t=1;
	while (b)
	{
		if (b&1) t=1ll*t*a%mod;
		a=1ll*a*a%mod;
		b>>=1;
	}
	return t;
}

int main()
{
	scanf("%d%d%d",&n,&X,&Y);
	jc[0]=1;
	for (int i=1; i<=n; i++) jc[i]=1ll*i*jc[i-1]%mod;
	inv[n]=quickmi(jc[n],mod-2);
	for (int i=n; i; i--) inv[i-1]=1ll*i*inv[i]%mod;
	for (int i=1; i<=n; i++) scanf("%d%d",&a[i].c,&a[i].v),A[i].ord=i,A[i].v=a[i].c;
	sort(A+1,A+1+n,cmp2); A[0].v=-1; int cnt=0;
	for (int i=1; i<=n; i++)
		if (A[i].v!=A[i-1].v) a[A[i].ord].c=(++cnt);
		else a[A[i].ord].c=cnt;
	sort(a+1,a+1+n,cmp);
	g[n]=n+1;
	for (int i=n-1; i; i--) g[i]=nxt(i+1,a[i+1].c);
	for (int i=1; i<=cnt; i++) c[i].clear();
	for (int i=1; i<=n; i++) c[a[i].c].push_back(i);
	for (int i=1; i<=cnt; i++)
	{
		sz=c[i].size(); G[c[i][sz-1]]=n+1;
		for (int j=0; j<sz-1; j++) G[c[i][j]]=c[i][j+1];
	}
	for (int i=1; i<=n; i++) fa[i]=i,v[i].clear(),v[i].push_back(i),f[i]=0;
	for (int i=1; i<=n; i++)
		if (fa[i]==i)
		{
			for (int j=i+1; j<=n&&a[j].v+a[i].v<=Y; j=nxt(j,a[i].c))
				{if (!f[i]) f[i]=j; unite(i,j);}
			if (f[i]) {for (int j=G[i]; j<=n&&a[j].v+a[f[i]].v<=Y; j=G[j]) unite(i,j);}
		}
	for (int i=1; i<=cnt; i++)
	{
		sz=c[i].size();
		for (int j=1; j<sz; j++)
			if (a[c[i][j]].v+a[c[i][0]].v<=X) unite(c[i][j],c[i][0]);
	}
	memset(C,0,sizeof(C));
	ans=1;
	for (int i=1; i<=n; i++)
		if (fa[i]==i) 
		{
			sz=v[i].size();
			for (int j=0; j<sz; j++) C[a[v[i][j]].c]++;
			ans=1ll*ans*jc[sz]%mod;
			for (int j=0; j<sz; j++) ans=1ll*ans*inv[C[a[v[i][j]].c]]%mod,C[a[v[i][j]].c]=0;
		}
	printf("%d\n",ans);
	return 0;
}

