const int MAXN = 200 * 1000 + 10, MOD = 1000 * 1000 * 1000 + 7;
vector <int> v[MAXN];
int mn[MAXN], m1[MAXN], m2[MAXN], fact[MAXN];

int _pow(int a, int p)
{
	if (!p)
		return 1;
	return _pow(a * a % MOD, p / 2) * ((p & 1) ? a : 1) % MOD;
}

int rev(int a)
{
	return _pow(a, MOD - 2);
}

int choose(int k, int n)
{
	return fact[n] * rev(fact[k] * fact[n - k]) % MOD;
}

