    int fst = -1, scnd = -1;
    for (int c = 0; c < n; c++)
    {
        if (a[c].empty()) continue;
        if (fst == -1)
            fst = c;
        else if (a[c][0] < a[fst][0])
        {
            scnd = fst;
            fst = c;
        }
        else if (scnd == -1 || a[c][0] < a[scnd][0])
            scnd = c;
    }
    for (int c = 0; c < N; c++)
