        {
            int p = upper_bound(a[c].begin(), a[c].end(), X - a[c][0]) - a[c].begin();
            if (p == 0) p = 1;
            if (scnd != -1)
                p = max(p, (int)(upper_bound(a[c].begin(), a[c].end(), Y - a[scnd][0]) - a[c].begin()));
            b[c] = p;
