int power(int x, int k) {
    if (k == 0) return 1;
    if (k == 1) return x;

    int mid = power(x, k >> 1);
    mid = mid * mid % MOD;

    if (k & 1) return mid * x % MOD;
    else return mid;
}

int inverse(int x) {
