int Pow(int a, int k)
{
	int ret = 1;
	while (k)
	{
		if (k & 1)
			ret = (ll)ret * a % mod;
		a = (ll)a * a % mod;
		k >>= 1;
	}
	return ret;
}
int C(int n, int m)
{
	if (n < m || m < 0)
		return 0;
	return (ll)fac[n] * inv[m] % mod * inv[n - m] % mod;
}
int main()
{
	scanf("%d%d%d", &n, &x, &y);
	for (int i = 1; i <= n; i++)
		mn[i] = inf;
	fac[0] = 1;
	for (int i = 1; i <= n; i++)
		fac[i] = (ll)fac[i - 1] * i % mod;
	inv[n] = Pow(fac[n], mod - 2);
	for (int i = n; i >= 1; i--)
		inv[i - 1] = (ll)inv[i] * i % mod;
	for (int i = 1; i <= n; i++)
	{
		scanf("%d%d", &c[i], &w[i]);
		mn[c[i]] = min(mn[c[i]], w[i]);
		cnt[c[i]]++;
	}
