				u = i;
	int v = inf;
	for (int i = 1; i <= n; i++)
		if (mn[i] != inf && i != u)
			v = min(v, mn[i]);
	for (int i = 1; i <= n; i++)
	{
		if (w[i] != mn[c[i]] && w[i] + mn[c[i]] <= x)
			continue;
		if (c[i] != u && w[i] + mn[u] <= y)
			continue;
		if (c[i] == u && w[i] + v <= y)
			continue;
		cnt[c[i]]--;
	}
	int num = cnt[u];
	for (int i = 1; i <= n; i++)
		if (mn[i] != inf && i != u)
			if (mn[i] + mn[u] <= y)
				num += cnt[i];
	int ans = 1;
	for (int i = 1; i <= n; i++)
		if (mn[i] != inf && (i == u || mn[i] + mn[u] <= y))
		{
			ans = (ll)ans * C(num, cnt[i]) % mod;
			num -= cnt[i];
		}
	printf("%d\n", ans);
}

