		while (low + 1 != co[i].size() && co[i][low + 1].first + co[i][0].first <= x) low++;

		FOE(j, 0, low) {
			int pos = co[i][j].second;

			val[pos] = low + 1;				
		}
	}

	sort(a + 1, a + n + 1);

	int low = 0;

	while (low != n && a[low + 1].first + a[1].first <= y) {
		low++;

		int pos = a[low].second;
		active[pos] = 1;

	//	printf("POS %d\n", pos);

		if (val[pos] > 0) {
			int len = val[pos] - 1;
			int color = col[pos];	

			if (!ext[color]) {
				FOE(i, 0, len) {
					int pp = co[color][i].second;

					active[pp] = 1;
				}
				ext[color] = 1;
			}
		}
	}

	LL ret = 1;


	FOE(i, 1, n) {
		if (active[i]) cols.pb(col[i]);
//		if (active[i]) printf("POS %d ACTIVE\n", i);
	}

	if (cols.size()) {
		sort(cols.begin(), cols.end());

		int last = -1, cnt = 0;
//		FOR(i, 0, cols.size()) printf("cols[%d] = %d\n", i, cols[i]);

		FOR(i, 0, cols.size()) {
			if (last == -1) {
				cnt = 1; 
				last = cols[0];	
			} else if (cols[i] != last) {
				cnts.pb(cnt);
				cnt = 1;
				last = cols[i];	
			} else {
				cnt++;	
			}
		}

		cnts.pb(cnt);

//		FOR(i, 0, cnts.size()) printf("cnts[%d] = %d\n", i, cnts[i]);

		int slot = 1;

		FOR(i, 0, cnts.size()) {
			ret = ret * C(slot + cnts[i] - 1, cnts[i]) % M;

			slot += cnts[i];
		}
	}

	cout << ret << endl;
}

