#define N (200000+5)
const int P = 1e9 + 7;

inline int Mul(int a, int b){return 1ll * a * b % P;}

int Pow(int a, int anum){
	int ret = 1;
	while(anum){
		if(anum & 1) ret = Mul(ret, a);
		a = Mul(a, a); anum >>= 1;
	}
	return ret;
}

struct node{
	int p, c, w;
	bool operator <(const node &rhs)const{return w < rhs.w;}
}ball[N];

vector<node> col[N];
int tot[N], tot2[N], fac[N], rfac[N];

int main(){	
	int n, x, y;

	scanf("%d%d%d", &n, &x, &y);
	For(i, 1, n){
		scanf("%d%d", &ball[i].c, &ball[i].w);
		ball[i].p = i;

		col[ball[i].c].pb(ball[i]);
	}

	int sw;
	For(i, 1, n) if(col[i].size()>0){
		sort(col[i].begin(), col[i].end());
		tot[i] = 1; sw = col[i][0].w;

		For(j, 1, col[i].size()-1){
			if(sw+col[i][j].w > x) break;
			++tot[i];
		}
	}

	sort(ball+1, ball+n+1);
	sw = ball[1].w; ++tot2[ball[1].c];

	int tw = -1;
	For(i, 2, n) if(ball[i].c != ball[1].c){
		tw = ball[i].w; break;
	}

	For(i, 2, n){
		if(sw + ball[i].w > y) continue;
		if(ball[i].c == ball[1].c){
			if(tw == -1 || tw+ball[i].w > y) continue;
		}

		++tot2[ball[i].c];
	}

	int ans, sum = 0;

	fac[0] = 1;
	For(i, 1, n){
		fac[i] = Mul(fac[i-1], i);

		if(tot2[i]) tot[i] = max(tot[i], tot2[i]), sum += tot[i];
		else tot[i] = 0;
	}
	rfac[n] = Pow(fac[n], P-2);
	Forr(i, n-1, 0) rfac[i] = Mul(rfac[i+1], i+1);

	ans = fac[sum];
	For(i, 1, n) ans = Mul(ans, rfac[tot[i]]);
	printf("%d\n", ans);

	return 0;
}

