#define int long long
const int mod=(1e9+7);
int n;
int fac[200001],inv[200001];
int qpow(int a,int b){
	int ans=1;
	for(;b;b>>=1,a=a*a%mod)
	if(b&1)ans=ans*a%mod;
	return ans;
}
int C(int n,int m){
	if(!n)return 1;
	if(m<n)return 0;
	return fac[m]*inv[m-n]%mod*inv[n]%mod;
}
void init(){
	fac[0]=1;
	for(int i=1;i<=n;++i)fac[i]=i*fac[i-1]%mod;
	inv[n]=qpow(fac[n],mod-2);
	for(int i=n-1;~i;--i)inv[i]=inv[i+1]*(i+1)%mod;
}
int col[200001];
int w[200001];
int allmin=0x7fffffff,secmin=0x7fffffff;
int minpos,secpos;
int minn[200001];
int A,B;
int sum[200001],allsum;
signed main(){
	memset(minn,0x7f,sizeof(minn));
	scanf("%lld%lld%lld",&n,&A,&B);
	init();
	for(int i=1;i<=n;++i){
		scanf("%lld%lld",&col[i],&w[i]);
		minn[col[i]]=min(minn[col[i]],w[i]);
		if(w[i]<allmin){
			secpos=minpos;
			minpos=i;
			secmin=allmin;
			allmin=w[i];
		}
		else if(w[i]<secmin){
			secpos=i;
			secmin=w[i];
		}
	}
	for(int i=1;i<=n;++i){
		if(minn[col[i]]+w[i]<=A){
			w[i]=minn[col[i]];
		}
		if(col[i]!=col[minpos]&&w[i]+w[minpos]<=B){
			allsum++;
			sum[col[i]]++;
		}
		if(col[i]==col[minpos]&&w[i]+w[secpos]<=B){
			allsum++;
			sum[col[i]]++;
		}
	}
	int ans=1;
	for(int i=1;i<=n;++i){
		if(sum[i]){
			ans=(ans*C(sum[i],allsum))%mod;
			allsum-=sum[i];
		}
	}
	printf("%lld\n",ans);
}

