void internal( int t ){
  if( not v[t].empty() ){
    int mx = x - v[t][0];
    int it = upper_bound( ALL(v[t]), mx ) - v[t].begin();
    REP( i , it-1 ){
      uf.unite( sum[t]+i, sum[t]+i+1 );
    }
  }
}

void external( int a, int t ){
  int mx = y - a;
  vi ad;
  REP( i , n ){
    if( i == t ){
      continue;
    }
    int it = upper_bound( ALL(v[i]), mx ) - v[i].begin();
    REP( j , it-1 ){
      uf.unite( sum[i]+j, sum[i]+j+1 );
    }
    if( it > 0 ){
      ad.pb( i );
    }
  }
  REP( i , SZ(ad)-1 ){
    uf.unite( sum[ad[i]], sum[ad[i+1]] );
  }
}

