struct edge
{
	int cnp, to[maxn], last[maxn], head[maxn];
	edge() { cnp = 2; }
	void add(int u, int v)
	{
		to[cnp] = v, last[cnp] = head[u], head[u] = cnp ++;
		to[cnp] = u, last[cnp] = head[v], head[v] = cnp ++;
	}
}E1;

struct node
{
	int c, w;
	friend bool operator <(const node &a, const node& b)
	{ 
		if(a.c == b.c) return a.w < b.w; 
		if(W[a.c] != W[b.c]) return W[a.c] < W[b.c]; 
		else return a.c < b.c;
	}
}P[maxn];

void dfs(int u)
{
	vis[u] = 1; cnt ++; C[P[u].c] ++;
	ans = ans * inv[C[P[u].c]] % mod;
	S[++ tot] = u;
	for(int i = E1.head[u]; i; i = E1.last[i])
	{
		int v = E1.to[i];
		if(vis[v]) continue;
		dfs(v);
	}
}

