ll MOD = 1E9 + 7;

ll F[200010];
ll I[200010];

ll power(ll a, ll b) {
	ll res = 1;
	while (b > 0) {
		if (b % 2) {
			res *= a;
			res %= MOD;
		}
		b /= 2;
		a *= a;
		a %= MOD;
	}
	return res;
}

ll nchoosek(ll a, ll b) {
	ll base = I[a - b] * I[b];
	base %= MOD;
	base *= F[a];
	base %= MOD;
	return base;
}

int main() {
