    }
    I[200000] = power(F[200000], MOD - 2);
    for (ll i = 200000 - 1;i >= 0;i--) {
    	I[i] = I[i + 1] * (i + 1);
    	I[i] %= MOD;
    }
    unordered_map<ll, vector<ll> > CC;
    ll m = 1E9;
    for (ll i = 0;i < N;i++) {
