const long MOD = 1000000007;
const int  N_MAX = 200001;
const int INF = 2e+9;

using namespace std;

long inv[N_MAX];
long fac[N_MAX];
long finv[N_MAX];

typedef pair<int, int> P;

void init(){
    inv[0] = 1;
    fac[0] = 1;
    finv[0] = 1;
    inv[1] = 1;
    fac[1] = 1;
    finv[1] = 1;
    for(int i = 2; i < N_MAX; i++){
        fac[i] = (fac[i-1]*i)%MOD;
        inv[i] = ((-(MOD/i)*inv[MOD%i])%MOD+MOD)%MOD;
        finv[i] = (finv[i-1]*inv[i])%MOD;
    }
}


long comb(int n, int m){
    long ans;
    ans = fac[n]*finv[m];
    ans %= MOD;
    ans *= finv[n-m];
    ans %= MOD;
    return ans;
}


