#include <bits/stdc++.h>
using namespace std;
#define modulo 1000000007
#define mod(mod_x) ((((long long)mod_x+modulo))%modulo)
#define Inf 1000000000000000000

struct unionfind{
	vector<int> data;
	vector<int> size;
	unionfind(int n){
		for(int i=0;i<n;i++){
			data.push_back(i);
			size.push_back(1);
		}
	}

	int find(int x){
		if(data[x]==x)return x;
		return data[x]=find(data[x]);
	}

	bool unite(int x,int y){
		x=find(x);y=find(y);
		if(x==y)return false;
		if(size[x]>size[y])swap(x,y);
		data[x]=y;
		size[y]+=size[x];
		return true;
	}

	bool check(int x,int y){
		return (find(x)==find(y));
	}

	int get_size(int x){
		int X = find(x);
		return size[X];
	}
};

//aのb乗
int beki(int a,int b,int M = modulo){
	int x = 1;
	while(b!=0){
		if(b&1){
			x=((long long)x*a)%M;
		}
		a=((long long)a*a)%M;
		b>>=1;
	}
	return x;
}


//aの逆元
int gyakugen(int a){
	return beki(a,modulo-2);
}

struct combi{
	deque<int> kaijou;
	deque<int> kaijou_;

	combi(int n){
		kaijou.push_back(1);
		for(int i=1;i<=n;i++){
			kaijou.push_back(mod(kaijou[i-1]*i));
		}

		int b=gyakugen(kaijou[n]);

		kaijou_.push_front(b);
		for(int i=1;i<=n;i++){
			int k=n+1-i;
			kaijou_.push_front(mod(kaijou_[0]*k));
		}
	}

	int combination(int n,int r){
		if(r>n)return 0;
		int a = mod(kaijou[n]*kaijou_[r]);
		a=mod(a*kaijou_[n-r]);
		return a;
	}

	int junretsu(int a,int b){
		int x = mod(kaijou_[a]*kaijou_[b]);
		x=mod(x*kaijou[a+b]);
		return x;
	}

	int catalan(int n){
		return mod(combination(2*n,n)*gyakugen(n+1));
	}

};

int main(){

	int N,X,Y;
	cin>>N>>X>>Y;

	vector<int> c(N),w(N);
	vector<vector<pair<int,int>>> num(N,vector<pair<int,int>>());
	for(int i=0;i<N;i++){
		cin>>c[i]>>w[i];
		c[i]--;
		num[c[i]].emplace_back(w[i],i);
	}

	unionfind uf(N);
	vector<pair<int,int>> P;

	for(int i=0;i<N;i++){
		if(num[i].size()==0)continue;
		sort(num[i].begin(),num[i].end());
		for(int j=0;j<num[i].size();j++){
			if(num[i][0].first + num[i][j].first <= X){
				uf.unite(num[i][0].second,num[i][j].second);
			}
		}
		P.push_back(num[i][0]);
	}
	sort(P.begin(),P.end());

	for(int i=0;i<min((int)P.size(),2);i++){
		int W = P[i].first;
		int C = c[P[i].second];
		for(int j=0;j<N;j++){
			if(C==c[j])continue;
			if(W+w[j]<=Y)uf.unite(j,P[i].second);
		}
	}

	vector<map<int,int>> mp(N,map<int,int>());

	for(int i=0;i<N;i++){
		mp[uf.find(i)][c[i]]++;
	}

	combi C(1000000);
	int ans = 1;
	for(int i=0;i<N;i++){
		int sum = 0;
		for(auto a:mp[i]){
			ans = mod(ans * C.kaijou_[a.second]);
			sum += a.second;
		}
		ans = mod(ans * C.kaijou[sum]);
	}

	cout<<ans<<endl;

	return 0;
}

