const int maxn = 200005, mod = 1000000007;
int color[maxn], weight[maxn];
std::vector<int> con[maxn];
int min[maxn];
int fa[maxn], size[maxn];
std::map<int, int> map[maxn];
ll fac[maxn], ifac[maxn];

inline ll power(ll x, int k) {
	if(k < 0) k += mod - 1;
	ll res = 1;
	while(k) {
		if(k & 1) (res *= x) %= mod;
		(x *= x) %= mod;
		k >>= 1;
	}
	return res;
}

int find(int x) {
	if(fa[x] == x) return x;
	return fa[x] = find(fa[x]);
}

inline void merge(int x, int y) {
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(size[x] > size[y]) std::swap(x, y);
	fa[x] = y;
	size[y] += size[x];
}

int main() {
	int n = read, x = read, y = read;
	weight[0] = 2000000000;

	for(int i = 1; i <= n; i ++) {
		read(color[i], weight[i]);
		con[color[i]].push_back(i);
		if(weight[i] < weight[min[color[i]]])
			min[color[i]] = i;
	}

	for(int i = 1; i <= n; i ++) {
		fa[i] = i;
		size[i] = 1;
	}

	int minc = 1, minc2 = 1;
	for(int c = 2; c <= n; c ++)
		if(weight[min[c]] < weight[min[minc]]) {
			minc2 = minc;
			minc = c;
		} else if(weight[min[c]] < weight[min[minc2]])
			minc2 = c;

	for(int c = 1; c <= n; c ++)
		for(int p : con[c])
			if(weight[p] + weight[min[c]] <= x)
				merge(p, min[c]);

	for(int c = 1; c <= n; c ++) {
		if(c != minc and weight[min[c]] + weight[min[minc]] <= y)
			merge(min[c], min[minc]);
		if(c != minc2 and weight[min[c]] + weight[min[minc2]] <= y)
			merge(min[c], min[minc2]);
	}

	for(int i = 1; i <= n; i ++)
		++ map[find(i)][color[i]];

	ll ans = 1;

	fac[0] = 1;
	for(int i = 1; i <= n; i ++)
		fac[i] = fac[i - 1] * i % mod;
	ifac[n] = power(fac[n], -1);
	for(int i = n; i; i --)
		ifac[i - 1] = ifac[i] * i % mod;

	for(int i = 1; i <= n; i ++)
		if(fa[i] == i) {
			int tot = 0;
			for(auto pr : map[i]) {
				tot += pr.second;
				(ans *= ifac[pr.second]) %= mod;
				/* debug("%d in %d\n", pr.second, i); */
			}
			(ans *= fac[tot]) %= mod;
		}

	printf("%lld\n", ans);
}

