bool cmp(Ball a, Ball b){
    return a.weight < b.weight;
}

ll f[200005], invf[200005], mod = 1e9+7;
Ball ball[200005];
vector<Ball> ballList[200005], lightestBalls;
vector<int> graf[200005];
bool vis[200005];

int dfs(int u, multiset<int> &ballInCc, vector<int> &ballInCcList){
    // cout << u << " ";
    int res = 1;
    vis[u] = 1;
    if(!ballInCc.count(ball[u].color)) ballInCcList.push_back(ball[u].color);
    ballInCc.insert(ball[u].color);
    for(auto v : graf[u]){
        if(!vis[v]){
            res += dfs(v, ballInCc, ballInCcList);
        }
    }
    return res;
}

ll mul(ll a, ll b){
    return ((a%mod)*(b%mod))%mod;
}

ll pw(ll b, ll e){
    if(e==0) return 1;
    ll t = pw(b,e/2);
    if(e&1) return mul(b,mul(t,t));
    return mul(t,t);
}

ll inverse(ll x){
    return pw(x,mod-2);
}

void precompute(){
    f[0] = invf[0] = 1;
    FOR(i,200000){
        f[i] = 1ll * i * f[i-1];
        f[i] %= mod;
        invf[i] = inverse(f[i]);
    }
}

int main(){

    ios :: sync_with_stdio(false);
    precompute();
    int N, X, Y;
    cin >> N >> X >> Y;

    FOR(i,N){
        cin >> ball[i].color >> ball[i].weight;
        ball[i].idx = i;
        ballList[ball[i].color].push_back(ball[i]);
    }

    FOR(i,N){
        if(ballList[i].empty()) continue;
        sort(ballList[i].begin(), ballList[i].end(), cmp);
        Ball minB = ballList[i][0];
        FOR(j, ballList[i].size()-1){
            Ball b = ballList[i][j];
            if(minB.weight + b.weight <= X){
                graf[minB.idx].push_back(b.idx);
                graf[b.idx].push_back(minB.idx);
            }
        }
        lightestBalls.push_back(minB);
    }

    sort(lightestBalls.begin(), lightestBalls.end(), cmp);
    REP(i,2){
        FORU(j,i+1,lightestBalls.size()-1){
            Ball x = lightestBalls[i];
            Ball y = lightestBalls[j];

            if(x.weight + y.weight <= Y){
                graf[x.idx].push_back(y.idx);
                graf[y.idx].push_back(x.idx);
            }
        }
    }

    ll ans = 1;
    FOR(i,N){
        if(!vis[i] && graf[i].size()>0){
            multiset<int> ballInCc;
            vector<int> ballInCcList;
            int sz = dfs(i, ballInCc, ballInCcList);
            // cout << "--" << endl;

            ll res = f[sz];
            REP(j, ballInCcList.size()){
                // cout << ballInCcList[j] << "-";
                res = mul(res, invf[ballInCc.count(ballInCcList[j])]);
            }

            // cout << endl;
            ans = mul(ans, res);
        }
    }

    cout << ans << endl;

    return 0;
}

