struct mod_t
{
	std::uint64_t val;
	mod_t(int x = 0) :val(x)
	{

	}
	mod_t& operator*=(mod_t const& x)
	{
		val *= x.val;
		val %= 1000000007;
		return *this;
	}
	mod_t& operator*=(int x)
	{
		return operator*=(mod_t(x));
	}
	mod_t& operator=(int x)
	{
		val = x;
		return *this;
	}
};

struct data_t
{
	int color;
	int weight;
};

struct union_find
{
	std::vector<std::set<int>> under;
	std::vector<int> over;
	std::vector<int> length;
	union_find(int N) :under(N), over(N, -1)
	{

	}
	int _find(int x)
	{
		if (over[x] == -1)
		{
			return x;
		}
		auto t = over[x];
		under[t].insert(under[x].begin(), under[x].end());
		under[x].clear();
		return _find(t);
	}

	void _union(int x, int y)
	{
		auto _x = _find(x);
		auto _y = _find(y);
		if (_x == _y)
		{
			return;
		}
		over[_y] = _x;
		under[_x].emplace(_y);
	}

	template<class Func>void _foreach(Func func, int start)
	{
		func(start);
		for (auto v : under[start])
		{
			_foreach(func, v);
		}
	}
};
mod_t operator*(mod_t lhs, mod_t const& rhs)
{
	lhs *= rhs;
	return lhs;
}
mod_t pow(mod_t x, std::uint64_t v)
{
	if (v == 0)
	{
		return mod_t(1);
	}
	else if (v == 1)
	{
		return x;
	}
	else if (v == 2)
	{
		return x*x;
	}
	else if (v % 2 == 0)
	{
		return pow(pow(x, v / 2), 2);
	}
	else
	{
		return pow(pow(x, v / 2), 2)*x;
	}
}
mod_t inverse(mod_t x)
{
	return pow(x, 1000000005);
}

int main()
{
	int N, X, Y;
	std::cin >> N >> X >> Y;
	std::vector<mod_t> fact(N + 1);
	std::vector<mod_t> inv(N + 1);
	fact[0] = 1;
	inv[0] = 1;
	for (int i = 1; i <= N; ++i)
	{
		fact[i] = fact[i - 1];
		fact[i] *= i;
		inv[i] = inverse(fact[i]);
	}
	std::vector<data_t> data(N);
	union_find target(N);
	for (int i{}; i < N; ++i)
	{
		std::cin >> data[i].color >> data[i].weight;
		for (int j{}; j < i; ++j)
		{
			if (data[j].color == data[i].color&&data[j].weight + data[i].weight <= X)
			{
				target._union(i, j);
			}
			else if (data[j].color != data[i].color&&data[j].weight + data[i].weight <= Y)
			{
				target._union(i, j);
			}
		}
	}
	mod_t ret(1);
	std::vector<int> flag(N);
	for (int i = 0; i < N; ++i)
	{
		if (flag[i])
		{
			continue;
		}
		auto start = target._find(i);
		std::map<int, int> map;
		int size{};
		target._foreach([&](int v)
		{
			++map[data[v].color];
			flag[v] = true;
			++size;
		}, start);
		for (auto const&p : map)
		{
			ret *= fact[size];
			ret *= inv[p.second];
			ret *= inv[size - p.second];
			size -= p.second;
		}
	}
	std::cout << ret.val << std::endl;
}

