int N;
int uf[1<<20];
int height[1<<20];

void initialize() {
	rep(i, N) uf[i] = i, height[i] = 1;
}

int root(int i) {
	while (i != uf[i]) {
		i = uf[i];
	}
	return i;
}

bool same_component(int i, int j) {
	if(root(i) == root(j)) return true;
	return false;
}

void add_component(int i, int j) {
	if(same_component(i, j)) return;
	int ri = root(i);
	int rj = root(j);
	if(height[ri] == height[rj]) {
		uf[ri] = rj;
		height[rj]++;
	} else {
		(height[ri] < height[rj]) ? uf[ri] = rj : uf[rj] = ri;
	}
}

ll X, Y;
vector<pll> A(1<<20);
int make_component(int s) {
	int e = s+1;
	while (e < N and A[e].first == A[s].first) {
		if(A[e].second+A[s].second <= X) {
			add_component(s, e);
		}
		e++;
	}
	return e;
}

bool comparator(pll& u, pll& v) {
	return u.second < v.second;
}

vector<int> g[1<<20];
ll fact[1<<20];

ll power(ll x, ll n) {
	if(n == 0) return 1;
	ll y = power(x, n/2);
	if(n%2 == 0) {
		return (y*y) % mod;
	}
    return ((y*y)%mod * x) % mod;
}

ll answer = 1;
void update_answer(int s) {
	unordered_map<int, int> ma;
	for(auto &x : g[s]) {
		ma[x]++;
	}

	ll a = fact[g[s].size()];
	ll b = 1;
	for(auto it = ma.begin();it != ma.end();it++) {
		b = (b*fact[it->second]) % mod;
	}

	answer = (answer*((a*power(b, mod-2))%mod))%mod;
}

int main() {
