	cin>>N>>X>>Y;
	rep(i, N) cin>>A[i].first>>A[i].second;
	sort(A.begin(), A.begin() + N);
	initialize();
	int start = 0;
	while (start < N) {
		start = make_component(start);
	}

	ll minval = A[0].second;
	ll minindex = 0;
	rep(i, N) if(A[i].second < minval) {
		minval = A[i].second;
		minindex = i;
	}

	for(int i = 0;i < N;i++) {
		if(i != minindex and A[minindex].first != A[i].first and
			A[minindex].second + A[i].second <= Y) {
			add_component(minindex, i);
		}
	}

	// rep(i, N) cout<<A[i].first<<" "; cout<<endl;
	rep(i, N) g[root(i)].pb(A[i].first);

	/*
	rep(i, N) {
		cout<<i<<": ";
		for(auto &val: g[i]) cout<<val<<" ";
		cout<<endl;
	}*/

	fact[0] = fact[1] = 1;
	for(int i = 2;i <= N;i++) fact[i] = (i*(fact[i-1])) % mod;

	rep(i, N) {
		update_answer(i);
	}

	cout<<answer<<endl;

	return 0;
}

