struct node { LL v; node *nxt; } edge[maxn*75],*head[maxn],*ncnt;
void addedge(LL u,LL v)
{
	ncnt++;
	ncnt->v=v,ncnt->nxt=head[u];
	head[u]=ncnt;
}
void dfs(LL u)
{
	vis[u]=true;
	cnt[c[u]]++,Siz++;
	for(node *p=head[u];p;p=p->nxt)
	{
		LL v=p->v;
		if(!vis[v]) dfs(v);
	}
}
