lint powerMod(long x, long exponent) {
  long prod = 1;
  for (int i = 63; i >= 0; --i) {
    prod = (prod * prod) % MOD;
    if ((exponent & 1L << i) != 0) {
      prod = (prod * x) % MOD;
    }
  }
  return prod;
}


lint fact[N];
lint invfact[N];
void initialize() {
  fact[0] = invfact[0] = 1;
  for (int i = 1; i < N; ++i)
    fact[i] = (i * fact[i - 1]) % MOD;
  invfact[N-1]=powerMod(fact[N-1],MOD-2);
  for(int i=N-2;i>=0;--i)
    invfact[i] = invfact[i+1]*(i+1)%MOD;
}

