void solve(ll N, ll X, ll Y, vector<ll> c, vector<ll> w) {
  init();
  REP(i,N) wl[c[i] - 1].emplace_back(int(w[i]), i);
  UnionFind uf(N);
  REP(i,N) {
    sort(ALL(wl[i]));
    for (int j = 0; j < (int)(wl[i].size()); ++j) {
      if (wl[i][0].first + wl[i][j].first <= X)
        uf.merge(wl[i][0].second, wl[i][j].second);
    }
  }
  vector<pair<int,int>> v;
  REP(i,N) {
    v.emplace_back(w[i], i);
  }
  sort(ALL(v));
  vector<pair<int,int>> vec;
  for (auto i: v) {
    if (vec.empty() || vec.back().second != i.second)
      vec.push_back(i);
  }

  for (int i = 0; i < min(2, int(vec.size())); ++i) {
    for (int j = 0; j < N; ++j) {
      if (vec[i].first + w[j] <= Y && c[vec[i].second] != c[j]) {
        uf.merge(vec[i].second, j);
      }
    }
  }
  REP(i,N) {
    mapsto[uf.root(i)][c[i] - 1]++;
  }
  Mod res = 1;
