	for(int i = 0; i < n; i++){
		int c, w;
		cin >> c >> w;
		color[c].push_back(w);
	}
	for(int i = 1; i <= n; i++){
		if(color[i].size() != 0) sort(color[i].begin(), color[i].end());
	}
	getfactmod();
	getinversefactmod();
	cout << solve() << endl;
	return 0;

}

