const int maxn = 200005;
const int mod = 1e9+7;

int fac[maxn],inc[maxn];
int fpm(LL p,LL k) {
	LL res=1ll;
	while (k) {
		if (k&1) (res*=p)%=mod;
		(p*=p)%=mod;k>>=1;
	}
	return res;
}
int w[maxn],c[maxn],X,Y,n,sum,mw[maxn],o,p,par[maxn],sz[maxn];
int findp(int t) {return par[t]?par[t]=findp(par[t]):t;}
void merge(int u,int v) {u=findp(u);v=findp(v);u!=v?par[u]=v:0;}
int main()
{
	#ifdef Amberframe
		freopen("agc012d.in","r",stdin);
		freopen("agc012d.out","w",stdout);
	#endif
	scanf("%d %d %d",&n,&X,&Y);
	for (int i=1;i<=n;i++)
		scanf("%d %d",&c[i],&w[i]);
	for (int i=1;i<=n;i++)
		if (!o||w[i]<w[o]) o=i;
	for (int i=1;i<=n;i++)
		if ((!p||w[i]<w[p])&&c[i]!=c[o]) p=i;
	for (int i=1;i<=n;i++)
		if (!mw[c[i]]||w[mw[c[i]]]>w[i]) mw[c[i]]=i;
	for (int i=1;i<=n;i++)
	{
		if (c[i]!=c[p]&&w[i]+w[p]<=Y) merge(i,p);
		if (c[i]!=c[o]&&w[i]+w[o]<=Y) merge(i,o);
		if (w[mw[c[i]]]+w[i]<=X) merge(mw[c[i]],i);
	}
	fac[0]=inc[0]=1;int ans=1;
	for (int i=1;i<=n;i++) fac[i]=(LL)fac[i-1]*i%mod;
	inc[n]=fpm(fac[n],mod-2);
	for (int i=n;i>=2;i--) inc[i-1]=(LL)inc[i]*i%mod;
	for (int i=1;i<=n;i++) if (findp(i)==findp(o)) sz[c[i]]++,sum++;
	for (int i=1;i<=n;i++) ans=(LL)ans*inc[sz[i]]%mod;
	printf("%d",(LL)ans*fac[sum]%mod);
	return 0;
}

