#include <bits/stdc++.h>
using namespace std;

#define FOR(i,l,r) for(int i = (int) (l);i < (int) (r);i++)
#define ALL(x) x.begin(),x.end()
template<typename T> bool chmax(T& a,const T& b){ return a < b ? (a = b,true) : false; }
template<typename T> bool chmin(T& a,const T& b){ return b < a ? (a = b,true) : false; }
typedef long long ll;

int N,X,Y;
pair<int,int> colorMin [200001];
vector<int> colors [200001];
ll fact [200001],rfact [200001];
const int INF = 2e9;
const ll MOD = 1e9 + 7;

ll mod_pow(ll x,ll y = MOD - 2)
{
	ll res = 1;
	while(y){
		if(y & 1) (res *= x) %= MOD;
		(x *= x) %= MOD;
		y >>= 1;
	}
	return res;
}

int main()
{
	scanf("%d%d%d",&N,&X,&Y);
	vector<int> C(N),W(N);
	fill(colorMin + 1,colorMin + N + 1,make_pair(INF,INF));
	FOR(i,0,N){
		scanf("%d%d",&C [i],&W [i]);
		colors [C [i]].push_back(W [i]);
		chmin(colorMin [C [i]],make_pair(W [i],C [i]));
	}
	FOR(i,1,N + 1){
		sort(ALL(colors [i]));
	}

	sort(colorMin + 1,colorMin + N + 1);
	int allMin = colorMin [1].first;
	int r = lower_bound(colorMin + 1,colorMin + N + 1,make_pair(Y - allMin + 1,0)) - colorMin;
	chmax(r,2);

	map<int,int> mp;
	for(int i = 1;i < r;i++){
		int idx = colorMin [i].second;
		int res = upper_bound(ALL(colors [idx]),X - colorMin [i].first) - colors [idx].begin();
		chmax(res,(int) (upper_bound(ALL(colors [idx]),Y - allMin) - colors [idx].begin()));
		chmax(res,1);
		mp [idx] += res;
	}

	fact [0] = rfact [0] = 1;
	for(int i = 1;i <= 200000;i++){
		fact [i] = fact [i - 1] * i % MOD;
		rfact [i] = mod_pow(fact [i]);
	}

	ll ans = 1,sum = 0;
	for(const auto& it : mp){
		(ans *= rfact [it.second]) %= MOD;
		sum += it.second;
	}
	(ans *= fact [sum]) %= MOD;

	printf("%lld\n",ans);

	return 0;
}

