ll pow_mod(ll a, ll st){
	ll ans = 1ll;
	for(; st; st /= 2ll){
		if (st & 1){
			ans = (ans * a) % MOD;
		}
		a = (a * a) % MOD;
	}
	return ans;
}

ll get_c(ll i, ll j){
	if (i < 0 || j < 0 || j > i){
		return 0ll;
	}
	return (((f[i] * f_inv[j]) % MOD) * f_inv[i - j]) % MOD;
}

void solve(){
	int n, x, y;
	scanf("%d%d%d", &n, &x, &y);
	REP(i, 0, n){
		scanf("%d%d", &pp[i]._2, &pp[i]._1);
	}

	f[0] = 1;
	REPN(i, 1, n){
		f[i] = (f[i - 1] * i) % MOD;
	}
	f_inv[n] = pow_mod(f[n], MOD - 2);
	for(int i = n - 1; i >= 0; i--){
		f_inv[i] = (f_inv[i + 1] * (i + 1)) % MOD;
	}

	/*REPN(i, 0, 10){
		printf("%d %lld %lld\n", i, f[i], f_inv[i]);
	}*/

	sort(pp, pp + n);
