		if (pp[i]._1 + pp[0]._1 <= y){
			good_col[pp[i]._2] = 1;
			cnt_col[pp[i]._2]++;
			cnt++;
			if (pp[i]._2 != pp[0]._2){
				fl = 1;
			}
