	if (!fl){
		printf("1\n");
		return;
	}
	REP(i, cnt, n){
		if (good_col[pp[i]._2] && mn[pp[i]._2] && mn[pp[i]._2] + pp[i]._1 <= x){
			cnt++;
			cnt_col[pp[i]._2]++;
		}
	}
	ll ans = 1ll;
	REPN(i, 1, n){
		if (cnt_col[i]){
			ans = (ans * get_c(cnt, cnt_col[i])) % MOD;
			cnt -= cnt_col[i];
		}
	}
	cout << ans << endl;
}   

