inline void read(int &x) {
	x = 0; char ch = getchar();
	while(!isdigit(ch)) ch = getchar();
	while(isdigit(ch)) x = x * 10 + ch - '0', ch = getchar();
}
inline int fpm(int bs, int mi) {
	int res = 1;
	while(mi) {
		if(mi & 1) res = 1LL * res * bs % mod;
		bs = 1LL * bs * bs % mod, mi >>= 1;
	}
	return res;
}

inline bool judge(node A, node B) { return A.c == B.c ? A.w + B.w <= x : A.w + B.w <= y; }

int main() {
	read(n), read(x), read(y);

	fac[0] = 1;
	for(int i = 1; i <= n; ++i) {
		fac[i] = 1LL * i * fac[i - 1] % mod;
		mBall[i].c = i, mBall[i].w = 1e9;
	}
	for(int i = 1, c, w; i <= n; ++i) {
		read(c), read(w);
		ball[i].c = c, ball[i].w = w;
		mBall[c].w = min(mBall[c].w, w);
	}

	m1Ball.w = m2Ball.w = 1e9;
	for(int i = 1; i <= n; ++i) {
		if(mBall[i].w < m2Ball.w) {
			m2Ball = mBall[i];
			if(m2Ball.w < m1Ball.w)
				swap(m1Ball, m2Ball);
		}
	}

	for(int i = 1; i <= n; ++i) {
		int c = ball[i].c;
		if(judge(m1Ball, ball[i])) {
			++cnt[c];
		} else if(judge(m2Ball, ball[i])) {
			++cnt[c];
