		}
	}

	int ans = 1, sum = 0;
	for(int i = 1; i <= n; ++i) {
		if(!cnt[i]) continue;
		sum += cnt[i];
		ans = 1LL * ans * fpm(fac[cnt[i]], mod - 2) % mod;
	}
	ans = 1LL * fac[sum] * ans % mod;
	printf("%d\n", ans);
	return 0;
}

