const int maxn = 2e5 + 5;
int n, x, y;
int c[maxn];
int w[maxn];
int dj[maxn];
int sz[maxn];
vi g[maxn];
int fac[maxn];
int ifac[maxn];
map<int, int> hs[maxn];
vi gg[maxn];

int binom(int a, int b) {
	if (a < 0 || a > b) return 0;
	if (!a || a == b) return 1;
	return mult(fac[b], mult(ifac[a], ifac[b - a]));
}

void init() {
	FOR(i, 0, n) dj[i] = i, sz[i] = 1;
}
int find(int u) {
	return dj[u] == u ? dj[u] : dj[u] = find(dj[u]);
}
void join(int u, int v) {
	int p = find(u);
	int q = find(v);
	if (p != q) {
		dj[p] = q;
		sz[q] += sz[p];
	}
}

int compare(int i, int j) {
	if (w[i] != w[j]) return w[i] < w[j];
	return i < j;
}

void solve() {
	fac[0] = 1; FOR(i, 1, maxn) fac[i] = mult(fac[i - 1], i);
	FOR(i, 0, maxn) ifac[i] = inv(fac[i]);
	cin >> n >> x >> y;
	FOR(i, 0, n) {
		cin >> c[i] >> w[i];
		gg[c[i]].pb(i);
	}
	vi ver; FOR(i, 0, n) ver.pb(i);
	sort(all(ver), compare);
	int u = ver[0], v = -1;
	FOR(i, 1, n) if (ver[i] != u) {
		v = ver[i];
		break;
	}
	init();
	FOR(i, 0, n) {
		if (c[u] == c[i] && w[u] + w[i] <= x) {
			join(u, i);
		}
		else if (c[u] != c[i] && w[u] + w[i] <= y) {
			join(u, i);
		}
	}
	if (v != -1) {
		FOR(i, 0, n) {
			if (c[v] == c[i] && w[v] + w[i] <= x) {
				join(v, i);
			}
			else if (c[v] != c[i] && w[v] + w[i] <= y) {
				join(v, i);
			}
		}
	}
	FOR(i, 0, maxn) {
		sort(all(gg[i]), compare);
		FOR(j, 0, sz(gg[i])) {
			int u = gg[i][0];
			int v = gg[i][j];
			if (c[u] == c[v] && w[u] + w[v] <= x) {
				join(u, v);
			}
			else if (c[u] != c[v] && w[u] + w[v] <= y) {
				join(u, v);
			}
		}
	}
	FOR(i, 0, n) {
		hs[find(i)][c[i]]++;
	}
	int ans = 1;
	FOR(i, 0, n) {
		int cnt = 0;
		FORall(it, hs[i]) {
			cnt += it->se;
			ans = mult(ans, binom(it->se, cnt));
		}
	}
	cout << ans << "\n";
}

