		map[c[i]].emplace_back(w[i]);
	}
	std::vector<PAIR> pv;
	for (auto& v : map) {
		std::sort(ALL(v.second));
		pv.emplace_back(PAIR(v.second[0], v.first));
	}
	int m = pv.size();
