				++ccnt[i];
				checked[i][j];
			}
		}
		(ans *= factInv[ccnt[i]]) %= MOD;
	}
	if (a.size() >= 2 && a[0][0] + a[1][0] <= y) {
		REP(j, a[0].size()) {
			if (a[1][0] + a[0][j] <= y || a[0][0] + a[0][j] <= x) {
				++ccnt[0];
				checked[0][j];
			}
		}
		(ans *= factInv[ccnt[0]]) %= MOD;
	}
	int cnt = 0;
	for (const auto& m1 : checked) {
		for (const auto& m2 : m1.second) ++cnt;
	}
	(ans *= fact[cnt]) %= MOD;
	OUT(ans)BR;
