using namespace std;
const int N=200005,mod=1e9+7;
int read(){
	int x=0;
	char ch=getchar();
	while (!isdigit(ch))
		ch=getchar();
	while (isdigit(ch))
		x=(x<<1)+(x<<3)+(ch^48),ch=getchar();
	return x;
}
int INF;
int n,x,y;
int c[N],w[N];
int Min[N],cnt[N];
int Fac[N],Inv[N];
int id[N];
int Pow(int x,int y){
	int ans=1;
	for (;y;y>>=1,x=1LL*x*x%mod)
		if (y&1)
			ans=1LL*ans*x%mod;
	return ans;
}
bool cmp(int a,int b){
	return Min[a]<Min[b];
}
int main(){
	n=read(),x=read(),y=read();
	INF=max(x,y)+1;
	for (int i=0;i<N;i++)
		Min[i]=INF;
	for (int i=1;i<=n;i++){
		c[i]=read(),w[i]=read(),id[i]=i;
		Min[c[i]]=min(Min[c[i]],w[i]);
	}
	for (int i=1;i<=n;i++)
		if (w[i]+Min[c[i]]<=x)
			w[i]=Min[c[i]];
	sort(id+1,id+n+1,cmp);
	int allcnt=0;
	memset(cnt,0,sizeof cnt);
	for (int i=1;i<=n;i++){
		if (id[1]!=c[i]){
			if (w[i]+Min[id[1]]<=y)
				allcnt++,cnt[c[i]]++;
		}
		else if (w[i]+Min[id[2]]<=y)
			allcnt++,cnt[c[i]]++;
	}
	for (int i=Fac[0]=1;i<=n;i++)
		Fac[i]=1LL*Fac[i-1]*i%mod;
	Inv[n]=Pow(Fac[n],mod-2);
	for (int i=n;i>=1;i--)
		Inv[i-1]=1LL*Inv[i]*i%mod;
	int ans=Fac[allcnt];
	for (int i=0;i<N;i++)
		ans=1LL*ans*Inv[cnt[i]]%mod;
	cout << ans;
	return 0;
}

