//x! O(x)
vll mod_factorial(ll x, ll mod) {
	if (x < 0) return{};
	else {
		vll ret((int)x + 1);
		ret[0] = 1;
		Loop1(i, (int)x) ret[i] = ret[i - 1] * i % mod;
		return ret;
	}
}

//x^y O(log y)
ll mod_pow(ll x, ll y, ll mod) {
	if (y == 1) return x;
	else {
		ll ans = mod_pow(x, y / 2, mod);
		ans = ans * ans % mod;
		if (y % 2 == 1) ans = ans * x % mod;
		return ans;
	}
}

//無向グラフの隣接リストを受け取って連結成分の一覧を返す
vvi cc(vvi nodes) {
	vvi ret;
	vector<bool> done(nodes.size(), false);
	Loop(i, nodes.size()) {
		if (done[i]) continue;
		queue<int> que;
		ret.push_back({});
		que.push(i);
		while (que.size()) {
			int a = que.front(); que.pop();
			if (done[a]) continue;
			ret.back().push_back(a);
			done[a] = true;
			Loop(j, nodes[a].size()) {
				int b = nodes[a][j];
				if (done[b]) continue;
				else {
					que.push(b);
				}
			}
		}
	}
	return ret;
}

int main() {
	ll n, x, y;
	cin >> n >> x >> y;
	vll c(n), w(n);
	Loop(i, n) cin >> c[i] >> w[i];

	map<ll, ll> mp1; //色→最小重量をもつindex
	Loop(i, n) {
		if (mp1.find(c[i]) == mp1.end()) mp1[c[i]] = i;
		else if (w[mp1[c[i]]] > w[i]) mp1[c[i]] = i;
	}
	ll min_index = INFLL; //全てのボールの最小重量をもつindex
	ll min2_index = INFLL; //上とは別の色で、最小重量をもつindex
	for (auto itr = mp1.begin(); itr != mp1.end(); itr++) {
		int t = (*itr).second;
		if (min_index == INFLL || w[min_index] > w[t]) {
			min2_index = min_index;
			min_index = t;
		}
		else if (min2_index == INFLL || w[min2_index] > w[t]) {
			min2_index = t;
		}
	}
	//可換indexどうしでエッジを張る
	vvi nodes(n);
	//操作1
	Loop(i, n) {
		if (w[i] + w[mp1[c[i]]] <= x) {
			int t = mp1[c[i]];
			if (i != t) {
				nodes[i].push_back(t);
				nodes[t].push_back(i);
			}
		}
	}
	//操作2
	Loop(i, n) {
		if (c[i] != c[min_index]) {
			if (w[i] + w[min_index] <= y) {
				nodes[i].push_back(min_index);
				nodes[min_index].push_back(i);
			}
		}
		else if (min2_index != INFLL) {
			if (w[i] + w[min2_index] <= y) {
				nodes[i].push_back(min2_index);
				nodes[min2_index].push_back(i);
			}
		}
	}
	//計算の準備
	vvi dat = cc(nodes);
	ll mod = 1e9 + 7;
	vll fact = mod_factorial(n, mod);
	vll invfact(n + 1);
	Loop(i, n + 1) {
		invfact[i] = mod_pow(fact[i], mod - 2, mod);
	}
	ll ans = 1;
	Loop(i, dat.size()) {
		map<ll, ll> mp2;
		Loop(j, dat[i].size()) {
			int index = dat[i][j];
			mp2[c[index]]++;
		}
		ll p = fact[dat[i].size()];
		for (auto itr = mp2.begin(); itr != mp2.end(); itr++) {
			ll k = (*itr).second;
			p = p * invfact[k] % mod;
		}
		ans = ans * p % mod;
	}
	cout << ans << endl;
	return 0;
}

#include <bits/stdc++.h>

#define MAXN (200010)
#define mod (1000000007)

int n, X, Y, cnt;
int c[MAXN], w[MAXN], fact[MAXN], rfact[MAXN];
bool vis[MAXN];
std::vector<int> col[MAXN];
std::vector<int> op2;
std::vector<int> vec[MAXN];
std::map<int, int> map;

void addedge(int u, int v){
	vec[u].push_back(v);
	vec[v].push_back(u);
}

int powmod(int a, int b){
	int ret = 1;
	while(b){
		if(b & 1) ret = 1ll * ret * a % mod;
		b >>= 1;
		a = 1ll * a * a % mod;
	}
	return ret;
}

void dfs(int u){
	++ cnt;
	++ map[c[u]];
	vis[u] = true;
	for(auto v : vec[u]){
		if(vis[v]) continue;
		dfs(v);
	}
}

bool cmp(const int &a, const int &b){
	return w[a] < w[b];
}

int main(){
	scanf("%d%d%d", &n, &X, &Y);
	for(int i = 1; i <= n; ++ i){
	    scanf("%d%d", c + i, w + i);
	    col[c[i]].push_back(i);
	}
	fact[0] = 1;
	for(int i = 1; i <= n; ++ i){
		fact[i] = 1ll * fact[i - 1] * i % mod;
	}
	rfact[n] = powmod(fact[n], mod - 2);
	for(int i = n - 1; i + 1; -- i){
		rfact[i] = 1ll * rfact[i + 1] * (i + 1) % mod;
	}
	//operation 1
	for(int i = 1; i <= n; ++ i){
		if(!col[i].size()) continue;
		int sit = col[i][0];
		for(int j = 1, sz = (int)col[i].size(); j < sz; ++ j){
			if(w[sit] > w[col[i][j]]){
				sit = col[i][j];
			}
		}
		op2.push_back(sit);
		for(int j = 0, sz = (int)col[i].size(); j < sz; ++ j){
			if(sit != col[i][j] && w[sit] + w[col[i][j]] <= X){
				addedge(sit, col[i][j]);
			}
		}
	}
	//operation 2
	std::sort(op2.begin(), op2.end(), cmp);
	if(op2.size() >= 2){
		int sit1 = op2[0], sit2 = op2[1];
		if(w[sit1] + w[sit2] <= Y){
			addedge(sit1, sit2);
		}
		for(int i = 1; i <= n; ++ i){
			if(c[i] != c[sit1] && w[i] + w[sit1] <= Y){
				addedge(i, sit1);
			}
			if(c[i] != c[sit2] && w[i] + w[sit2] <= Y){
				addedge(i, sit2);
			}
		}
	}
	int ans = 1;
	for(int i = 1; i <= n; ++ i){
		if(!vis[i]){
			cnt = 0;
			map.clear();
			dfs(i);
			ans = 1ll * ans * fact[cnt] % mod;
			for(auto p : map){
				ans = 1ll * ans * rfact[p.second] % mod;
			}
		}
	}
	printf("%d\n", ans);
	return 0;
}

