void getmin()
{
	for(int i=1;i<=n;i++)
	{
		if(minc[i]<minc[min1])
		{
			min2=min1;
			min1=i;
		}
		else if(minc[i]<minc[min2])
			min2=i;
	}
}

int poww(int a,int b)
{
	int ans=1;
	while(b)
	{
		if(b&1)
			ans=(1ll*ans*a)%mod;
		a=(1ll*a*a)%mod;
		b>>=1;
	}
	return ans;
}

void preC()
{
	fac[0]=1;
    for(int i=1;i<=n;i++)
        fac[i]=1ll*i*fac[i-1]%mod;
    inv[n]=poww(fac[n],mod-2);
    for(int i=n-1;i>=0;i--)
        inv[i]=1ll*inv[i+1]*(i+1)%mod;
}

int C(int n,int m)
{
    return ((1ll*fac[m]*inv[m-n])%mod*inv[n])%mod;
}

