#define mod 1000000007
int N;
int uf[1<<20];
int height[1<<20];

void initialize() {
	rep(i, N) uf[i] = i, height[i] = 1;
}

int root(int i) {
	while (i != uf[i]) {
		i = uf[i];
	}
	return i;
}

bool same_component(int i, int j) {
	if(root(i) == root(j)) return true;
	return false;
}

void add_component(int i, int j) {
	if(same_component(i, j)) return;
	int ri = root(i);
	int rj = root(j);
	if(height[ri] == height[rj]) {
		uf[ri] = rj;
		height[rj]++;
	} else {
		(height[ri] < height[rj]) ? uf[ri] = rj : uf[rj] = ri;
	}
}

ll X, Y;
vector<pll> A(1<<20);
int make_component(int s) {
	int e = s+1;
	while (e < N and A[e].first == A[s].first) {
		if(A[e].second+A[s].second <= X) {
			add_component(s, e);
		}
		e++;
	}
	return e;
}

bool comparator(pll& u, pll& v) {
	return u.second < v.second;
}

vector<int> g[1<<20];
ll fact[1<<20];

ll power(ll x, ll n) {
	if(n == 0) return 1;
	ll y = power(x, n/2);
	if(n%2 == 0) {
		return (y*y) % mod;
	}
    return ((y*y)%mod * x) % mod;
}

ll answer = 1;
void update_answer(int s) {
	unordered_map<int, int> ma;
	for(auto &x : g[s]) {
		ma[x]++;
	}

	ll a = fact[g[s].size()];
	ll b = 1;
	for(auto it = ma.begin();it != ma.end();it++) {
		b = (b*fact[it->second]) % mod;
	}

	answer = (answer*((a*power(b, mod-2))%mod))%mod;
}

int main() {
  	//freopen("input.in","r",stdin);
  	//freopen("output.out","w",stdout);
	cin>>N>>X>>Y;
	rep(i, N) cin>>A[i].first>>A[i].second;
	sort(A.begin(), A.begin() + N);
	//rep(i, N) cout<<A[i].first<<" "<<A[i].second<<endl;
	initialize();
	int start = 0;
	while (start < N) {
		start = make_component(start);
	}

	ll minval = A[0].second;
	ll minindex = 0;
	rep(i, N) if(A[i].second < minval) {
		minval = A[i].second;
		minindex = i;
	}

	for(int i = 0;i < N;i++) {
		if(i != minindex and A[minindex].first != A[i].first and
			A[minindex].second + A[i].second <= Y) {
			add_component(minindex, i);
		}
	}

	if(N >= 2) {
		int sminindex = -1;
		for(int i = 0;i < N;i++) {
			if(A[i].first != A[minindex].first) {
				if(sminindex == -1)
					sminindex = i;
				else if(A[i].second < A[sminindex].second)
						sminindex = i;
			}
		}

		minindex = sminindex;
		if(minindex != -1)
		for(int i = 0;i < N;i++) {
			if(i != minindex and A[minindex].first != A[i].first and
				A[minindex].second + A[i].second <= Y) {
				add_component(minindex, i);
			}
		}
	}

	// rep(i, N) cout<<A[i].first<<" "; cout<<endl;
	rep(i, N) g[root(i)].pb(A[i].first);

	/*
	rep(i, N) {
		cout<<i<<": ";
		for(auto &val: g[i]) cout<<val<<" ";
		cout<<endl;
	}*/

	fact[0] = fact[1] = 1;
	for(int i = 2;i <= N;i++) fact[i] = (i*(fact[i-1])) % mod;

	rep(i, N) {
		update_answer(i);
	}

	cout<<answer<<endl;

	return 0;
}

#include <bits/stdc++.h>
#define mod 1000000007ll
#define M 200010
using namespace std;
struct edge
{
	int to;
	int nxt;
}e[3000010];
int n,minnum,minnum2;
int color[M],dlfl[M],pos[M],vis[M];
long long val[M],minn[M];
long long fac[M],rfac[M];
long long X,Y;
long long min1 = 2147483647ll,min2 = 2147483647ll;
int head[M],cnt;
void addedge(int x,int y)
{
	e[++cnt].nxt = head[x];
	e[cnt].to = y;
	head[x] = cnt;
}
void add(int x,int y)
{
	addedge(x,y);
	addedge(y,x);
}
long long qpow(long long a,long long b)
{
	long long ans = 1,res = a;
	while(b)
	{
		if(b&1)ans = (ans * res) % mod;
		res *= res;
		res %= mod;
		b >>= 1;
	}
	return ans;
}
long long C(long long n,long long k)
{
	return  fac[n] * rfac[k] % mod * rfac[n - k] % mod;
}
void init()
{
	fac[0] = 1;
	for(int i = 1;i <= n;i++)fac[i] = (i * fac[i - 1]) % mod;
	rfac[n] = qpow(fac[n],mod - 2);
	for(int i = n; i > 0; i--)rfac[i - 1] = (i * rfac[i]) % mod;
}
void dfs(int x)
{
	vis[x] = 1;
	for(int i = head[x]; i; i = e[i].nxt)
	{
		if(!vis[e[i].to])dfs(e[i].to);
	}
}
void find()
{
	for(int i = 1; i <= n; i++)
	{
		if(val[i] < min1)
		{
			min1 = val[i];
			minnum = i;
		}
	}
	for(int i = 1; i <= n; i++)
	{
		if(val[i] <= min2 && color[i] != color[minnum])
		{
			min2 = val[i];
			minnum2 = i;
		}
	}
}
int main()
{
	scanf("%d%lld%lld",&n,&X,&Y);
	init();
	for(int i = 1;i <= n;i++)minn[i] = 2147483647ll;
	for(int i = 1;i <= n;i++)scanf("%d%lld",&color[i],&val[i]);
	for(int i = 1;i <= n;i++)
	{
		if(val[i] < minn[color[i]])
		{
			minn[color[i]] = val[i];
			pos[color[i]] = i;
		}
	}
	for(int i = 1; i <= n; i++)
	{
		if(i != pos[color[i]] && val[i] + minn[color[i]] <= X)
		{
			add(i,pos[color[i]]);
		}
	}
	find();
	for(int i = 1; i <= n; i++)
	{
		if(i != minnum)
		{
			if(color[i] != color[minnum] && val[i] + val[minnum] <= Y)
			{
				add(i,minnum);
			}
			if(minnum2 && color[i] != color[minnum2] && val[i] + val[minnum2] <= Y)
			{
				add(i,minnum2);
			}
		}

	}
	dfs(minnum);
	long long fldl = 0;
	for(int i = 1; i <= n; i++)
	{
		if(vis[i])
		{
			dlfl[color[i]]++;
		}
	}
	for(int i = 1;i <= n;i++)fldl += dlfl[i];
	long long ans = 1;
	for(int i = 1; i <= n; i++)
	{
		if(dlfl[i])
		{
			ans *= C(fldl,dlfl[i]);
			ans %= mod;
			fldl -= dlfl[i];
		}
	}
	printf("%lld",ans);
	return 0;
}

