#include <bits/stdc++.h>
#define mod 1000000007
using namespace std;
typedef long long ll;
int n,X,Y,A1,A2,vis[200010],col[200010],tim[200010];
ll ans,divi,fac[200010];
pair <int,int> P[200010];
vector <int> V[200010];
struct edge
{
	int u,v,next;
}vs[1200010];
int st[200010],ee;
inline void addedge(int u,int v)
{
	vs[++ee].v=v;vs[ee].next=st[u];st[u]=ee;
}
inline ll qpow(ll bas,ll pw)
{
	ll ans=1; for(;pw;pw>>=1,(bas*=bas)%=mod)
	if(pw&1) (ans*=bas)%=mod; return ans;
}
int dfs(int x,int ti)
{
	vis[x]=1; int size=1;
	if(col[P[x].second]!=ti)
	{
		col[P[x].second]=ti;
		tim[P[x].second]=1;
	}
	else
	{
		divi*=(++tim[P[x].second]); divi%=mod;
	}
	for(int i=st[x];i;i=vs[i].next)
		if(!vis[vs[i].v]) size+=dfs(vs[i].v,ti);
	return size;
}
int main()
{
//	freopen("read.in","r",stdin);
	scanf("%d%d%d",&n,&X,&Y);
	for(int i=1;i<=n;i++)
		scanf("%d%d",&P[i].second,&P[i].first);
	sort(P+1,P+1+n);
	fac[0]=1; for(int i=1;i<=n;i++) fac[i]=fac[i-1]*i%mod;
	for(int i=1;i<=n;i++)
	{
		if(!A1||!A2)
		{
			if(!A1) A1=i;
			else if(P[A1].second!=P[i].second) A2=i;
		}
		V[P[i].second].push_back(i);
	}
	for(int i=1;i<=n;i++)
	{
		if(!V[i].size()) continue;
		int s=V[i][0];
		for(int j=1;j<V[i].size();i++)
		{
			int x=V[i][j];if(P[x].first+P[s].first<=X)
			addedge(x,s), addedge(s,x);
		}
	}
	if(P[A1].first+P[A2].first<=Y&&A1&&A2) addedge(A1,A2), addedge(A2,A1);
	for(int i=1;i<=n;i++)
	{
		if(i==A1||i==A2) continue;
		if(P[i].second!=P[A1].second&&P[i].first+P[A1].first<=Y)
			addedge(i,A1), addedge(A1,i);
		if(P[i].second!=P[A2].second&&P[i].first+P[A2].first<=Y)
			addedge(i,A2), addedge(A2,i);
	} 
	ans=1; 
	for(int i=1;i<=n;i++)
	{
		if(vis[i]) continue;
		divi=1;int size=dfs(i,i);  
		 ans*=fac[size]; ans%=mod;
		 ans*=qpow(divi,mod-2); ans%=mod;
	} 
	cout<<ans<<endl;
	return 0;
}

