        }
    }



    vvi adj(N);
    int v0 = minc[cprs[0].second];
    int v1 = 0;
    if (cprs.size() > 1) v1 = minc[cprs[1].second];

    for (int i=0;i<N;i++) {
        // compare to smallest
        if (c[i] != cprs[0].second && w[i] + w[v0] <= Y) {
            adj[i].push_back(v0);
            adj[v0].push_back(i);
        }

        // compare to second smallest
        if (cprs.size() > 1) {
            if (c[i] != cprs[1].second && w[i] + w[v1] <= Y) {
                adj[i].push_back(v1);
                adj[v1].push_back(i);
            }
        }

        int vc = minc[c[i]];
        if (w[i] + w[vc] <= X) {
            adj[i].push_back(vc);
            adj[vc].push_back(i);
        }
    }

    // for (int i=0;i<N;i++) {
    //     cout << i << ": ";
    //     for (int v : adj[i]) cout << v << " ";
    //     cout << endl;
    // }

    vi comps(N, -1);
    vvi cvs;
    int ncomp = 0;
    for (int i=0; i<N; i++) {
        if (comps[i] == -1) {
            comps[i] = ncomp;
            queue<int> bfs;
            bfs.push(comps[i]);
            cvs.push_back(vi{comps[i]});

            while (!bfs.empty()) {
                int cur = bfs.front();
                bfs.pop();

                for (int nbr : adj[cur]) {
                    if (comps[nbr] == -1) {
                        comps[nbr] = ncomp;
                        cvs[ncomp].push_back(nbr);
                        bfs.push(nbr);
                    }
                }
            }

            ncomp++;
        }
    }

    modnum<MOD> ans = 1;

    for (auto& cv: cvs) {
        map<int, int> cmap;
        for (int v : cv) {
            cmap[c[v]]++;
