        modnum<MOD> term = modnum<MOD>::fact(cv.size());
        for (auto cnt : cmap) {
            // cout << cnt.first << " " << cnt.second << endl;
            term /= modnum<MOD>::fact(cnt.second);
        }
        // cout << term << endl;
        ans *= term;
    }

    cout << ans << endl;

    return 0;
}

