    } else if (n > 1) {
      while (b < c[i].size() && c[1][0] + c[i][b] <= y) ++b;
    }
    ca[i] = a, cb[i] = b;
    if (b) m = i;
  }
  n = 0;
  for (int i = 0; i < m; ++i) n += std::max(ca[i], cb[i]);
  std::vector<int64> fac(n + 1, 1), ifac(n + 1, 1);
  for (int i = 1; i <= n; ++i) {
    fac[i] = fac[i - 1] * i % mod;
    ifac[i] = pow_mod(fac[i], mod - 2);
  }
  int64 ret = fac[n];
  for (int i = 0; i < m; ++i) {
    ret = ret * ifac[std::max(ca[i], cb[i])] % mod;
  }
  printf("%lld\n", ret);
  return 0;
}

