const int N = 2e5 + 10, mod = 1e9 + 7;
long long n, s, d, w[N], cnt[N], fc[N], ifc[N], r[N];
bool mark[N];
vector<int> gr[N], c[N], mm;
pair<long long, long long> mn = {mod, mod};
long long ans = 1;
long long power(long long a, long long b) {
	if (!b)
		return 1;
	long long rtr = power(a, b / 2);
	if (b % 2)
		return rtr * rtr % mod * a % mod;
	return rtr * rtr % mod;
}
void getFC() {
	fc[0] = ifc[0] = 1;
	for (int i = 1; i < N - 2; i++) {
		fc[i] = 1ll * fc[i - 1] * i % mod;
		ifc[i] = 1ll * ifc[i - 1] * power(i, mod - 2) % mod;
	}
	return;
}
void dfs(int v) {
	mm.push_back(v);
	mark[v] = 1;
	for (auto u : gr[v])
		if (!mark[u])
			dfs(u);
	return;
}
