		sort(c[i].begin(), c[i].end(), [] (int x, int y) { return (w[x] < w[y]); });
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < c[i].size(); j++) {
			if (w[c[i][j]] + w[c[i][0]] <= s) {
				gr[c[i][0]].push_back(c[i][j]);
				gr[c[i][j]].push_back(c[i][0]);
			}
			int u = c[i][j], v = mn.second;
			if (w[u] + w[v] <= d) {
				gr[u].push_back(v);
				gr[v].push_back(u);
			}
		}
	}
	for (int i = 0; i < n; i++) {
		if (!mark[i]) {
			dfs(i);
			long long rtr = 1ll * fc[(int) mm.size()] % mod;
			for (auto u : mm) {
				rtr = 1ll * rtr * fc[cnt[r[u]]] % mod;
				cnt[r[u]]++;
				rtr = 1ll * rtr * ifc[cnt[r[u]]] % mod;
			}
			for (auto u : mm)
				cnt[r[u]] = 0;
			mm.clear();
			ans = 1ll * (ans * rtr) % mod;
		}
	}
	cout << ans % mod;
	return 0;
}

