typedef long long ll;typedef vector<int> vi;typedef pair<int,int> pi;const int inf = (int)1e9+1;const double INF = 1e12, EPS = 1e-9;


const int mod = 1e9 + 7;
const int MX = 210000;
int p[MX];
int root(int x){
	if(p[x] == x) return x;
	return p[x] = root(p[x]);
}
void merge(int a, int b){
	a = root(a); b = root(b);
	if(a != b) p[b] = a;
}
ll inv[MX], f[MX], invf[MX];
void calc(){
	inv[0] = inv[1] = f[0] = f[1] = invf[0] = invf[1] = 1;
	for (int i = 2; i < MX; i++){
		inv[i] = mod - mod / i * inv[mod % i] % mod;
		f[i] = f[i - 1] * i % mod;
		invf[i] = invf[i - 1] * inv[i] % mod;
	}
}
inline ll C(ll n, ll k){
	return f[n] * invf[k] % mod * invf[n - k] % mod;
}

int main(){
	calc();

	cin.tie(0); cin.sync_with_stdio(0);
	int n, x, y; cin >> n >> x >> y;
	vector<pi> col;
	rep(i, n){
		int a, b; cin >> a >> b;
		col.emplace_back(b, a);
	}
	sort(all(col));
	rep(i, n) p[i] = i;

	int lim = 1e8;

	rep(i, n){
		for(int j = i + 1; j < n && col[i].first + col[j].first <= x; j++){
			assert(--lim >= 0);
			if(col[i].second == col[j].second){
				merge(i, j);
				break;
			}
		}
		int found = -1;
		for(int j = i + 1; j < n && col[i].first + col[j].first <= y; j++){
			assert(--lim >= 0);
			if(col[i].second != col[j].second && col[j].second != found){
				merge(i, j);
				if(found >= 0) break;
				found = col[j].second;
			}
		}
	}
	map<int,map<int,int>> sz;
	rep(i, n) ++sz[root(i)][col[i].second];
	//dbg(sz);

	ll ans = 1;
	for(auto i : sz){
		int sum = 0;
		for(auto j : i.second) sum += j.second;
		for(auto j : i.second){
			ans *= C(sum, j.second);
			ans %= mod;
			sum -= j.second;
		}
	}
	cout << ans << endl;

	return 0;
}

