		by[i] = by[i - 1] * i;
		by[i] %= MOD;
	}
	long long int sum = 0;
	for (int i = 0; i < N; i++) {
		if (v[i].second <= R - m) {
			num[v[i].first]++;
			sum++;
		}
	}
	long long int ans = by[sum];
	for (int i = 0; i < N; i++) {
		ans *= power(by[num[i]], MOD - 2, MOD);
		ans %= MOD;
	}
	cout << ans << endl;
	return 0;
}

