inline int read()
{
	int num = 0, f = 1;
	char ch = getchar();
	while( !isdigit( ch ) ) { if(ch == '-') f = -1; ch = getchar(); }
	while( isdigit( ch ) ) num = (num << 3) + (num << 1) + (ch ^ 48), ch = getchar();
	return num * f;
}

inline int mpow(int a, int x)
{
	int ans = 1;
	while(x)
	{
		if(x & 1) ans = 1ll * ans * a % mod;
		a = 1ll * a * a % mod;
		x >>= 1;
	}
	return ans;
}

inline int find(int x) { return pa[x] == x ? x : pa[x] = find(pa[x]); }

inline void merge(int x, int y)
{
	x = find(x), y = find(y);
	if(x == y) return;
	pa[x] = y;
	sum[y] += sum[x];
}

int main()
{
	n = read();
	x = read(), y = read();

	w[0] = inf;
	fac[0] = 1;
	for(int i = 1; i <= n; i++) fac[i] = 1ll * fac[i - 1] * i % mod;
	inv[n] = mpow(fac[n], mod - 2);
	for(int i = n - 1; i >= 0; i--) inv[i] = 1ll * inv[i + 1] * (i + 1) % mod;

	for(int i = 1; i <= n; i++) pa[i] = i, sum[i] = 1;

	for(int i = 1; i <= n; i++)
	{
		c[i] = read(), w[i] = read();
