	{
		if(i != mn[ c[i] ] && w[i] + w[ mn[ c[i] ] ] <= x) merge(i, mn[ c[i] ]);
		if(c[i] != c[mn1] && w[i] + w[mn1] <= y) merge(i, mn1);
