		if(find(i) == root) t[ c[i] ] ++;

	int ans = 1;
	for(int i = 1; i <= n; i++)
		if(t[i]) ans = 1ll * ans * inv[ t[i] ] % mod;
	ans = 1ll * ans * fac[ sum[ find(mn1) ] ] % mod;
	printf("%d", ans);
	return 0;
}

