	RMQ rmq(n,INF);
	for(int i = 0;i < n;i++) mi[i] = INF;
	for(int i = 0;i < n;i++){
		cin >> c[i] >> w[i]; c[i]--;
		mi[c[i]] = min(w[i],mi[c[i]]);
	}
	for(int i = 0;i < n;i++){
		rmq.update(i,mi[i]);
		if(mi[c[i]] + w[i] <= x) w[i] = mi[c[i]];
	}
	for(int i = 0;i < n;i++){
		int ami = min(rmq.get(0,c[i]),rmq.get(c[i] + 1,n));
		if(ami + w[i] <= y){
			sum++;
			cnt[c[i]]++;
		}
	}
	for(int i = 0;i < n;i++){
		(ans *= nCr(sum,cnt[i])) %= MOD;
		sum -= cnt[i];
	}
	cout << ans << endl;
	return 0;
}

