int powmod(int a, int b){
	int ret = 1;
	while(b){
		if(b & 1) ret = 1ll * ret * a % mod;
		b >>= 1;
		a = 1ll * a * a % mod;
	}
	return ret;
}

void dfs(int u){
	++ cnt;
	++ map[c[u]];
	vis[u] = true;
	for(auto v : vec[u]){
