int64 lgpow(int64 a, int b) {
	if (b == 0) {
		return 1;
	}

	int64 x = lgpow(a, b>>1);
	if (b&1)
		return x*x%kMod*a%kMod;
	return x*x%kMod;
}

void solve() {

	int n, x, y;

	cin >> n >> x >> y;

	fac[0] = 1;
	for (int i = 1; i <= n; ++i) {
		fac[i] = fac[i-1] * i % kMod;	
	}
	for (int i = 0; i <= n; ++i) {
		invfac[i] = lgpow(fac[i], kMod-2);
	}

	B.resize(n+1);

	for (int i = 1; i <= n; ++i) {
		cin >> c[i] >> w[i];

		B[c[i]].push_back(w[i]);
	}

	for (int i = 1; i <= n; ++i) {
		sort(B[i].begin(), B[i].end());	
	}

	sort(B.begin(), B.end());

	int minb = 0;

	for (int i = 1; i <= n; ++i) {
		if (B[i].empty()) {
			continue;
		}
		if (minb == 0) {
			minb = i;
		}

		reach[i] = 1;

		for (int j = 1; j < B[i].size(); ++j) {
			if (B[i][0] + B[i][j] <= x) {
				reach[i] = j+1;
			}
		}

		// cout << i << " " << reach[i] << "\n";
	}

	int totalReach = minb;

	for (int i = 1; i <= n; ++i) {
		if (B[i].empty() || i == minb)
			continue;
		if (B[minb][0] + B[i][0] <= y) {
			totalReach = i;

			for (int j = reach[minb]; j < B[minb].size(); ++j) {
				if (B[i][0] + B[minb][j] <= y) {
					reach[minb] = j+1;
				}
			}
		}

		for (int j = 1; j < B[i].size(); ++j) {
			if (B[minb][0] + B[i][j] <= y) {
				if (j+1 > reach[i]) {
					reach[i] = j+1;
				}
			}
		}
	}

	// cout << totalReach << "\n";

	int64 ans = 1;
	int total = 0;

	for (int i = 1; i <= n; ++i) {
		if (i <= totalReach) {
			ans = ans * invfac[reach[i]] % kMod;
			total += reach[i];
		}
	}
	ans = ans * fac[total] % kMod;

	cout << ans << "\n";
}

