LL r(LL a, LL p) {
	if (p == 0) {
		return 1;
	}
	LL res = r(a, p / 2);
	res *= res;
	res %= mod;
	if (p & 1) {
		res *= a;
		res %= mod;
	}
	return res;
}

LL c(int n, int m) {
	if (m == 0) {
		return 1;
	}
	LL res = fact[n] * inv[m];
	res %= mod;
	return (res * inv[n - m]) % mod;
}

