    fact[0] = 1;
    for(int i = 1; i < 200010; i++) {
        fact[i] = 1LL * fact[i - 1] * i % mod;
    }
    for(int i = 0; i < 200010; i++) {
        invf[i] = inv(fact[i]);
    }

    scanf("%d %d %d", &N, &X, &Y);

    for(int i = 0; i < N; i++) {
        int c, w; scanf("%d %d", &c, &w);
