        lmn[i] = C[i].size()? C[i][0] : 1e9;
        if(i) lmn[i] = min(lmn[i], lmn[i - 1]);
    }
    for(int i = N - 1; i >= 0; i--) {
        rmn[i] = C[i].size()? C[i][0] : 1e9;
        if(i != N - 1) rmn[i] = min(rmn[i], rmn[i + 1]);
    }

    for(int i = 0; i < N; i++) {
        if(C[i].size() == 0) continue;

        int mn = 1e9;
        if(i) mn = min(mn, lmn[i - 1]);
        if(i != N - 1) mn = min(mn, rmn[i + 1]);

        while(C[i].size() > 1 && C[i].back() + mn > Y && C[i].back() + C[i][0] > X) {
            C[i].pop_back();
        }
    }

    int mn = 2e9, c = -1;
    for(int i = 0; i < N; i++) {
        if(C[i].size()) {
            if(mn > C[i][0]) {
                mn = C[i][0];
                c = i;
            }
        }
    }

    int ans = 1;
    int sum = 0;
    for(int i = 0; i < N; i++) {
        if(i == c) continue;
        if(C[i].size() && C[i][0] + mn <= Y) {
            ans = 1LL * ans * invf[ C[i].size() ] % mod;
            sum += C[i].size();
        }
    }
    if(sum) {
        ans = 1LL * ans * invf[ C[c].size() ] % mod;
        sum += C[c].size();
    }

    ans = 1LL * ans * fact[sum] % mod;
    printf("%d", ans);
}

