			for (auto t : ws[i]) cnt[i] += t + v <= X || t + ouv <= Y;
	}
	int ans = fac[std::accumulate(cnt + 1, cnt + 1 + n, 0)];
	for (int i = 1; i <= n; ++i) ans = mul(ans, inv[cnt[i]]);
	std::cout << ans << std::endl;
	return 0;
}

