int find_(vector<pii> &a, int k)
{
	int l = 0, r = a.size() - 1;
	while (l != r) {
		int mid = (l + r) >> 1;
		if (a[mid].first <= k) l = mid + 1;
		else r = mid;
	}
	return l - 1;
}

