ll upp(ll a, ll i){
if(i == 0)return 1;
if(i%2 ==0){
    ll h = upp(a,i/2);
    return (h*h)%big;
}
return (upp(a,i-1)*a)%big;
}

void setup(){

ll t = 1;

for(ll c1 = 0; c1 < 100001; c1++){
    FAC[c1] = t;
    INV[c1] = upp(t,big-2);
