	for (ll col=1;col<=n;col++) {
		denom=(denom*fact[colcnt[col]])%MOD;
	}
	ll numer=fact[all];
	ll final=(numer*mod_inv(denom, MOD))%MOD;
	printf("%lld\n",final);
}

