vector <int> adj[MAXN];
int vis[MAXN];

int64_t inv[MAXN];

void add_edge(int u, int v) {
    adj[u].push_back(v);
    adj[v].push_back(u);
}

void dfs(int u, int c) {
    vis[u] = c;
    for (int v : adj[u])
        if (vis[v] == -1)
            dfs(v, c);
}

int main() {
    cin >> n >> x >> y;
    for (int i = 0; i < n; i++) {
        cin >> c[i] >> w[i];
        c[i]--;
        vals[c[i]].push_back({w[i], i});
    }
    // swap => same connected component
    vector <pair <int, int>> group_mins;
    for (int i = 0; i < n; i++) {
        sort(vals[i].begin(), vals[i].end());
        // edges within each color group
        for (int j = 1; j < vals[i].size(); j++)
            if (vals[i][0].first + vals[i][j].first <= x)
                add_edge(vals[i][0].second, vals[i][j].second);
        if (vals[i].size() > 0)
            group_mins.push_back(vals[i][0]);
    }
    sort(group_mins.begin(), group_mins.end());
    for (int i = 0; i < n; i++) {
        // edges across color groups
        if (c[group_mins[0].second] == c[i]) {
            if (group_mins.size() > 1 && group_mins[1].first + w[i] <= y)
                add_edge(group_mins[1].second, i);
        }
        else {
            if (group_mins[0].first + w[i] <= y)
                add_edge(group_mins[0].second, i);
        }
    }

    int ngroups = 0;
    for (int i = 0; i < n; i++)
        vis[i] = -1;
    for (int i = 0; i < n; i++)
        if (vis[i] == -1)
            dfs(i, ngroups++);

    // MOD = i*q+r, i*q = -r, -q*r^{-1} = i^{-1}
    inv[1] = 1;
    for (int i = 2; i <= n; i++)
        inv[i] = (MOD - MOD / i * inv[MOD % i] % MOD) % MOD;

    unordered_map <int64_t, int> cnt;
    vector <int> group_cnt(ngroups);
    int64_t res = 1;
    for (int i = 0; i < n; i++) {
        res = res * ++group_cnt[vis[i]] % MOD;
        int64_t key = (1LL << 30) * vis[i] + c[i];
        res = res * inv[++cnt[key]] % MOD;
    }
    cout << res << endl;
}

