template<class T>
T modularExp(T base, T  exp)
{
	T answer(1);
	while (exp)
	{
		if (exp & 1)
			answer = answer * base % MOD;
		base = base * base % MOD;
		exp = exp >> 1;
	}
	return answer;
}

int N, X, Y;
