}

void prepare()
{
	fact[0] = 1;
	for (int i = 1; i < MAXN; i++)
		fact[i] = fact[i - 1] * i % MOD;

	inv[MAXN - 1] = modularExp(fact[MAXN - 1], MOD - 2) % MOD;
	for (int i = MAXN - 2; i >= 0; i--)
		inv[i] = inv[i + 1] * (i + 1) % MOD;
	//assert(inv[1] == 2);
}

void DFS(int cur)
{
	vist[cur] = true;
	totCnt++, colCnt[C[cur]]++;
	finalBlk.push_back(C[cur]);

	for(int to : Adj[cur])
		if(!vist[to])
			DFS(to);

