int union_tree[300000];
int union_find(int now) {	
	if (union_tree[now] == now) return now;
	return union_tree[now] = union_find(union_tree[now]);
}
void union_merge(int a, int b) {
	a = union_find(a);
	b = union_find(b);
	union_tree[a] = b;
}
int color[300000];
int weight[300000];
int cnt[300000];
int minnest_color[300000];
long long mae[300000];
long long gyaku[300000];
long long inv(long long now) {
	long long hoge = MAX_MOD - 2LL;
	long long ans = 1;
	while (hoge != 0) {
		if (hoge % 2 == 1) {
			ans *= now;
			ans %= MAX_MOD;
		}
		now *= now;
		now %= MAX_MOD;
		hoge /= 2;
	}
	return ans;
}
vector<int> colors_find[300000];
int main() {
	int n, x, y;
	cin >> n >> x >> y;
	mae[0] = 1;
	gyaku[0] = 1;
	for (long long i = 1; i <= 200000; ++i) {
		mae[i] = i * mae[i - 1];
		mae[i] %= MAX_MOD;
		gyaku[i] = inv(mae[i]);
	}
	REP(i, n) {
		cin >> color[i] >> weight[i];
		colors_find[color[i]].push_back(i);
		union_tree[i] = i;
		minnest_color[i+1] = -1;
	}
	int now_min_color = 0;
	REP(i, n) {
		if (weight[i] < weight[now_min_color]) {
			now_min_color = i;
		}
		if (minnest_color[color[i]] == -1 || weight[i] < weight[minnest_color[color[i]]]) {
			minnest_color[color[i]] = i;
		}
	}
	REP(i, n) {
		if (weight[i] + weight[now_min_color] <= y) {
			union_merge(i, now_min_color);
		}
		if (weight[i] + weight[minnest_color[color[i]]] <= x) {
			union_merge(i, minnest_color[color[i]]);
		}
	}
	REP(i, n) {
		cnt[union_find(i)]++;
	}
	long long ans = 1;
	REP(i, n) {
		ans *= mae[cnt[i]];
		ans %= MAX_MOD;
		cnt[i] = 0;
	}
	for (int i = 1; i <= n; ++i) {
		REP(q, colors_find[i].size()) {
			cnt[union_find(colors_find[i][q])]++;
		}
		REP(q, colors_find[i].size()) {
			ans *= gyaku[cnt[union_find(colors_find[i][q])]];
			ans %= MAX_MOD;
			cnt[union_find(colors_find[i][q])] = 0;
		}
	}
	cout << ans << endl;
}

