void sadd(int &a, int b)
{
	a += b;
	if (a >= MOD) a -= MOD;
}
int add(int a, int b)
{
	sadd(a, b);
	return a;
}
int mul(int a, int b)
{
	return (a * 1LL * b) % MOD;
}
int fpow(int x, long long n)
{
	if (n == 0) return 1;
	int a = fpow(x, n >> 1);
	a = mul(a, a);
	if (n & 1) a = mul(a, x);
	return a;
}
int rev(int x)
{
	return fpow(x, MOD - 2);
}
int divi(int a, int b)
{
	return mul(a, rev(b) );
}

const int N = (int) 2e5 + 100;
vector <int> ws[N];
int fact[N], rfact[N], ri[N];


void init()
{
	fact[0] = rfact[0] = 1;
	for (int i = 1; i < N; i++)
	{
		fact[i] = mul(i, fact[i - 1] );
		if (i == 1) ri[i] = 1;
		else ri[i] = MOD - mul(MOD / i, ri[MOD % i] );
		rfact[i] = mul(rfact[i - 1], ri[i] );
	}
}

int X, Y;

int C(int n, int k)
{
	if (k < 0 || k > n) throw;
//	eprintf("n = %d, k = %d\n", n, k);
//	eprintf("fact[n] = %d, rfact[k] = %d, rfact[n - k] = %d\n", fact[n], rfact[k], rfact[n - k] );
	return mul(fact[n], mul(rfact[k], rfact[n - k] ) );
}

int solveColor(vector <int> &v, int kmove)
{
	return 1;
	int pos = kmove;
	while (pos < (int) v.size() && v[pos] + v[0] <= X) pos++;
	return C(pos, kmove);
}

bool cmp(const vector <int> &a, const vector <int> &b)
{
	return a[0] < b[0];
}


int main(int,  char **)
{
#ifdef LOCAL
