	for (int i = 0; i < n; i++)
	{
		int c, w;
		scanf("%d%d", &c, &w);
		c--;
		ws[c].push_back(w);
	}

	int m = 0;
	for (int i = 0; i < n; i++)
		if (!ws[i].empty() )
			ws[m++] = ws[i];

	for (int i = 0; i < m; i++)
		sort(ws[i].begin(), ws[i].end() );

	if (m == 1)
	{
		int ans = solveColor(ws[0], 0);
		printf("%d\n", ans);
		return 0;
	}

	int pos = min_element(ws, ws + m, cmp) - ws;
	swap(ws[0], ws[pos] );
	pos = min_element(ws + 1, ws + m, cmp) - ws;
	swap(ws[1], ws[pos] );

	vector <int> ks;

	int ans = 1;
	for (int i = 0; i < m; i++)
	{
		int oth = 0;
		if (i == 0) oth = 1;
		int k = 0;
		while (k < (int) ws[i].size() && ws[i][k] + ws[oth][0] <= Y) k++;
		ks.push_back(k);
		ans = mul(ans, solveColor(ws[i], k) );
	}
	int sumk = 0;
	for (int k : ks)
		sumk += k;
	for (int k : ks)
	{
		ans = mul(ans, C(sumk, k) );
//		eprintf("C(%d, %d) = %d\n", sumk, k, C(sumk, k) );
		sumk -= k;
	}
	printf("%d\n", ans);

	return 0;
