using namespace std;
const int N = 2e5 + 11;
const int mod = 1e9 + 7;
int fac[N], inv[N];
int n, x, y, tot, fa[N], tong[N];
struct ddd{
    int c, w;
    bool operator < (const ddd &X) const{
        if(c != X.c)return c < X.c;
        return w < X.w;
    }
}b[N];
int find(int x){
    return fa[x] == x ? x : fa[x] = find(fa[x]);
}
void merge(int x, int y){
    int fx = find(x), fy = find(y);
    if(fx == fy)return ;
    fa[fx] = fy;
}
int main(){
    //freopen("agc012d.in", "r", stdin);
    inv[0] = inv[1] = fac[0] = fac[1] = 1;
    for(int i = 2;i <= 2e5; i++){
        fac[i] = 1LL * fac[i-1] * i % mod;
        inv[i] = (mod - 1LL * mod / i * inv[mod%i] % mod);
    }
    for(int i = 1;i <= 2e5; i++)inv[i] = 1LL * inv[i-1] * inv[i] % mod;
    cin>>n>>x>>y;
    int pmi = 1;
    for(int i = 1;i <= n; i++){
        fa[i] = i;
        scanf("%d%d", &b[i].c, &b[i].w);
    }
    sort(b + 1, b + 1 + n);
    for(int i = 1;i <= n; i++)if(b[i].w < b[pmi].w)pmi = i;
    for(int i = 1;i <= n; i++){
        if(b[i].c == b[pmi].c)continue;
        if(b[i].w + b[pmi].w <= y)merge(i, pmi);
    }
    int mi, smi = 1;
    for(int i = 1;i <= n; i++){
        if(b[i].c != b[i-1].c)mi = i;
        else{
            if(b[i].w + b[mi].w <= x)merge(i, mi);
        }
        if(b[i].c != b[pmi].c && b[i].w < b[smi].w)smi = i;
    }
    for(int i = pmi + 1;i <= n && b[i].c == b[i-1].c; i++)if(b[i].w + b[smi].w <= y)merge(i, smi);
    for(int i = 1;i <= n; i++){
        if(find(i) == find(pmi))tong[b[i].c]++;
    }
    int ans = 0, pai = 1;
    for(int i = 1;i <= n; i++){
        if(!tong[i])continue;
        ans += tong[i];
        pai = 1LL * pai * inv[tong[i]] % mod;
        //printf("i=%d tong=%d\n", i, tong[i]);
    }
    ans = 1LL * fac[ans] * pai % mod;
    cout<<ans<<endl;
    return 0;
}

