intl fpm(intl a, intl b) {
	if (!a) return 0LL;
	intl ans = 1LL;
	for (; b; b >>= 1){
		if (b & 1) ans *= a, ans %= Mo;
		a *= a; a %= Mo;
	}
	return ans;
}

intl C(int a, int b) {
	return fac[a] * inv[b] % Mo * inv[a - b] % Mo;
}

int main() {
