            std::sort(cv[i].begin(), cv[i].end(), 
                [](const int a, const int b) { return w[a] < w[b]; }
            );

            for (int j = 1; j < cv[i].size(); j++) {
                if (w[cv[i][0]] + w[cv[i][j]] <= X) {
