		for(int k = i; k <= j; k ++)
			if(!rec) break;
			else if(i != rec && P[k].w + P[rec].w <= Y) E1.add(k, rec);  
		if(i == 1) rec = j + 1; i = j; 
	}
	for(int i = 1; i <= n; i ++) 
		if(!vis[i]) 
		{
			cnt = 0, tot = 0, dfs(i);
			ans = ans * fac[cnt] % mod;
			for(int j = 1; j <= tot; j ++) C[P[S[j]].c] --;
		}
	printf("%lld\n", ans);
	return 0;
}

