int fsp(int bs, int p) {
  int rt = 1;
  while (p) {
    if (p & 1) rt = 1ll * rt * bs % mod;
    bs = 1ll * bs * bs % mod, p >>= 1;
  }
  return rt;
}

int fac[maxn], caf[maxn];
void init(int n) {
  fac[0] = 1;
  for (int i = 1; i <= n; ++i) fac[i] = 1ll * i * fac[i - 1] % mod;
  caf[n] = fsp(fac[n], mod - 2);
  for (int i = n; i >= 1; --i) caf[i - 1] = 1ll * i * caf[i] % mod;
}

