int qp(int x, int y) {
    int z = 1;
    for (; y; y >>= 1, x = 1LL * x * x % P) {
        if (y & 1) z = 1LL * z * x % P;
    }
    return z;
}

int main() {
    scanf("%d %d %d", &n, &X, &Y);
    for (int i = 1, x, y; i <= n; i++) {
        scanf("%d %d", &x, &y), col[i] = x;
        V[x].push_back(y), C[x].push_back(i);
    }
    for (int i = fact[0] = finv[0] = 1; i <= n; i++) {
        fact[i] = 1LL * i * fact[i - 1] % P;
        finv[i] = qp(fact[i], P - 2);
    }
    int p1 = 0, p2 = 0;
    for (int i = 1; i <= n; i++) if (!V[i].empty()) {
        sort(V[i].begin(), V[i].end());
        if (!p1) p1 = i;
        else if (!p2) p2 = i;
        if (p1 && p2) {
            int j = i;
            if (V[j][0] < V[p1][0]) swap(j, p1);
            if (V[j][0] < V[p2][0]) swap(j, p2);
        }
    }
    auto add = [&](int u, int v) {
        G[u].push_back(v), G[v].push_back(u);
    };
    for (int i = 1; i <= n; i++) if (!V[i].empty()) {
        for (int j = 1; j < V[i].size(); j++) {
            if (V[i][0] + V[i][j] <= X) add(C[i][0], C[i][j]);
        }
        if (p1 && i != p1) {
            for (int j = 0; j < V[i].size(); j++) {
                if (V[p1][0] + V[i][j] <= Y) add(C[p1][0], C[i][j]);
            }
        }
        if (p2 && i == p1) {
            for (int j = 1; j < V[i].size(); j++) {
                if (V[p2][0] + V[i][j] <= Y) add(C[p2][0], C[i][j]);
            }
        }
    }
    int ans = 1;
    for (int i = 1; i <= n; i++) if (!vis[i]) {
        vector<int> V;
        function<void(int)> dfs = [&](int v) {
            if (!cnt[col[v]]) V.push_back(col[v]);
