		mn[i]=inf;
		fac[i]=(fac[i-1]*i)%mod;
	}
	ny[n]=ksm(fac[n],mod-2);
	for(long long i=n;i>=1;--i) ny[i-1]=(ny[i]*i)%mod;
	for(long long i=1;i<=n;++i) mn[col[i]]=min(mn[col[i]],val[i]);
