struct edge
{
	int cnp, to[maxn], last[maxn], head[maxn];
	edge() { cnp = 2; }
	void add(int u, int v)
	{
		to[cnp] = v, last[cnp] = head[u], head[u] = cnp ++;
		to[cnp] = u, last[cnp] = head[v], head[v] = cnp ++;
	}
}E1;

struct node
{
	int c, w;
	friend bool operator <(const node& a, const node& b)
	{ 
		if(a.c == b.c) return a.w < b.w; 
		if(W[a.c] != W[b.c]) return W[a.c] < W[b.c]; 
		return a.c < b.c;
	}
}P[maxn];

void dfs(int u)
{
	vis[u] = 1; cnt ++; C[P[u].c] ++;
	ans = ans * inv[C[P[u].c]] % mod;
	S[++ tot] = u;
	for(int i = E1.head[u]; i; i = E1.last[i])
	{
		int v = E1.to[i];
		if(vis[v]) continue;
		dfs(v);
	}
}

signed main()
{
	n = read(), X = read(), Y = read();
	fac[0] = 1; inv[0] = inv[1] = 1; 
	for(int i = 1; i < maxn; i ++) fac[i] = fac[i - 1] * i % mod;
	for(int i = 2; i < maxn; i ++) inv[i] = (mod - mod / i) * inv[mod % i] % mod;

	for(int i = 1; i <= n; i ++) W[i] = INF;
	for(int i = 1; i <= n; i ++) 
	{
		P[i].c = read(), P[i].w = read();
		W[P[i].c] = min(W[P[i].c], P[i].w);
	}
	sort(P + 1, P + 1 + n);
	for(int i = 1, j = 1; i <= n; i ++, j ++)
	{
		while(j < n && P[j + 1].c == P[i].c) j ++;
		for(int k = i + 1; k <= j; k ++)
			if(P[k].w + P[i].w <= X) E1.add(i, k);
			else break;

		for(int k = i; k <= j; k ++) 
			if(i != 1 && P[k].w + P[1].w <= Y) E1.add(k, 1);
		for(int k = i; k <= j; k ++)
			if(!rec) break;
			else if(i != rec && P[k].w + P[rec].w <= Y) E1.add(rec, k);	
		if(i == 1 && j + 1 <= n) rec = j + 1; i = j; 
	}

	for(int i = 1; i < rec; i ++)
		if(P[i].w + P[rec].w <= Y) E1.add(rec, i);
		else break; 

	for(int i = 1; i <= n; i ++) 
		if(!vis[i]) 
		{
			cnt = 0, tot = 0, dfs(i);
			ans = ans * fac[cnt] % mod;
			for(int j = 1; j <= tot; j ++) C[P[S[j]].c] --;
		}
	printf("%lld\n", ans);
	return 0;
}

