#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005, mod = 1e9+7;

inline int read()
{
	int a = 0, c;
	do c = getchar(); while (!isdigit(c));
	while (isdigit(c)) {
		a = a*10+c-'0';
		c = getchar();
	}
	return a;
}

struct point {
	int w, id;
	friend bool operator < (const point &a, const point &b)
	{ return a.w < b.w; }
};

int n, x, y, c[MAXN], w[MAXN];
vector<point> v[MAXN];
int fa[MAXN];
inline int findf(int nd)
{ return fa[nd]?fa[nd]=findf(fa[nd]):nd; }
inline void link(int u, int v)
{
	u = findf(u), v = findf(v);
	if (u != v) fa[u] = v;
}
map<int,int> st[MAXN];
int siz[MAXN];

int fac[MAXN], ifac[MAXN], inv[MAXN];

int main()
{
	n = read(), x = read(), y = read();
	inv[1] = 1;
	for (int i = 2; i <= n; i++)
		inv[i] = (mod-(long long)mod/i*inv[mod%i]%mod)%mod;
	fac[0] = ifac[0] = 1;
	for (int i = 1; i <= n; i++)
		fac[i] = (long long)fac[i-1]*i%mod, ifac[i] = (long long)ifac[i-1]*inv[i]%mod;
	for (int i = 1; i <= n; i++) {
		c[i] = read(), w[i] = read();
		v[c[i]].push_back({w[i], i});
	}
	for (int i = 1; i <= n; i++) sort(v[i].begin(), v[i].end());
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j < v[i].size(); j++) {
			if (v[i][j].w+v[i][0].w <= x)
				link(v[i][j].id, v[i][0].id);
			else break;
		}
	}
	int pos = -1;
	for (int i = 1; i <= n; i++)
		if (!v[i].empty() && (pos == -1 || v[i][0] < v[pos][0]))
			pos = i;
	assert(pos != -1);
	int min_weight = 1e9;
	for (int i = 1; i <= n; i++) {
		if (i == pos) continue;
		for (int j = 0; j < v[i].size(); j++) {
			if (v[i][j].w+v[pos][0].w <= y) {
				link(v[i][j].id, v[pos][0].id);
				min_weight = min(min_weight, v[i][j].w);
			}
			else break;
		}
	}
	for (int i = 1; i < v[pos].size(); i++) {
		if (v[pos][i].w + min_weight <= y) link(v[pos][i].id, v[pos][0].id);
		else break;
	}
	for (int i = 1; i <= n; i++) {
		int f = findf(i);
		st[f][c[i]]++;
		siz[f]++;
	}
	int ans = 1;
	for (int i = 1; i <= n; i++)
		if (fa[i] == 0) {
			ans = (long long)ans*fac[siz[i]]%mod;
			for (auto j : st[i]) 
				ans = (long long)ans*ifac[j.second]%mod;
		}
	cout << ans << endl;
	return 0;
}

