const ll M = 1000000007;
ll modpow(ll x,ll k){
	if(k == 0)return 1;
	ll ret = modpow(x,k/2);
	ret *= ret; ret %= M;
	if(k&1LL){
		ret *= x; ret %= M;
	}
	return ret;
}
ll FAC[200010];
void init_FAC(){
	FAC[0] = 1;
	rep1(i,200000){
		FAC[i] = FAC[i-1]*i;
		FAC[i] %= M;
	}
}

int main(){
	init_FAC();
	static int n,x,y;
	static int c[200010],w[200010];
	scanf("%d%d%d",&n,&x,&y);
	rep1(i,n){
		scanf("%d%d",&c[i],&w[i]);
	}

	static vector<int> vec[200010];
	rep1(i,n){
		vec[c[i]].pb(i);
	}
	static int minw[200010];
	rep1(i,n){
		minw[i] = INF;
		for(int id: vec[i]){
			minw[i] = min( minw[i] , w[id] );
		}
	}

	P minc[2] = {P(INF,INF),P(INF,INF)};
	rep1(i,n){
		if(minc[1] > P(minw[i],i)){
			minc[1] = P(minw[i],i);
			if(minc[0] > minc[1]){
				swap(minc[0],minc[1]);
			}
		}
	}

	vector<int> vec_;
	rep1(i,n){
		if(vec[i].size() == 0)continue;
		int mw_ex = minc[0].fr;
		if(minc[0].sc == i)mw_ex = minc[1].fr;
		if(mw_ex+minw[i] > y)continue;
		int cnt = 0;
		for(int id: vec[i]){
			if(w[id]+mw_ex <= y || w[id]+minw[i] <= x)cnt ++;
		}
		vec_.pb(cnt);
	}

	ll ret = 1;
	ll sum = 0;
	for(int i: vec_){
		sum += i;
		ret *= modpow(FAC[i],M-2);
		ret %= M;
	}
	ret *= FAC[sum];
	ret %= M;
	cout << ret << endl;
}

