using namespace std;

typedef pair<int, int> pii;

const int mod = 1e9 + 7;
const int MN = 200010;

int exp(int x, int n) {
    int ret = 1;
    while(n) {
        if(n & 1) ret = 1LL * ret * x % mod;
        x = 1LL * x * x % mod;
        n >>= 1;
    }
    return ret;
}
int inv(int x) {
    return exp(x, mod - 2);
}
int fact[MN], invf[MN];

int N, X, Y;
pii P[MN];
vector<int> V[MN];

int main() {
    fact[0] = 1;
    for(int i = 1; i < MN; i++) {
        fact[i] = 1LL * fact[i - 1] * i % mod;
    }
    for(int i = 0; i < MN; i++) {
        invf[i] = inv(fact[i]);
    }

    scanf("%d %d %d", &N, &X, &Y);

    int mn1 = 1e9 + 2, p1 = -1;
    int mn2 = 1e9 + 2, p2 = -1;
    for(int i = 0; i < N; i++) {
        int c, w; scanf("%d %d", &c, &w);
        c--;

        P[i] = {c, w};
        V[c].push_back(w);

        if(mn1 > w) {
            if(c != p1) mn2 = mn1, p2 = p1;
            mn1 = w, p1 = c;
        }
        else if(mn2 > w) {
            if(c != p1) mn2 = w, p2 = c;
        }
    }
    for(int i = 0; i < N; i++) {
        sort(V[i].begin(), V[i].end());
    }

    vector<int> C;
    int tot = 0;
    for(int i = 0; i < N; i++) {
        if(V[i].size() == 0) continue;

        int mn = i == p1? mn2 : mn1;
        if(mn + V[i][0] > Y) {
            continue;
        }

        int cnt = 1;
        for(int j = 1; j < V[i].size(); j++) {
            if(V[i][j] + mn > Y && V[i][j] + V[i][0] > X) break;
            cnt++;
        }
        tot += cnt;
        C.push_back(cnt);
    }

    int ans = fact[tot];
    for(int i = 0; i < C.size(); i++) ans = 1LL * ans * invf[ C[i] ] % mod;
    printf("%d", ans);
}

