using namespace std;
typedef long long LL;
const int N = 1e5 + 5;
const LL MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;
int n;
LL c[N], w[N];
LL cc[N];
int cp[N];
LL x, y;
LL fac[N];
LL pow_mod(LL a, LL b, LL p){//a的b次方求余p 
    LL ret = 1;
    while(b){
        if(b & 1) ret = (ret * a) % p;
        a = (a * a) % p;
        b >>= 1;
    }
    return ret;
}
LL Fermat(LL a, LL p){//费马求a关于b的逆元 
        return pow_mod(a, p-2, p);
}
bool judge(int p, int nn){
	if(p == nn) return false;
	if(c[p] == c[nn]) return w[p] + w[nn] <= x;
	return w[p] + w[nn] <= y;
}
int main(){
	ios::sync_with_stdio(false);
	fac[0] = 1;
	for(int i = 1; i < N; ++ i) fac[i] = (fac[i-1]*i) % MOD;
	cin >> n >> x >> y;
	for(int i = 0; i < n; ++ i){
		cin >> c[i] >> w[i];
	}
	int p1 = min_element(c, c+n) - c, p2 = -1;
	for(int i = 0; i < n; ++ i){
		if(c[p1] == c[i]) continue;
		if(p2 == -1 || w[p2] > w[i]) p2 = i;
	}
	memset(cp, -1, sizeof(cp));
	for(int i = 0; i < n; ++ i){
		if(cp[c[i]] == -1 || w[cp[c[i]]] > w[i]) cp[c[i]] = i;
	}
	for(int i = 0; i < n; ++ i){
		if(judge(p1, i) || ~p2 && judge(p2, i) || judge(cp[c[i]], i)) ++ cc[c[i]];
	}
	LL ans = 0, tmp = 1;
	for(int i = 0; i < N; ++ i){
		if(cc[i] && (i == c[p1] || w[p1] + w[cp[i]] <= y)){
			ans = (ans + cc[i]) % MOD;
			tmp = (tmp * fac[cc[i]]) % MOD;
		}
	}
	ans = fac[ans] % MOD;
	ans = ans * Fermat(tmp, MOD) % MOD;
	cout << ans << endl;
}

