template<int um> class UF {
public:
	vector<int> par;
	UF() { par = vector<int>(um, 0); rep(i, 0, um) par[i] = i; }
	int operator[](int x) { return par[x] == x ? x : par[x] = operator[](par[x]); }
	void operator()(int x, int y) { x = operator[](x); y = operator[](y); if (x != y) par[x] = y; }
};
int mod = 1000000007;
int add(int x, int y) { return (x += y) >= mod ? x - mod : x; }
int mul(int x, int y) { return 1LL * x * y % mod; }
int modpow(int a, long long b) {
	int ret = 1;
	while (b > 0) {
		if (b & 1) ret = 1LL * ret * a % mod;
		a = 1LL * a * a % mod; b >>= 1;
	}
	return ret;
}
int modinv(int a) { return modpow(a, mod - 2); }

int fac[201010], ifac[201010];
void initfac() {
	fac[0] = ifac[0] = 1;
	rep(i, 1, 201010) fac[i] = 1LL * i * fac[i - 1] % mod;
	rep(i, 1, 201010) ifac[i] = modinv(fac[i]);
}
//-----------------------------------------------------------------------------------
int N, X, Y, C[201010], W[201010];
UF<201010> uf;
void naive_merge() {
	rep(a, 0, N) rep(b, a + 1, N) {
		if (C[a] == C[b] && W[a] + W[b] <= X) uf(a, b);
		if (C[a] != C[b] && W[a] + W[b] <= Y) uf(a, b);
	}
}
//-----------------------------------------------------------------------------------
void optimized_merge() {
	map<int, vector<pair<int, int>>> color;
	rep(i, 0, N) color[C[i]].push_back({ W[i], i });
	for (auto& g : color) sort(g.second.begin(), g.second.end());

	// same color
	for (auto g : color) {
		auto v = g.second;
		rep(i, 1, v.size()) if (v[0].first + v[i].first <= X) uf(v[0].second, v[i].second);
	}

	// different color
	vector<int> order;
	for (auto g : color) order.push_back(g.first);
	sort(order.begin(), order.end(), [&](int a, int b) {
		return color[a][0].first < color[b][0].first;
	});
	rep(i, 0, order.size() - 1) {
		auto v1 = color[order[i]];
		auto v2 = color[order[i + 1]];

		// v1[0] -> v2[?]
		rep(j, 0, v2.size()) if (v1[0].first + v2[j].first <= Y) uf(v1[0].second, v2[j].second);

		// v2[0] -> v1[?]
		rep(j, 0, v1.size()) if (v2[0].first + v1[j].first <= Y) uf(v2[0].second, v1[j].second);
	}
	rep(i, 1, order.size()) {
		auto v1 = color[order[0]];
		auto v2 = color[order[i]];
		if (v1[0].first + v2[0].first <= Y) uf(v1[0].second, v2[0].second);
	}
}
//-----------------------------------------------------------------------------------
int count() {
	map<int, vector<int>> group;
	rep(i, 0, N) group[uf[i]].push_back(i);

	int res = 1;
	for (auto g : group) {
		auto v = g.second;

		int com = fac[v.size()];

		map<int, int> cnt;
		for (int i : v) cnt[C[i]]++;
		for (auto p : cnt) com = mul(com, ifac[p.second]);

		res = mul(res, com);
	}

	return res;
}
//-----------------------------------------------------------------------------------
int main() {
	initfac();
	cin >> N >> X >> Y;
	rep(i, 0, N) scanf("%d%d", &C[i], &W[i]);

	//naive_merge();
	optimized_merge();
	cout << count() << endl;
}

