#include <bits/stdc++.h>
using namespace std;

const int N = 201000, MOD = 1e9 + 7;

namespace {
  int Mul(int x, int y) { return 1LL * x * y % MOD; }
  int Kissme(int x, int y) {
    int c = 1;
    while(y) {
      if(y & 1) c = Mul(c, x);
      x = Mul(x, x);
      y >>= 1;
    }
    return c;
  }
}

struct Node {
  int c, w;

  bool operator < (const Node &rhs) const {
    return c != rhs.c ? c < rhs.c : w < rhs.w;
  }
}a[N];

int fac[N], inv[N], n, X, Y, tmp[N], fa[N], siz[N];
map<int, int> mp;

void Init(void) {
  fac[0] = 1;
  for(int i = 1; i <= n; i++)
    fac[i] = Mul(fac[i - 1], i);
  inv[n] = Kissme(fac[n], MOD - 2);
  for(int i = n - 1; i >= 0; i--)
    inv[i] = Mul(inv[i + 1], i + 1);
}

int C(int x, int y) {
  return Mul(Mul(fac[x], inv[y]), inv[x - y]);
}

int Find(int x) {
  return fa[x] == x ? x : fa[x] = Find(fa[x]);
}

void Merge(int x, int y) {
  x = Find(x), y = Find(y);
  fa[y] = x;
  siz[x] += siz[y];
}

int main(void) {
  scanf("%d%d%d", &n, &X, &Y);
  Init();
  for(int i = 1; i <= n; i++) {
    scanf("%d%d", &a[i].c, &a[i].w);
  }
  sort(a + 1, a + n + 1);
  for(int i = 1; i <= n; i++) {
    if(a[i].c != a[i - 1].c)
      mp[a[i].w]++;
    fa[i] = i, siz[i] = 1;
    //cerr << i << " :: " << a[i].c << " " << a[i].w << endl; 
  }
  for(int i = 1; i <= n; i++) {
    int j = i;
    while(a[j + 1].c == a[j].c) j++;
    for(int k = i; k <= j; k++)
      tmp[k] = a[k].w;
    if(!--mp[a[i].w]) mp.erase(a[i].w);
    int lim = max(X - a[i].w, Y - mp.begin()->first);
    int ind = upper_bound(tmp + i + 1, tmp + j + 1, lim) - tmp - 1;
    //cerr << i << " " << ind << endl;
    for(int k = i + 1; k <= ind; k++)
      Merge(i, k);
    mp[a[i].w]++;
    i = j;
  }
  int lim = mp.begin()->first, root, Ans = 1, all = 0;
  for(int i = 1; i <= n; i++)
    if(fa[i] == i && a[i].w == lim) {
      root = i, all = siz[i];
      break;
    }
  lim = Y - lim;
  for(int i = 1; i <= n; i++)
    if(fa[i] == i && a[i].w <= lim && i != root) {
      //cerr << " " << all + siz[i] << endl;
      Ans = Mul(Ans, C(all + siz[i], all));
      all += siz[i];
    }
  cout << Ans << endl;
}

