int C(int n, int k) {
	return mul(fact[n], mul(inv_fact[n - k], inv_fact[k]));
}

struct DSU {
	vi par;

	DSU(int n = 0) {
		par.assign(n, -1);
	}

	int get(int x) {
		return par[x] < 0 ? x : par[x] = get(par[x]);
	}

	void unite(int x, int y) {
		x = get(x);
		y = get(y);
		if  (x == y) {
			return;
		}
		if  (-par[x] < -par[y]) {
			swap(x, y);
		}
		par[x] += par[y];
		par[y] = x;
	}
};

vii ws[MAXN];

int get(vi cs) {
	sort(all(cs));

	int ans = 1;
	int have = 0;
	for (int i = 0, j = 0; i < sz(cs); i = j) {
		while (j < sz(cs) && cs[i] == cs[j]) {
			++j;
		}

		int len = j - i;
		ans = mul(ans, C(have + len, len));
		have += len;
	}

	return ans;
}

