	vii cs;
	forn(c, n) {
		if  (!ws[c].empty()) {
			cs.pb(mp(ws[c].front().fst, c));
		}
	}
	sort(all(cs));

	forn(i, min(2, sz(cs))) {
		int C = cs[i].snd;
		int W = cs[i].fst;
		forn(c, n) {
			if  (c == C) {
				continue;
			}
			forn(i, sz(ws[c])) {
