        } else if (col_min[i] < g_min2.first) {
            g_min2 = std::make_pair(col_min[i], i);
        }
    }
    for (int i = 0; i < n; ++i) {
        bool conn = false;
        if (w[i] + col_min[c[i]] <= x) conn = true;
        else {
            int g_min = (c[i] == g_min1.second ? g_min2.first : g_min1.first);
            if (g_min + col_min[c[i]] <= y && w[i] + g_min <= y) conn = true;
        }
        if (conn) ++col_ct[c[i]];
    }
    int g_winner = g_min1.second;
    col_conn[g_winner] = true; tot += col_ct[g_winner];
    for (int i = 0; i < n; ++i) if (i != g_winner) {
        if (g_min1.first + col_min[i] <= y) {
            col_conn[i] = true; tot += col_ct[i];
        }
    }

    preprocess_binomials();
