using namespace std;

struct Mod
{
    static const auto P = int(1e9+7);
    long long k;

    Mod() = default;
    Mod(const long long k) : k(k%P) {}
};

Mod operator*(const Mod a, const Mod b) { return a.k * b.k; }
Mod& operator*=(Mod& a, const Mod b) { return a = a*b; }
Mod power(const Mod a, const int k)
{
    if (k == 0) return 1;
    else if (k % 2 == 0) return power(a*a, k/2);
    else return a * power(a*a, k/2);
}
Mod inverse(const Mod a) { return power(a, Mod::P-2); }

int main()
{
    int N, X, Y; cin >> N >> X >> Y;

    struct Ball { int index, color, weight; };
    auto balls = vector<Ball>(N);
    for (auto i = 0; i < N; i++)
    {
        int c, w; cin >> c >> w;
        balls[i] = {i, c, w};
    }

    const auto infinity = numeric_limits<int>::max();
    auto global_min_weight = infinity, global_second_weight = infinity;
    auto global_min_color = 0;

    auto by_color = map<int, vector<Ball>>();
    for (auto i = 0; i < N; i++)
        by_color[balls[i].color].push_back(balls[i]);
    for (auto& kv : by_color)
    {
        auto min_weight = infinity;
        for (const auto b : kv.second)
            min_weight = min(min_weight, b.weight);

        for (const auto b : kv.second)
            if (min_weight + b.weight <= X)
                balls[b.index].weight = min_weight;

        if (min_weight < global_min_weight)
        {
            global_second_weight = global_min_weight;
            global_min_weight = min_weight;
            global_min_color = kv.first;
        }
        else if (min_weight < global_second_weight)
            global_second_weight = min_weight;
    }

    auto counts = map<int, int>();
    auto total = 0;
    for (const auto b : balls)
    {
        const auto x = b.color == global_min_color ? global_second_weight : global_min_weight;
        if (b.weight + x <= Y)
        {
            counts[b.color]++;
            total++;
        }
    }

    auto factorials = vector<Mod>(total+1);
    factorials[0] = 1;
    for (auto n = 1; n <= total; n++)
        factorials[n] = n * factorials[n-1];

    auto inverse_factorials = vector<Mod>(total+1);
    inverse_factorials[total] = inverse(factorials[total]);
    for (auto n = total; n >= 1; n--)
        inverse_factorials[n-1] = n * inverse_factorials[n];

    auto result = factorials[total];
    for (auto kv : counts) result *= inverse_factorials[kv.second];
    cout << result.k << endl;
}

