  for (int i = 0; i < n; ++i) if (i != il) {
    if (w[i] < mn1) {
      mn1 = w[i];
      il1 = i;
    }
  }
  V<bool> fixed(n);
  for (int i = 0; i < n; ++i) {
    if (c[i] != c[il]) {
      if (w[i] + w[il] <= y) continue;
      if (ws[c[i]][0] + w[il] <= y and w[i] + ws[c[i]][0] <= x) continue;
      fixed[i] = true;
    } else {
      if (w[i] + w[il1] <= y) continue;
      if (ws[c[i]][0] + w[il1] <= y and w[i] + ws[c[i]][0] <= x) continue;
      fixed[i] = true;
    }
  }
  init(n);
  map<int, int> mp;
  int s = 0;
  for (int i = 0; i < n; ++i) if (!fixed[i]) {
    ++mp[c[i]];
    ++s;
  }
  Mint res = fact[s];
  for (const auto& e : mp) {
    res *= ifact[e.second];
  }
  cout << res << '\n';
}

