		fi = min(fi,tmp);
	}
	for(i=0; i<n; ++i){
		if(c[i]==c[fi.second]){
			continue;
		}
		se = min(se,P(w[i],i));
	}
	for(i=0; i<n; ++i){
		if(gfi[c[i]].first + w[i] <= x){
			unionf(gfi[c[i]].second,i);
		}
		if(c[i]==c[fi.second]){
			if(se.first + w[i] <= y){
