typedef long long ll;

const int M = 1e9 + 7;
const int N = 2e5 + 7;
const int K = 20;

vector <pair <int, int> > g[N][K];
bool u[N][K];
vector <int> ind;

void dfs(int i, int k)
{
    if (u[i][k])
    {
        return;
    }
    u[i][k] = true;
    if (k == 0)
    {
        ind.push_back(i);
    }
    for (auto to : g[i][k])
    {
        dfs(to.first, to.second);
    }
}

int bin(int a, int n)
{
    if (!n)
    {
        return 1;
    }
    if (n % 2 == 0)
    {
        int t = bin(a, n / 2);
        return (t * (ll) t) % M;
    }
    else
    {
        return (a * (ll) bin(a, n - 1)) % M;
    }
}

