struct UnionFind{
    int num;
    vector<int> par,rank;
    UnionFind(int n):num(n),par(n),rank(n,1){
        iota(par.begin(),par.end(),0);
    }
    int root(int x){
        return (par[x]==x?x:par[x]=root(par[x]));
    }
    bool merge(int x, int y){
        x=root(x),y=root(y);
        if (x==y) return false;
        if (rank[x]<rank[y]) swap(x,y);
        par[y]=x;
        rank[x]+=rank[y];
        --num;
        return true;
    }
    bool same(int x, int y){return root(x)==root(y);}
    int size(int x){return rank[root(x)];}
    int count(){return num;}
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    COMinit();
    int N,X,Y; cin >> N >> X >> Y;
    vector<int> c(N),w(N),Min(N,MOD),Min_pos(N,-1);
    for (int i=0;i<N;++i){
        cin >> c[i] >> w[i]; --c[i];
        if (w[i]<Min[c[i]]){
            Min[c[i]]=w[i];
            Min_pos[c[i]]=i;
        }
    }
    UnionFind UF(N);
    for (int i=0;i<N;++i){
        if (w[i]+Min[c[i]]<=X){
            UF.merge(Min_pos[c[i]],i);
        }
    }
    int Most_Min_Color,Most_Min=MOD;
    for (int i=0;i<N;++i){
        if (Min[i]<Most_Min){
            Most_Min=Min[i];
            Most_Min_Color=i;
        }
    }
    for (int i=0;i<N;++i){
        if (c[i]!=Most_Min_Color&&w[i]+Most_Min<=Y){
            UF.merge(Min_pos[Most_Min_Color],i);
        }
    }
    int Next_Min_Color=-1,Next_Min=MOD;
    for (int i=0;i<N;++i){
        if (c[i]!=Most_Min_Color&&w[i]<Next_Min){
            Next_Min=w[i];
            Next_Min_Color=c[i];
        }
    }
    for (int i=0;i<N;++i){
        if (c[i]==Most_Min_Color&&w[i]+Next_Min<=Y){
            UF.merge(i,Min_pos[Next_Min_Color]);
        }
    }
    vector<map<int,int>> cnt(N);
    vector<int> sum(N,0);
    for (int i=0;i<N;++i){
        int r=UF.root(i);
        ++cnt[r][c[i]]; ++sum[r];
    }
    mint ans=1;
    for (int i=0;i<N;++i){
        for (auto p:cnt[i]){
            ans*=COM(sum[i],p.second);
            sum[i]-=p.second;
        }
    }
    cout << ans << '\n';
}

