ll poww(ll a, ll b) {
    ll ans = 1;

    while (b > 0) {
        if (b & 1) ans = (ans * a) % mod;
        b >>= 1;
        a = (a * a) % mod;
    }

    return ans;
}

void pre() {
    int i;

    fact[0] = 1;
    for (i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % mod;
    inv_fact[n] = poww(fact[n], mod - 2);
    for (i = n - 1; i >= 1; i--)
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % mod;
    inv_fact[0] = 1;
}


void dfs(int node) {
    us[node] = true;
    cols.pb(rez[node].col);
    for (auto to : list[node])
        if (!us[to])
            dfs(to);
}

