    inv[0] = 1;
    fac[0] = 1;
    finv[0] = 1;
    inv[1] = 1;
    fac[1] = 1;
    finv[1] = 1;
    for(int i = 2; i < N_MAX; i++){
        fac[i] = (fac[i-1]*i)%MOD;
        inv[i] = ((-(MOD/i)*inv[MOD%i])%MOD+MOD)%MOD;
        finv[i] = (finv[i-1]*inv[i])%MOD;
    }
}


long comb(int n, int m){
    long ans;
    ans = fac[n]*finv[m];
    ans %= MOD;
    ans *= finv[n-m];
    ans %= MOD;
    return ans;
}


int main(){
    init();
    int N, X, Y;
    vector<int> v[200000];
