    sort(begin(bs[c]), end(bs[c]));
    mins.emplace_back(c, bs[c][0]);
  }
  sort(begin(mins), end(mins));

  i64 cnt = 0, q = 1;
  for (i64 c = 1; c <= n; ++c) {
    if (bs[c].empty()) continue;
    i64 min_w;
