typedef long long ll;
int MAX = (int)2e5;
ll MOD = (ll)1e9+7;

ll fanmod(int a){
  int i;
  ll res=1;
  for(i=1;i<=a;i++)
    res = res*i%MOD;
  return res;
}

ll inv(ll a){
  ll ret = 1;
  ll m = MOD-2;
  while(m!=0){
    if(m&1)
      ret = ret*a%MOD;
    m /= 2;
    a = a*a%MOD;
  }
  return ret;
}

int main(){
  int n,x,y,
      min1,min2,sum=0,
      i,j;
  pair<int,int> a[MAX];
  ll ans=1;

  scanf("%d%d%d",&n,&x,&y);
  for(i=0;i<n;i++)
    scanf("%d%d",&a[i].first,&a[i].second);

  sort(a,a+n,[](pair<int,int> &x, pair<int,int> &y){
    return x.first != y.first ?
           x.first < y.first :
      	   x.second < y.second;
  });
  if(n==1){printf("1\n");return 0;}
  min1 = 0;
  for(i=1;i<n;i++)if(a[min1].second > a[i].second)min1 = i;
  min2 = min1==0 ? 1 : 0;
  for(i=1;i<n;i++)
    if(a[min1].first != a[i].first && (min2 == -1 || a[min2].second > a[i].second))min2 = i;
  if(min2==-1 || a[min1].second+a[min2].second > y){printf("1\n");return 0;}

  i=0;
  while(i<n){
    int t = i != min1 ? min1 : min2;
    if(a[t].second+a[i].second <= y){
      int g = max(y-a[t].second,x-a[i].second);
      j = i+1;sum++;
      while(j<n && a[j].first==a[i].first && a[j].second <= g){j++;sum++;}
      ans = ans*inv(fanmod(j-i))%MOD;
    }
    i++;
    while(i<n && a[i].first == a[i-1].first)i++;
  }
  ans = ans*fanmod(sum)%MOD;

  printf("%lld\n",ans);
  return 0;
}

