int Power(int x,int p)
{
	int res=1;
	for (;p;p>>=1)
	{
		if (p&1) res=1ll*res*x%Mod;
		x=1ll*x*x%Mod;
	}
	return res;
} 

void Add_Edge(int x,int y)
{

	E[x].push_back(y);
	E[y].push_back(x);	
}

void Dfs(int x,int &tot)
{
	cnt[c[x]]++; tot++;
	if (!vis_color[x])
	{
		vis_color[x]=true;
		color.push_back(c[x]);
	}

	for (int i=0;i<E[x].size();i++)
	{
		int y=E[x][i]; if (vis[y]) continue;
		vis[y]=true; Dfs(y,tot);
	}
}

int C(int n,int m)
{
	if (m==0) return 1;
	if (n==0) return 0;
	int res=1ll*fac[n]*fac_inv[m]%Mod;
	return 1ll*res*fac_inv[n-m]%Mod;
}

