using namespace std;

typedef long long ll;

const int md = 1e9 + 7;

int mul(int a, int b) {
  return ((ll)a * b) % md;
}

int power(int a, ll b) {
  int res = 1;
  while (b > 0) {
    if (b & 1) res = mul(res, a);
    a = mul(a, a);
    b >>= 1;
  }
  return res;
}

int inv(int a) {
  return power(a, md - 2);
}

const int N = 2e5 + 7;
int f[N];
int rf[N];

int p[N];

int get(int a) {
  return (a == p[a] ? a : p[a] = get(p[a]));
}

void join(int a, int b) {
  a = get(a);
  b = get(b);
  p[a] = b;
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
#ifdef LOCAL
  freopen("input.txt", "r", stdin);
#endif
  f[0] = 1;
  for (int i = 1; i < N; ++i) f[i] = mul(f[i - 1], i);
  rf[N - 1] = inv(f[N - 1]);
  for (int i = N - 2; i >= 0; --i) rf[i] = mul(rf[i + 1], i + 1);
  int n, x, y;
  cin >> n >> x >> y;
  vector <int> c(n), w(n);
  vector <vector <int>> who(n);
  for (int i = 0; i < n; ++i) {
    cin >> c[i] >> w[i];
    --c[i];
    who[c[i]].push_back(i);
  }
  for (int i = 0; i < n; ++i) {
    p[i] = i;
  }

  for (int i = 0; i < n; ++i) {
    sort(who[i].begin(), who[i].end(), [&] (int f, int s) {
      return w[f] < w[s];
    });
  }
  for (int i = 0; i < n; ++i) {
    for (int j = 1; j < (int)who[i].size(); ++j) {
      if (w[who[i][0]] + w[who[i][j]] <= x) {
        join(who[i][0], who[i][j]);
      }
    }   
  }
  vector <int> best;
  for (int i = 0; i < n; ++i) {
    if (!who[i].empty()) {
      best.push_back(who[i][0]);
    }
  }
  sort(best.begin(), best.end(), [&] (int f, int s) {
    return w[f] < w[s];
  });
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < min(2, (int)best.size()); ++j) {
      if (c[i] != c[best[j]] && w[i] + w[best[j]] <= y) {
        join(i, best[j]);
      }
    }
  }
  map <int, int> cnt;
  map <pair <int, int>, int> cntc;
  for (int i = 0; i < n; ++i) {
    ++cnt[get(i)];
    ++cntc[{get(i), c[i]}];
  }
  int ans = 1;
  for (auto p : cnt) ans = mul(ans, f[p.second]);
  for (auto p : cntc) ans = mul(ans, rf[p.second]);
  cout << ans << '\n';
}

