using namespace std;

typedef long long Int;
#define MOD (1000000007)
#define INF (1LL << 60)

Int n, x, y;
Int c[216000], w[216000];
vector<Int> l[216000], ls;
Int fact[216000];
Int changecnt[216000];
Int pow(Int x, Int p){
  if(p == 0)return 1;
  Int res = pow(x, p / 2);
  res = res * res % MOD;
  if(p % 2 == 1)res *= x;
  return res % MOD;
}

Int inv(Int x){
  return pow(x, MOD - 2);
}

void init(){
  fact[0] = 1;
  for(int i = 1;i < 216000;i++)fact[i] = fact[i-1] * i % MOD;
}

Int solve(vector<Int> vec){
  int n = vec.size();
  Int res = 1;
  Int sum = 0;
  for(int i = 0;i < n;i++){
    sum += vec[i];
  }
  res = fact[sum];
  for(int i = 0;i < n;i++){
    res = res * inv(fact[vec[i]]) % MOD;
  }
  return res;
}

int main(){
  init();

  cin >> n >> x >> y;

  for(int i = 0;i < n;i++){
    cin >> c[i] >> w[i];
    l[c[i]].push_back(w[i]);
  }

  for(int i = 0;i <= n;i++){
    if(l[i].empty())continue;
    sort(l[i].begin(), l[i].end());
    ls.push_back(l[i][0]);
  }
  ls.push_back(INF);
  sort(ls.begin(), ls.end());

  for(int i = 0;i <= n;i++){
    if(l[i].empty())continue;
    Int otherl = ls[0];
    if(otherl == l[i][0])otherl = ls[1];
    int bottom = 0, top = l[i].size();
    while(top - bottom > 1){
      int mid = (top + bottom) / 2;
      bool ok = false;
      if(l[i][0] + l[i][mid] <= x)ok = true;
      if(l[i][mid] + otherl <= y)ok = true;
      if(ok)bottom = mid;
      else top = mid;
    }
    changecnt[i] = bottom + 1;
  }

  ls.pop_back();
  int bottom = 0, top = ls.size();
  while(top - bottom > 1){
    int mid = (top + bottom) / 2;
    bool ok = false;
    if(ls[0] + ls[mid] <= y)ok = true;
    if(ok)bottom = mid;
    else top = mid;
  }
  Int changecol = bottom;
  vector<Int> vec;
  for(int i = 0;i <= n;i++){
    if(l[i].empty())continue;
    if(l[i][0] > ls[changecol])continue;
    vec.push_back(changecnt[i]);
  }

  cout << solve(vec) << endl;
  return 0;
}

