std::vector<int> ed[maxn];
int n,x,y;
bool vis[maxn];
int minw[maxn],c[maxn],w[maxn],id[maxn],seq[maxn];
int read()
{
    char ch=getchar();
    int x=0,f=1;
    while(!isdigit(ch))
    {
        f=(ch=='-')?-f:f;
        ch=getchar();
    }
    while(isdigit(ch))
    {
        x=x*10+ch-'0';
        ch=getchar();
    }
    return f<0?-x:x;
}
bool cmpid(int id1,int id2)
{
    return w[minw[id1]]<w[minw[id2]];
}
int cnt;
void fill(int x)
{
    if(vis[x]) return;
    vis[x]=true;
    seq[++cnt]=c[x];
    for(int i=0;i<ed[x].size();i++) fill(ed[x][i]);
}
void addedge(int u,int v)
{
    ed[u].push_back(v);
    ed[v].push_back(u);
}
LL qp(LL x,int y)
{
    if(y==0) return 1;
    int w=0;
    while((y>>w)>1)w++;
    LL ret=x;
    while(w>0)
    {
        --w;
        ret=ret*ret%mod;
        if((y>>w)&1)ret=ret*x%mod;
    }
    return ret;
}
int main()
{
    n=read();x=read();y=read();
    for(int i=1;i<=n;i++){c[i]=read();w[i]=read();}
    for(int i=1;i<=n;i++) minw[i]=0;
    w[0]=inf;
    for(int i=1;i<=n;i++) if(w[i]<w[minw[c[i]]]) minw[c[i]]=i;
    for(int i=1;i<=n;i++) id[i]=i;
    std::sort(id+1,id+n+1,cmpid);
    for(int i=1;i<=n;i++)if(w[i]+w[minw[c[i]]]<=x&&i!=minw[c[i]])
        addedge(i,minw[c[i]]);
    for(int i=1;i<=n;i++)
    {
        if(c[i]!=id[1]&&w[i]+w[minw[id[1]]]<=y) addedge(i,minw[id[1]]);
        if(minw[id[2]]>0&&c[i]!=id[2]&&w[i]+w[minw[id[2]]]<=y) addedge(i,minw[id[2]]);
    }
    fac[0]=1;
    for(int i=1;i<=n;i++) fac[i]=fac[i-1]*i%mod;
    invfac[n]=qp(fac[n],mod-2);
    for(int i=n-1;i>=0;i--) invfac[i]=invfac[i+1]*(i+1)%mod;
    memset(vis,0,sizeof vis);
    LL ans=1;
    for(int i=1;i<=n;i++) if(!vis[i])
    {
        cnt=0;
        fill(i);
        ans=ans*fac[cnt]%mod;
        std::sort(seq+1,seq+cnt+1);
        int cur=1;
        for(int j=2;j<=cnt;j++)
            if(seq[j]!=seq[j-1])
            {
                ans=ans*invfac[cur]%mod;
                cur=1;
            } else cur++;
        ans=ans*invfac[cur]%mod;
    }
    printf("%lld",ans);
