ll find (ll x)
{
	if (x == p[x]) return x;
	return p[x] = find (p[x]);
}

void unite (ll a, ll b)
{
	a = find (a);
	b = find (b);

	if (a == b) return;

	if (sz[a] < sz[b]) swap (a, b);

	p[b] = a;

	sz[a] += sz[b];
}

int main ()
{
	cin >> n >> X >> Y;

	fact[0] = 1;
	for (ll i = 1; i <= n; i++)
		fact[i] = (i * fact[i-1]) % MOD;

	for (ll i = 0; i < n; i++)
	{
		p[i] = i;
		sz[i] = 1;
		ll c, w;

		scanf ("%lld%lld", &c, &w);

