	for (ll i = 0; i < n; i++)
	{
		u[i] = 1;

		if (min_c[a[i].c] == -1) min_c[a[i].c] = i;
		else if (a[min_c[a[i].c]].w + a[i].w <= X) unite (min_c[a[i].c], i);
		else u[i] = 0;
	}

	for (ll i = 0; i <= n; i++)
		if (min_c[i] != -1)
			s.push_back ({a[min_c[i]].w, min_c[i]});

	for (ll i = 0; i < n; i++)
		if (!u[i])
		{
			if (a[s[0].second].c == a[i].c)
				if (s.size () > 1 && s[1].first + a[i].w <= Y) unite (s[1].second, i);
			else if (s[0].first + a[i].w <= Y) unite (s[0].second, i);
		}

	for (ll i = 1; i < s.size (); i++)
		if (s[i].first + s[0].first <= Y) unite (s[i].second, s[0].second);

	for (ll i = 0; i < n; i++)
	{
		mp[find (i)][a[i].c]++;
		sum[find (i)]++;
	}

	for (ll i = 0; i <= n; i++)
		if (sum[i])
		{
			ll den = 1;
			for (auto a : mp[i])
				den = (den * fact[a.second]) % MOD;

			ans = (ans * (fact[sum[i]] * qpow (den, MOD - 2) % MOD)) % MOD;
		}

	cout << ans;

}

