#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 10, mod = 1e9 + 7;
long long n, s, d, w[N], cnt[N], fc[N], ifc[N], mark[N], r[N];
vector<long long> gr[N], c[N], mm;
pair<long long, long long> mn = {mod, mod};
long long ans = 1;
long long power(long long a, long long b) {
	if (!b)
		return 1;
	long long rtr = power(a, b / 2);
	if (b % 2)
		return rtr * rtr % mod * a % mod;
	return rtr * rtr % mod;
}
void getFC() {
	fc[0] = ifc[0] = 1;
	for (int i = 1; i < N - 2; i++) {
		fc[i] = 1ll * fc[i - 1] * i % mod;
		ifc[i] = 1ll * ifc[i - 1] * power(i, mod - 2) % mod;
	}
	return;
}
void dfs(int v) {
	mm.push_back(v);
	mark[v] = 1;
	for (auto u : gr[v])
		if (!mark[u])
			dfs(u);
	return;
}
int main() {
	getFC();
	cin >> n >> s >> d;
	for (int i = 0; i < n; i++) {
		cin >> r[i] >> w[i];
		r[i]--;
		c[r[i]].push_back(i);
		mn = min(mn, {w[i], i});
	}
	for (int i = 0; i < n; i++) 
		sort(c[i].begin(), c[i].end(), [] (int x, int y) { return w[x] < w[y]; });
	for (int i = 0; i < n; i++) {
		for (int j = 1; j < c[i].size(); j++) {
			if (w[c[i][j]] + w[c[i][0]] <= s) {
				gr[c[i][0]].push_back(c[i][j]);
				gr[c[i][j]].push_back(c[i][0]);
			}
		}
		if (!c[i].empty()) {
			int v = c[i][0], u = mn.second;
			if (w[v] + w[u] <= d) {
				gr[v].push_back(u);
				gr[u].push_back(v);
			}
		}
	}
	for (int i = 0; i < n; i++) {
		if (!mark[i]) {
			dfs(i);
			long long rtr = 1ll * fc[(int) mm.size()] % mod;
			for (auto u : mm) {
				rtr = 1ll * rtr * fc[cnt[r[u]]] % mod;
				cnt[r[u]]++;
				rtr = 1ll * rtr * ifc[cnt[r[u]]] % mod;
			}
			for (auto u : mm)
				cnt[r[u]] = 0;
			mm.clear();
			ans = 1ll * (ans * rtr) % mod;
		}
	}
	cout << ans % mod;
	return 0;
}

