using namespace std;

const int N = 200010;
const int mod = 1e9 + 7;
typedef long long LL;
typedef pair<int, int> pii;
vector<pii> b;
vector<int> t[N];
int n, x, y, lc[N], col[N], ls[N], tc[N], w[N];

#define bi b[i].second

int f[N], st[N];
int f_f(int x) { return x == f[x] ? x : f[x] = f_f(f[x]);} 

void merge(int x1, int x2)
{
	int f1 = f_f(x1), f2 = f_f(x2);
	if (f1 != f2) f[f1] = f2;
}

LL p[N];
LL qpow(LL a, LL b)
{
	LL ret = 1, base = a;
	while (b) {
		if (b & 1) ret = ret * base % mod;
		base = base * base % mod, b >>= 1;
	}
	return ret;
}
LL C(int a, int b) {return p[a] * qpow(p[b], mod - 2) % mod * qpow(p[a - b], mod - 2) % mod;}

int main()
{
	scanf("%d%d%d", &n, &x, &y);
	Rep(i, n){
		scanf("%d%d", &col[i], &w[i]);
		b.push_back(mp(w[i], i));
		f[i] = i;
	}
	sort(b.begin(), b.end());

	memset(ls, -1, sizeof(ls));

	Rep(i, n - 1){
		int tmp = ls[col[bi]];
		if (tmp != -1 && b[i].first + b[tmp].first <= x) merge(bi, b[tmp].second);
		if (col[bi] != col[b[0].second] && b[i].first + b[0].first <= y) merge(bi, b[0].second);
		if (!ls[col[bi]]) ls[col[bi]] = i;
	}

	Rep(i, n) t[f_f(i)].push_back(col[i]);
	p[0] = 1;
	Rep(i, n) p[i] = p[i - 1] * i % mod;

	LL ans = 1;

	Rep(i, n) if (t[i].size()) {
		sort(t[i].begin(), t[i].end());	
		int top = 0, cnt = 0;
		for (int j = 0; j < t[i].size(); j ++){
			if (t[i][j] != t[i][j - 1] && j != 0) st[++ top] = cnt, cnt = 0;
			cnt ++;
		}
		int tmp = cnt;
		LL tans = 1;
		while (top){
			tans = tans * C(tmp + st[top], st[top]) % mod;
			tmp += st[top], top --;
		}
		ans = ans * tans % mod;
	}
	printf("%lld\n", ans);

	return 0;
}

