	while(c<'0'||'9'<c){if(c==EOF)exit(0);if(c=='-')f=1;c=getchar();}
	while('0'<=c&&c<='9') x=(x<<3)+(x<<1)+(c^48),c=getchar();
	return !f?x:-x;
}
#define MAXN 200000
#define INF 0x3f3f3f3f
#define Mod (int)(1e9+7)
LL fac[MAXN+5],inv[MAXN+5];
LL Pow(LL x,LL y){
	LL ret=1;
	while(y){
		if(y&1) ret=ret*x%Mod;
		x=x*x%Mod,y>>=1;
	}
	return ret;
}
void Prepare(){
	fac[0]=1;
	for(int i=1;i<=MAXN;i++)
		fac[i]=fac[i-1]*i%Mod;
	inv[MAXN]=Pow(fac[MAXN],Mod-2);
	for(int i=MAXN-1;i>=0;i--)
		inv[i]=inv[i+1]*(i+1)%Mod;
	return ;
}
vector<int> Ball[MAXN+5];
struct node{
	int c,w;
	friend bool operator < (node a,node b){return a.w<b.w;}
}ball[MAXN+5];
int Max[MAXN+5];
bool vis[MAXN+5];
int main(){
	Prepare();
	int n=read(),x=read(),y=read();
	for(int i=1;i<=n;i++){
		int c=read(),w=read();
		ball[i]=(node){c,w};
		//Ball[c].push_back(i);
	}
	sort(ball+1,ball+n+1);
	vis[ball[1].c]=1,Max[ball[1].c]++;
	for(int i=2;i<=n;i++)
		if(ball[1].w+ball[i].w<=y)
			vis[ball[i].c]=1,Max[ball[i].c]++;
	for(int i=1;i<=n;i++){
		sort(Ball[i].begin(),Ball[i].end());
		if(Ball[i].size())
			Max[i]=max(Max[i],1);
		for(int j=1;j<(int)Ball[i].size();j++)
			if(ball[Ball[i][0]].w+ball[Ball[i][j]].w<=x)
				Max[i]=max(Max[i],j+1);
	}//
	LL ans=1;
	int cnt=0;
	for(int i=1;i<=n;i++)
		if(vis[i])
			ans=ans*inv[Max[i]]%Mod,cnt+=Max[i];
	ans=ans*fac[cnt]%Mod;
	printf("%lld\n",ans);
	return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;
#define int long long

const int maxn=2e5+5,pps=1e9+7;

bool vis[maxn];
int n,x,y,tot,ans=1,top;
int fac[maxn],inv[maxn],sta[maxn],insta[maxn];
int sum[maxn],now[maxn],pre[maxn<<2],son[maxn<<2],color[maxn];

int read() {
	int x=0,f=1;char ch=getchar();
	for(;ch<'0'||ch>'9';ch=getchar())if(ch=='-')f=-1;
	for(;ch>='0'&&ch<='9';ch=getchar())x=x*10+ch-'0';
	return x*f;
}

struct Ball {
	int c,w,id;
}b[maxn];

int quick(int a,int b) {
	int sum=1;
	while(b) {
		if(b&1)sum=1ll*sum*a%pps;
		a=1ll*a*a%pps,b>>=1;
	}
	return sum;
}

bool cmp1(Ball a,Ball b) {
	if(a.c==b.c)return a.w<b.w;
	return a.c<b.c;
}

bool cmp2(Ball a,Ball b) {
	if(a.w==b.w)return a.c<b.c;
	return a.w<b.w;
}

void add(int a,int b) {
	pre[++tot]=now[a];
	now[a]=tot,son[tot]=b;
}

void work1() {
	int lst=0;
	for(int i=1;i<=n;i++) {
		if(b[i].c!=b[lst].c) {
			lst=i;continue;
		}
		if(b[i].w+b[lst].w<=x) {
			add(b[i].id,b[lst].id);
			add(b[lst].id,b[i].id);
		}
	}
}

void work2() {
	int fake;
	for(fake=2;fake<=n;fake++)
		if(b[fake].c!=b[1].c)break;
	for(int i=2;i<=n;i++)
		if(b[i].c!=b[1].c) {
			if(b[i].w+b[1].w>y)break;
			add(b[i].id,b[1].id);
			add(b[1].id,b[i].id);
		}
		else if(b[i].w+b[fake].w<=y) {
			add(b[i].id,b[fake].id);
			add(b[fake].id,b[i].id);
		}
}

void prepare() {
	fac[0]=inv[0]=1;
	for(int i=1;i<=n;i++)
		fac[i]=1ll*fac[i-1]*i%pps;
	inv[n]=quick(fac[n],pps-2);
	for(int i=n-1;i;i--)
		inv[i]=1ll*inv[i+1]*(i+1)%pps;
}

void dfs(int u) {
	vis[u]=1;
	int c=color[u];
	if(!insta[c]) {
		sta[++top]=c;
		insta[c]=top;
		sum[top]=1;
	}
	else sum[insta[c]]++;
	for(int p=now[u],v=son[p];p;p=pre[p],v=son[p])
		if(!vis[v])dfs(v);
}

void calc() {
	int cnt=0;
	while(top) {
		ans=1ll*ans*inv[sum[top]]%pps;
		cnt+=sum[top],insta[sta[top]]=0,sta[top]=0,sum[top]=0,top--;
	}
	ans=1ll*ans*fac[cnt]%pps;
}

signed main() {
	n=read(),x=read(),y=read(),prepare();
	for(int i=1;i<=n;i++)
		color[i]=b[i].c=read(),b[i].w=read(),b[i].id=i;
	sort(b+1,b+n+1,cmp1);work1();
	sort(b+1,b+n+1,cmp2);work2();
	for(int i=1;i<=n;i++)
		if(!vis[i])dfs(i),calc();
	printf("%lld\n",ans);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n, x, y, ans = 1;
const int MOD = 1000000007;
const int N = 200010;
int ok[N];
vector <int> bi[N], ls;
int fac[N], inv[N], sum;
int powi(int a, int b)
{
    int c = 1;
    for (; b; b >>= 1, a = 1ll * a * a % MOD)
        if (b & 1) c = 1ll * c * a % MOD;
    return c;
}
int main()
{
    cin >> n >> x >> y;
    fac[0] = 1;
    for (int i = 1; i <= n; ++ i) fac[i] = 1ll * fac[i - 1] * i % MOD;
    inv[n] = powi(fac[n], MOD - 2);
    for (int i = n - 1; ~i; -- i) inv[i] = 1ll * inv[i + 1] * (i + 1) % MOD;

    for (int i = 1; i <= n; ++ i)
    {
        int c, w;
        cin >> c >> w;
        bi[c].push_back(w);
    }
    for (int i = 1; i <= n; ++ i)
    {
        sort(bi[i].begin(), bi[i].end());
    }

    int fs = 0, sc = 0;
    for (int i = 1; i <= n; ++ i) if (bi[i].size())
    {
        if (!fs || bi[fs][0] > bi[i][0]) sc = fs, fs = i;
        else if (!sc || bi[sc][0] > bi[i][0]) sc = i;
    }
    if (!sc) {puts("1"); return 0;}
    ok[fs] = 1;
    for (int i = 1; i <= n; ++ i) if (bi[i].size())
        if (bi[fs][0] + bi[i][0] <= y) ok[i] = 1;

    for (int i = 1; i <= n; ++ i) if (bi[i].size() && ok[i])
    {
        int cnt = 1;
        for (int j = 1; j < bi[i].size(); ++ j)
            if (bi[i][0] + bi[i][j] <= x || bi[fs == i? sc: fs][0] + bi[i][j] <= y)
                cnt ++;
        ls.push_back(cnt); sum += cnt;
    }
    ans = fac[sum];
    for (int i = 0; i < ls.size(); ++ i) ans = 1ll * ans * inv[ls[i]] % MOD;
    cout << ans;
}

