int max_kai = 150000;
vel kai(max_kai, 1);
vel inv_kai(max_kai, 1);
int rui(int a, int n, int mod) {
    if (n == 0) { return 1 % mod; }
    int x = rui(a, n / 2, mod);
    x *= x; x %= mod;
    if (n % 2 == 1) { x *= a; x %= mod; }
    return x;
}
vel pa;
vel siz;
int root(int x) {
    if (pa[x] == -1) { return x; }
    int ans = root(pa[x]); pa[x] = ans;
    return ans;
}
bool mar(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) { pa[x] = y; }
    return (x != y);
}
int gcd(int x, int y) {
    if (x < y) { return gcd(y, x); }
    if (y == 0) { return x; }
    return gcd(y, x % y);
}
long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}
void make_kai() {
    rep(i, max_kai - 1) {
        kai[i+1] = kai[i] * (i+1); kai[i+1] %= p;
        inv_kai[i+1] = modinv(kai[i+1], p);
    }
}
int com(int n, int r) {
    if ((n < 0) || (r < 0) || (r > n)){return 0;}
    int ans = (kai[n] * inv_kai[r])%p;
    return (ans * inv_kai[n - r]) % p;
}
