int inf = 100000;
vel dijk(V<V<pin>>& way, int st) {
    int n = way.size();
    vel dist(n, inf); dist[st] = 0;
    priority_queue<pin,vector<pin>,greater<pin>> pq;
    pq.push(mkp(0, st));
    veb is_checked(n, false);
    while (!pq.empty()) {
        pin x = pq.top(); pq.pop();
        int pot = x.second;
        if (!is_checked[pot]) {
            is_checked[pot] = true;
            for (auto y : way[pot]) {
                int nex_dist = x.first + y.second;
                int nex_pot = y.first;
                if (dist[nex_pot] > nex_dist) {
                    dist[nex_pot] = nex_dist;
                    pq.push(mkp(nex_dist, y.first));
                }
            }
        }
    }
    return dist;
}
double solve(vel &x,vel &y,vel &c) {
    int n = x.size();
    V<pair<double, pin>> list;
    rep(i, n) {
        rep(j, n) {
            double dx = x[i] - x[j];
            double dy = y[i] - y[j];
            double dist = (dx * dx) + (dy * dy);
            dist = sqrt(dist);
            if (c[i] != c[j]) { dist *= 10; }
            list.push_back(mkp(dist, mkp(i, j)));
        }
    }
    sor(list);
    pa = vel(n, -1);
    double ans = 0;
    for (auto x : list) {
        pin kumi = x.second;
        if (mar(kumi.first, kumi.second)) {
            ans += x.first;
        }
    }
    return ans;
}
int sol(int st, int to, vvel& count) {
    int ans = 0;
    rep(i, 26) {
        if (count[st][i] < count[to][i]) { ans++; }
    }
    return ans;
}
int find_min(int st, int kind, vvel& count) {
    int n = count.size() - 1;
    if (sol(st, n, count) < kind) { return n + 1; }
    int ok = n;
    int ng = st;
    while (ok - ng > 1) {
        int mid = (ok + ng) / 2;
        if (sol(st, mid, count) >= kind) { ok = mid; }
        else { ng = mid; }
    }
    return ok;
}
