int inm(int x, int y) {return (ll)x*y%Mod;}

int power(int x, int y)
{
    if(!y) return 1;
    if(y&1) return inm(x, power(inm(x, x), y/2));
    return power(inm(x, x), y/2);
}

void add_edge(int x, int y)
{
    edge[x].push_back(y);
    edge[y].push_back(x);
}

void dfs(int node)
{
    used[node] = 1;
    if(!ap[colour[node]]) colours.push_back(colour[node]);
    ++ap[colour[node]];

    for(auto it : edge[node])
        if(!used[it]) dfs(it);
}

int get_answer()
{
    int sum = 0, ans = 1;
    for(auto it : colours)
    {
        sum += ap[it];
        ans = inm(ans, invfact[ap[it]]);
        ap[it] = 0;
    }

    ans = inm(ans, fact[sum]);
    colours.clear();
    return ans;
}

