const int MN = 200100;
class U {
	private:
		int n,nc;
		vi p,rk,sz;
	public:
		int num() {return nc;}
		U(int v) {
			nc = n = v;
			rk.assign(n,0);
			sz.assign(n,1);
			for(int i=0;i<n;i++) {p.push_back(i);}
		}
		int find(int a) {
			if(a == p[a]) return a;
			return p[a] = find(p[a]);
		}
		bool same(int a, int b) {return find(a) == find(b);}
		int size(int a) {return sz[find(a)];}
		bool un(int a, int b) {
			int x = find(a),y = find(b);
			if(x == y) return false;
			nc--;
			if(rk[x] > rk[y]) {
				p[y] = x;
				sz[x] += sz[y];
				return true;}
			if(rk[x] == rk[y]) rk[y]++;
			p[x] = y;
			sz[y] += sz[x];
			return true;
		}
};
inline ll mul(ll a, ll b) {return (a*b)%M;}
ll bp(ll b, ll p) {
	ll ac = 1;
	while(p) {
		if(p&1) {ac = mul(ac,b);}
		b = mul(b,b);
		p >>= 1;
	}
	return ac;
}
inline ll inv(ll v) {return bp(v,M-2);}
vpl wo[MN];
vpl w;
vl col;
vl fr;
int main() {
	ll n,x,y;
	cin >> n >> x >> y;
	for(int i=0;i<n;i++) {
		ll c,k;
		cin >> c >> k;
		c--;
		wo[c].push_back({k,i});
		w.push_back({k,i});
		col.push_back(c);
	}
	fr.assign(n,0);
	sort(w.begin(),w.end());
	for(int i=0;i<n;i++) {
		sort(wo[i].begin(),wo[i].end());
	}
	U bs(n);
	for(int i=0;i<n;i++) {
		if(w[i].first+w[0].first <= y) {
			bs.un(w[i].second, w[0].second);
		}
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<wo[i].size();i++) {
			if(wo[i][j].first+wo[i][0].first <= x) {
				bs.un(wo[i][j].second,wo[i][0].second);
			}
		}
	}
	int mu = w[0].second;
	ll tot = 0;
	for(int i=0;i<n;i++) {
		if(bs.same(i,mu)) {
			fr[col[i]]++;
			tot++;
		}
	}
	ll ra = 1,rb = 1;
	for(int i=2;i<=tot;i++) {
		ra = mul(ra,i);
	}
	for(int i=0;i<n;i++) {
		for(int j=2;j<=fr[i];j++) {
			rb = mul(rb,j);
		}
	}
	ll res = mul(ra,inv(rb));
	cout << res << '\n';
}

