  s.erase(i);
  cs[p[i].c].erase(i);
  bio[i] = 1;
  ++tot;
  cols.push_back(p[i].c);

  while (!s.empty()) {
    int j = *s.begin();
    if (p[j].w + p[i].w > y) break;
    dfs(j);
  }

  while (!cs[p[i].c].empty()) {
    int j = *cs[p[i].c].begin();
    if (p[j].w + p[i].w > x) break;
    dfs(j);
  }
}

