}

int n, col[MAXN], X, Y, fac[MAXN], finv[MAXN];

struct Node {
	int w, id;
	bool operator < (const Node &rhs) const {
		return w < rhs.w;
	}
} mn, mn2;
vector<Node> a[MAXN];

int vis[MAXN], siz;
vector<int> g[MAXN];
map<int, int> mp;

inline void AddEdge(int u, int v) {
	g[u].push_back(v);
	g[v].push_back(u);
}

void DFS(int u) {
	siz += (vis[u] = 1);
	++mp[col[u]];
	for (auto v : g[u]) {
		if (vis[v]) continue;
		DFS(v);
	}
}

void init() {
	read(n); read(X); read(Y);
	for (int i = 1, w; i <= n; ++i) {
		read(col[i]); read(w);
		a[col[i]].push_back((Node){w, i});
	}
	fac[0] = 1;
	for (int i = 1; i <= n; ++i) {
		fac[i] = Mul(fac[i - 1], i);
	}
	finv[n] = ksm(fac[n], MOD - 2);
	for (int i = n; i >= 1; --i) {
		finv[i - 1] = Mul(finv[i], i);
	}
}

void solve() {
	mn.w = mn2.w = INF;
	for (int i = 1; i <= n; ++i) {
		int sz = a[i].size();
		if (sz == 0) continue;
		sort(a[i].begin(), a[i].end());
		Node cur = a[i][0];
		for (int j = 1; j < sz; ++j) {
			if (cur.w + a[i][j].w <= X) {
				AddEdge(cur.id, a[i][j].id);
			}
		}
		if (cur < mn) {
			mn2 = mn;
			mn = cur;
		} else if (a[i][0] < mn2) {
			mn2 = cur;
		}
	}
	if (mn2.id) {
		for (int i = 1; i <= n; ++i) {
			Node cur = ((i == col[mn.id])? mn2 : mn);
			for (auto p : a[i]) {
				if (p.w + cur.w <= Y) {
					AddEdge(p.id, cur.id);
				} else {
					break;
				}
			}
		}
	}

	int ans = 1;
	for (int i = 1; i <= n; ++i) {
		if (vis[i]) continue;
		siz = 0;
		mp.clear();
		DFS(i);
		ans = Mul(ans, fac[siz]);
		for (auto p : mp) {
			ans = Mul(ans, finv[p.second]);
		}
	}
	printf("%d\n", ans);
}

int main() {
	init();
	solve();	
	return 0;
}

