int N, X, Y;
vector<int> c, w;
constexpr lint MOD = 1e9 + 7;

vector<lint> fac, facInv, inv;
void facInit(int nmax)
{
    fac = facInv = inv = vector<lint>(nmax + 1, 1);
    for (int i = 2; i <= nmax; i++)
    {
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        facInv[i] = facInv[i-1] * inv[i] % MOD;
    }
}

int main()
{
    cin >> N >> X >> Y;
    c.resize(N);
    w.resize(N);

    map<int, int> wmin_ec;
    int wmin = 1e9;
    set<int> wmincolor;

    REP(i, N)
    {
        cin >> c[i] >> w[i];
        wmin_ec[c[i]] = wmin_ec[c[i]] ? min(wmin_ec[c[i]], w[i]) : w[i];
        if (w[i] < wmin)
        {
            wmin = w[i];
            wmincolor.clear();
            wmincolor.insert(c[i]);
        }
        else if (w[i] == wmin) wmincolor.insert(c[i]);
    }

    map<int, int> movable_ec;
    REP(i, N)
    {
        if (((wmin_ec[c[i]] + w[i] <= X || wmin_ec[c[i]] == w[i]) && wmin_ec[c[i]] + wmin <= Y && set<int>{c[i]} != wmincolor) ||
            (w[i] + wmin <= X && wmincolor.find(c[i]) != wmincolor.end())) movable_ec[c[i]]++;
    }

    facInit(N);
    lint ans = 1;
    int count = 0;
    for (auto pa : movable_ec)
    {
        (ans *= facInv[pa.second]) %= MOD;
        count += pa.second;
    }
    cout << ans * fac[count] % MOD << endl;
}

