            ret = (int64_t) ret * x % MOD;
        }
        x = (int64_t) x * x % MOD;
    }
    return ret;
}

int invMod(int x) {
    return Pow(x, MOD - 2);
}

void precalc(int n) {
    fact = vector<int>(n + 1);
    fact[0] = 1; 
    for (int i = 1; i <= n; ++i) {
        fact[i] = (int64_t) fact[i - 1] * i % MOD;
    }
    invFact = vector<int>(n + 1);
    invFact[n] = invMod(fact[n]);
    for (int i = n - 1; i >= 0; --i) {
        invFact[i] = (int64_t) invFact[i + 1] * (i + 1) % MOD;
    }
}

int comb(int n, int k) {
    return (int64_t) fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
}

