    cin.tie(0);

    int n, X, Y;
    cin >> n >> X >> Y;

    precalc(5 * n);

    vector<vector<pair<int, int>>> A(n + 1);
    for (int i = 1; i <= n; ++i) {
        int c, w;
        cin >> c >> w;
        A[c].push_back(make_pair(w, 1));
    }
    for (int i = 1; i <= n; ++i) {
        if (A[i].empty()) continue;
        sort(A[i].begin(), A[i].end());
        vector<pair<int, int>> B = {{A[i][0].first, 1}};
        for (int j = 1; j < SZ(A[i]); ++j) {
            if (A[i][j].first + A[i][0].first <= X) {
                B.back().second++;
            } else {
                B.push_back(A[i][j]);
            }
        }
        A[i] = B;
    }
    int vmin1 = INF, pos = 0, vmin2 = INF;
    int xcnt = 0;
    for (int i = 1; i <= n; ++i) {
        if (A[i].empty()) continue;
        if (A[i][0].first < vmin1) {
            vmin2 = vmin1;
            vmin1 = A[i][0].first;
            xcnt = A[i][0].second;
            pos = i;
        } else if (A[i][0].first < vmin2) {
            vmin2 = A[i][0].first;
        }
    }
    int total = 0;
    int ans = 1;
    for (int i = 1; i <= n; ++i) {
        if (pos == i) continue;
        int add = 0;
        for (const pair<int, int>& p: A[i]) {
            if (p.first + vmin1 <= Y) {
                add += p.second;
            }
        }
        ans = (int64_t) ans * comb(total + add, add) % MOD;
        total += add;
    }
    for (int i = 1; i < SZ(A[pos]); ++i) {
        pair<int, int> p = A[pos][i];
        if (p.first + vmin2 <= Y) {
            xcnt += p.second;
        }
    }
    ans = (int64_t) ans * comb(total + xcnt, xcnt) % MOD;

    ans %= MOD;
    if (ans < 0) ans += MOD;

    cout << ans << '\n';
}

