	P(){}
	P(int a,int b,int q){c=a;w=b;id=q;}
}a[N];
bool operator <(P a,P b){
	if(a.w!=b.w) return a.w>b.w;
	return a.id>b.id;
}
bool cmp(P a,P b){
	return a.id<b.id;
}
int n,x,y,fa[N],sum[N],s[N],top;
ll f[N],inv[N];
