int find(int k){
	if(fa[k]!=k) fa[k]=find(fa[k]);
	return fa[k];
}
ll quick_pow(ll a,ll b){
	ll ans=1;
	for(;b;b>>=1,a=a*a%mod)
		if(b&1) ans=ans*a%mod;
	return ans;
}
ll C(ll n,ll m){
	return f[n]*inv[m]%mod*inv[n-m]%mod;
}
int main(){
	scanf("%d%d%d",&n,&x,&y);
	f[0]=inv[0]=1;
	for(int i=1;i<=n;i++){
		f[i]=f[i-1]*i%mod;
		inv[i]=quick_pow(f[i],mod-2);
		scanf("%d%d",&a[i].c,&a[i].w);
		a[i].id=i;
		fa[i]=i;
	}
	for(int i=1;i<=n;i++) q[i].push(P(i,inf,n+1)),q[0].push(P(i,inf,n+1));
