	for(int i=1;i<=n;i++){
		P now=q[0].top(),pre,mn=P(0,inf,0);int f1,f2;
		top=0;
		while(now.w+a[i].w<=y){
			int S=y;
			if(now.c==a[i].c) S=-inf;
			while(q[now.c].top().w+a[i].w<=S){
				pre=q[now.c].top();q[now.c].pop();
				f1=find(pre.id);f2=find(a[i].id);
				fa[f1]=f2;
				if(pre.w<mn.w&&pre.c!=a[i].c) mn=pre;
			}
			s[++top]=now.c;
			q[0].pop();now=q[0].top();
		}
		now=q[a[i].c].top();
		while(now.w+a[i].w<=x){
			f1=find(now.id);f2=find(a[i].id);
			fa[f1]=f2;
			q[a[i].c].pop();
			now=q[a[i].c].top();
		}
		q[a[i].c].push(a[i]);
		if(mn.c) q[mn.c].push(mn);
		bool T=0;
		for(int p=1;p<=top;p++){
			q[0].push(q[s[p]].top());
			if(s[p]==a[i].c) T=1;
		}
		if(!T) q[0].push(q[a[i].c].top());
	}
	sort(a+1,a+n+1,cmp);
	for(int i=1;i<=n;i++){
		sum[find(i)]++;
		if(m.find(mp(fa[i],a[i].c))==m.end()) m[mp(fa[i],a[i].c)]=0;
		m[mp(fa[i],a[i].c)]++;
	}
	ll ans=1;
