		int g=m[mp(fa[i],a[i].c)];m[mp(fa[i],a[i].c)]=0;
		ans=ans*C(sum[fa[i]],g)%mod;
		sum[fa[i]]-=g;
	}
	printf("%lld",ans);
	return 0;
}

