template <int mod>
struct ModInt
{
    using lint = long long;
    int val;
    ModInt() : val(0) {}
    void _setval(lint v) { v = (v % mod) + mod; val = v >= mod ? v - mod : v; }
    ModInt(lint v) { _setval(v); }
    ModInt operator+(const ModInt &x) const { return ModInt((lint)val + x.val); }
    ModInt operator-(const ModInt &x) const { return ModInt((lint)val - x.val); }
    ModInt operator*(const ModInt &x) const { return ModInt((lint)val * x.val); }
    ModInt operator/(const ModInt &x) const { return ModInt((lint)val * x.inv().val); }
    ModInt operator-() const { return ModInt(-val); }
    ModInt &operator+=(const ModInt &x) { return *this = *this + x; }
    ModInt &operator-=(const ModInt &x) { return *this = *this - x; }
    ModInt &operator*=(const ModInt &x) { return *this = *this * x; }
    ModInt &operator/=(const ModInt &x) { return *this = *this / x; }
    bool operator==(const ModInt &x) { return val == x.val; }
    bool operator!=(const ModInt &x) { return val != x.val; }
    friend ostream &operator<<(ostream &os, const ModInt &x) { os << x.val;  return os; }

    lint power(lint n) const {
        ModInt ans(1), tmp(val);
        while (n) {
            if (n & 1) ans *= tmp;
            tmp *= tmp;
            n /= 2;
        }
        return ans.val;
    }
    ModInt inv() const { return this->power(mod - 2); }

    ModInt fac() const {
        static vector<ModInt> facs;
        int l0 = facs.size();
        if (l0 > this->val) return facs[this->val];

        facs.resize(this->val + 1);
        for (int i = l0; i <= this->val; i++) facs[i] = (i == 0 ? 1 : facs[i - 1] * i);
        return facs[this->val];
    }

    ModInt nCr(const ModInt &r) const {
        if (this->val < r.val) return ModInt(0);
        return this->fac() / ((*this - r).fac() * r.fac());
    }
};
using mint = ModInt<MOD>;


struct UnionFind // UnionFind Tree (0-indexed)
{
    vector<int> par, rank;
    UnionFind(int N) : par(N), rank(N) { REP(i, N) par[i] = i; }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        if (rank[x] < rank[y]) par[x] = y; else par[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
    }
    bool same(int x, int y) { return find(x) == find(y); }
};



int main()
{
    cin >> N >> X >> Y;
    c.resize(N);
    w.resize(N);

    UnionFind uf(N + 1);

    map<int, int> ec_min_pos;
    priority_queue<pint, vector<pint>, greater<pint>> pq;

    REP(i, N)
    {
        cin >> c[i] >> w[i];
        pq.push(pint(w[i], i));
        if (ec_min_pos[c[i]])
        {
            if (w[ec_min_pos[c[i]]] > w[i]) ec_min_pos[c[i]] = i;
        }
        else ec_min_pos[c[i]] = i;
    }

    if (ec_min_pos.size() == 1) cout << 1 << endl, exit(0);

    int w1, i1, w2, i2;
    tie(w1, i1) = pq.top();
    while (c[pq.top().second] == c[i1]) pq.pop();
    tie(w2, i2) = pq.top();
    if (w1 + w2 > Y) cout << 1 << endl, exit(0);

    uf.unite(N, i1);
    uf.unite(N, i2);

    REP(i, N)
    {
        if (w[ec_min_pos[c[i]]] + w[i] <= X) uf.unite(i, ec_min_pos[c[i]]);
        if (c[i] != c[i1] && w[i] + w1 <= Y) uf.unite(N, i);
        if (c[i] != c[i2] && w[i] + w2 <= Y) uf.unite(N, i);
    }

    map<int, int> movable_ec;
    int num = 0;
    REP(i, N) if (uf.same(N, i))
    {
        movable_ec[c[i]]++;
        num++;
    }

    mint ans = mint(num).fac();
    for (auto pa : movable_ec) ans /= mint(pa.second);
    cout << ans << endl;
}

