#include <cstdio>
#include <algorithm>
#include <vector>
using namespace std;

typedef pair <int, int> pii;

const int MAXN = 200005;
const int offset = 1 << 18;
const int MOD = 1000000007;

int N, X, Y;
pii ball[MAXN];
vector <pii> t[2 * offset], v[2 * offset];
vector <int> comp[MAXN];
int dad[MAXN], rnk[MAXN];
int fact[MAXN], inv[MAXN];
int cnt[MAXN];
int sum[MAXN];

void load() {
	scanf("%d%d%d", &N, &X, &Y);
	for (int i = 0; i < N; i++)
		scanf("%d%d", &ball[i].second, &ball[i].first);
}

inline int mul(int x, int y) {
	return (long long)x * y % MOD;
}

int pot(int x, int y) {
	int res = 1;
	for (; y; y /= 2) {
		if (y % 2)
			res = mul(res, x);
		x = mul(x, x);
	}
	return res;
}

void add(int pos) {
	for (int x = pos + offset; x; x /= 2)
		t[x].push_back({ball[pos].second, pos});
}

void update(int x, int lo, int hi, int from, int to, int val, int type) {
	if (lo >= to || hi <= from)
		return;
	if (lo >= from && hi <= to) {
		v[x].push_back({val, type});
		return;
	}
	int mid = (lo + hi) / 2;
	update(2 * x, lo, mid, from, to, val, type);
	update(2 * x + 1, mid, hi, from, to, val, type);
}

void update(int from, int to, int val, int type) {
	update(1, 0, offset, from, to, val, type);
}

int find(int x) {
	return dad[x] == x ? x : dad[x] = find(dad[x]);
}

void join(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)
		return;
	if (rnk[x] > rnk[y])
		swap(x, y);
	dad[x] = y;
	rnk[y] += rnk[x] == rnk[y];
}

int get_pos(int x, int val) {
	return lower_bound(t[x].begin(), t[x].end(), pii(val, -1)) - t[x].begin();
}

void merge(int x, int val, int lo, int hi) {
	if (lo >= hi)
		return;
	join(val, t[x][lo].second);
	sum[lo]++;
	sum[hi - 1]--;
}

void work(int x) {
	for (int i = 0; i < t[x].size(); i++)
		sum[i] = 0;

	sort(t[x].begin(), t[x].end());

	for (auto it : v[x]) {
		int lo = get_pos(x, ball[it.first].second);
		int hi = get_pos(x, ball[it.first].second + 1);
		if (it.second == 1) 
			merge(x, it.first, lo, hi);
		else {
			merge(x, it.first, 0, lo);
			merge(x, it.first, hi, t[x].size());
		}
	}

	for (int i = 0; i < (int)t[x].size() - 1; i++) {
		if (i)
			sum[i] += sum[i - 1];
		if (sum[i])
			join(t[x][i].second, t[x][i + 1].second);
	}
}

int get_last(int val) {
	return lower_bound(ball, ball + N, pii(val + 1, 0)) - ball;
}

int solve() {
	sort(ball, ball + N);

	for (int i = 0; i < N; i++) {
		dad[i] = i;
		update(i + 1, get_last(X - ball[i].first), i, 1);
		update(i + 1, get_last(Y - ball[i].first), i, 2);
		add(i);
	}

	for (int i = 0; i < 2 * offset; i++)
		work(i);

	for (int i = 0; i < N; i++)
		comp[find(i)].push_back(i);

	fact[0] = 1;
	for (int i = 1; i <= N; i++) {
		fact[i] = mul(fact[i - 1], i);
		inv[i] = pot(i, MOD - 2);
	}

	int sol = 1;
	for (int i = 0; i < N; i++) {
		sol = mul(sol, fact[comp[i].size()]);
		for (auto it : comp[i])
			sol = mul(sol, inv[++cnt[ball[it].second]]);
		for (auto it : comp[i])
			cnt[ball[it].second]--;
	}

	return sol;
}

int main() {
	load();
	printf("%d\n", solve());
	return 0;
}

