	F[0] = FR[0] = 1;
	FOR(i, 1, MAX)
	{
		F[i] = (F[i - 1] * i) % MOD;
		FR[i] = inv(F[i]);
	}

	cin >> n >> x >> y;
	FOR(i, 0, n)
	{
		cin >> A[i].second >> A[i].first;
	}

	sort(A, A + n);
	FILL(C, -1);
	FOR(i, 0, n)
	{
		int c = A[i].second;
		P[i] = C[c];
		if (C[c] == -1) C[c] = i;
	}

	int p = -1;
	FOR(i, 0, n)
	{
		if (A[i].second != A[0].second)
		{
			p = i;
			break;
		}
	}

	D.init();
	FOR(i, 1, n)
	{
		if (A[i].second == A[0].second)
		{
			if (A[i].first + A[0].first <= x)
			{
				D.unionSet(0, i);
			}

			if (p != -1 && A[i].first + A[p].first <= y)
			{
				D.unionSet(p, i);
			}

			continue;
		}

		if (A[i].first + A[0].first <= y)
		{
			D.unionSet(i, 0);
		}

		if (P[i] != -1 && A[i].first + A[P[i]].first <= x)
		{
			D.unionSet(i, P[i]);
		}
	}

	LL ans = D.calc();
	cout << ans << endl;
}

