bool vis[MAX_N];

ll dfs(ll u, unordered_map<ll, ll> &col_cnt) {
    if (vis[u]) return 0;
    vis[u] = true;
    ll ans = 1;
    col_cnt[col[u]]++;
    for (ll v : adj[u]) {
        ans += dfs(v, col_cnt);
    }
    return ans;
}

ll fact(ll x) {
    ll ans = 1;
    for (ll i = 1; i <= x; i++) {
        ans = (ans * i) % MOD;
    }
    return ans;
}

ll pow(ll b, ll e) {
    if (e == 0) return 1;
    ll res = pow(b, e >> 1);
    res = (res * res) % MOD;
    if (e & 1) res = (res * b) % MOD;
    return res;
}

ll inv(ll x) {
    return pow(x, MOD - 2);
}

ll permute(ll cnt, unordered_map<ll, ll> &col_cnt) {
    ll ans = fact(cnt);
    for (pair<ll, ll> c : col_cnt) {
        if (c.second > 0) {
            ans = (ans * inv(fact(c.second))) % MOD;
        }
    }
    return ans;
}

