	{
		int k = Q.front(); Q.pop(); ++tot;
		for (int i = 0; i < v[k].size(); i++)
		{
			int to = v[k][i]; if (vis[to]) continue;
			if (last[c[to]] == Clock) ++cnt[c[to]];
			else cnt[c[to]] = 1,last[c[to]] = Clock,s.push(c[to]);
			vis[to] = 1; Q.push(to);
		}
	}
}

