using namespace std;
typedef long long llong;
#define FOR(i,n) for(int i=0; i<int(n); i++)
#define FOR1(i,m,n) for(int i=int(m); i<int(n); i++)

typedef struct _Node {
    bool flag = false;
    int color;
    int weight;
    vector<struct _Node*> next;
} Node;

typedef struct _Graph {
    vector<Node> nodes;
} Graph;

void getConnected(Node* node,
                  vector<Node*> &connected) {
    if (node->flag == true) {
        return;
    }

    connected.push_back(node);
    node->flag = true;
    for (auto n : node->next) {
        if (n->flag == false)
            getConnected(n, connected);
    }

    return;
}

llong factorial(int n) {
    if (n <= 1)
        return 1;

    llong ans = 1;
    FOR1(i, 2, n+1)
        ans *= i;

    return ans;
}

llong pow(llong b, int n) {
    if (n == 0)
        return 1;
    else if (n % 2 == 1)
        return b * pow(b, n-1);
    else {
        llong x = pow(b, n/2);
        return x*x;
    }
}

llong getCombMod(vector<Node*> connected, llong mod) {
    if (connected.size() == 0) {
        return 1;
    }

    int max_color = 0;
    for (auto node : connected) {
        if (max_color < node->color)
            max_color = node->color;
    }

    vector<int> hist(max_color, 0);
    for (auto node : connected)
        hist[node->color-1]++;

    llong ans = factorial(connected.size());
    for (auto n : hist) ans /= factorial(n);

    return ans % mod;
}

