// Modular operations
const int MOD = 1E9 + 7;

int Add(int a, int b, int m = MOD){
  a += b;
  if(a >= m) a -= m;
  return a;
}

int Sub(int a, int b, int m = MOD){
  a -= b;
  if(a < 0) a += m;
  return a;
}

int AddTo(int& to, int w, int m = MOD){
  to += w;
  if(to >= m) to -= m;
  return to;
}

int SubTo(int& to, int w, int m = MOD){
  to -= w;
  if(to < 0) to += m;
  return to;
}

int Mult(int a, int b, int m = MOD){
  return (a * 1LL * b) % m;
}

int Pow(int a, ll deg, int m = MOD){
  int res = 1 % m;
  for(;deg > 0;deg >>= 1, a = Mult(a, a, m))
    if(deg & 1) res = Mult(res, a, m);
  return res;
}

int Oem(int to, int m = MOD){
  return Pow(to, m - 2, m);
}

int Div(int a, int b, int m = MOD){
  return Mult(a, Oem(b, m), m);
}

// Solution
const int MAXN = 2E5 + 10;

int par[MAXN];

int GetPar(int vr){
  return par[vr] == vr ?
    vr : par[vr] = GetPar(par[vr]);
}

void Merge(int a, int b){
  a = GetPar(a), b = GetPar(b);
  par[a] = b;
}

int n, x, y;
int col[MAXN], w[MAXN];

bool Compare(int f, int s){
  return w[f] < w[s];
}

vi by_col[MAXN];
vi glob;

int fact[MAXN];

int Shuffle(const vi& of){
  int tot = 0;
  for(int e : of) tot += e;

  int ch = fact[tot], zm = 1;
  for(int e : of) zm = Mult(zm, fact[e]);

  return Div(ch, zm);
}

int main(){
  for(int i = 0;i < MAXN;++i) par[i] = i;

  fact[0] = 1;
  for(int i = 1;i < MAXN;++i)
    fact[i] = Mult(i, fact[i - 1]);

  scanf("%d%d%d", &n, &x, &y);
  for(int i = 0;i < n;++i){
    scanf("%d%d", &col[i], &w[i]);
    glob.pb(i);
    by_col[col[i]].pb(i);
  }

  sort(all(glob), Compare);
  for(int i = 1;i <= n;++i)
    sort(all(by_col[i]), Compare);

  for(int i = 1;i <= n;++i)
    for(int j = 1;j < sz(by_col[i]);++j)
      if(w[by_col[i][0]] + w[by_col[i][j]] <= x)
        Merge(by_col[i][0], by_col[i][j]);

  int a = glob[0], b = -1;
  for(int e : glob)
    if(b == -1 && col[a] != col[e]){
      b = e;
      break;
    }
  if(b == -1) b = a;

  for(int e : glob){
    if(col[a] != col[e] && w[a] + w[e] <= y) Merge(a, e);
    if(col[b] != col[e] && w[b] + w[e] <= y) Merge(b, e);
  }

  map<int, map<int, int>> grp;
  for(int i = 0;i < n;++i)
    ++grp[GetPar(i)][col[i]];

  int ans = 1;
  for(const auto& e : grp){
    vi use;
    for(const auto& r : e.se) use.pb(r.se);
    ans = Mult(ans, Shuffle(use));
  }

  printf("%d\n", ans);

  return 0;
}

