	}
	return b;
}


ll nCm(int n, int m)
{
	int i;
	ll r;

	if(m*2>n) m=n-m;

	r=1;
	for(i=0;i<m;i++)
	{
		r=(r*(n-i)/(i+1))%MODU;
	}
	return r;
}


