}


int cmp(const void *pa, const void *pb)
{
	const ball_t *a, *b;

	a=pa;
	b=pb;
	if(a->w<b->w) return -1;
	return (a->w>b->w);
}


int cmp2(const void *pa, const void *pb)
{
	const ball_t *a, *b;

	a=pa;
	b=pb;
	if(a->c<b->c) return -1;
	if(a->c>b->c) return 1;

	if(a->w<b->w) return -1;
	return (a->w>b->w);
}


ll calc(int c_num[], int n)
{
	ll ret=1, t, d;
	int i, j, k;
	static ll work[N_MAX+1];
	int work_num=0;

	for(i=0;i<n;i++)
	{
		if(c_num[i]==0) continue;

		for(j=1;j<=c_num[i];j++)
		{
			work[work_num]=work_num+1;
			work_num++;
		}
	}

	for(i=0;i<n;i++)
	{
		if(c_num[i]==0) continue;

		for(j=1;j<=c_num[i];j++)
		{
			t=j;
			for(k=0;k<work_num && t>1;k++)
			{
				if(work[k]==1)
				{
					work[k--]=work[--work_num];
					continue;
				}

				d=gcd(work[k], t);
				if(d>1)
				{
					work[k]/=d;
					t/=d;
				}
			}
		}
	}

	ret=1;
	for(i=0;i<work_num;i++)
	{
		ret=(ret*work[i])%MODU;
	}
	return ret;
}


