    static int mod = 1000000000 + 7;

    static long modpow(long b, int e) {
        if(e == 0) return 1;
        if((e & 1) == 1) return (modpow(b, e-1) * b) % mod;
        long m = modpow(b, e >> 1);
        return (m * m) % mod; 
    }
    static long inverse(long x) {
        return modpow(x, mod - 2);
    }
    static class Dsu {
        int [] par;
        ArrayList <Integer> [] t; 

        Dsu (int n) {
            par = new int [n + 5];
            t = new ArrayList [n + 5];
            for(int i = 0; i <= n; i++) {
                t[i] = new ArrayList <> ();
                par[i] = i;
                t[i].add(c[i]);
            }
        }
        void merge(int p, int q) {
            p = root(p);
            q = root(q);
            if(t[p].size() > t[q].size()) {
                int temp = p;
                p = q;
                q = temp;
            }
            if(p == q) return ;
            par[p] = q;
            for(Integer i : t[p]) {
                t[q].add(i);
            }
            t[p].clear();
        }
        int root(int p) {
            if(par[p] == p) return p;
            else return par[p] = root(par[p]);
        }
        long size(int p) {
            TreeMap <Integer, Integer> s = new TreeMap <> ();
            for(Integer i : t[root(p)]) {
                if(s.containsKey(i)) {
                    s.put(i, s.get(i) + 1);
                } else {
                    s.put(i, 1);
                }
            }
            long ans = fac[ t[root(p)].size() ];
            for(Map.Entry <Integer, Integer>  i : s.entrySet()) {
                ans *= inverse( fac[i.getValue()] );
                ans %= mod;
            }
            return ans;
        }
    }
