		for(int i=0;i<n;i++) {
			b[i].i = i;
		}

		UnionFind uf = new UnionFind(n);
		ArrayList<Ball>[] bk = new ArrayList[n+1];
		for(int i=0;i<=n;i++) {
			bk[i] = new ArrayList<>();
		}
		for(int i=0;i<n;i++) {
			bk[b[i].c].add(b[i]);
		}
		for(int c=0;c<=n;c++) {
			ArrayList<Ball> al = bk[c];
			if (al.size() == 0) continue;
			al.sort((b1,b2)->Integer.compare(b1.w, b2.w));
			Ball light = al.get(0);
			for(Ball bb: al) {
				if (light.w + bb.w <= x) {
					uf.union(light.i, bb.i);
				}
			}
		}
		Ball light = null;
		for(int i=0;i<n;i++) {
			if (light == null || light.w > b[i].w) {
				light = b[i];
			}
		}
		type2(n, y, b, uf, light);
//		System.err.println(light);
		Ball light2 = null;
		for(int i=0;i<n;i++) {
			if ((b[i].c != light.c) && (light2 == null || light2.w > b[i].w)) {
				light2 = b[i];
			}
		}
		if (light2 != null) {
			type2(n, y, b, uf, light2);
		}

		long[] fact = Mod.factorialArray(200010, MOD);
		long[] factInv = Mod.factorialInverseArray(200010, MOD, Mod.inverseArray(200010, MOD));
		long ans = 1;
		for(int i=0;i<n;i++) {
			if (b[i].i != i) {
				throw new RuntimeException();
			}
		}
		for(ArrayList<Integer> g: uf.groups()) {
			ArrayList<Integer> cs = new ArrayList<>();
			for(int i:g) {
				cs.add(b[i].c);
			}
			cs.sort(null);
//			System.err.println(cs);
			int m = cs.size();
			long pi = fact[m];
			for(int l=0;l<m;) {
				int r = l;
				while(r < m - 1 && cs.get(r+1) == cs.get(l)) {
					r++;
				}
//				System.err.println(r-l+1);
				pi = pi * factInv[r-l+1] % MOD;
				l = r + 1;
			}
//			System.out.println(pi);
			ans = ans * pi % MOD;
		}
		System.out.println(ans);
	}
	private static void type2(int n, int y, Ball[] b, UnionFind uf, Ball light) {
		for(int i=0;i<n;i++) {
			if (light.c != b[i].c && light.w + b[i].w <= y) {
				uf.union(light.i, b[i].i);
			}
		}
	}
}
