		void Read()
		{
			sc.Read(out N, out X, out Y);
			bs = sc.ReadManyLines<int, int>(N);
		}
		void SolveOne()
		{
			Array.Sort(bs, (x, y) => { var c = x.Item2.CompareTo(y.Item2); return c == 0 ? x.Item1.CompareTo(y.Item1) : c; });
			var uf = new UnionFindTree(N);
			var col = new List<int>[N];
			for (var i = 0; i < N; i++) col[i] = new List<int>();
			for (var i = 0; i < N; i++) col[bs[i].Item1 - 1].Add(i);
			foreach (var cols in col)
			{
				var j = 1;
				while (j < cols.Count && bs[cols[0]].Item2 + bs[cols[j]].Item2 <= X) j++;
				for (var i = 1; i < j; i++) uf.UniteCategory(cols[0], cols[i]);
			}
			var k = 1;
			while (k < N && bs[0].Item2 + bs[k].Item2 <= Y) k++;
			for (var i = 1; i < k; i++) if (bs[0].Item1 != bs[i].Item1) uf.UniteCategory(0, i);
			var l = 0;
			while (l < N && bs[0].Item1 == bs[l].Item1) l++;
			if (l != N)
			{
				k = l + 1;
				while (k < N && bs[l].Item2 + bs[k].Item2 <= Y) k++;
				for (var i = l + 1; i < k; i++) if (bs[l].Item1 != bs[i].Item1) uf.UniteCategory(l, i);
			}
			var fact = new long[N + 1];
			fact[0] = 1;
			for (var i = 1; i <= N; i++) fact[i] = (i * fact[i - 1]) % Mod;
			var ifact = new long[N + 1];
			ifact[0] = 1;
			for (var i = 1; i <= N; i++) ifact[i] = (Inverse(i, Mod) * ifact[i - 1]) % Mod;
			var p = 1L;
			var z = new List<int>[N];
			for (var i = 0; i < N; i++) z[i] = new List<int>();
			for (var i = 0; i < N; i++) z[uf.GetRootOf(i)].Add(i);
			for (var i = 0; i < N; i++) if (z[i].Count != 0)
				{
					p = (p * fact[z[i].Count]) % Mod;
					var y = new Dictionary<int, int>();
					foreach (var j in z[i])
					{
						var c = bs[j].Item1;
						if (!y.ContainsKey(c)) y[c] = 1;
						else y[c]++;
