		if (node.Left != sentinel) edges.Append($"\tv{code} -> v{code}L;\n");
		if (node.Right != sentinel) edges.Append($"\tv{code} -> v{code}R;\n");
		ConcatSubTree(nodes, edges, node.Left, $"{code}L");
		ConcatSubTree(nodes, edges, node.Right, $"{code}R");
