			var col = new List<int>[N];
			for (var i = 0; i < N; i++) col[i] = new List<int>();
			for (var i = 0; i < N; i++) col[bs[i].Item1 - 1].Add(i);
			foreach (var t in col) if (t.Count > 0) foreach (var i in t) if (bs[t[0]].Item2 + bs[i].Item2 <= X) uf.UniteCategory(t[0], i);
			for (var i = 1; i < N; i++) if (bs[0].Item1 != bs[i].Item1 && bs[0].Item2 + bs[i].Item2 <= Y) uf.UniteCategory(0, i);
			for (var l = 1; l < N; l++) if (bs[0].Item1 != bs[l].Item1)
				{
					for (var i = 0; i < N; i++) if (bs[l].Item1 != bs[i].Item1 && bs[l].Item2 + bs[i].Item2 <= Y) uf.UniteCategory(l, i);
					break;
				}
			var fact = new long[N + 1];
			fact[0] = 1;
			for (var i = 1; i <= N; i++) fact[i] = (i * fact[i - 1]) % Mod;
			var ifact = new long[N + 1];
			ifact[0] = 1;
			for (var i = 1; i <= N; i++) ifact[i] = (Inverse(i, Mod) * ifact[i - 1]) % Mod;
			var ans = 1L;
			var z = new List<int>[N];
			for (var i = 0; i < N; i++) z[i] = new List<int>();
			for (var i = 0; i < N; i++) z[uf.GetRootOf(i)].Add(i);
			for (var i = 0; i < N; i++)
			{
				ans = (ans * fact[z[i].Count]) % Mod;
				var y = new Dictionary<int, int>();
				foreach (var j in z[i])
				{
					var C = bs[j].Item1;
					if (!y.ContainsKey(C)) y[C] = 1;
					else y[C]++;
				}
				foreach (var s in y) ans = (ans * ifact[s.Value]) % Mod;
			}
			if (ans < 0) ans += Mod;
			pr.WriteLine(ans);
		}
		int[] SuffixArray(string S)
		{
			var N = S.Length;
			var sa = new int[N + 1];
			var r = new int[N + 1];
			for (var i = 0; i <= N; i++)
			{
				sa[i] = i;
				r[i] = i < N ? S[i] : -1;
			}
			var k = 1;
			Comparison<int> comp = (i, j) =>
			  {
				  if (r[i] != r[j]) return r[i] - r[j];
				  var a = i + k <= N ? r[i + k] : -1;
				  var b = j + k <= N ? r[j + k] : -1;
				  return a - b;
			  };
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
	}
	class RangeSegmentTree
	{
		int N2;
		int[] seg, unif;
		public RangeSegmentTree(int N)
		{
			N2 = 1;
			while (N2 < N) N2 <<= 1;
			seg = new int[2 * N2 - 1];
			unif = new int[2 * N2 - 1];
		}
		void LazyEvaluate(int node)
		{
			if (unif[node] == 0) return;
			seg[node] += unif[node];
			if (node < N2 - 1)
			{
				unif[2 * node + 1] += unif[node];
				unif[2 * node + 2] += unif[node];
			}
			unif[node] = 0;
		}
		void Update(int node) => seg[node] = seg[2 * node + 1] + seg[2 * node + 2];
		public void AddRange(int from, int to, int value) => AddRange(from, to, value, 0, 0, N2);
		void AddRange(int from, int to, int value, int node, int l, int r)
		{
			if (from <= l && r <= to) unif[node] += value;
			else if (l < to && from < r)
			{
				AddRange(from, to, value, 2 * node + 1, l, (l + r) >> 1);
				AddRange(from, to, value, 2 * node + 2, (l + r) >> 1, r);
				Update(node);
			}
			LazyEvaluate(node);
		}
		public int this[int n] { get { return Sum(n, n + 1); } set { AddRange(n, n + 1, value - this[n]); } }
		public int Sum(int from, int to) => Sum(from, to, 0, 0, N2);
		int Sum(int from, int to, int node, int l, int r)
		{
			LazyEvaluate(node);
			if (to <= l || r <= from) return 0;
			else if (from <= l && r <= to) return seg[node];
			else return Sum(from, to, 2 * node + 1, l, (l + r) >> 1) + Sum(from, to, 2 * node + 2, (l + r) >> 1, r);
		}
	}
