		{
			while (deq.Count > 0 && a[deq.PeekBack()] <= a[index]) deq.PopBack();
			deq.PushBack(index);
		}
		public void Remove(int index)
		{
			if (deq.Count > 0 && deq.PeekFront() == index) deq.PopFront();
		}
