		long[] f = new long[N+1];
		f[0] = f[1] = 1;
		for(int i=2;i<=N;i++){
			f[i] = f[i-1] *i;
			if(f[i] >= mod) f[i] %= mod;
		}

		Pair[] P = new Pair[N];
		for(int i=0;i<N;i++){
			P[i] = new Pair(i,C[i],W[i]);
		}

		Array.Sort(P,(p,q) => p.W.CompareTo(q.W));

		Dictionary<int,List<int>> D = new Dictionary<int,List<int>>();
		Dictionary<int,int> Same = new Dictionary<int,int>();
		for(int i=0;i<N;i++){
			if(!D.ContainsKey(P[i].C)){
				D.Add(P[i].C,new List<int>());
				Same.Add(P[i].C,0);
			}
			D[P[i].C].Add(P[i].Idx);
			if(P[i].W + W[D[P[i].C][0]] <= X) Same[P[i].C]++;
		}


		int[] CC = D.Keys.ToArray();
		int NN = CC.Length;
		int[] WW = new int[NN];
		for(int i=0;i<NN;i++) WW[i] = W[D[CC[i]][0]];

		Array.Sort(WW,CC);
		long ret = 1;
		int t=0;
		for(;t<NN;t++){
			int nt = t;
//Console.WriteLine("{0} {1} {2}",t,WW[t],CC[t]);
			long way = 1;
			Console.WriteLine(way);
			while(true){
				if(nt+1<NN && WW[nt+1]+WW[t]<=Y){
					if(nt == t) way = Same[CC[t]];
					nt++;
					int can = 0;
					while(true){
						if(can+1 < D[CC[nt]].Count && W[D[CC[nt]][can+1]] + WW[t] <= Y){
							can++;
							continue;
						}
						break;
					}
					way += Math.Max(Same[CC[nt]],can+1);
					continue;
				}
				break;
			}

			ret *= f[way];
			if(ret >= mod) ret %= mod;
			t = nt;
		}
		Console.WriteLine(ret);
	}

