  }
  sort.Sort(b)
  if b[0].c == b[n-1].c { fmt.Println(1);return }
  b = append(b,Ball{0,0})
  u := NewUnionFind(n)
  for i,j:=0,0;i<n; {
    for b[j].c == b[i].c { j++ }
    for k:=i+1;k<j;k++ {
      if b[i].w+b[k].w <= x { u.Unite(i,k) }
    }
    i = j
  }
  p := 0
  for i:=0;i<n;i++ {
    if b[p].w > b[i].w { p = i }
  }
  q := 0
  for i:=0;i<n;i++ {
    if b[i].c != b[p].c { q = i;break }
  }
  for i:=0;i<n;i++ {
    if b[i].c != b[p].c && b[q].w > b[i].w { q = i }
  }
  for i:=0;i<n;i++ {
    if b[i].c == b[p].c {
      if b[i].w+b[q].w <= y { u.Unite(i,q) }
    } else {
      if b[i].w+b[p].w <= y { u.Unite(i,p) }
    }
  }
