// import dcomp.scanner, dcomp.modint;

alias Mint = ModInt!(10^^9 + 7);

immutable INF = 10^^9 + 10^^7;

Mint[] fact, iFac;
static this() {
    fact = factTable!Mint(300_000);
    iFac = invFactTable!Mint(300_000);
}

Mint C(int n, int k) {
    if (n < 0 || n < k) return Mint(0);
    return fact[n]*iFac[k]*iFac[n-k];
}

int main() {
    auto sc = new Scanner(stdin);
    int n, x, y;
    sc.read(n, x, y);
    int[] c = new int[n], w = new int[n];

    int[] mi = new int[n]; mi[] = INF;
    foreach (i; 0..n) {
        sc.read(c[i], w[i]); c[i]--;
        mi[c[i]] = min(mi[c[i]], w[i]);
    }
    int[] lmi = new int[n+1], rmi = new int[n+1];
    lmi[] = INF; rmi[] = INF;
    foreach (i; 0..n) {
        lmi[i+1] = min(lmi[i], mi[i]);
    }
    foreach_reverse (i; 0..n-1) {
        rmi[i] = min(rmi[i+1], mi[i+1]);
    }
    bool[] ok = new bool[n];
    foreach (i; 0..n) {
        int nc = c[i], nw = w[i];
        int my = mi[nc];
        int other = min(lmi[i], rmi[i]);
        if (other + my > y) continue;
        if (other + nw <= y || my + nw <= x) ok[i] = true;
    }

//    writeln(ok);
    int[] co = new int[n];
    foreach (i; 0..n) {
        if (ok[i]) co[c[i]]++;
    }

    int all = co.sum;
    Mint ans = 1;
    foreach (i; 0..n) {
        ans *= C(all, co[i]);
        all -= co[i];
    }
    writeln(ans);
    return 0;
}
