    const INF: i64 = 1 << 50;
    let mut miy = INF;
    let mut miyi = n;
    let mut mi = vec![INF; n];
    for i in 0 .. n {
        c[i] = get::<usize>() - 1;
        w[i] = get::<i64>();
        mi[c[i]] = min(mi[c[i]], w[i]);
        if miy > w[i] {
            miy = w[i];
            miyi = i;
        }
    }
    for i in 0 .. n {
        let mix = mi[c[i]];
        if mix + w[i] <= x {
            w[i] = mix;
        }
    }
    let mut miz = INF;
    let mut mizi = n;
    for i in 0 .. n {
        if c[i] != c[miyi] {
            if miz > w[i] {
                miz = w[i];
                mizi = i;
            }
        }
    }
    let mut uf = UnionFind::new(n);
    for i in 0 .. n {
        if c[i] != c[miyi] {
            if w[i] + w[miyi] <= y {
                uf.unite(i, miyi);
            }
        } else {
            if mizi < n {
                if w[i] + w[mizi] <= y {
                    uf.unite(i, mizi);
                }
            }
        }
    }
    let mut occur = vec![HashMap::new(); n];
    for i in 0 .. n {
        let r = uf.root(i);
        let man = &mut occur[r];
        let newv = match
            man.get(&c[i]) {
                None => 1,
                Some(x) => x + 1,
            };
        man.insert(c[i], newv);
    }
    let mut prod = 1;
    let mut fact = vec![1; n + 1];
    for i in 0 .. n {
        fact[i + 1] = fact[i] * (i + 1) as i64 % MOD;
    }
    for i in 0 .. n {
        prod = prod * calc(&occur[i], &fact) % MOD;
    }
    println!("{}", prod);
}

